    public record TriggerUpdateOutcome(boolean accepted, boolean stale, boolean durable, boolean runtimeReady,
                                       long bindingEpoch, String bindingHash, List<TriggerBinding> bindings,
                                       String diagnostic) {
        public TriggerUpdateOutcome {
            bindingHash = bindingHash == null || bindingHash.isBlank() ? null : bindingHash;
            bindings = bindings == null ? List.of() : List.copyOf(bindings);
            diagnostic = diagnostic == null ? "" : diagnostic;
        }

        public boolean hasAuthoritativeState() {
            return bindingEpoch > 0L && bindingHash != null && !bindingHash.isBlank();
        }

        public boolean successful() {
            return accepted && durable && hasAuthoritativeState();
        }

        public static TriggerUpdateOutcome rejected(String diagnostic) {
            return new TriggerUpdateOutcome(false, false, false, false, 0L, null, List.of(), diagnostic);
        }
    }

