    public enum CoreGraphActivationState {
        PENDING,
        LIVE,
        READ_ONLY,
        INCOMPATIBLE,
        MISSING
    }

    public record CoreGraphActivationOutcome(CoreGraphActivationState state, String reason, long revision) {
        public CoreGraphActivationOutcome {
            state = Objects.requireNonNull(state, "Core graph activation state is required");
            reason = reason == null ? "" : reason.trim();
            if (revision < 0L) {
                throw new IllegalArgumentException("Core graph activation revision cannot be negative");
            }
        }
    }

    public record CoreGraphListSnapshot(ServerId serverId, ReSyncResourceType type, UUID requestId,
                                        UUID correlationId, Set<ServerResourceLocator> resources,
                                        Set<ServerResourceLocator> tombstones, boolean authoritative) {
        public CoreGraphListSnapshot {
            serverId = Objects.requireNonNull(serverId, "Core list server is required");
            type = Objects.requireNonNull(type, "Core list resource type is required");
            requestId = Objects.requireNonNull(requestId, "Core list request ID is required");
            correlationId = Objects.requireNonNull(correlationId, "Core list correlation ID is required");
            resources = resources == null ? Set.of() : Set.copyOf(resources);
            tombstones = tombstones == null ? Set.of() : Set.copyOf(tombstones);
            boolean invalidResource = false;
            for (ServerResourceLocator resource : resources) {
                if (resource == null || !serverId.equals(resource.serverId())
                    || !type.typeId().equals(resource.resourceType().value())) {
                    invalidResource = true;
                    break;
                }
            }
            if (!type.isGraph() || !resources.containsAll(tombstones) || invalidResource) {
                throw new IllegalArgumentException("Core list snapshots require one server and graph resource type");
            }
        }

        public Set<ServerResourceLocator> liveResources() {
            HashSet<ServerResourceLocator> live = new HashSet<>(resources);
            live.removeAll(tombstones);
            return Set.copyOf(live);
        }
    }

    public record CoreGraphMutationResult(
        UUID requestId,
        UUID correlationId,
        UUID traceId,
        UUID mutationId,
        ResourceOperationKind operation,
        ServerResourceLocator resource,
        long expectedRevision,
        ContentHash requestPayloadHash,
        long revision,
        UUID authoritativeMutationId,
        ContentHash payloadHash,
        ProtocolEnvelope.Status status,
        boolean deleted
    ) {
        public CoreGraphMutationResult {
            requestId = Objects.requireNonNull(requestId, "Core mutation request ID is required");
            correlationId = Objects.requireNonNull(correlationId, "Core mutation correlation ID is required");
            traceId = Objects.requireNonNull(traceId, "Core mutation trace ID is required");
            mutationId = Objects.requireNonNull(mutationId, "Core mutation ID is required");
            operation = Objects.requireNonNull(operation, "Core mutation operation is required");
            resource = Objects.requireNonNull(resource, "Core mutation resource is required");
            status = Objects.requireNonNull(status, "Core mutation status is required");
            if (!resourceMutationOperation(operation)) {
                throw new IllegalArgumentException("Core mutation results require a mutation operation");
            }
            if (expectedRevision < 0L || revision < 0L) {
                throw new IllegalArgumentException("Core mutation revisions cannot be negative");
            }
        }

        public boolean accepted() {
            return status == ProtocolEnvelope.Status.OK || status == ProtocolEnvelope.Status.ACCEPTED;
        }

        public boolean conflict() {
            return status == ProtocolEnvelope.Status.CONFLICT;
        }
    }

    public record CoreGraphResourceTransition(
        ServerResourceLocator resource,
        ReSyncResourceType type,
        CoreGraphResourceProjection.Projection projection,
        GraphResourceState state,
        GraphResourceCache.Status status
    ) {
        public CoreGraphResourceTransition {
            resource = Objects.requireNonNull(resource, "Core resource is required");
            type = Objects.requireNonNull(type, "Core resource type is required");
            projection = Objects.requireNonNull(projection, "Core projection is required");
            if (!resource.equals(projection.resource())) {
                throw new IllegalArgumentException("Core transition resource does not match its projection");
            }
            if (state != null && !resource.equals(state.resource())) {
                throw new IllegalArgumentException("Core transition resource does not match its state");
            }
            if (status == null && !projection.readOnly()) {
                throw new IllegalArgumentException("Authoritative Core transitions require a cache status");
            }
        }

        public boolean readOnly() {
            return projection.readOnly();
        }

        public boolean tombstoned() {
            return projection.tombstoned();
        }

        public boolean authoritative() {
            return state != null;
        }
    }

