    public ReSyncLuckPermsClient luckPerms() {
        ReSyncLuckPermsClient current = luckPermsClient;
        if (current != null) {
            if (shutdownRequested) throw new IllegalStateException("ReSync client is shut down");
            return current;
        }
        synchronized (this) {
            if (shutdownRequested) throw new IllegalStateException("ReSync client is shut down");
            if (luckPermsClient == null) {
                luckPermsClient = luckPermsProvider.get(this);
            }
            return luckPermsClient;
        }
    }

    public ReadinessState readiness() {
        if (isConnectedState()) {
            return ReadinessState.READY;
        }
        ConnectionFailure failure = connectionFailure();
        if (failure == ConnectionFailure.PROTOCOL_MISMATCH || failure == ConnectionFailure.RUNTIME_VERSION_MISMATCH) {
            return ReadinessState.INCOMPATIBLE;
        }
        if (isConnected()) {
            return ReadinessState.WAITING_FOR_REGISTRY;
        }
        if (connectionState() == ConnectionState.CONNECTING) {
            return ReadinessState.CONNECTING;
        }
        return ReadinessState.DISCONNECTED;
    }

    public String readinessFailureMessage() {
        return "ReSync Flow Contract Mismatch. Update ReSync And Remotely";
    }

