    public Optional<OptionCatalogLoader.CoreRequest> automaticCoreOptionRequest(
        ContractRef<InspectorFieldId> sourceReference, ServerResourceLocator currentResource,
        Map<String, TypedValue> context, Map<String, TypedValue> dependencies, String search) {
        return coreOptionRequest(sourceReference, currentResource, context, dependencies, search, true);
    }

    private Optional<OptionCatalogLoader.CoreRequest> coreOptionRequest(
        ContractRef<InspectorFieldId> sourceReference, ServerResourceLocator resource,
        Map<String, TypedValue> context, Map<String, TypedValue> dependencies, String search,
        boolean automaticCurrentResource) {
        if (shutdownRequested || sourceReference == null || !catalogAuthoringAdvertised
            || catalogAuthority != CatalogAuthority.TYPED_PUBLICATION) {
            return Optional.empty();
        }
        synchronized (catalogLifecycleLock) {
            Optional<ReSyncCatalogAuthoringProjection.Snapshot> active = activeAuthoringSnapshot();
            if (active.isEmpty()) {
                return Optional.empty();
            }
            ReSyncCatalogAuthoringProjection.Snapshot snapshot = active.orElseThrow();
            try {
                AdvertisedOptionSourceResolver.Resolved resolved = AdvertisedOptionSourceResolver
                    .resolve(snapshot.publication(), sourceReference).orElse(null);
                if (resolved == null) {
                    return Optional.empty();
                }
                ServerResourceLocator queryResource = automaticCurrentResource
                    && resolved.source().querySchema().resource() == null
                    ? null : resource;
                return Optional.of(new OptionCatalogLoader.CoreRequest(protocolServerId(), resolved.reference(),
                    resolved.source(), queryResource, context, dependencies, search, snapshot.publication().binding(),
                    snapshot.publication().contractVersion(), snapshot.checksum(), snapshot.revision(),
                    optionQueryAuthorityEpoch()));
            } catch (RuntimeException exception) {
                logger().operation("Option Source").with("source", sourceReference.canonicalText())
                    .with("reason", exception.getMessage()).warn("Rejected invalid advertised option source");
                return Optional.empty();
            }
        }
    }

    public boolean requestCoreOptionCatalog(OptionCatalogLoader.CoreRequest request, boolean forceRefresh) {
        return requestCoreOptionCatalogOutcome(request, forceRefresh) == OptionCatalogLoader.CoreRequestOutcome.STARTED;
    }

    OptionCatalogLoader.CoreRequestOutcome requestCoreOptionCatalogOutcome(OptionCatalogLoader.CoreRequest request,
                                                                            boolean forceRefresh) {
        OptionCatalogCache cache = OptionCatalogCache.getInstance();
        synchronized (coreOptionDispatchLock) {
            if (request == null || !request.automaticSupported()) {
                return OptionCatalogLoader.CoreRequestOutcome.REJECTED;
            }
            if (!optionQueriesAdvertised) {
                return OptionCatalogLoader.CoreRequestOutcome.REJECTED;
            }
            if (!currentCoreOptionRequest(request)) {
                return OptionCatalogLoader.CoreRequestOutcome.REJECTED;
            }
            OptionCatalogCache.CoreAdmission admission = cache.admit(request.key(), forceRefresh);
            if (admission != OptionCatalogCache.CoreAdmission.STARTED) {
                return switch (admission) {
                    case FRESH -> OptionCatalogLoader.CoreRequestOutcome.FRESH;
                    case COALESCED -> OptionCatalogLoader.CoreRequestOutcome.COALESCED;
                    case BUSY -> OptionCatalogLoader.CoreRequestOutcome.BUSY;
                    case STARTED -> throw new IllegalStateException("Started option request was not dispatched");
                };
            }
            int generation = connectionGeneration.get();
            ConnectionSource source = connectionSource(generation);
            if (source == null || !isConnectionReadyGeneration(generation)) {
                cache.fail(request.key(), "The ReSync connection is unavailable");
                return OptionCatalogLoader.CoreRequestOutcome.REJECTED;
            }
            PendingCoreOptionRequest pending = PendingCoreOptionRequest.first(request, generation, source);
            if (!sendCoreOptionRequest(pending)) {
                cache.fail(request.key(), "The option query could not be sent");
                return OptionCatalogLoader.CoreRequestOutcome.REJECTED;
            }
            logger().operation("Option Query").with("source", request.sourceReference().canonicalText())
                .with("requestId", pending.requestId()).with("generation", generation)
                .debug("Option catalog query dispatched");
            return OptionCatalogLoader.CoreRequestOutcome.STARTED;
        }
    }

    private boolean currentCoreOptionRequest(OptionCatalogLoader.CoreRequest request) {
        return !shutdownRequested && catalogAuthoringAdvertised && optionQueriesAdvertised
            && catalogAuthority == CatalogAuthority.TYPED_PUBLICATION && optionQueryAuthorityReady()
            && currentCoreOptionPublication(request);
    }

    private boolean currentCoreOptionPublication(OptionCatalogLoader.CoreRequest request) {
        if (request == null || request.authorityEpoch() != handshakeAuthorityEpoch) {
            return false;
        }
        synchronized (catalogLifecycleLock) {
            Optional<ReSyncCatalogAuthoringProjection.Snapshot> active = activeAuthoringSnapshot();
            if (active.isEmpty()) {
                return false;
            }
            ReSyncCatalogAuthoringProjection.Snapshot snapshot = active.orElseThrow();
            if (snapshot.revision() != request.publicationRevision()
                || !snapshot.checksum().equals(request.publicationChecksum())
                || !snapshot.publication().binding().equals(request.catalogBinding())
                || !snapshot.publication().contractVersion().equals(request.publicationContractVersion())) {
                return false;
            }
            try {
                return AdvertisedOptionSourceResolver.resolve(snapshot.publication(), request.sourceReference())
                    .filter(resolved -> resolved.source().equals(request.source()))
                    .isPresent();
            } catch (RuntimeException exception) {
                return false;
            }
        }
    }

    private boolean sendCoreOptionRequest(PendingCoreOptionRequest pending) {
        if (pending == null
            || !pending.matchesGeneration(connectionGeneration.get(), connectionSource(connectionGeneration.get()))) {
            return false;
        }
        synchronized (coreOptionDispatchLock) {
            synchronized (catalogLifecycleLock) {
                if (!currentCoreOptionRequest(pending.request())
                    || pendingCoreOptionRequests.putIfAbsent(pending.requestId(), pending) != null) {
                    return false;
                }
            }
            return dispatchCoreOptionRequest(pending);
        }
    }

    private boolean dispatchCoreOptionRequest(PendingCoreOptionRequest pending) {
        ProtocolEnvelope<Map<String, Object>> envelope;
        try {
            envelope = new ProtocolEnvelope<>(
                ProtocolEnvelope.Kind.REQUEST,
                ReSyncProtocolContract.GENERIC_RESOURCE_CONTRACT_VERSION,
                UUID.randomUUID(),
                pending.requestId(),
                pending.correlationId(),
                pending.traceId(),
                pending.request().serverId(),
                null,
                0L,
                pending.request().authorityEpoch(),
                null,
                OPTION_QUERY_OPERATION,
                OPTION_QUERY_CAPABILITIES,
                OPTION_PAGE_TYPE,
                null,
                null,
                false,
                pending.request().publicationContractVersion(),
                pending.request().catalogBinding().catalogChecksum(),
                pending.request().catalogBinding().bindingManifestHash(),
                null,
                null,
                0L,
                ProtocolEnvelope.Status.ACCEPTED,
                List.of(),
                Map.of(),
                new ProtocolBody.OptionQueryRequest(pending.query())
            );
        } catch (RuntimeException exception) {
            pendingCoreOptionRequests.remove(pending.requestId(), pending);
            return false;
        }
        boolean sent;
        try {
            sent = sendFrame(MESSAGE_PROTOCOL_ENVELOPE, protocolEnvelopeCodec.encodeBytes(envelope), CONTROL_CHANNEL_ID,
                false, pending.generation());
        } catch (RuntimeException exception) {
            sent = false;
        }
        if (!sent) {
            pendingCoreOptionRequests.remove(pending.requestId(), pending);
            cancelPendingSend(pending.requestId().toString());
            return false;
        }
        try {
            heartbeatScheduler.schedule(() -> failCoreOptionRequest(pending, "Option catalog request timed out", true), Duration.ofSeconds(TYPED_RESOURCE_RESPONSE_TIMEOUT_SECONDS));
        } catch (RuntimeException exception) {
            failCoreOptionRequest(pending, "Option catalog request could not be monitored");
            return false;
        }
        return true;
    }

    public CoreGraphDocumentAuthoringAdapter.TemplateTransport authoringTemplateTransport() {
        return this::requestAuthoringTemplate;
    }

    public boolean requestAuthoringTemplate(UUID requestId, AuthoringTemplateRequest request,
                                             Consumer<AuthoringTemplateResponse> responseConsumer) {
        if (shutdownRequested || requestId == null || request == null || responseConsumer == null
            || !catalogAuthoringAdvertised || !catalogAuthorityAllowsGraphInteraction(catalogAuthority)
            || !isConnected()) {
            return false;
        }
        ServerId expectedServer = protocolServerId();
        if (!validAuthoringTemplateRequest(request, expectedServer)) {
            return false;
        }
        int generation = connectionGeneration.get();
        ConnectionSource source = connectionSource(generation);
        if (source == null || !isConnectionReadyGeneration(generation)) {
            return false;
        }
        CatalogVersion contractVersion = genericResourceContractVersion;
        if (contractVersion == null) {
            return false;
        }
        long authorityEpoch;
        try {
            authorityEpoch = authorityEpochForTypedEnvelope();
        } catch (RuntimeException exception) {
            return false;
        }
        UUID correlationId = UUID.randomUUID();
        UUID traceId = UUID.randomUUID();
        PendingAuthoringTemplateRequest pending = new PendingAuthoringTemplateRequest(requestId, correlationId, traceId,
            expectedServer, request, responseConsumer, generation, source, authorityEpoch, contractVersion);
        if (pendingAuthoringTemplateRequests.putIfAbsent(requestId, pending) != null) {
            return false;
        }
        ProtocolEnvelope<Map<String, Object>> envelope;
        try {
            envelope = new ProtocolEnvelope<>(
                ProtocolEnvelope.Kind.REQUEST,
                pending.contractVersion(),
                UUID.randomUUID(),
                pending.requestId(),
                pending.correlationId(),
                pending.traceId(),
                expectedServer,
                null,
                0L,
                authorityEpoch,
                null,
                AUTHORING_TEMPLATE_OPERATION,
                AUTHORING_TEMPLATE_CAPABILITIES,
                AUTHORING_TEMPLATE_REQUEST_TYPE,
                null,
                null,
                false,
                null,
                null,
                null,
                null,
                null,
                0L,
                ProtocolEnvelope.Status.ACCEPTED,
                List.of(),
                Map.of(),
                new ProtocolBody.ControlRequest(AUTHORING_TEMPLATE_ACTION,
                    Map.of("request", AuthoringTemplateCodec.INSTANCE.encodeRequest(request).toJava()))
            );
        } catch (RuntimeException exception) {
            pendingAuthoringTemplateRequests.remove(requestId, pending);
            return false;
        }
        boolean sent;
        try {
            sent = sendFrame(MESSAGE_PROTOCOL_ENVELOPE, protocolEnvelopeCodec.encodeBytes(envelope), CONTROL_CHANNEL_ID,
                false, generation);
        } catch (RuntimeException exception) {
            sent = false;
        }
        if (!sent) {
            pendingAuthoringTemplateRequests.remove(requestId, pending);
            cancelPendingSend(requestId.toString());
            return false;
        }
        try {
            heartbeatScheduler.schedule(() -> completeAuthoringTemplateRequest(pending, null), Duration.ofSeconds(15L));
        } catch (RuntimeException exception) {
            completeAuthoringTemplateRequest(pending, null);
        }
        return true;
    }

    private boolean validAuthoringTemplateRequest(AuthoringTemplateRequest request, ServerId expectedServer) {
        if (expectedServer == null || request == null || request.resource() == null
            || !expectedServer.equals(request.resource().serverId())
            || !PROTOCOL_OWNER.equals(request.resource().owner())
            || !AUTHORING_TEMPLATE_RESOURCE_TYPES.contains(request.resource().resourceType().value())
            || request.acknowledgedCatalogKey() == null
            || !expectedServer.equals(request.acknowledgedCatalogKey().serverId())
            || !request.acknowledgedCatalogKey().hasCatalogBinding()
            || request.acknowledgedAuthoringPublicationChecksum() == null) {
            return false;
        }
        synchronized (catalogLifecycleLock) {
            Optional<ReSyncCatalogAuthoringProjection.Snapshot> active = activeAuthoringSnapshot();
            if (active.isEmpty()) {
                return false;
            }
            ReSyncCatalogAuthoringProjection.Snapshot snapshot = active.orElseThrow();
            return snapshot.key().equals(request.acknowledgedCatalogKey())
                && snapshot.checksum().equals(request.acknowledgedAuthoringPublicationChecksum())
                && snapshot.publication().binding().equals(request.acknowledgedCatalogKey().catalogBinding());
        }
    }

    private Optional<ReSyncCatalogAuthoringProjection.Snapshot> activeAuthoringSnapshot() {
        return catalogAuthoringProjection.active()
            .filter(authoring -> catalogPublicationProjection.active()
                .map(node -> node.publication().key().equals(authoring.key())
                    && authoring.publication().binding().equals(node.publication().catalogBinding()))
                .orElse(false));
    }

