    public boolean requestCoreResourcePage(ReSyncResourceType type, UUID correlationId) {
        if (shutdownRequested) return false;
        if (type == null || !type.isGraph() || correlationId == null) {
            return false;
        }
        CorePageContinuation continuation = corePageContinuations.get(correlationId);
        if (continuation == null || continuation.type() != type || continuation.nextCursor() == null
            || continuation.nextCursor().isBlank()) {
            return false;
        }
        if (!supportsGenericCoreResource(type, continuation.operation(), false)) {
            return false;
        }
        if (!corePageContinuations.remove(correlationId, continuation)) {
            return false;
        }
        if (sendCoreGraphList(type, continuation.nextCursor(), continuation.query(), continuation.correlationId(),
            continuation.traceId(), continuation.operation())) {
            return true;
        }
        corePageContinuations.putIfAbsent(correlationId, continuation);
        return false;
    }

