    public String catalogAuthorityDebugState() {
        ReSyncCatalogPublicationProjection.Snapshot active = catalogPublicationProjection.active().orElse(null);
        CatalogCacheKey acknowledged = catalogPublicationProjection.acknowledgedKey().orElse(null);
        ReSyncCatalogAuthoringProjection.Snapshot authoring = catalogAuthoringProjection.active().orElse(null);
        TypedInteractionState interaction = typedInteractionState.get();
        return "server=" + serverId
            + ",client=" + stableClientId
            + ",transport=" + (frameTransport == null ? "websocket" : "bridge")
            + ",generation=" + connectionGeneration.get()
            + ",connected=" + isConnected()
            + ",authority=" + catalogAuthority
            + ",diagnostic=" + catalogAuthorityDiagnostic
            + ",typedAdvertised=" + typedCatalogAuthorityAdvertised
            + ",authoringAdvertised=" + catalogAuthoringAdvertised
            + ",publicationConfirmed=" + catalogPublicationConfirmed
            + ",activeKey=" + (active == null ? "none" : active.publication().key().canonicalText())
            + ",acknowledgedKey=" + (acknowledged == null ? "none" : acknowledged.canonicalText())
            + ",authoringKey=" + (authoring == null ? "none" : authoring.key().canonicalText())
            + ",authoringRevision=" + (authoring == null ? -1L : authoring.revision())
            + ",interactionKey=" + (interaction == null ? "none" : interaction.key().canonicalText())
            + ",identityDiagnostic=" + catalogPublicationProjection.identityDiagnostic().orElse("none")
            + ",retryRequired=" + catalogAcquisitionRetryRequired();
    }

    public boolean typedCatalogAuthorityAdvertised() {
        return !legacyCompatibilityProven;
    }

    public boolean catalogAuthoringAdvertised() {
        return catalogAuthoringAdvertised;
    }

    private void setCatalogAuthoringAdvertised(boolean advertised) {
        catalogAuthoringAdvertised = advertised;
        if (catalogPublicationReceiptHandler != null) {
            catalogPublicationReceiptHandler.setAuthoringRequired(advertised);
        }
        if (!advertised) {
            synchronized (catalogLifecycleLock) {
                if (catalogAuthoringProjection.active().isPresent()) {
                    retireTypedInteractionProjection();
                }
                catalogAuthoringProjection.clear();
            }
            failPendingAuthoringTemplateRequests("Catalog authoring is not negotiated");
            failPendingCoreOptionRequests("Catalog authoring is not negotiated");
        }
    }

    public boolean acknowledgeCatalogPublicationKey(CatalogCacheKey key) {
        if (shutdownRequested) return false;
        synchronized (catalogLifecycleLock) {
            typedCatalogAuthorityAdvertised = true;
            legacyCompatibilityProven = false;
            catalogPublicationConfirmed = false;
            boolean accepted = catalogPublicationProjection.acknowledgeActiveKey(key);
            if (!accepted) {
                retireTypedInteractionProjection();
                catalogPublicationProjection.clear();
                catalogAuthoringProjection.clear();
                beginTypedReconciliation("CATALOG_PUBLICATION_KEY_MISMATCH_RECONCILIATION");
                return false;
            }
            catalogPublicationConfirmed = catalogPublicationProjection.active()
                .map(snapshot -> snapshot.publication().key().equals(key)).orElse(false);
            if (typedCatalogAuthority()) {
                refreshCatalogAuthority();
                notifyCatalogAuthorityUpdated();
                return true;
            }
            if (catalogPublicationConfirmed && !typedInteractionDiagnostic.isBlank()) {
                refreshCatalogAuthority();
                notifyCatalogAuthorityUpdated();
                return false;
            }
            beginTypedReconciliation("CATALOG_PUBLICATION_KEY_MISMATCH_RECONCILIATION");
            return false;
        }
    }

    private boolean typedCatalogAuthority() {
        boolean authoringReady = !catalogAuthoringAdvertised || activeAuthoringSnapshot().isPresent();
        return catalogPublicationConfirmed
            && catalogPublicationProjection.identityDiagnostic().isEmpty()
            && authoringReady
            && currentTypedInteractionProjection()
            && catalogPublicationProjection.active().flatMap(snapshot -> catalogPublicationProjection.acknowledgedKey()
                .filter(snapshot.publication().key()::equals)).isPresent();
    }

    private void refreshCatalogAuthority() {
        Optional<String> identityDiagnostic = catalogPublicationProjection.identityDiagnostic();
        if (identityDiagnostic.isPresent()) {
            if (legacyCompatibilityProven) {
                catalogAuthority = CatalogAuthority.LEGACY_COMPATIBILITY;
                catalogAuthorityDiagnostic = identityDiagnostic.orElseThrow() + ";LEGACY_COMPATIBILITY";
            } else {
                catalogAuthority = CatalogAuthority.UNAVAILABLE;
                catalogAuthorityDiagnostic = identityDiagnostic.orElseThrow();
            }
            return;
        }
        if (typedCatalogAuthority()) {
            ReSyncResourceDropCapabilities.clearCatalog(serverId);
            catalogAuthority = CatalogAuthority.TYPED_PUBLICATION;
            catalogAuthorityDiagnostic = "";
            return;
        }
        if (catalogPublicationProjection.active().isPresent()) {
            catalogAuthority = CatalogAuthority.TYPED_RECONCILIATION;
            catalogAuthorityDiagnostic = typedInteractionDiagnostic.isBlank()
                ? "CATALOG_PUBLICATION_RECONCILIATION_REQUIRED" : typedInteractionDiagnostic;
            return;
        }
        if (typedCatalogAuthorityAdvertised) {
            catalogAuthority = CatalogAuthority.TYPED_RECONCILIATION;
            if (catalogAuthorityDiagnostic == null || catalogAuthorityDiagnostic.isBlank()) {
                catalogAuthorityDiagnostic = "CATALOG_TYPED_PUBLICATION_UNAVAILABLE";
            }
            return;
        }
        if (legacyCompatibilityProven) {
            catalogAuthority = CatalogAuthority.LEGACY_COMPATIBILITY;
            catalogAuthorityDiagnostic = "CATALOG_TYPED_PUBLICATION_UNAVAILABLE;LEGACY_COMPATIBILITY";
            return;
        }
        catalogAuthority = CatalogAuthority.UNAVAILABLE;
        catalogAuthorityDiagnostic = "CATALOG_PUBLICATION_RECONCILIATION_REQUIRED";
    }

    private void beginTypedReconciliation(String reason) {
        typedCatalogAuthorityAdvertised = true;
        legacyCompatibilityProven = false;
        catalogPublicationConfirmed = false;
        clearTypedInteractionProjection();
        retireLegacyRegistryProjection();
        ReSyncResourceDropCapabilities.clearCatalog(serverId);
        catalogAuthority = CatalogAuthority.TYPED_RECONCILIATION;
        catalogAuthorityDiagnostic = reason;
        notifyCatalogAuthorityUpdated();
    }

    private void clearCatalogPublication(String reason) {
        catalogPublicationWorkEpoch.incrementAndGet();
        retireCatalogAcquisition();
        resetCatalogChunkAssembly();
        cancelNodeRegistryRetry();
        List<PendingCoreOptionRequest> retired;
        synchronized (coreOptionDispatchLock) {
            retired = retirePendingCoreOptionRequests(
                "The catalog publication changed before the option query completed");
            coreOptionInvalidationSequences.clear();
            synchronized (catalogLifecycleLock) {
                catalogAuthoringProjection.expectedServerId()
                    .ifPresent(OptionCatalogCache.getInstance()::markCoreServerStale);
                retireTypedInteractionProjection();
                catalogPublicationProjection.clear();
                catalogAuthoringProjection.clear();
                ReSyncResourceDropCapabilities.clearCatalog(serverId);
                retireLegacyRegistryProjection();
                typedCatalogAuthorityAdvertised = false;
                setCatalogAuthoringAdvertised(false);
                legacyCompatibilityProven = false;
                catalogPublicationConfirmed = false;
                catalogAuthority = CatalogAuthority.UNAVAILABLE;
                catalogAuthorityDiagnostic = reason;
                notifyCatalogAuthorityUpdated();
            }
        }
        cancelRetiredCoreOptionRequests(retired);
    }

    private void retireLegacyRegistryProjection() {
        NodeRegistry registry = NodeRegistry.getInstance();
        if (registry != null) {
            registry.clearServer(serverId, false);
        }
    }

