    private void bindCollaborationChannel() {
        collaboration.bind(new CollaborationService.Channel() {
            @Override
            public boolean available() {
                return isConnected();
            }

            @Override
            public void publishPresence(CollaborationService.PresenceUpdate update) {
                CollaborationService.Target target = update.target();
                sendCollaborationPresence(target.resourceType(), target.resourceId(), target.viewId(),
                    update.x(), update.y(), update.active(), update.typing());
            }

            @Override
            public void publishMessage(CollaborationService.MessageDraft message) {
                sendCollaborationMessage(message.message());
            }
        });
    }

    private ReSyncWorkspaceClient.WorkspaceSource bindWorkspaceChannel() {
        return workspaces.bind(new LiveDocumentChannel.Transport<>() {
            @Override
            public void join(WorkspaceTarget target) {
                sendWorkspaceTarget(ReSyncProtocolContract.FLOW_PACKET_WORKSPACE_JOIN, target);
            }

            @Override
            public void leave(WorkspaceTarget target) {
                sendWorkspaceTarget(ReSyncProtocolContract.FLOW_PACKET_WORKSPACE_LEAVE, target);
            }

            @Override
            public boolean publishOperation(WorkspaceTarget target, long baseSequence, String operationId,
                                            List<WorkspacePatch<JsonElement>> patches) {
                JsonObject request = workspaceTarget(target);
                request.addProperty("operationId", operationId);
                request.addProperty("baseSequence", baseSequence);
                JsonArray encoded = new JsonArray();
                for (WorkspacePatch<JsonElement> patch : patches) {
                    JsonObject value = new JsonObject();
                    value.addProperty("op", patch.op());
                    value.addProperty("path", patch.path());
                    if (patch.value() != null) {
                        value.add("value", patch.value());
                    }
                    encoded.add(value);
                }
                request.add("patches", encoded);
                return sendWorkspacePacket(ReSyncProtocolContract.FLOW_PACKET_WORKSPACE_OPERATION, request);
            }

            @Override
            public boolean publishAwareness(WorkspaceTarget target, JsonObject state) {
                JsonObject request = workspaceTarget(target);
                request.add("state", state != null ? state : new JsonObject());
                return sendWorkspacePacket(ReSyncProtocolContract.FLOW_PACKET_WORKSPACE_AWARENESS, request);
            }
        }, this::submitCurrentConnectionCallback);
    }

    private void sendWorkspaceTarget(byte packetType, WorkspaceTarget target) {
        sendWorkspacePacket(packetType, workspaceTarget(target), true);
    }

    private JsonObject workspaceTarget(WorkspaceTarget target) {
        JsonObject request = new JsonObject();
        request.addProperty("type", target.resourceType());
        request.addProperty("resourceId", target.resourceId());
        request.addProperty("documentVersion", 1);
        request.addProperty("authorityEpoch", handshakeAuthorityEpoch);
        catalogPublicationProjection.acknowledgedKey().ifPresent(key -> request.addProperty("catalogKey", key.canonicalText()));
        return request;
    }

    public ReSyncWorkspaceClient workspaces() {
        return workspaces;
    }

    public Async<Void> connect() {
        if (frameTransport != null) {
            return connectFrameTransport();
        }
        int generation;
        synchronized (outboundLock) {
            if (shutdownRequested || isConnected() || !connecting.compareAndSet(false, true)) {
                return Async.completed(null);
            }
            generation = connectionGeneration.incrementAndGet();
            pendingHandshakeGeneration.set(generation);
            lastRetirementDiagnostic = "none";
            lastTransportFailureDiagnostic = "none";
            resetHandshakeAuthorityEpoch();
        }
        observeHandshakeStage(generation, HandshakeStage.CONNECTING, "websocket_connecting");
        resetResourceListProjection(generation);
        clearCatalogPublication("CATALOG_PUBLICATION_RECONNECTING");
        scheduleCatalogCacheHydration(generation);
        refreshCatalogAuthority();
        nodeRegistrySynced = false;
        lastFullNodeRegistryRequestAt = 0L;
        scheduleConnectTimeout(generation);
        logger().operation("Connect").info("Connecting to ReSync");

        if (directWsUrl != null && !directWsUrl.isBlank()) {
            this.apiKey = directApiKey;
            if (this.apiKey == null || this.apiKey.isBlank()) {
                logger().operation("Connect").warn("Direct ReSync credentials are unavailable");
                abandonConnectionGeneration(generation);
                notifyError("ReSyncApiKeyMissing");
                return Async.completed(null);
            }
            logger().operation("Connect").with("endpoint", directWsUrl).info("Using direct ReSync endpoint");
            initWebSocketConnection(normalizeWsUrl(directWsUrl), generation);
            return Async.completed(null);
        }
        if (apiClient != null) {
            return apiClient.getReSyncConfig(serverId).thenCompose(config -> {
                if (!isActiveGeneration(generation)) {
                    return Async.completed(null);
                }
                if (config != null && config.port > 0) {
                    return apiClient.getServers().thenCompose(servers -> {
                        if (!isActiveGeneration(generation)) {
                            return Async.completed(null);
                        }
                        String serverUrl = servers != null ? servers.stream()
                            .filter(s -> serverId.equals(s.identifier))
                            .findFirst()
                            .map(s -> {
                                String ip = (s.ipAlias != null && !s.ipAlias.isEmpty()) ? s.ipAlias : s.ip;
                                return ip + ":" + config.port;
                            })
                            .orElse(null) : null;
                        if (serverUrl == null) {
                            abandonConnectionGeneration(generation);
                            notifyError("ReSyncServerNotFound");
                            return Async.completed(null);
                        }
                        return apiClient.getReSyncApiKey(serverId).thenAccept(key -> {
                            if (!isActiveGeneration(generation)) {
                                return;
                            }
                            this.apiKey = key;
                            if (this.apiKey != null && !this.apiKey.isEmpty()) {
                                String wsUrl = normalizeWsUrl(serverUrl);
                                initWebSocketConnection(wsUrl, generation);
                            } else {
                                abandonConnectionGeneration(generation);
                                notifyError("ReSyncApiKeyMissing");
                            }
                        });
                    });
                }
                abandonConnectionGeneration(generation);
                notifyError("ReSyncNotEnabled");
                return Async.completed(null);
            }).exceptionally(error -> {
                if (!isActiveGeneration(generation) || !abandonConnectionGeneration(generation)) {
                    return null;
                }
                scheduleReconnect(generation + 1);
                if (notifyConnectionErrorUnlessRetrying("ReSync Connection Failed. Check That The Server Is Online And ReSync Is Enabled")) {
                    logger().operation("Connect").error("Could not connect to ReSync", error);
                }
                return null;
            });
        }
        abandonConnectionGeneration(generation);
        notifyError("ReSyncNotEnabled");
        return Async.completed(null);
    }

    private void initWebSocketConnection(String wsUrl, int generation) {
        try {
            URI uri = URI.create(wsUrl);
            logger().operation("Connect").with("endpoint", wsUrl).debug("Opening ReSync WebSocket");
            Object client = ReSyncDirectSockets.connector.open(uri, new ReSyncDirectSockets.Handler() {
                @Override
                public void onOpen(Object socket) {
                    if (!isCurrentWebSocket(socket, generation)) {
                        ReSyncDirectSockets.connector.close(socket);
                        return;
                    }
                    logger().operation("Connect").info("ReSync WebSocket opened");
                    logger().operation("Handshake").debug("Sending handshake");
                    sendHandshake(generation);
                }

                @Override
                public void onMessage(Object socket, ByteBuffer bytes) {
                    if (!isCurrentWebSocket(socket, generation)) {
                        return;
                    }
                    handleBinaryMessage(bytes, generation);
                }

                @Override
                public void onClose(Object socket, int code, String reason, boolean remote) {
                    if (!isCurrentWebSocket(socket, generation)) {
                        return;
                    }
                    synchronized (connectionCleanupLock) {
                        ConnectionRetirement retirement = retireConnectionGeneration(generation, "websocket_closed");
                        if (!retirement.retired()) {
                            return;
                        }
                        submitConnectionCleanup(retirement.source(), () -> {
                        authenticated.set(false);
                        clearCatalogPublication("CATALOG_PUBLICATION_DISCONNECTED");
                        disconnectCollaboration("Disconnected", generation);
                        notifyPluginChannelsUnavailable();
                        playerTrackingSubscribed = false;
                        playerControlCapabilities = null;
                         failPendingConnectionRequests("ReSync Disconnected", true);
                         notifyFlowManagerDisconnected();
                        failPlayerControlRequests("ReSync Disconnected");
                        cancelConnectTimeout(generation);
                        nodeRegistrySynced = false;
                        cancelNodeRegistryTimeout();
                        OptionCatalogCache.getInstance().clearRequestsInFlight(serverId);
                        OptionCatalogCache.getInstance().markServerStale(serverId);
                        stopHeartbeat();
                        logger().operation("Connect").with("code", code).with("reason", reason).with("remote", remote).warn("ReSync WebSocket closed");
                        scheduleReconnect(generation + 1);
                        connecting.set(false);
                        runLifecycleListener("disconnect listener", disconnectListener);
                        });
                    }
                }

                @Override
                public void onError(Object socket, Exception ex) {
                    if (!isCurrentWebSocket(socket, generation)) {
                        return;
                    }
                    synchronized (connectionCleanupLock) {
                        ConnectionRetirement retirement = retireConnectionGeneration(generation, "websocket_error");
                        if (!retirement.retired()) {
                            return;
                        }
                        submitConnectionCleanup(retirement.source(), () -> {
                        logger().operation("Connect").error("ReSync WebSocket failed", ex);
                        authenticated.set(false);
                        clearCatalogPublication("CATALOG_PUBLICATION_CONNECTION_FAILED");
                        disconnectCollaboration("Connection Failed", generation);
                        notifyPluginChannelsUnavailable();
                        playerTrackingSubscribed = false;
                        playerControlCapabilities = null;
                         failPendingConnectionRequests("ReSync Connection Failed", true);
                         notifyFlowManagerDisconnected();
                        failPlayerControlRequests("ReSync Connection Failed");
                        cancelConnectTimeout(generation);
                        nodeRegistrySynced = false;
                        cancelNodeRegistryTimeout();
                        OptionCatalogCache.getInstance().clearRequestsInFlight(serverId);
                        OptionCatalogCache.getInstance().markServerStale(serverId);
                        stopHeartbeat();
                        if (retirement.socket() != null) {
                            ReSyncDirectSockets.connector.close(retirement.socket());
                        }
                        scheduleReconnect(generation + 1);
                        connecting.set(false);
                        runLifecycleListener("disconnect listener", disconnectListener);
                        });
                    }
                }
            });
            synchronized (outboundLock) {
                if (!isActiveGeneration(generation)) {
                    ReSyncDirectSockets.connector.close(client);
                    return;
                }
                activeTransportGeneration = generation;
                connectionSource = new ConnectionSource(generation);
                generationWebSocket = client;
                wsClient.set(client);
            }
            ReSyncDirectSockets.connector.connect(client);
        } catch (Exception e) {
            if (!isActiveGeneration(generation) || !abandonConnectionGeneration(generation)) {
                return;
            }
            logger().operation("Connect").error("Could not open ReSync WebSocket", e);
            scheduleReconnect(generation + 1);
        }
    }

    private void sendHandshake(int generation) {
        observeHandshakeStage(generation, HandshakeStage.HANDSHAKE_SENDING, "handshake_frame");
        String clientId = stableClientId;
        logger().operation("Handshake").with("clientId", clientId).debug("ReSync client identified");
        byte[] apiKeyBytes = apiKey.getBytes(StandardCharsets.UTF_8);
        byte[] clientIdBytes = clientId.getBytes(StandardCharsets.UTF_8);
        byte[] clientVersionBytes = CLIENT_VERSION.getBytes(StandardCharsets.UTF_8);
        byte[] capabilitiesBytes = clientCapabilitiesJson().getBytes(StandardCharsets.UTF_8);
        byte[] collaborationProfileBytes = collaborationProfile().getBytes(StandardCharsets.UTF_8);

        ByteBuffer buffer = ByteBuffer.allocate(
                4 + apiKeyBytes.length +
                        4 + clientIdBytes.length +
                        4 +
                        4 + clientVersionBytes.length +
                        4 + capabilitiesBytes.length +
                        4 + collaborationProfileBytes.length
        );

        buffer.putInt(apiKeyBytes.length);
        buffer.put(apiKeyBytes);

        buffer.putInt(clientIdBytes.length);
        buffer.put(clientIdBytes);

        buffer.putInt(PROTOCOL_VERSION);
        buffer.putInt(clientVersionBytes.length);
        buffer.put(clientVersionBytes);
        buffer.putInt(capabilitiesBytes.length);
        buffer.put(capabilitiesBytes);
        buffer.putInt(collaborationProfileBytes.length);
        buffer.put(collaborationProfileBytes);

        if (sendFrame(0, buffer.array(), (short) 0, false, generation)) {
            observeHandshakeStage(generation, HandshakeStage.HANDSHAKE_SENT, "waiting_for_response");
        } else {
            observeHandshakeFailure(generation, HandshakeStage.FAILED, "handshake_send_rejected");
        }
    }

    private List<String> clientCapabilities() {
        List<String> capabilities = new ArrayList<>(FLOW_CONTRACT.clientCapabilities());
        if (!capabilities.contains(CATALOG_AUTHORING_CAPABILITY)) {
            capabilities.add(CATALOG_AUTHORING_CAPABILITY);
        }
        return List.copyOf(capabilities);
    }

    private String clientCapabilitiesJson() {
        JsonArray json = new JsonArray();
        clientCapabilities().forEach(json::add);
        return json.toString();
    }

    private String collaborationProfile() {
        CollaborationService.Identity identity = collaborationIdentity();
        collaboration.identify(identity);
        JsonObject json = new JsonObject();
        json.addProperty("subjectId", identity.subjectId());
        json.addProperty("displayName", identity.displayName());
        json.addProperty("avatar", identity.avatar());
        json.addProperty("source", identity.source());
        return json.toString();
    }

    private CollaborationService.Identity collaborationIdentity() {
        if (identityProvider != null) {
            return Objects.requireNonNull(identityProvider.collaborationIdentity(stableClientId),
                "ReSync collaboration identity is required");
        }
        String resolvedSubject = stableClientId == null || stableClientId.isBlank() ? "remotely" : stableClientId.trim();
        if (resolvedSubject.length() > 128) {
            resolvedSubject = resolvedSubject.substring(0, 128);
        }
        resolvedSubject = resolvedSubject.replaceAll("[^A-Za-z0-9._-]", "_");
        return new CollaborationService.Identity(resolvedSubject, "Collaborator", "", "restudio");
    }

    private void subscribeStartupChannels(int generation) {
        observeHandshakeStage(generation, HandshakeStage.FLOW_SUBSCRIPTION_SENDING, "flow");
        if (!sendStartupSubscribe("flow", "", generation)) {
            observeHandshakeFailure(generation, HandshakeStage.FAILED, "flow_subscription_rejected");
            return;
        }
        observeHandshakeStage(generation, HandshakeStage.FLOW_SUBSCRIBED, "flow");
        observeHandshakeStage(generation, HandshakeStage.WORLD_MANAGEMENT_SUBSCRIPTION_SENDING, "world_management");
        if (!sendStartupSubscribe("world_management", "", generation)) {
            observeHandshakeFailure(generation, HandshakeStage.FAILED, "world_management_subscription_rejected");
            return;
        }
        observeHandshakeStage(generation, HandshakeStage.WORLD_MANAGEMENT_SUBSCRIBED, "world_management");
        observeHandshakeStage(generation, HandshakeStage.WORLDGEN_SUBSCRIPTION_SENDING, "worldgen");
        if (!sendStartupSubscribe("worldgen", "", generation)) {
            observeHandshakeFailure(generation, HandshakeStage.FAILED, "worldgen_subscription_rejected");
            return;
        }
        observeHandshakeStage(generation, HandshakeStage.WORLDGEN_SUBSCRIBED, "worldgen");
        observeHandshakeStage(generation, HandshakeStage.PLAYER_TRACKING_SUBSCRIPTION_SENDING, "player_tracking");
        if (!sendStartupSubscribe("player_tracking", "{\"mode\":\"scoped\"}", generation)) {
            observeHandshakeFailure(generation, HandshakeStage.FAILED, "player_tracking_subscription_rejected");
            return;
        }
        observeHandshakeStage(generation, HandshakeStage.PLAYER_TRACKING_SUBSCRIBED, "player_tracking");
        playerTrackingSubscribed = true;
        for (UUID playerId : watchedPlayers) sendPlayerTrackingAction("watch", playerId);
        observeHandshakeStage(generation, HandshakeStage.STARTUP_SUBSCRIPTIONS_SENT, "startup_subscriptions_sent");
    }

    private Async<Void> connectFrameTransport() {
        if (shutdownRequested) {
            return Async.completed(null);
        }
        if (frameTransport == null) {
            notifyError("ReSyncUnavailable");
            return Async.completed(null);
        }
        Async<Void> cleanup = connectionCleanupCompletion;
        if (!Boolean.TRUE.equals(inConnectionEvent.get()) && !cleanup.isDone()) {
            return deferFrameTransportConnect(cleanup);
        }
        if (!isRetryableConnectionFailure() && terminalFrameDisconnectPublished.get() && !frameTransport.reusableAfterDisconnect()) {
            return Async.completed(null);
        }
        if (!frameTransport.isOpen()) {
            ReSyncFrameTransport.State state = frameTransport.state();
            if (state == ReSyncFrameTransport.State.CONNECTING) {
                return Async.completed(null);
            }
            if (!frameTransport.reconnectable() && state != ReSyncFrameTransport.State.NEW) {
                connectionFailure.set(ConnectionFailure.ENDPOINT_UNREACHABLE);
                notifyConnectionError("ReSync Endpoint Unreachable");
                return Async.completed(null);
            }
            frameTransport.setOpenHandler(() -> submitConnectionEvent(this::connectFrameTransport));
            frameTransport.setCloseReasonHandler(this::observeFrameTransportCloseReason);
            frameTransport.setCloseHandler(this::handleFrameTransportOpeningFailure);
            frameTransport.setErrorHandler(error -> handleFrameTransportOpeningFailure());
            frameOpeningFailureHandled.set(false);
            try {
                frameTransport.connect();
            } catch (RuntimeException error) {
                handleFrameTransportOpeningFailure();
            }
            return Async.completed(null);
        }
        return startFrameTransportConnection();
    }

    private void handleFrameTransportOpeningFailure() {
        if (shutdownRequested || frameTransport == null || frameTransport.isOpen()) {
            return;
        }
        if (!frameOpeningFailureHandled.compareAndSet(false, true)) {
            return;
        }
        connectionFailure.compareAndSet(ConnectionFailure.NONE, ConnectionFailure.ENDPOINT_UNREACHABLE);
        connecting.set(false);
        if (!beginFrameRecovery(currentConnectionGeneration())) {
            publishTerminalFrameDisconnect(frameConnectionFailureMessage(), true);
        }
    }

    private boolean beginFrameRecovery(int generation) {
        if (shutdownRequested || frameTransport == null || !frameTransport.reconnectable()
            || !isRetryableConnectionFailure()) {
            return false;
        }
        int failures = consecutiveReconnectFailures.updateAndGet(count -> Math.min(count + 1, 11));
        scheduleReconnect(generation, reconnectDelay(failures));
        return isReconnectPending();
    }

    private boolean isRetryableConnectionFailure() {
        ConnectionFailure failure = connectionFailure();
        return failure == ConnectionFailure.NONE || failure == ConnectionFailure.ENDPOINT_UNREACHABLE
            || failure == ConnectionFailure.HANDSHAKE_REJECTED;
    }

    private Duration reconnectDelay(int failures) {
        return switch (failures) {
            case 1 -> Duration.ofMillis(250L);
            case 2 -> Duration.ofSeconds(1L);
            case 3 -> Duration.ofSeconds(3L);
            case 4, 5, 6 -> Duration.ofSeconds(5L);
            case 7, 8, 9, 10 -> Duration.ofSeconds(10L);
            default -> Duration.ofSeconds(30L);
        };
    }

    private String frameConnectionFailureMessage() {
        return switch (connectionFailure()) {
            case ACCESS_DENIED -> "ReSync Access Denied";
            case PROTOCOL_MISMATCH -> "ReSync Protocol Mismatch. Update ReSync And Remotely";
            case RUNTIME_VERSION_MISMATCH -> "ReSync Runtime Version Mismatch. Update ReSync And Remotely";
            case HANDSHAKE_REJECTED -> "ReSync Connection Rejected";
            default -> "ReSync Endpoint Unreachable";
        };
    }

    private void publishTerminalFrameDisconnect(String message, boolean showError) {
        if (!terminalFrameDisconnectPublished.compareAndSet(false, true)) {
            return;
        }
        notifyFlowManagerDisconnected();
        runLifecycleListener("disconnect listener", disconnectListener);
        if (showError) {
            notifyConnectionError(message);
        }
    }

    private void observeFrameTransportCloseReason(String reason) {
        String text = reason == null ? "" : reason;
        if (text.contains("Ticket Expired") || text.contains("Access Denied") || text.contains("Unauthorized")
            || text.contains("Invalid API key") || text.contains("Invalid client id") || text.contains("No Permission")) {
            connectionFailure.set(ConnectionFailure.ACCESS_DENIED);
        } else if (text.contains("Protocol") || text.contains("Invalid ReSync Frame")
            || text.contains("Binary Protocol Required")) {
            connectionFailure.set(ConnectionFailure.PROTOCOL_MISMATCH);
        } else if (text.contains("Version")) {
            connectionFailure.set(ConnectionFailure.RUNTIME_VERSION_MISMATCH);
        } else if (text.contains("Upstream") || text.contains("Unavailable") || text.contains("Send Failed")) {
            connectionFailure.set(ConnectionFailure.ENDPOINT_UNREACHABLE);
        }
    }

    private Async<Void> deferFrameTransportConnect(Async<Void> cleanup) {
        while (true) {
            Async<Void> deferred;
            synchronized (outboundLock) {
                if (shutdownRequested) {
                    return Async.completed(null);
                }
                Async<Void> existing = deferredFrameConnect.get();
                if (existing != null && !existing.isDone()) {
                    return existing;
                }
                deferred = Async.pending();
                if (!deferredFrameConnect.compareAndSet(existing, deferred)) {
                    continue;
                }
            }
            scheduleFrameTransportConnect(cleanup, deferred);
            return deferred;
        }
    }

    private void scheduleFrameTransportConnect(Async<Void> cleanup, Async<Void> deferred) {
        cleanup.whenComplete((ignored, failure) -> {
            if (!submitConnectionEvent(() -> resumeFrameTransportConnect(deferred))) {
                deferredFrameConnect.compareAndSet(deferred, null);
                deferred.complete(null);
            }
        });
    }

    private void resumeFrameTransportConnect(Async<Void> deferred) {
        if (deferredFrameConnect.get() != deferred || deferred.isDone()) {
            return;
        }
        if (shutdownRequested) {
            deferredFrameConnect.compareAndSet(deferred, null);
            deferred.complete(null);
            return;
        }
        Async<Void> cleanup = connectionCleanupCompletion;
        if (!cleanup.isDone()) {
            scheduleFrameTransportConnect(cleanup, deferred);
            return;
        }
        Async<Void> started;
        try {
            started = connectFrameTransport();
        } catch (RuntimeException | Error error) {
            deferredFrameConnect.compareAndSet(deferred, null);
            deferred.fail(error);
            throw error;
        }
        started.whenComplete((ignored, failure) -> {
            deferredFrameConnect.compareAndSet(deferred, null);
            if (failure == null) {
                deferred.complete(null);
            } else {
                deferred.fail(failure);
            }
        });
    }

    private Async<Void> startFrameTransportConnection() {
        if (frameTransport == null || !frameTransport.isOpen()) {
            return Async.completed(null);
        }
        int generation;
        synchronized (outboundLock) {
            if (shutdownRequested || isConnected()) {
                return Async.completed(null);
            }
            if (frameTransport == null || !frameTransport.isOpen()) {
                return Async.completed(null);
            }
            if (!connecting.compareAndSet(false, true)) {
                return Async.completed(null);
            }
            generation = connectionGeneration.incrementAndGet();
            pendingHandshakeGeneration.set(generation);
            lastRetirementDiagnostic = "none";
            lastTransportFailureDiagnostic = "none";
            activeTransportGeneration = generation;
            connectionSource = new ConnectionSource(generation);
            resetHandshakeAuthorityEpoch();
        }
        observeHandshakeStage(generation, HandshakeStage.CONNECTING, "frame_transport_connecting");
        resetResourceListProjection(generation);
        clearCatalogPublication("CATALOG_PUBLICATION_RECONNECTING");
        scheduleCatalogCacheHydration(generation);
        refreshCatalogAuthority();
        nodeRegistrySynced = false;
        lastFullNodeRegistryRequestAt = 0L;
        scheduleConnectTimeout(generation);
        frameTransport.setFrameAdmissionHandler(data -> data != null && admitBinaryMessage(ByteBuffer.wrap(data), generation));
        frameTransport.setOpenHandler(() -> {});
        frameTransport.setSendReadyHandler(() -> resumePendingSends(generation));
        frameTransport.setCloseReasonHandler(reason -> {
            synchronized (connectionCleanupLock) {
                if (isActiveGeneration(generation)) observeFrameTransportCloseReason(reason);
            }
        });
        frameTransport.setErrorHandler(error -> failConnectionAttempt(isRetryableConnectionFailure()
            ? "ReSync Endpoint Unreachable" : frameConnectionFailureMessage(), generation));
        frameTransport.setCloseHandler(() -> {
            synchronized (connectionCleanupLock) {
                ConnectionRetirement retirement = retireConnectionGeneration(generation, "frame_transport_closed");
                if (!retirement.retired()) {
                    return;
                }
                connectionFailure.compareAndSet(ConnectionFailure.NONE, ConnectionFailure.ENDPOINT_UNREACHABLE);
                boolean recovering = beginFrameRecovery(generation + 1);
                submitConnectionCleanup(retirement.source(), () -> {
                authenticated.set(false);
                clearCatalogPublication("CATALOG_PUBLICATION_DISCONNECTED");
                disconnectCollaboration("Disconnected", generation);
                notifyPluginChannelsUnavailable();
                playerTrackingSubscribed = false;
                playerControlCapabilities = null;
                 failPendingConnectionRequests("ReSync Disconnected", true);
                failPlayerControlRequests("ReSync Disconnected");
                cancelConnectTimeout(generation);
                nodeRegistrySynced = false;
                cancelNodeRegistryTimeout();
                OptionCatalogCache.getInstance().clearRequestsInFlight(serverId);
                OptionCatalogCache.getInstance().markServerStale(serverId);
                stopHeartbeat();
                connecting.set(false);
                if (!recovering) {
                    publishTerminalFrameDisconnect(frameConnectionFailureMessage(), frameTransport.reconnectable());
                }
                });
            }
        });
        this.apiKey = directApiKey == null ? "bridge" : directApiKey;
        sendHandshake(generation);
        return Async.completed(null);
    }

    private boolean sendSubscribe(String channelId) {
        return sendSubscribe(channelId, "");
    }

    private boolean sendSubscribe(String channelId, String data) {
        byte[] channelBytes = channelId.getBytes(StandardCharsets.UTF_8);
        byte[] dataBytes = data == null ? new byte[0] : data.getBytes(StandardCharsets.UTF_8);
        ByteBuffer buffer = ByteBuffer.allocate(4 + channelBytes.length + 4 + dataBytes.length);
        buffer.putInt(channelBytes.length);
        buffer.put(channelBytes);
        buffer.putInt(dataBytes.length);
        buffer.put(dataBytes);
        return sendFrame(ReSyncProtocolContract.MESSAGE_SUBSCRIBE, buffer.array(), CONTROL_CHANNEL_ID);
    }

    private boolean sendStartupSubscribe(String channelId, String data, int generation) {
        byte[] channelBytes = channelId.getBytes(StandardCharsets.UTF_8);
        byte[] dataBytes = data == null ? new byte[0] : data.getBytes(StandardCharsets.UTF_8);
        ByteBuffer buffer = ByteBuffer.allocate(4 + channelBytes.length + 4 + dataBytes.length);
        buffer.putInt(channelBytes.length);
        buffer.put(channelBytes);
        buffer.putInt(dataBytes.length);
        buffer.put(dataBytes);
        return sendFrame(ReSyncProtocolContract.MESSAGE_SUBSCRIBE, buffer.array(), CONTROL_CHANNEL_ID, true, generation, true);
    }

    private boolean sendFrame(int messageType, byte[] payload, short channel) {
        return sendFrame(messageType, payload, channel, true, -1);
    }

    private boolean sendFrame(int messageType, byte[] payload, short channel, boolean retainWhenOrdered) {
        return sendFrame(messageType, payload, channel, retainWhenOrdered, -1);
    }

    private boolean sendFrame(int messageType, byte[] payload, short channel, boolean retainWhenOrdered,
                              int expectedGeneration) {
        return sendFrame(messageType, payload, channel, retainWhenOrdered, expectedGeneration, false);
    }

    private boolean sendFrame(int messageType, byte[] payload, short channel, boolean retainWhenOrdered,
                              int expectedGeneration, boolean startupSubscription) {
        return sendFrame(messageType, payload, channel, retainWhenOrdered, expectedGeneration, startupSubscription, null);
    }

    private boolean sendFrame(int messageType, byte[] payload, short channel, boolean retainWhenOrdered,
                              int expectedGeneration, boolean startupSubscription,
                              Consumer<ReSyncFrameTransport.SendResult> resultHandler) {
        if (shutdownRequested) {
            return failPendingSend();
        }
        byte[] outboundPayload = payload == null ? new byte[0] : payload;
        synchronized (outboundLock) {
            if (shutdownRequested) {
                return failPendingSend();
            }
            int generation = connectionGeneration.get();
            if (activeTransportGeneration != generation
                || (expectedGeneration >= 0 && generation != expectedGeneration)) {
                return failPendingSend();
            }
            if (startupSubscription && (messageType != ReSyncProtocolContract.MESSAGE_SUBSCRIBE
                || expectedGeneration < 0 || startupSubscriptionGeneration != expectedGeneration)) {
                return failPendingSend();
            }
            boolean startupOrdering = startupSubscriptionGeneration == generation;
            if (messageType != 0 && pendingSendThread != TaskIdentities.access.current()
                && ((startupOrdering && !startupSubscription) || !pendingSends.isEmpty())) {
                if (retainWhenOrdered) {
                    if (!enqueueOrderedFrame(messageType, outboundPayload, channel, expectedGeneration, generation, resultHandler)) {
                        if (outboundPriority(messageType, outboundPayload, channel) != PendingSendPriority.REPLACEABLE) {
                            scheduleTransportFailure(generation, "ordered_send_admission");
                        }
                        return failPendingSend();
                    }
                    if (!startupOrdering) {
                        schedulePendingFlush();
                    }
                    return true;
                }
                return false;
            }
            if (outboundGeneration != generation) {
                outboundGeneration = generation;
                sequenceCounter = 0;
            }
            try {
                byte[] frame = frameCodec.encode(messageType, outboundPayload, channel, sequenceCounter);
                if (frameTransport != null) {
                    if (!frameTransport.isOpen()) {
                        scheduleTransportFailure(generation, "frame_transport_closed");
                        return failPendingSend();
                    }
                    ReSyncFrameTransport.SendAdmission admission = frameTransport.admitSend(frame, resultHandler);
                    if (admission == ReSyncFrameTransport.SendAdmission.QUEUE_FULL) {
                        if (retainWhenOrdered && messageType != 0 && pendingSendThread != TaskIdentities.access.current()) {
                            if (!enqueueOrderedFrame(messageType, outboundPayload, channel, expectedGeneration, generation,
                                resultHandler)) {
                                if (outboundPriority(messageType, outboundPayload, channel) != PendingSendPriority.REPLACEABLE) {
                                    scheduleTransportFailure(generation, "ordered_send_admission");
                                }
                                return failPendingSend();
                            }
                            if (!startupOrdering) schedulePendingFlush();
                            return true;
                        }
                        return failPendingSend();
                    }
                    if (admission != ReSyncFrameTransport.SendAdmission.ACCEPTED) {
                        scheduleTransportFailure(generation, "frame_transport_rejected");
                        return failPendingSend();
                    }
                    sequenceCounter++;
                    if (pendingSendThread == TaskIdentities.access.current()) {
                        pendingSendCommitted = true;
                    }
                    return true;
                }
                Object client = generationWebSocket;
                if (client == null || wsClient.get() != client || !ReSyncDirectSockets.connector.isOpen(client)) {
                    scheduleTransportFailure(generation, "websocket_unavailable");
                    return failPendingSend();
                }
                long enqueuedAtNanos = System.nanoTime();
                ReSyncDirectSockets.connector.send(client, frame);
                sequenceCounter++;
                if (pendingSendThread == TaskIdentities.access.current()) {
                    pendingSendCommitted = true;
                }
                if (resultHandler != null) {
                    resultHandler.accept(ReSyncFrameTransport.SendReceipt.immediate(enqueuedAtNanos, frame.length));
                }
                return true;
            } catch (RuntimeException exception) {
                logger().operation("Send Frame").with("reason", exception.getMessage()).warn("ReSync frame send failed");
                scheduleTransportFailure(generation, "send_exception");
                return failPendingSend();
            }
        }
    }

    private void scheduleTransportFailure(int generation) {
        scheduleTransportFailure(generation, "unspecified");
    }

    private void scheduleTransportFailure(int generation, String diagnostic) {
        if (shutdownRequested) return;
        lastTransportFailureDiagnostic = diagnostic == null || diagnostic.isBlank() ? "unspecified" : diagnostic;
        transportFailureGeneration.accumulateAndGet(generation, Math::max);
        if (!transportFailureScheduled.compareAndSet(false, true)) return;
        try {
            heartbeatScheduler.execute(this::drainTransportFailure);
        } catch (RuntimeException ignored) {
            transportFailureScheduled.set(false);
        }
    }

    private void drainTransportFailure() {
        try {
            int generation = transportFailureGeneration.getAndSet(-1);
            if (!shutdownRequested && generation >= 0) {
                failConnectionAttempt("ReSync Connection Failed", generation);
            }
        } finally {
            transportFailureScheduled.set(false);
            if (!shutdownRequested && transportFailureGeneration.get() >= 0) {
                scheduleTransportFailure(transportFailureGeneration.get());
            }
        }
    }

    private void resumePendingSends(int generation) {
        synchronized (outboundLock) {
            if (!isConnectionReadyGeneration(generation) || pendingSends.isEmpty()) return;
            schedulePendingFlush();
        }
    }

    private void schedulePendingFlush() {
        synchronized (outboundLock) {
            if (shutdownRequested) return;
            pendingFlushRequested = true;
            if (!pendingFlushScheduled.compareAndSet(false, true)) return;
        }
        try {
            heartbeatScheduler.execute(() -> {
                boolean retryBlocked = false;
                try {
                    retryBlocked = flushPendingSends();
                } finally {
                    boolean reschedule;
                    synchronized (outboundLock) {
                        pendingFlushScheduled.set(false);
                        reschedule = (!retryBlocked || pendingFlushRequested) && !shutdownRequested && isConnected()
                            && startupSubscriptionGeneration < 0 && !drainingPendingSends && !pendingSends.isEmpty();
                        if (!drainingPendingSends) pendingFlushRequested = false;
                    }
                    if (reschedule) {
                        schedulePendingFlush();
                    }
                }
            });
        } catch (RuntimeException ignored) {
            synchronized (outboundLock) {
                pendingFlushScheduled.set(false);
                pendingFlushRequested = false;
            }
        }
    }

    private boolean submitConnectionEvent(Runnable event) {
        return submitConnectionEvent(null, event, BoundedTransportExecutor.Priority.STANDARD, CALLBACK_RETAINED_BYTES,
            null, false);
    }

    private boolean submitConnectionEvent(ConnectionSource source, Runnable event) {
        return submitConnectionEvent(source, event, BoundedTransportExecutor.Priority.CRITICAL,
            CALLBACK_RETAINED_BYTES, null, false);
    }

    private boolean submitConnectionEvent(ConnectionSource source, Runnable event,
                                          BoundedTransportExecutor.Priority priority, long retainedBytes,
                                          String coalesceKey, boolean terminal) {
        if (event == null) {
            return false;
        }
        int expectedGeneration = source != null && !terminal ? source.generation() : -1;
        try {
            return connectionEvents.offer(expectedGeneration, retainedBytes, priority, coalesceKey, () -> {
                boolean leased = source != null && !terminal;
                if (leased && !source.acquire()) {
                    return;
                }
                inConnectionEvent.set(true);
                ConnectionSource previous = inboundSource.get();
                if (source != null) {
                    inboundSource.set(source);
                }
                try {
                    event.run();
                } catch (RuntimeException exception) {
                    logger().operation("Connection Event").with("reason", exception.getMessage())
                        .warn("ReSync connection event failed", exception);
                } finally {
                    if (previous == null) {
                        inboundSource.remove();
                    } else {
                        inboundSource.set(previous);
                    }
                    inConnectionEvent.remove();
                    if (leased) {
                        source.release();
                    }
                }
            });
        } catch (RuntimeException ignored) {
            return false;
        }
    }

    private void submitConnectionCleanup(ConnectionSource source, Runnable cleanup) {
        Async<Void> completion = Async.pending();
        connectionCleanupCompletion = completion;
        Runnable task = () -> {
            terminalConnectionCallback.set(true);
            try {
                if (source != null) source.awaitLeases();
                failPendingTriggerUpdates("ReSync Connection Changed");
                clearCatalogPublication("CATALOG_PUBLICATION_GENERATION_RETIRED");
                cleanup.run();
                completion.complete(null);
            } catch (RuntimeException | Error error) {
                completion.fail(error);
                throw error;
            } finally {
                terminalConnectionCallback.remove();
            }
        };
        if (!submitConnectionEvent(source, task, BoundedTransportExecutor.Priority.TERMINAL,
            CALLBACK_RETAINED_BYTES, null, true)) {
            connecting.set(false);
            completion.fail(new IllegalStateException("ReSync connection cleanup queue is full"));
        }
    }

    private boolean submitCurrentConnectionCallback(Runnable callback) {
        boolean terminal = Boolean.TRUE.equals(terminalConnectionCallback.get());
        return submitConnectionCallback(inboundSource.get(), callback, terminal, false, terminal ? callback : null);
    }

    private boolean submitConnectionCallback(ConnectionSource source, Runnable callback) {
        return submitConnectionCallback(source, callback, false);
    }

    private boolean submitConnectionCallback(ConnectionSource source, Runnable callback, boolean terminal) {
        return submitConnectionCallback(source, callback, terminal, false);
    }

    private boolean submitConnectionCallback(ConnectionSource source, Runnable callback, boolean terminal,
                                              boolean shutdownSettlement) {
        return submitConnectionCallback(source, callback, terminal, shutdownSettlement, null);
    }

    private boolean submitConnectionCallback(ConnectionSource source, Runnable callback, boolean terminal,
                                              boolean shutdownSettlement, Runnable rejected) {
        if (callback == null || shutdownRequested && !terminal) {
            return false;
        }
        ConnectionSource callbackSource = source;
        if (callbackSource == null && !terminal && !shutdownSettlement) {
            callbackSource = connectionSource(currentConnectionGeneration());
        }
        ConnectionSource capturedSource = callbackSource;
        Runnable delivery = () -> {
            boolean leased = capturedSource != null && !terminal && !shutdownSettlement;
            if (leased && !capturedSource.acquire()) {
                return;
            }
            try {
                if (shutdownFinalized && !shutdownSettlement
                    || !terminal && (shutdownRequested
                        || capturedSource != null && !capturedSource.acceptsCallbacks())) {
                    return;
                }
                try {
                    callback.run();
                } catch (RuntimeException | Error exception) {
                    logger().operation("Connection Callback").with("reason", exception.getMessage()).warn("ReSync connection callback failed");
                }
            } finally {
                if (leased) {
                    capturedSource.release();
                }
            }
        };
        if (shutdownSettlement && Boolean.TRUE.equals(inConnectionCallback.get())) {
            delivery.run();
            return true;
        }
        int expectedGeneration = terminal || shutdownSettlement ? -1
            : capturedSource != null ? capturedSource.generation() : currentConnectionGeneration();
        BoundedTransportExecutor.Priority priority = terminal || shutdownSettlement
            ? BoundedTransportExecutor.Priority.TERMINAL : BoundedTransportExecutor.Priority.STANDARD;
        int retainedBytes = Math.max(CALLBACK_RETAINED_BYTES,
            inboundFrameBytes.get() != null ? inboundFrameBytes.get() : CALLBACK_RETAINED_BYTES);
        try {
            boolean admitted = connectionCallbacks.offer(expectedGeneration, retainedBytes, priority, null,
                connectionCallbackTask(delivery));
            if (!admitted && terminal && rejected != null && !connectionCallbacks.isShutdown()) {
                admitted = connectionCallbacks.offer(-1, CALLBACK_RETAINED_BYTES,
                    BoundedTransportExecutor.Priority.TERMINAL, null, connectionCallbackTask(rejected));
            }
            if (!admitted) {
                logger().operation("Connection Callback").warn("ReSync connection callback queue rejected delivery");
                if (!shutdownRequested && capturedSource != null) {
                    scheduleTransportFailure(capturedSource.generation(), "callback_admission");
                }
            }
            return admitted;
        } catch (RuntimeException | Error exception) {
            logger().operation("Connection Callback").with("reason", exception.getMessage()).warn("ReSync connection callback queue failed");
            if (!shutdownRequested && capturedSource != null) {
                scheduleTransportFailure(capturedSource.generation(), "callback_exception");
            }
            return false;
        }
    }

    private Runnable connectionCallbackTask(Runnable callback) {
        return () -> {
            inConnectionCallback.set(true);
            try {
                callback.run();
            } catch (RuntimeException | Error exception) {
                logger().operation("Connection Callback").with("reason", exception.getMessage()).warn("ReSync connection callback failed");
            } finally {
                inConnectionCallback.remove();
            }
        };
    }

    private Async<Void> submitConnectionDrain() {
        Async<Void> drained = Async.pending();
        if (onConnectionLifecycleThread() || !submitConnectionEvent(() -> drained.complete(null))) {
            drained.complete(null);
        }
        return drained;
    }

    private Async<Void> submitConnectionCallbackDrain() {
        Async<Void> drained = Async.pending();
        if (Boolean.TRUE.equals(inConnectionCallback.get())) {
            drained.complete(null);
            return drained;
        }
        try {
            if (!connectionCallbacks.offer(-1, CALLBACK_RETAINED_BYTES,
                BoundedTransportExecutor.Priority.TERMINAL, null, () -> {
                inConnectionCallback.set(true);
                try {
                    drained.complete(null);
                } finally {
                    inConnectionCallback.remove();
                }
            })) {
                drained.complete(null);
            }
        } catch (RuntimeException exception) {
            drained.complete(null);
        }
        return drained;
    }

    private void awaitConnectionDrain(Async<Void> drained) {
        if (drained == null || onConnectionLifecycleThread()) {
            return;
        }
        boolean interrupted = false;
        while (!drained.isDone()) {
            try {
                drained.join();
            } catch (Exception ignored) {
                break;
            }
        }
        if (interrupted) {
            TaskIdentities.access.interrupt();
        }
    }

    private void awaitConnectionCallbacks(Async<Void> drained) {
        if (Boolean.TRUE.equals(inConnectionCallback.get())) {
            return;
        }
        awaitConnectionDrain(drained);
        boolean interrupted = false;
        while (!connectionCallbacks.isTerminated()) {
            try {
                if (connectionCallbacks.awaitTermination(Long.MAX_VALUE)) {
                    break;
                }
            } catch (InterruptedException exception) {
                interrupted = true;
            }
        }
        if (interrupted) {
            TaskIdentities.access.interrupt();
        }
    }

    private boolean failPendingSend() {
        if (pendingSendThread == TaskIdentities.access.current()) {
            pendingSendFailed = true;
        }
        return false;
    }

    private static byte[] copyRemaining(ByteBuffer buffer) {
        ByteBuffer copy = buffer.slice();
        byte[] bytes = new byte[copy.remaining()];
        copy.get(bytes);
        return bytes;
    }

    private void handleBinaryMessage(byte[] data, int generation) {
        if (data != null) {
            admitBinaryMessage(ByteBuffer.wrap(data), generation);
        }
    }

    private void handleBinaryMessage(ByteBuffer data, int generation) {
        if (data != null) {
            admitBinaryMessage(data.slice(), generation);
        }
    }

    private boolean admitBinaryMessage(ByteBuffer data, int generation) {
        ConnectionSource source = connectionSource(generation);
        if (source == null) {
            return false;
        }
        ByteBuffer frame = data.slice();
        int retainedBytes = frame.remaining();
        InboundAdmission admission = inboundAdmission(frame, generation);
        BoundedTransportExecutor.Priority priority = admission.priority() == BoundedTransportExecutor.Priority.CRITICAL
            ? BoundedTransportExecutor.Priority.LOSSLESS : admission.priority();
        boolean admitted = connectionEvents.offer(generation, Math.max(1, retainedBytes), priority,
            admission.coalesceKey(), () -> {
                byte[] retained = new byte[retainedBytes];
                frame.get(retained);
                return () -> {
                    inConnectionEvent.set(true);
                    try {
                        processAdmittedBinaryMessage(retained, generation, source);
                    } finally {
                        inConnectionEvent.remove();
                    }
                };
            });
        if (!admitted && priority != BoundedTransportExecutor.Priority.REPLACEABLE) {
            scheduleTransportFailure(generation, "inbound_admission");
        }
        return admitted;
    }

    private void processAdmittedBinaryMessage(byte[] data, int generation, ConnectionSource source) {
        if (source.generation() != generation || connectionSource(generation) != source || !source.acquire()) {
            return;
        }
        processBinaryMessage(data, generation, source);
    }

    private InboundAdmission inboundAdmission(ByteBuffer frame, int generation) {
        if (frame.remaining() < 12) {
            return InboundAdmission.critical();
        }
        int start = frame.position();
        boolean compressed = (frame.get(start) & 0x80) != 0;
        byte messageType = frame.get(start + 1);
        short channel = frame.getShort(start + 2);
        if (messageType == ReSyncProtocolContract.MESSAGE_HEARTBEAT) {
            return InboundAdmission.replaceable("heartbeat:" + generation);
        }
        if (compressed || messageType != ReSyncProtocolContract.MESSAGE_DATA
            || channel != numericChannel("flow", FLOW_CHANNEL_ID) || frame.remaining() <= 12) {
            return InboundAdmission.critical();
        }
        byte packet = frame.get(start + 12);
        if (packet == ReSyncProtocolContract.FLOW_PACKET_PRESENCE_SNAPSHOT) {
            return InboundAdmission.replaceable("presence:" + generation);
        }
        if (packet == ReSyncProtocolContract.FLOW_PACKET_TRACE_SNAPSHOT) {
            return replaceableInboundAdmission("trace:" + generation + ':', inboundResourceKey(frame, start + 13));
        }
        if (packet == ReSyncProtocolContract.FLOW_PACKET_WORKSPACE_SNAPSHOT
            || packet == ReSyncProtocolContract.FLOW_PACKET_WORKSPACE_AWARENESS) {
            return replaceableInboundAdmission("workspace:" + generation + ':' + (packet & 0xFF) + ':',
                inboundResourceKey(frame, start + 13));
        }
        return InboundAdmission.critical();
    }

    private InboundAdmission replaceableInboundAdmission(String prefix, String resourceKey) {
        return InboundAdmission.replaceable(resourceKey == null ? null : prefix + resourceKey);
    }

    private String inboundResourceKey(ByteBuffer frame, int payloadStart) {
        if (payloadStart >= frame.limit()) {
            return null;
        }
        String type = probeJsonString(frame, payloadStart, "type");
        if (type == null) {
            type = probeJsonString(frame, payloadStart, "resourceType");
        }
        String id = probeJsonString(frame, payloadStart, "resourceId");
        if (id == null) {
            id = probeJsonString(frame, payloadStart, "id");
        }
        if (id == null) {
            id = probeJsonString(frame, payloadStart, "viewId");
        }
        if (id == null) {
            return null;
        }
        String author = probeJsonString(frame, payloadStart, "authorSessionId");
        return (type == null ? "" : type) + ':' + id + (author == null ? "" : ':' + author);
    }

    private String probeJsonString(ByteBuffer frame, int payloadStart, String field) {
        byte[] name = ('"' + field + '"').getBytes(StandardCharsets.UTF_8);
        int limit = Math.min(frame.limit(), payloadStart + INBOUND_COALESCE_PROBE_BYTES);
        int depth = 0;
        boolean string = false;
        boolean escaped = false;
        for (int index = payloadStart; index < limit; index++) {
            byte current = frame.get(index);
            if (string) {
                if (escaped) {
                    escaped = false;
                } else if (current == '\\') {
                    escaped = true;
                } else if (current == '"') {
                    string = false;
                }
                continue;
            }
            if (current == '{' || current == '[') {
                depth++;
                continue;
            }
            if (current == '}' || current == ']') {
                depth--;
                if (depth < 0) {
                    return null;
                }
                continue;
            }
            if (current != '"') {
                continue;
            }
            if (depth != 1 || index > limit - name.length) {
                string = true;
                continue;
            }
            int matched = 0;
            while (matched < name.length && frame.get(index + matched) == name[matched]) {
                matched++;
            }
            if (matched != name.length) {
                string = true;
                continue;
            }
            int cursor = index + name.length;
            while (cursor < limit && Character.isWhitespace(frame.get(cursor) & 0xFF)) {
                cursor++;
            }
            if (cursor >= limit || frame.get(cursor++) != ':') {
                string = true;
                continue;
            }
            while (cursor < limit && Character.isWhitespace(frame.get(cursor) & 0xFF)) {
                cursor++;
            }
            if (cursor >= limit || frame.get(cursor++) != '"') {
                return null;
            }
            byte[] value = new byte[INBOUND_COALESCE_VALUE_BYTES];
            int length = 0;
            while (cursor < limit && length < value.length) {
                byte next = frame.get(cursor++);
                if (next == '\\') {
                    return null;
                }
                if (next == '"') {
                    return length == 0 ? null : new String(value, 0, length, StandardCharsets.UTF_8);
                }
                value[length++] = next;
            }
            return null;
        }
        return null;
    }

    private void processBinaryMessage(byte[] data, int generation, ConnectionSource source) {
        inboundGeneration.set(generation);
        inboundSource.set(source);
        inboundFrameBytes.set(data.length);
        try {
            try {
                ReSyncDecodedFrame frame = frameCodec.decode(data, validDataChannelIds);
                inboundFrameBytes.set(Math.max(data.length, frame.payload().length + 12));
                if (!source.accepts(generation) || connectionSource(generation) != source) {
                    return;
                }
                switch (frame.messageType()) {
                    case ReSyncProtocolContract.MESSAGE_HANDSHAKE_RESPONSE:
                        handleHandshakeResponse(frame.payload(), generation);
                        break;
                    case ReSyncProtocolContract.MESSAGE_DATA:
                        handleDataMessage(frame.channel(), frame.payload(), generation);
                        break;
                    case ReSyncProtocolContract.MESSAGE_HEARTBEAT:
                        break;
                    case ReSyncProtocolContract.MESSAGE_ERROR:
                        handleError(frame.payload(), generation);
                        break;
                    case MESSAGE_CHANNEL_REGISTRY:
                        if (!isConnectionReadyGeneration(generation)) {
                            return;
                        }
                        handleChannelRegistry(frame.payload());
                        break;
                    case MESSAGE_PROTOCOL_ENVELOPE:
                        if (!isConnectionReadyGeneration(generation) || frame.channel() != CONTROL_CHANNEL_ID) {
                            return;
                        }
                        handleProtocolEnvelope(frame.payload(), generation);
                        break;
                    default:
                        protocolError("Unknown message type: " + (frame.messageType() & 0xFF));
                }
            } finally {
                source.release();
            }
        } catch (IllegalArgumentException exception) {
            protocolError(exception.getMessage());
        } catch (Exception e) {
            logger().operation("Process Message").error("Could not process ReSync message", e);
            if (!authenticated.get()) {
                observeHandshakeFailure(generation, HandshakeStage.FAILED, "message_processing_exception");
                failConnectionAttempt("ReSync Handshake Failed. Retrying", generation);
            }
        } finally {
            inboundGeneration.remove();
            inboundSource.remove();
            inboundFrameBytes.remove();
        }
    }

    private void handleProtocolEnvelope(byte[] payload) {
        handleProtocolEnvelope(payload, -1);
    }

    private void handleProtocolEnvelope(byte[] payload, int generation) {
        if (!authenticated.get()) {
            return;
        }
        if (payload == null || payload.length == 0) {
            protocolError("Empty protocol envelope");
            return;
        }
        ProtocolEnvelope<Map<String, Object>> envelope;
        try {
            envelope = protocolEnvelopeCodec.decodeBytes(payload);
        } catch (RuntimeException exception) {
            protocolError("Invalid protocol envelope");
            return;
        }
        if (generation >= 0 && !isConnectionReadyGeneration(generation)) {
            return;
        }
        if (envelope.body() instanceof ProtocolBody.OptionInvalidationEvent event) {
            handleCoreOptionInvalidation(envelope, event, generation);
            return;
        }
        if (isAuthoringTemplateEnvelope(envelope)) {
            if (isRejectedProtocolEnvelope(envelope)) {
                handleRejectedAuthoringTemplateEnvelope(envelope, generation);
            } else {
                handleAuthoringTemplateEnvelope(envelope, generation);
            }
            return;
        }
        PendingCoreOptionRequest optionPending = envelope.requestId() == null ? null
            : pendingCoreOptionRequests.get(envelope.requestId());
        if (optionPending != null || isCoreOptionEnvelope(envelope)) {
            if (optionPending == null) {
                return;
            }
            if (isRejectedProtocolEnvelope(envelope)) {
                handleRejectedCoreOptionEnvelope(envelope, optionPending, generation);
            } else {
                handleCoreOptionEnvelope(envelope, optionPending, generation);
            }
            return;
        }
        if (isRejectedProtocolEnvelope(envelope)) {
            try {
                handleRejectedProtocolEnvelope(envelope);
            } catch (RuntimeException exception) {
                failCorrelatedCoreEnvelope(envelope, "The server returned a malformed rejected Core response.");
            }
            return;
        }
        if (envelope.body() instanceof ProtocolBody.ResourceCreateResponse response) {
            handleAggregateResourceCreateEnvelope(envelope, response, generation);
            return;
        }
        if (envelope.body() instanceof ProtocolBody.ResourceDocumentResponse
            && rejectPrimaryOnlyAggregateCreateEnvelope(envelope)) {
            return;
        }
        boolean coreEnvelope;
        try {
            coreEnvelope = isCoreGraphEnvelope(envelope);
        } catch (RuntimeException exception) {
            failCorrelatedCoreEnvelope(envelope, "The server returned a malformed Core graph response.");
            return;
        }
        if (coreEnvelope) {
            handleCoreGraphEnvelope(envelope, generation);
            return;
        }
        PendingCoreGraphRequest correlatedCore = pendingCoreGraphRequest(envelope);
        if (correlatedCore != null && envelope.kind() != ProtocolEnvelope.Kind.EVENT) {
            failCorePending(correlatedCore, "The server returned a malformed Core graph response.");
            return;
        }
        ReSyncProtocolEnvelopeProjection.Projection projection;
        try {
            projection = ReSyncProtocolEnvelopeProjection.project(envelope,
                ReSyncProtocolEnvelopeProjection.genericResourceCapabilities(FLOW_CONTRACT.clientCapabilities()));
        } catch (RuntimeException exception) {
            failCorrelatedCoreEnvelope(envelope, "The server returned an invalid resource response.");
            return;
        }
        boolean validKind = envelope.kind() == ProtocolEnvelope.Kind.ACK || envelope.kind() == ProtocolEnvelope.Kind.EVENT
            || envelope.kind() == ProtocolEnvelope.Kind.CONFLICT || envelope.kind() == ProtocolEnvelope.Kind.RESPONSE;
        boolean validStatus = envelope.kind() == ProtocolEnvelope.Kind.CONFLICT
            ? envelope.status() == ProtocolEnvelope.Status.CONFLICT
            : envelope.status() == ProtocolEnvelope.Status.OK || envelope.status() == ProtocolEnvelope.Status.ACCEPTED
                || envelope.status() == ProtocolEnvelope.Status.REJECTED;
        boolean activation = isResourceActivationEnvelope(envelope);
        boolean page = envelope.body() instanceof ProtocolBody.ResourcePageResponse;
        boolean conflictWithoutCurrent = envelope.kind() == ProtocolEnvelope.Kind.CONFLICT
            && envelope.body() instanceof ProtocolBody.ConflictResponse conflict && conflict.current() == null;
        if (!validKind || !validStatus || !matchesServer(envelope)
            || projection.hasUnsupportedCapabilities()
            || (!activation && !page && !projection.canApplyTypedResource() && !conflictWithoutCurrent)) {
            failCorrelatedCoreEnvelope(envelope, "The server returned an invalid Core graph response.");
            return;
        }
        if (!acceptAuthorityEpoch(envelope.authorityEpoch())) {
            failCorrelatedCoreEnvelope(envelope, "The Core graph response used an invalid authority epoch.");
            return;
        }
        if (generation >= 0 && !isConnectionReadyGeneration(generation)) {
            return;
        }
        if (page) {
            handleTypedResourcePage(envelope, (ProtocolBody.ResourcePageResponse) envelope.body(), generation);
            return;
        }
        if (activation) {
            handleResourceActivationEnvelope(projection);
            return;
        }
        ResourceDocument<Map<String, Object>> document = projection.resourceDocument();
        ServerResourceLocator resource = document != null ? document.resource()
            : envelope.body() instanceof ProtocolBody.ConflictResponse conflict ? conflict.requestedResource() : envelope.resource();
        if (resource == null) {
            return;
        }
        ReSyncResourceType type = ReSyncResourceType.byTypeId(resource.resourceType().value());
        if (!isProtocolResourceType(type) || !serverId.equals(resource.serverId().canonicalText())) {
            return;
        }
        PendingTypedResourceRequest pending = matchingPendingTypedResourceRequest(envelope, document, resource, type);
        if (envelope.kind() != ProtocolEnvelope.Kind.EVENT && pending == null) {
            return;
        }
        String saveTrackerId = pending != null && pending.mutation()
            && (pending.operation() == ResourceOperationKind.CREATE || pending.operation() == ResourceOperationKind.SAVE)
            ? saveRequestId(pending) : null;
        ResourceSaveFence saveFence = saveTrackerId != null ? resourceSaveFence(saveTrackerId) : null;
        if (envelope.kind() == ProtocolEnvelope.Kind.CONFLICT) {
            if (saveTrackerId != null && (saveFence == null || generation != saveFence.transportGeneration()
                || !currentResourceSaveFence(saveFence))) {
                return;
            }
            handleTypedResourceConflict(envelope, pending, document, type, resource, generation);
            return;
        }
        if (saveTrackerId != null && (saveFence == null || generation != saveFence.transportGeneration()
            || !currentResourceSaveFence(saveFence))) {
            failTypedResourceRequest(pending, "The ReSync connection changed before the resource update was confirmed.");
            return;
        }
        FlowManager manager = client != null ? client.getFlowManager() : null;
        if (manager == null) {
            if (pending != null) {
                failTypedResourceRequest(pending, "The ReSync client is unavailable.");
            }
            return;
        }
        JsonObject normalizedPayload = null;
        Object item = null;
        ProjectionRetryDiagnostic projectionDiagnostic = new ProjectionRetryDiagnostic();
        captureProjectionRetrySaveState(projectionDiagnostic, pending);
        try {
            if (!document.deleted()) {
                JsonElement payloadElement = gson.toJsonTree(document.payload());
                if (!payloadElement.isJsonObject()) {
                    throw new IllegalArgumentException("The resource response did not contain an object payload.");
                }
                normalizedPayload = payloadElement.getAsJsonObject();
                item = type.deserialize(normalizedPayload.toString());
                if (item == null || !resource.id().equals(type.extractId(item))) {
                    throw new IllegalArgumentException("The resource response had the wrong resource identity.");
                }
            }
            boolean exactPendingReplay = pending != null
                && exactAuthoritativeResourceDocument(type, document, envelope.authorityEpoch());
            if (isStaleResourceRevision(type, resource.id(), document.revision()) && !exactPendingReplay) {
                logger().operation("Resource Synchronization").warn("Rejected stale generic resource reply");
                return;
            }
            GenericResourceProjectionOutcome projectionOutcome = GenericResourceProjectionOutcome.APPLIED;
            if (!exactPendingReplay) {
                ReSyncResourceRevisionReconciler.ResourceResult result = new ReSyncResourceRevisionReconciler.ResourceResult(
                    serverId, type.typeId(), resource.id(), document.revision(), document.mutationId().toString(),
                    document.payloadHash().canonicalText(), document.deleted(), normalizedPayload, envelope.authorityEpoch());
                ReSyncResourceRevisionReconciler.Admission admission = resourceRevisionReconciler.prepare(result);
                if (!admission.accepted()) {
                    if (admission.outcome() == ReSyncResourceRevisionReconciler.Outcome.STALE
                        || admission.outcome() == ReSyncResourceRevisionReconciler.Outcome.CONFLICT) {
                        logger().operation("Resource Synchronization").warn("Rejected stale or conflicting generic resource reply");
                    }
                    if (admission.outcome() == ReSyncResourceRevisionReconciler.Outcome.INVALID) {
                        failTypedResourceRequest(pending, "The server returned an invalid resource result.");
                    }
                    return;
                }
                if (saveFence != null) {
                    Object projectedItem = item;
                    GenericResourceProjectionOutcome[] fencedOutcome = {GenericResourceProjectionOutcome.REJECTED};
                    boolean projected = runCurrentServer(manager, saveFence.connectionToken(), () -> {
                        if (currentResourceSaveFence(saveFence)) {
                            fencedOutcome[0] = projectGenericResource(manager, type, resource.id(), projectedItem,
                                document.deleted(), admission, true, null, pending,
                                () -> currentResourceSaveFence(saveFence), projectionDiagnostic);
                        }
                    });
                    projectionOutcome = projected ? fencedOutcome[0] : GenericResourceProjectionOutcome.REJECTED;
                } else {
                    BooleanSupplier projectionFence = generation >= 0
                        ? () -> typedResourceDocumentFenceCurrent(generation, envelope.authorityEpoch()) : () -> true;
                    projectionOutcome = projectGenericResource(manager, type, resource.id(), item, document.deleted(),
                        admission, pending != null && pending.mutation(), null, pending, projectionFence,
                    projectionDiagnostic);
                }
            } else if (pending.operation() == ResourceOperationKind.LOAD && pending.openWhenReceived()) {
                consumeTypedOpenIntent(pending, type, resource.id());
            }
            if (projectionOutcome == GenericResourceProjectionOutcome.RETRY) {
                logProjectionDiagnostic(envelope, document, type, resource, pending, generation, projectionDiagnostic,
                    "Deferred generic resource reply after projection failure");
                if (envelope.requestId() != null && pendingAggregateCreateReplays.containsKey(envelope.requestId())) {
                    scheduleAggregateCreateReplay(envelope.requestId(), "primary_projection_retry");
                } else {
                    scheduleTypedDocumentReplay(envelope, generation, "projection_retry");
                }
                return;
            }
            if (projectionOutcome != GenericResourceProjectionOutcome.APPLIED) {
                if (projectionOutcome == GenericResourceProjectionOutcome.REJECTED) {
                    logger().operation("Resource Synchronization").warn("Rejected stale or conflicting generic resource reply");
                }
                scheduleAggregateCreateReplay(envelope.requestId(), "primary_projection_rejected");
                return;
            }
        } catch (RuntimeException exception) {
            failTypedResourceRequest(pending, "The server returned an invalid resource result.");
            return;
        }
        traceLifecycle(serverId, "wire_accepted", "serverId", serverId, "resourceKey",
            type.typeId() + ":" + resource.id(), "operation", pending != null ? pending.operation() : "event",
            "requestId", envelope.requestId(), "mutationId", document.mutationId(), "generation", generation,
            "authorityEpoch", envelope.authorityEpoch(), "revision", document.revision(), "elapsedMs",
            temporaryLifecycleElapsed(envelope.requestId(), false));
        traceLifecycle(serverId, "authoritative_cache_applied", "serverId", serverId, "resourceKey",
            type.typeId() + ":" + resource.id(), "requestId", envelope.requestId(), "mutationId",
            document.mutationId(), "generation", generation, "authorityEpoch", envelope.authorityEpoch(), "revision",
            document.revision(), "deleted", document.deleted());
        if (pending != null && pending.operation() == ResourceOperationKind.DELETE
            && envelope.kind() == ProtocolEnvelope.Kind.ACK && document.deleted()
            && pending.mutationId() != null && pending.mutationId().equals(document.mutationId())) {
            manager.acknowledgeResourceDelete(serverId, type, resource.id());
        }
        long savedRevision = document.revision();
        String savedHash = document.payloadHash().canonicalText();
        String requestId;
        if (pending == null) {
            requestId = envelope.requestId() != null ? envelope.requestId().toString() : "";
        } else {
            requestId = saveRequestId(pending);
        }
        if (pending != null) {
            removePendingTypedResourceRequest(pending);
            cancelPendingSend(pending.requestId().toString());
        }
        if (pending != null && pending.mutation()) {
            if (pending.mutationId() != null) {
                pendingCreatePresentations.remove(pending.mutationId());
            }
            completeResourceSave(requestId);
        }
        DesignerSaveNotifications.SaveTarget completedSave = pending != null && pending.mutation()
            ? DesignerSaveNotifications.complete(serverId, type, resource.id(), requestId,
                projectionDiagnostic.currentAtFinish()) : null;
        if (pending != null && pending.mutation()) {
            traceLifecycle(serverId, "settlement_complete", "serverId", serverId, "resourceKey",
                type.typeId() + ":" + resource.id(), "operation", pending.operation(), "requestId",
                pending.requestId(), "mutationId", pending.mutationId(), "generation", generation, "authorityEpoch",
                envelope.authorityEpoch(), "revision", document.revision(), "elapsedMs",
                temporaryLifecycleElapsed(pending.requestId(), true));
        } else if (pending != null) {
            temporaryLifecycleRequestStarts.remove(pending.requestId());
        }
        if (pending != null && aggregatePrimaryResponses.contains(pending.requestId())) {
            aggregatePrimarySettlements.add(pending.requestId());
        }
        FlowManager.ServerConnectionToken projectionToken = saveFence != null
            ? saveFence.connectionToken() : captureUiToken(manager);
        executeCurrentServerUi(manager, projectionToken, () -> {
            GraphEditorScreen.clearEditorErrorsForServer(serverId, type.typeId(), resource.id());
            GraphEditorScreen studioScreen = GraphEditorScreen.getStudioScreen(serverId);
            if (studioScreen != null) {
                studioScreen.markStudioDocumentSaved(type.typeId(), resource.id(), completedSave != null ? completedSave.sequence() : 0L,
                    savedRevision, savedHash);
            }
        });
    }

    @SuppressWarnings("unchecked")
    private void handleAggregateResourceCreateEnvelope(ProtocolEnvelope<Map<String, Object>> envelope,
                                                       ProtocolBody.ResourceCreateResponse response,
                                                       int generation) {
        PendingTypedResourceRequest typed = envelope != null && envelope.requestId() != null
            ? pendingTypedResourceRequests.get(envelope.requestId()) : null;
        PendingCoreGraphRequest core = envelope != null && envelope.requestId() != null
            ? pendingCoreGraphRequests.get(envelope.requestId()) : null;
        UUID mutationId = typed != null ? typed.mutationId() : core != null ? core.mutationId() : null;
        ResourcePresentationIntent expectedPresentation = mutationId != null
            ? pendingCreatePresentations.get(mutationId) : null;
        ResourceCreateResult result = response != null ? response.result() : null;
        ResourceDocument<?> rawPrimary = result != null ? result.resource() : null;
        ResourceDocument<?> rawMetadata = result != null ? result.projectMetadata() : null;
        ReSyncResourceType type = rawPrimary != null && rawPrimary.resource() != null ? ReSyncResourceType.byTypeId(
            rawPrimary.resource().resourceType().value()) : null;
        boolean pendingMatches = typed != null ^ core != null;
        pendingMatches = pendingMatches && (typed == null || typed.operation() == ResourceOperationKind.CREATE
            && typed.resource().equals(rawPrimary != null ? rawPrimary.resource() : null)
            && typed.correlationId().equals(envelope.correlationId()) && typed.traceId().equals(envelope.traceId()))
            && (core == null || core.operation() == ResourceOperationKind.CREATE
            && core.resource().equals(rawPrimary != null ? rawPrimary.resource() : null)
            && core.correlationId().equals(envelope.correlationId()) && core.traceId().equals(envelope.traceId()));
        boolean valid = envelope != null && response != null && result != null && rawPrimary != null
            && rawMetadata != null && rawMetadata.resource() != null && type != null && expectedPresentation != null
            && pendingMatches
            && envelope.kind() == ProtocolEnvelope.Kind.ACK
            && (envelope.status() == ProtocolEnvelope.Status.OK || envelope.status() == ProtocolEnvelope.Status.ACCEPTED)
            && coreOperation(envelope, ResourceOperationKind.CREATE)
            && ProtocolEnvelope.supportsResourceCreatePresentation(envelope.contractVersion(), envelope.capabilities())
            && serverId.equals(envelope.serverId().canonicalText())
            && envelope.resource() != null && envelope.resource().equals(rawPrimary.resource())
            && mutationId.equals(envelope.mutationId()) && mutationId.equals(rawPrimary.mutationId())
            && mutationId.equals(rawMetadata.mutationId()) && Objects.equals(envelope.payloadHash(), rawPrimary.payloadHash())
            && !rawPrimary.deleted() && !rawMetadata.deleted() && Objects.equals(result.presentation(), expectedPresentation)
            && rawMetadata.resource().serverId().equals(rawPrimary.resource().serverId())
            && ReSyncResourceType.PROJECT_METADATA.typeId().equals(rawMetadata.resource().resourceType().value())
            && serverId.equals(rawMetadata.resource().id())
            && generation >= 0 && isConnectionReadyGeneration(generation)
            && (typed == null || typed.transportGeneration() == generation)
            && (core == null || core.transportGeneration() == generation);
        boolean authorityAccepted = valid && acceptAuthorityEpoch(envelope.authorityEpoch());
        if (!valid || !authorityAccepted) {
            String reason = response == null || result == null || rawPrimary == null || rawMetadata == null
                ? "aggregate_body" : !pendingMatches ? "pending_identity"
                : expectedPresentation == null ? "presentation_missing"
                : generation < 0 || typed != null && typed.transportGeneration() != generation
                    || core != null && core.transportGeneration() != generation ? "generation_fence"
                : !authorityAccepted ? "authority_epoch" : "contract_or_document_identity";
            traceLifecycle(serverId, "create_aggregate_rejected", "serverId", serverId, "resourceKey",
                type != null && rawPrimary.resource() != null ? type.typeId() + ":" + rawPrimary.resource().id()
                    : "unknown:unknown", "requestId", envelope != null ? envelope.requestId() : null, "mutationId",
                mutationId, "generation", generation, "authorityEpoch", envelope != null ? envelope.authorityEpoch() : 0L,
                "revision", rawPrimary != null ? rawPrimary.revision() : 0L, "reason", reason);
            failAggregateResourceCreate(typed, core, "The server returned an invalid aggregate creation result.");
            return;
        }
        ResourceDocument<Map<String, Object>> primary = (ResourceDocument<Map<String, Object>>) rawPrimary;
        ResourceDocument<Map<String, Object>> metadata = (ResourceDocument<Map<String, Object>>) rawMetadata;
        if (!aggregatePresentationMatches(type, primary.resource().id(), metadata, expectedPresentation)) {
            traceLifecycle(serverId, "create_aggregate_rejected", "serverId", serverId, "resourceKey",
                type.typeId() + ":" + primary.resource().id(), "requestId", envelope.requestId(), "mutationId",
                mutationId, "generation", generation, "authorityEpoch", envelope.authorityEpoch(), "revision",
                primary.revision(), "reason", "presentation_row");
            failAggregateResourceCreate(typed, core, "The server returned mismatched resource presentation metadata.");
            return;
        }
        pendingAggregateCreateReplays.putIfAbsent(envelope.requestId(),
            new PendingAggregateCreateReplay(envelope, generation));
        TypedPageProjection aggregateProjection = new TypedPageProjection();
        boolean metadataAlreadyAuthoritative;
        boolean aggregateSettled = false;
        typedPageProjection.set(aggregateProjection);
        try {
            GenericResourceProjectionOutcome metadataProjection;
            aggregateMetadataProjection.set(true);
            try {
                metadataProjection = applyTypedResourceDocument(ReSyncResourceType.PROJECT_METADATA, metadata,
                    envelope.authorityEpoch(), false, false, generation);
            } finally {
                aggregateMetadataProjection.remove();
            }
            metadataAlreadyAuthoritative = metadataProjection != GenericResourceProjectionOutcome.APPLIED
                && exactAuthoritativeResourceDocument(ReSyncResourceType.PROJECT_METADATA, metadata,
                    envelope.authorityEpoch());
            if (metadataProjection != GenericResourceProjectionOutcome.APPLIED && !metadataAlreadyAuthoritative) {
                rollbackTypedPageProjection(aggregateProjection);
                traceLifecycle(serverId, "create_aggregate_projection_deferred", "serverId", serverId, "resourceKey",
                    type.typeId() + ":" + primary.resource().id(), "requestId", envelope.requestId(), "mutationId",
                    mutationId, "generation", generation, "authorityEpoch", envelope.authorityEpoch(), "revision",
                    primary.revision(), "reason", "project_metadata_projection_"
                        + metadataProjection.name().toLowerCase(Locale.ROOT));
                scheduleAggregateCreateReplay(envelope.requestId(), "project_metadata_projection_"
                    + metadataProjection.name().toLowerCase(Locale.ROOT));
                return;
            }
            if (metadataAlreadyAuthoritative) {
                traceLifecycle(serverId, "create_aggregate_metadata_replayed", "serverId", serverId, "resourceKey",
                    type.typeId() + ":" + primary.resource().id(), "requestId", envelope.requestId(), "mutationId",
                    mutationId, "generation", generation, "authorityEpoch", envelope.authorityEpoch(), "revision",
                    metadata.revision());
            }
            traceLifecycle(serverId, "create_aggregate_metadata_committed", "serverId", serverId, "resourceKey",
                type.typeId() + ":" + primary.resource().id(), "requestId", envelope.requestId(), "mutationId",
                mutationId, "generation", generation, "authorityEpoch", envelope.authorityEpoch(), "revision",
                metadata.revision());
            ProtocolEnvelope<Map<String, Object>> primaryEnvelope = aggregatePrimaryEnvelope(envelope, primary);
            aggregatePrimaryResponses.add(envelope.requestId());
            try {
                handleProtocolEnvelope(protocolEnvelopeCodec.encodeBytes(primaryEnvelope), generation);
            } finally {
                aggregatePrimaryResponses.remove(envelope.requestId());
            }
            boolean primarySettled = aggregatePrimarySettlements.remove(envelope.requestId());
            if (!primarySettled || pendingCreatePresentations.containsKey(mutationId)) {
                rollbackTypedPageProjection(aggregateProjection);
                return;
            }
            aggregateSettled = true;
        } finally {
            aggregateMetadataProjection.remove();
            typedPageProjection.remove();
        }
        if (!aggregateSettled) {
            return;
        }
        FlowManager manager = client != null ? client.getFlowManager() : null;
        publishTypedPageProjection(aggregateProjection);
        if (metadataAlreadyAuthoritative && manager != null) {
            ReSyncProjectMetadata committedMetadata = decodeProjectMetadata(metadata);
            if (committedMetadata == null) {
                return;
            }
            manager.notifyResourceDataReceivedAfterCommit(serverId, ReSyncResourceType.PROJECT_METADATA,
                committedMetadata);
        }
        boolean journalSettled = manager != null && manager.settleAggregateCreation(serverId, type,
            primary.resource().id(), envelope.requestId(), mutationId);
        traceLifecycle(serverId, journalSettled ? "create_aggregate_journal_confirmed"
            : "create_aggregate_journal_deferred", "serverId", serverId, "resourceKey",
            type.typeId() + ":" + primary.resource().id(), "requestId", envelope.requestId(), "mutationId",
            mutationId, "generation", generation, "authorityEpoch", envelope.authorityEpoch(), "revision",
            primary.revision(), "metadataRevision", metadata.revision());
        pendingAggregateCreateReplays.remove(envelope.requestId());
    }

    private boolean exactAuthoritativeResourceDocument(ReSyncResourceType type,
                                                       ResourceDocument<Map<String, Object>> document,
                                                       long authorityEpoch) {
        if (type == null || document == null || document.resource() == null) {
            return false;
        }
        try {
            JsonObject payload = null;
            if (!document.deleted()) {
                JsonElement payloadElement = gson.toJsonTree(document.payload());
                if (!payloadElement.isJsonObject()) {
                    return false;
                }
                payload = payloadElement.getAsJsonObject();
            }
            ReSyncResourceRevisionReconciler.ResourceResult current = resourceRevisionReconciler.get(serverId,
                type.typeId(), document.resource().id());
            return current != null && current.revision() == document.revision()
                && current.authorityEpoch() == authorityEpoch && current.deleted() == document.deleted()
                && document.mutationId().toString().equals(current.mutationId())
                && document.payloadHash().canonicalText().equals(current.payloadHash())
                && Objects.equals(payload, current.payload());
        } catch (RuntimeException exception) {
            return false;
        }
    }

    private boolean aggregatePresentationMatches(ReSyncResourceType type, String id,
                                                 ResourceDocument<Map<String, Object>> metadata,
                                                 ResourcePresentationIntent expected) {
        ReSyncProjectMetadata projectMetadata = decodeProjectMetadata(metadata);
        if (projectMetadata == null || type == null || id == null || id.isBlank() || expected == null) {
            return false;
        }
        ReSyncProjectMetadata.ResourceEntry entry = projectMetadata.getResources().stream()
            .filter(candidate -> candidate != null && type.typeId().equals(candidate.getType())
                && id.equals(candidate.getId()))
            .findFirst().orElse(null);
        return entry != null && expected.displayName().equals(entry.getDisplayName())
            && expected.path().equals(ReSyncProjectMetadata.normalizePath(entry.getPath()))
            && expected.sortOrder() == entry.getSortOrder();
    }

    private ProtocolEnvelope<Map<String, Object>> aggregatePrimaryEnvelope(
        ProtocolEnvelope<Map<String, Object>> aggregate, ResourceDocument<Map<String, Object>> primary) {
        return new ProtocolEnvelope<>(ProtocolEnvelope.Kind.ACK, aggregate.contractVersion(), UUID.randomUUID(),
            aggregate.requestId(), aggregate.correlationId(), aggregate.traceId(), aggregate.serverId(),
            primary.resource(), primary.revision(), aggregate.authorityEpoch(), primary.mutationId(),
            aggregate.operation(), aggregate.capabilities(), RESOURCE_DOCUMENT_TYPE, null, primary.payloadHash(),
            primary.deleted(), aggregate.selectedVersion(), aggregate.catalogChecksum(), aggregate.bindingManifestHash(),
            aggregate.editability(), aggregate.fallbackReason(), aggregate.sequence(), aggregate.status(),
            aggregate.diagnostics(), aggregate.unknown(),
            new ProtocolBody.ResourceDocumentResponse(ResourceOperationKind.CREATE, primary));
    }

    private void failAggregateResourceCreate(PendingTypedResourceRequest typed, PendingCoreGraphRequest core,
                                             String message) {
        UUID requestId = typed != null ? typed.requestId() : core != null ? core.requestId() : null;
        if (requestId != null) {
            pendingAggregateCreateReplays.remove(requestId);
            aggregatePrimarySettlements.remove(requestId);
        }
        if (typed != null) {
            failTypedResourceRequest(typed, message);
        }
        if (core != null) {
            failCorePending(core, message);
        }
    }

    private void scheduleAggregateCreateReplay(UUID requestId, String reason) {
        PendingAggregateCreateReplay replay = requestId != null ? pendingAggregateCreateReplays.get(requestId) : null;
        if (replay == null) {
            return;
        }
        boolean exhausted;
        synchronized (replay) {
            if (replay.scheduled) {
                return;
            }
            exhausted = replay.attempts >= MAX_AGGREGATE_CREATE_REPLAY_ATTEMPTS;
            if (!exhausted) {
                replay.attempts++;
                replay.scheduled = true;
            }
        }
        if (exhausted) {
            PendingTypedResourceRequest typed = pendingTypedResourceRequests.get(requestId);
            PendingCoreGraphRequest core = pendingCoreGraphRequests.get(requestId);
            traceLifecycle(serverId, "create_aggregate_replay_exhausted", "serverId", serverId, "resourceKey",
                typed != null ? temporaryLifecycleResourceKey(typed.type(), typed.resource())
                    : core != null ? temporaryLifecycleResourceKey(core.type(), core.resource()) : "unknown",
                "requestId", requestId, "mutationId", typed != null ? typed.mutationId()
                    : core != null ? core.mutationId() : null, "generation", replay.generation,
                "authorityEpoch", handshakeAuthorityEpoch, "revision", replay.envelope.revision(), "reason", reason);
            failAggregateResourceCreate(typed, core, "Aggregate resource creation could not be projected.");
            return;
        }
        try {
            heartbeatScheduler.schedule(() -> {
                synchronized (replay) {
                    replay.scheduled = false;
                }
                if (pendingAggregateCreateReplays.get(requestId) != replay) {
                    return;
                }
                if (!isConnectionReadyGeneration(replay.generation)) {
                    failAggregateResourceCreate(pendingTypedResourceRequests.get(requestId),
                        pendingCoreGraphRequests.get(requestId), "The ReSync connection changed during creation settlement.");
                    return;
                }
                if (replay.envelope.body() instanceof ProtocolBody.ResourceCreateResponse response) {
                    handleAggregateResourceCreateEnvelope(replay.envelope, response, replay.generation);
                }
            }, Duration.ofMillis(100L));
        } catch (RuntimeException exception) {
            synchronized (replay) {
                replay.scheduled = false;
            }
            failAggregateResourceCreate(pendingTypedResourceRequests.get(requestId),
                pendingCoreGraphRequests.get(requestId), "Aggregate resource creation replay was unavailable.");
        }
    }

    private void scheduleTypedDocumentReplay(ProtocolEnvelope<Map<String, Object>> envelope, int generation,
                                             String reason) {
        UUID requestId = envelope != null ? envelope.requestId() : null;
        PendingTypedResourceRequest pending = requestId != null ? pendingTypedResourceRequests.get(requestId) : null;
        if (pending == null || envelope.kind() == ProtocolEnvelope.Kind.EVENT
            || !pending.matches(envelope,
                envelope.body() instanceof ProtocolBody.ResourceDocumentResponse response
                    ? castResourceDocument(response.document()) : null,
                envelope.resource(), pending.type())) {
            return;
        }
        PendingTypedDocumentReplay replay = pendingTypedDocumentReplays.computeIfAbsent(requestId,
            ignored -> new PendingTypedDocumentReplay(envelope, generation));
        if (!replay.matches(envelope, generation)) {
            failTypedResourceRequest(pending, "The server returned a mismatched resource replay.");
            return;
        }
        boolean exhausted;
        synchronized (replay) {
            if (replay.scheduled) {
                return;
            }
            exhausted = replay.attempts >= MAX_TYPED_DOCUMENT_REPLAY_ATTEMPTS;
            if (!exhausted) {
                replay.attempts++;
                replay.scheduled = true;
            }
        }
        if (exhausted) {
            traceLifecycle(serverId, "typed_document_replay_exhausted", "serverId", serverId, "resourceKey",
                temporaryLifecycleResourceKey(pending.type(), pending.resource()), "operation", pending.operation(),
                "requestId", pending.requestId(), "mutationId", pending.mutationId(), "generation",
                replay.generation, "authorityEpoch", envelope.authorityEpoch(), "revision", envelope.revision(),
                "reason", reason);
            failTypedResourceRequest(pending, "The resource response could not be projected consistently.");
            return;
        }
        try {
            heartbeatScheduler.schedule(() -> {
                synchronized (replay) {
                    replay.scheduled = false;
                }
                PendingTypedResourceRequest current = pendingTypedResourceRequests.get(requestId);
                if (pendingTypedDocumentReplays.get(requestId) != replay || current != pending
                    || !isConnectionReadyGeneration(replay.generation)) {
                    return;
                }
                handleProtocolEnvelope(protocolEnvelopeCodec.encodeBytes(replay.envelope), replay.generation);
            }, Duration.ofMillis(100L));
        } catch (RuntimeException exception) {
            synchronized (replay) {
                replay.scheduled = false;
            }
            failTypedResourceRequest(pending, "The resource response replay was unavailable.");
        }
    }

    @SuppressWarnings("unchecked")
    private static ResourceDocument<Map<String, Object>> castResourceDocument(ResourceDocument<?> document) {
        return (ResourceDocument<Map<String, Object>>) document;
    }

    private boolean rejectPrimaryOnlyAggregateCreateEnvelope(ProtocolEnvelope<Map<String, Object>> envelope) {
        if (envelope == null || envelope.requestId() == null) {
            return false;
        }
        if (aggregatePrimaryResponses.contains(envelope.requestId())) {
            return false;
        }
        PendingTypedResourceRequest typed = pendingTypedResourceRequests.get(envelope.requestId());
        PendingCoreGraphRequest core = pendingCoreGraphRequests.get(envelope.requestId());
        UUID mutationId = typed != null ? typed.mutationId() : core != null ? core.mutationId() : null;
        if (mutationId == null || !pendingCreatePresentations.containsKey(mutationId)) {
            return false;
        }
        failAggregateResourceCreate(typed, core, "ReSync did not return the complete resource creation result.");
        return true;
    }

    private void handleTypedResourcePage(ProtocolEnvelope<Map<String, Object>> envelope,
                                         ProtocolBody.ResourcePageResponse response, int generation) {
        PendingTypedResourceRequest pending = envelope.requestId() == null
            ? null : pendingTypedResourceRequests.get(envelope.requestId());
        if (pending == null || pending.mutation() || pending.operation() != response.operation()
            || (response.operation() != ResourceOperationKind.LIST && response.operation() != ResourceOperationKind.QUERY)
            || envelope.resource() != null || !pending.correlationId().equals(envelope.correlationId())
            || !pending.traceId().equals(envelope.traceId()) || !currentTypedResourcePage(pending, generation)) {
            return;
        }
        TypedResourceListKey listKey = new TypedResourceListKey(pending.type(), pending.query());
        UUID activeCorrelation = activeTypedResourceListCorrelations.get(listKey);
        if (activeCorrelation != null && !activeCorrelation.equals(pending.correlationId())) {
            return;
        }
        ResourcePage<?> rawPage = response.page();
        if (rawPage == null) {
            failTypedResourceRequest(pending, "The server returned an empty resource page.");
            return;
        }
        List<ResourceDocument<Map<String, Object>>> documents = new ArrayList<>();
        for (ResourceDocument<?> rawDocument : rawPage.items()) {
            if (rawDocument == null || rawDocument.resource() == null
                || !serverId.equals(rawDocument.resource().serverId().canonicalText())
                || !pending.type().typeId().equals(rawDocument.resource().resourceType().value())) {
                failTypedResourceRequest(pending, "The server returned a resource page with the wrong typed identity.");
                return;
            }
            @SuppressWarnings("unchecked")
            ResourceDocument<Map<String, Object>> document =
                (ResourceDocument<Map<String, Object>>) (ResourceDocument<?>) rawDocument;
            documents.add(document);
        }
        PendingTypedPageReplay replay = pendingTypedPageReplays.computeIfAbsent(pending.requestId(),
            ignored -> new PendingTypedPageReplay(envelope, response, generation));
        if (!replay.matches(envelope, generation)) {
            failTypedResourceRequest(pending, "The server returned a mismatched resource page replay.");
            return;
        }
        TypedPageProjection pageProjection = new TypedPageProjection();
        List<String> ids = new ArrayList<>();
        typedPageProjection.set(pageProjection);
        try {
            for (ResourceDocument<Map<String, Object>> document : documents) {
                if (!currentTypedResourcePage(pending, generation)) {
                    rollbackTypedPageProjection(pageProjection);
                    return;
                }
                GenericResourceProjectionOutcome projection = applyTypedResourceDocument(pending.type(), document,
                    envelope.authorityEpoch(), false, false, generation);
                if (projection == GenericResourceProjectionOutcome.RETRY) {
                    rollbackTypedPageProjection(pageProjection);
                    traceLifecycle(serverId, "typed_page_projection_deferred", "serverId", serverId, "resourceKey",
                        pending.type().typeId() + ":catalog", "operation", pending.operation(), "requestId",
                        pending.requestId(), "mutationId", pending.mutationId(), "generation", generation,
                        "authorityEpoch", envelope.authorityEpoch(), "memberCount", documents.size(), "reason",
                        "projection_retry");
                    scheduleTypedPageReplay(pending.requestId());
                    return;
                }
                if (projection != GenericResourceProjectionOutcome.APPLIED) {
                    rollbackTypedPageProjection(pageProjection);
                    failTypedResourceRequest(pending, "The server returned an invalid resource page.");
                    return;
                }
                ids.add(document.resource().id());
            }
        } finally {
            typedPageProjection.remove();
        }
        if (!currentTypedResourcePage(pending, generation)) {
            rollbackTypedPageProjection(pageProjection);
            return;
        }
        pendingTypedPageReplays.remove(pending.requestId(), replay);
        publishTypedPageProjection(pageProjection);
        List<String> accumulated = typedResourceListResults.computeIfAbsent(pending.correlationId(),
            ignored -> new ArrayList<>());
        synchronized (accumulated) {
            accumulated.addAll(ids);
        }
        if (!removePendingTypedResourceRequest(pending)) {
            clearTypedResourceListState(pending);
            return;
        }
        cancelPendingSend(pending.requestId().toString());
        if (pending.transportGeneration() != generation || !isConnectionReadyGeneration(generation)) {
            clearTypedResourceListState(pending);
            return;
        }
        if (!rawPage.complete()) {
            if (rawPage.nextCursor() == null || rawPage.nextCursor().isBlank()) {
                clearTypedResourceListState(pending);
                return;
            }
            traceLifecycle(serverId, "authoritative_list_page", "serverId", serverId, "resourceKey",
                pending.type().typeId() + ":catalog", "operation", pending.operation(), "requestId",
                pending.requestId(), "mutationId", pending.mutationId(), "generation", generation, "authorityEpoch",
                envelope.authorityEpoch(), "memberCount", ids.size(), "elapsedMs",
                temporaryLifecycleElapsed(pending.requestId(), true));
            sendTypedResourceList(pending.type(), rawPage.nextCursor(), pending.query(), pending.correlationId(), pending.traceId());
            return;
        }
        List<String> completedIds;
        synchronized (accumulated) {
            completedIds = List.copyOf(accumulated);
        }
        clearTypedResourceListState(pending);
        if (client != null && client.getFlowManager() != null) {
            markResourceListProjection(pending.type(), pending.operation(), pending.query());
            applyServerResourceList(client.getFlowManager(), pending.type(), completedIds);
            traceLifecycle(serverId, "authoritative_list_applied", "serverId", serverId, "resourceKey",
                pending.type().typeId() + ":catalog", "operation", pending.operation(), "requestId",
                pending.requestId(), "mutationId", pending.mutationId(), "generation", generation, "authorityEpoch",
                envelope.authorityEpoch(), "memberCount", completedIds.size(), "elapsedMs",
                temporaryLifecycleElapsed(pending.requestId(), true));
            logger().operation("Resource Hydration").info("Typed resource list applied: type="
                + pending.type().typeId() + ",count=" + completedIds.size() + ",generation=" + generation
                + ",correlation=" + pending.correlationId());
        } else {
            temporaryLifecycleRequestStarts.remove(pending.requestId());
        }
    }

    private void rollbackTypedPageProjection(TypedPageProjection projection) {
        FlowManager manager = client != null ? client.getFlowManager() : null;
        if (projection == null) {
            return;
        }
        List<TypedPageProjectionEntry> entries = projection.entries();
        for (int index = entries.size() - 1; index >= 0; index--) {
            TypedPageProjectionEntry entry = entries.get(index);
            if (manager != null && entry.snapshot() != null && entry.lease() != null) {
                manager.restoreResourceProjection(entry.snapshot(), entry.lease());
            }
            if (entry.admission() != null && resourceRevisionReconciler.rollback(entry.admission())) {
                String watermarkKey = resourceRevisionKey(entry.type(), entry.resourceId());
                resourceRevisionWatermarks.compute(watermarkKey, (ignored, current) ->
                    current != null && current == entry.revision() ? entry.previousWatermark() : current);
            }
        }
    }

    private void publishTypedPageProjection(TypedPageProjection projection) {
        FlowManager manager = client != null ? client.getFlowManager() : null;
        if (manager == null || projection == null) {
            return;
        }
        for (TypedPageProjectionEntry entry : projection.entries()) {
            try {
                if (entry.deleted()) {
                    manager.notifyResourceDeletionCommitted(serverId, entry.type(), entry.resourceId(),
                        entry.removedMetadata());
                } else {
                    manager.notifyResourceDataReceivedAfterCommit(serverId, entry.type(), entry.item());
                }
            } catch (RuntimeException exception) {
                logger().operation("Resource Synchronization").warn("Could not publish a committed resource page projection");
            }
        }
    }

    private void scheduleTypedPageReplay(UUID requestId) {
        PendingTypedPageReplay replay = requestId != null ? pendingTypedPageReplays.get(requestId) : null;
        PendingTypedResourceRequest pending = requestId != null ? pendingTypedResourceRequests.get(requestId) : null;
        if (replay == null || pending == null) {
            return;
        }
        boolean exhausted;
        synchronized (replay) {
            if (replay.scheduled) {
                return;
            }
            exhausted = replay.attempts >= MAX_TYPED_PAGE_REPLAY_ATTEMPTS;
            if (!exhausted) {
                replay.attempts++;
                replay.scheduled = true;
            }
        }
        if (exhausted) {
            traceLifecycle(serverId, "typed_page_replay_exhausted", "serverId", serverId, "resourceKey",
                pending.type().typeId() + ":catalog", "operation", pending.operation(), "requestId",
                pending.requestId(), "mutationId", pending.mutationId(), "generation", replay.generation,
                "authorityEpoch", replay.envelope.authorityEpoch(), "memberCount", replay.response.page().items().size(),
                "reason", "projection_retry_exhausted");
            failTypedResourceRequest(pending, "The resource list could not be projected consistently.");
            return;
        }
        try {
            heartbeatScheduler.schedule(() -> {
                synchronized (replay) {
                    replay.scheduled = false;
                }
                PendingTypedResourceRequest current = pendingTypedResourceRequests.get(requestId);
                if (pendingTypedPageReplays.get(requestId) != replay || current != pending
                    || !currentTypedResourcePage(current, replay.generation)) {
                    return;
                }
                handleTypedResourcePage(replay.envelope, replay.response, replay.generation);
            }, Duration.ofMillis(100L));
        } catch (RuntimeException exception) {
            synchronized (replay) {
                replay.scheduled = false;
            }
            failTypedResourceRequest(pending, "The resource list replay was unavailable.");
        }
    }

    private boolean currentTypedResourcePage(PendingTypedResourceRequest pending, int generation) {
        return pending != null && generation >= 0 && pending.transportGeneration() == generation
            && isConnectionReadyGeneration(generation)
            && pendingTypedResourceRequests.get(pending.requestId()) == pending;
    }

    private PendingCoreGraphRequest pendingCoreGraphRequest(ProtocolEnvelope<Map<String, Object>> envelope) {
        UUID requestId = envelope == null ? null : envelope.requestId();
        return requestId == null ? null : pendingCoreGraphRequests.get(requestId);
    }

    private boolean failCorrelatedCoreEnvelope(ProtocolEnvelope<Map<String, Object>> envelope, String message) {
        PendingCoreGraphRequest pending = pendingCoreGraphRequest(envelope);
        if (pending == null || envelope == null) {
            return false;
        }
        try {
            if (envelope.serverId() == null || !serverId.equals(envelope.serverId().canonicalText())) {
                return false;
            }
        } catch (RuntimeException exception) {
            return false;
        }
        diagnoseCoreRead(pending, "admission_false");
        return failCorePending(pending, message);
    }

    private boolean matchesServer(ProtocolEnvelope<Map<String, Object>> envelope) {
        try {
            return envelope != null && envelope.serverId() != null
                && serverId.equals(envelope.serverId().canonicalText());
        } catch (RuntimeException exception) {
            return false;
        }
    }

    private boolean isRejectedProtocolEnvelope(ProtocolEnvelope<Map<String, Object>> envelope) {
        if (envelope == null || (envelope.kind() != ProtocolEnvelope.Kind.RESPONSE
            && envelope.kind() != ProtocolEnvelope.Kind.CONFLICT)) {
            return false;
        }
        return envelope.status() == ProtocolEnvelope.Status.REJECTED
            || envelope.status() == ProtocolEnvelope.Status.NOT_FOUND
            || envelope.status() == ProtocolEnvelope.Status.READ_ONLY
            || envelope.status() == ProtocolEnvelope.Status.UPGRADE_REQUIRED;
    }

    private boolean isAuthoringTemplateEnvelope(ProtocolEnvelope<Map<String, Object>> envelope) {
        return envelope != null && AUTHORING_TEMPLATE_OPERATION.equals(envelope.operation())
            && (AUTHORING_TEMPLATE_REQUEST_TYPE.equals(envelope.payloadType())
                || AUTHORING_TEMPLATE_RESPONSE_TYPE.equals(envelope.payloadType()));
    }

    private boolean isCoreOptionEnvelope(ProtocolEnvelope<Map<String, Object>> envelope) {
        return envelope != null && OPTION_QUERY_OPERATION.equals(envelope.operation())
            && OPTION_PAGE_TYPE.equals(envelope.payloadType())
            && envelope.body() instanceof ProtocolBody.OptionPageResponse;
    }

    private void handleCoreOptionInvalidation(ProtocolEnvelope<Map<String, Object>> envelope,
                                              ProtocolBody.OptionInvalidationEvent event, int generation) {
        List<PendingCoreOptionRequest> retired = new ArrayList<>();
        synchronized (coreOptionDispatchLock) {
            ConnectionSource source = inboundSource.get();
            if (source == null || source != connectionSource(generation) || !source.accepts(generation)
                || !isConnectionReadyGeneration(generation) || !catalogAuthoringAdvertised || !optionQueriesAdvertised
                || catalogAuthority != CatalogAuthority.TYPED_PUBLICATION || !optionQueryAuthorityReady()) {
                return;
            }
            synchronized (catalogLifecycleLock) {
                Optional<ReSyncCatalogAuthoringProjection.Snapshot> active = activeAuthoringSnapshot();
                if (active.isEmpty()) {
                    return;
                }
                ReSyncCatalogAuthoringProjection.Snapshot snapshot = active.orElseThrow();
                OptionInvalidation invalidation = event.invalidation();
                if (!matchesCoreOptionInvalidationEnvelope(envelope, event, snapshot, invalidation)
                    || replayedCoreOptionInvalidation(envelope, snapshot, invalidation)) {
                    return;
                }
                Set<OptionCatalogCache.CoreKey> invalidated = OptionCatalogCache.getInstance().invalidate(invalidation,
                    snapshot.publication().binding(), snapshot.publication().contractVersion(), snapshot.checksum(),
                    snapshot.revision(), envelope.authorityEpoch());
                for (PendingCoreOptionRequest pending : List.copyOf(pendingCoreOptionRequests.values())) {
                    if (invalidated.contains(pending.request().key())
                        && pendingCoreOptionRequests.remove(pending.requestId(), pending)) {
                        retired.add(pending);
                    }
                }
            }
        }
        cancelRetiredCoreOptionRequests(retired);
    }

    private boolean matchesCoreOptionInvalidationEnvelope(ProtocolEnvelope<Map<String, Object>> envelope,
                                                           ProtocolBody.OptionInvalidationEvent event,
                                                           ReSyncCatalogAuthoringProjection.Snapshot snapshot,
                                                           OptionInvalidation invalidation) {
        if (envelope == null || event == null || snapshot == null || invalidation == null
            || envelope.kind() != ProtocolEnvelope.Kind.EVENT || envelope.status() != ProtocolEnvelope.Status.OK
            || envelope.requestId() != null || !protocolServerId().equals(envelope.serverId())
            || !protocolServerId().equals(invalidation.serverId())
            || !ReSyncProtocolContract.GENERIC_RESOURCE_CONTRACT_VERSION.equals(envelope.contractVersion())
            || !OPTION_QUERY_OPERATION.equals(envelope.operation()) || !OPTION_PAGE_TYPE.equals(envelope.payloadType())
            || !OPTION_QUERY_CAPABILITIES.equals(envelope.capabilities()) || envelope.resource() != null
            || envelope.revision() != 0L
            || !acceptOptionQueryAuthorityEpoch(envelope.authorityEpoch())
            || envelope.mutationId() != null || envelope.canonicalPayload() != null || envelope.payloadHash() != null
            || envelope.deleted() || !snapshot.publication().contractVersion().equals(envelope.selectedVersion())
            || !snapshot.publication().binding().catalogChecksum().equals(envelope.catalogChecksum())
            || !snapshot.publication().binding().bindingManifestHash().equals(envelope.bindingManifestHash())
            || envelope.editability() != null || envelope.fallbackReason() != null
            || !envelope.diagnostics().isEmpty() || !envelope.unknown().isEmpty() || !event.unknown().isEmpty()) {
            return false;
        }
        try {
            return AdvertisedOptionSourceResolver.resolve(snapshot.publication(), invalidation.sourceRef())
                .filter(resolved -> resolved.source().capability().equals(invalidation.query()))
                .isPresent();
        } catch (RuntimeException exception) {
            return false;
        }
    }

    private boolean replayedCoreOptionInvalidation(ProtocolEnvelope<Map<String, Object>> envelope,
                                                    ReSyncCatalogAuthoringProjection.Snapshot snapshot,
                                                    OptionInvalidation invalidation) {
        if (envelope.sequence() == 0L) {
            return false;
        }
        Map<String, Object> scope = new LinkedHashMap<>();
        scope.put("contractVersion", envelope.contractVersion().toString());
        scope.put("selectedVersion", envelope.selectedVersion().toString());
        scope.put("catalogBinding", snapshot.publication().binding().canonicalText());
        scope.put("publicationChecksum", snapshot.checksum().canonicalText());
        scope.put("publicationRevision", snapshot.revision());
        scope.put("authorityEpoch", envelope.authorityEpoch());
        scope.put("serverId", invalidation.serverId().canonicalText());
        scope.put("sourceRef", invalidation.sourceRef().canonicalText());
        scope.put("query", invalidation.query().canonicalText());
        scope.put("resource", invalidation.resource() == null ? null : invalidation.resource().canonicalValue());
        scope.put("dependencyKeys", invalidation.dependencyKeys().stream().sorted().toList());
        String key = CanonicalJson.canonicalize(scope);
        Long previous = coreOptionInvalidationSequences.get(key);
        if (previous != null && envelope.sequence() <= previous) {
            return true;
        }
        coreOptionInvalidationSequences.put(key, envelope.sequence());
        while (coreOptionInvalidationSequences.size() > MAX_CORE_OPTION_INVALIDATION_SCOPES) {
            String oldest = coreOptionInvalidationSequences.keySet().iterator().next();
            coreOptionInvalidationSequences.remove(oldest);
        }
        return false;
    }

    private void handleCoreOptionEnvelope(ProtocolEnvelope<Map<String, Object>> envelope,
                                          PendingCoreOptionRequest pending, int generation) {
        synchronized (coreOptionDispatchLock) {
            ConnectionSource source = inboundSource.get();
            if (!pending.matchesGeneration(generation, source)) {
                return;
            }
            if (!pending.matchesResponse(envelope) || !acceptOptionQueryAuthorityEpoch(envelope.authorityEpoch())
                || !currentCoreOptionPublication(pending.request())) {
                failCoreOptionRequest(pending, "The server returned an invalid option catalog response");
                return;
            }
            ProtocolBody.OptionPageResponse body = (ProtocolBody.OptionPageResponse) envelope.body();
            OptionPage page = body.page();
            try {
                PendingCoreOptionRequest next = pending.accept(page);
                if (page.complete()) {
                    logger().operation("Option Query").with("source", pending.request().sourceReference().canonicalText())
                        .with("requestId", pending.requestId()).with("items", next.items().size())
                        .debug("Option catalog query completed");
                    settleCoreOptionRequest(pending, next.completeCatalog());
                    return;
                }
                if (!pendingCoreOptionRequests.remove(pending.requestId(), pending)) {
                    return;
                }
                cancelPendingSend(pending.requestId().toString());
                if (!OptionCatalogCache.getInstance().continueRequest(pending.request().key())
                    || !sendCoreOptionRequest(next)) {
                    OptionCatalogCache.getInstance().fail(pending.request().key(),
                        "The next option catalog page could not be requested");
                }
            } catch (RuntimeException exception) {
                failCoreOptionRequest(pending, "The server returned an inconsistent option catalog page");
            }
        }
    }

    private void handleRejectedCoreOptionEnvelope(ProtocolEnvelope<Map<String, Object>> envelope,
                                                  PendingCoreOptionRequest pending, int generation) {
        synchronized (coreOptionDispatchLock) {
            ConnectionSource source = inboundSource.get();
            if (!pending.matchesGeneration(generation, source)) {
                return;
            }
            if (!pending.matchesRejection(envelope)) {
                failCoreOptionRequest(pending, "The server returned an invalid option query rejection");
                return;
            }
            String diagnostic = rejectionMessage(envelope);
            boolean retryable = rejectionRetryable(envelope);
            logger().operation("Option Query").with("source", pending.request().sourceReference().canonicalText())
                .with("requestId", pending.requestId()).with("retryable", retryable)
                .with("reason", diagnostic).warn("Option catalog query was rejected");
            failCoreOptionRequest(pending, diagnostic, retryable);
        }
    }

    private boolean settleCoreOptionRequest(PendingCoreOptionRequest pending,
                                            OptionCatalogCache.CompletedCoreCatalog catalog) {
        synchronized (coreOptionDispatchLock) {
            if (pending == null || catalog == null || !pendingCoreOptionRequests.remove(pending.requestId(), pending)) {
                return false;
            }
            cancelPendingSend(pending.requestId().toString());
            if (!currentCoreOptionPublication(pending.request())) {
                OptionCatalogCache.getInstance().retry(pending.request().key());
                return false;
            }
            try {
                return OptionCatalogCache.getInstance().put(pending.request().key(), catalog)
                    != OptionCatalogCache.CoreSettlement.REJECTED;
            } catch (RuntimeException exception) {
                OptionCatalogCache.getInstance().fail(pending.request().key(),
                    "The server returned an invalid option catalog");
                return false;
            }
        }
    }

    private boolean failCoreOptionRequest(PendingCoreOptionRequest pending, String diagnostic) {
        return failCoreOptionRequest(pending, diagnostic, false);
    }

    private boolean failCoreOptionRequest(PendingCoreOptionRequest pending, String diagnostic, boolean retryable) {
        synchronized (coreOptionDispatchLock) {
            if (pending == null || !pendingCoreOptionRequests.remove(pending.requestId(), pending)) {
                return false;
            }
            cancelPendingSend(pending.requestId().toString());
            OptionCatalogCache cache = OptionCatalogCache.getInstance();
            if (retryable) {
                cache.retry(pending.request().key());
            } else {
                cache.fail(pending.request().key(), diagnostic);
            }
            return true;
        }
    }

    private List<PendingCoreOptionRequest> retirePendingCoreOptionRequests(String diagnostic) {
        List<PendingCoreOptionRequest> retired = new ArrayList<>();
        OptionCatalogCache cache = OptionCatalogCache.getInstance();
        for (PendingCoreOptionRequest pending : List.copyOf(pendingCoreOptionRequests.values())) {
            if (pendingCoreOptionRequests.remove(pending.requestId(), pending)) {
                cache.fail(pending.request().key(), diagnostic);
                retired.add(pending);
            }
        }
        return List.copyOf(retired);
    }

    private List<PendingCoreOptionRequest> retirePendingCoreOptionRequestsExcept(
        ReSyncCatalogAuthoringProjection.Snapshot publication, long authorityEpoch, String diagnostic) {
        List<PendingCoreOptionRequest> retired = new ArrayList<>();
        OptionCatalogCache cache = OptionCatalogCache.getInstance();
        for (PendingCoreOptionRequest pending : List.copyOf(pendingCoreOptionRequests.values())) {
            OptionCatalogCache.CoreKey key = pending.request().key();
            boolean current = key.catalogBinding().equals(publication.publication().binding())
                && key.publicationContractVersion().equals(publication.publication().contractVersion())
                && key.publicationChecksum().equals(publication.checksum())
                && key.publicationRevision() == publication.revision() && key.authorityEpoch() == authorityEpoch;
            if (!current && pendingCoreOptionRequests.remove(pending.requestId(), pending)) {
                cache.fail(key, diagnostic);
                retired.add(pending);
            }
        }
        return List.copyOf(retired);
    }

    private void cancelRetiredCoreOptionRequests(List<PendingCoreOptionRequest> retired) {
        for (PendingCoreOptionRequest pending : retired) {
            cancelPendingSend(pending.requestId().toString());
        }
    }

    private void handleAuthoringTemplateEnvelope(ProtocolEnvelope<Map<String, Object>> envelope, int generation) {
        PendingAuthoringTemplateRequest pending = envelope.requestId() == null ? null
            : pendingAuthoringTemplateRequests.get(envelope.requestId());
        if (pending == null) {
            return;
        }
        ConnectionSource source = inboundSource.get();
        if (!pending.matchesResponseIdentity(envelope, generation, source)) {
            return;
        }
        if (!pending.matchesResponseEnvelope(envelope, generation, source)) {
            completeAuthoringTemplateRequest(pending, null);
            return;
        }
        if (!acceptAuthorityEpoch(envelope.authorityEpoch())) {
            completeAuthoringTemplateRequest(pending, null);
            return;
        }
        try {
            if (!(envelope.body() instanceof ProtocolBody.ControlResponse responseBody)
                || responseBody.values().size() != 1 || !responseBody.values().containsKey("response")) {
                throw new IllegalArgumentException("Authoring template response body is invalid");
            }
            AuthoringTemplateResponse response = AuthoringTemplateCodec.INSTANCE.decodeResponse(
                JsonValue.fromJava(responseBody.values().get("response")));
            if (!validAuthoringTemplateResponse(pending, response)) {
                throw new IllegalArgumentException("Authoring template response identity is stale");
            }
            completeAuthoringTemplateRequest(pending, response);
        } catch (RuntimeException exception) {
            logger().operation("Authoring Template").warn("Rejected invalid authoring template response");
            completeAuthoringTemplateRequest(pending, null);
        }
    }

    private void handleRejectedAuthoringTemplateEnvelope(ProtocolEnvelope<Map<String, Object>> envelope, int generation) {
        PendingAuthoringTemplateRequest pending = envelope.requestId() == null ? null
            : pendingAuthoringTemplateRequests.get(envelope.requestId());
        if (pending == null) {
            return;
        }
        ConnectionSource source = inboundSource.get();
        if (!pending.matchesRejectionIdentity(envelope, generation, source)) {
            return;
        }
        if (authoringTemplateRefreshRequired(envelope)) {
            ensureCatalogPublication(true);
        }
        completeAuthoringTemplateRequest(pending, null);
    }

    static boolean authoringTemplateRefreshRequired(ProtocolEnvelope<Map<String, Object>> envelope) {
        if (envelope == null || !(envelope.body() instanceof ProtocolBody.ControlResponse response)) {
            return false;
        }
        Object code = response.values().get("rejectionCode");
        return ProtocolRejectionCode.RESOURCE_REVISION_CONFLICT.wireValue().equals(code);
    }

    private boolean validAuthoringTemplateResponse(PendingAuthoringTemplateRequest pending,
                                                    AuthoringTemplateResponse response) {
        if (pending == null || response == null || !catalogAuthoringAdvertised
            || !catalogAuthorityAllowsGraphInteraction(catalogAuthority)) {
            return false;
        }
        AuthoringTemplateRequest request = pending.request();
        if (!request.resource().equals(response.resource())
            || !request.acknowledgedCatalogKey().equals(response.publicationKey())
            || !request.acknowledgedCatalogKey().catalogBinding().equals(response.catalogBinding())
            || !request.acknowledgedAuthoringPublicationChecksum().equals(response.authoringPublicationChecksum())) {
            return false;
        }
        synchronized (catalogLifecycleLock) {
            Optional<ReSyncCatalogAuthoringProjection.Snapshot> active = activeAuthoringSnapshot();
            if (active.isEmpty()) {
                return false;
            }
            ReSyncCatalogAuthoringProjection.Snapshot snapshot = active.orElseThrow();
            CatalogAuthoringPublication publication = snapshot.publication();
            return snapshot.key().equals(request.acknowledgedCatalogKey())
                && snapshot.checksum().equals(response.authoringPublicationChecksum())
                && publication.compatible()
                && publication.advertisedEditCapabilities().containsAll(response.editCapabilities())
                && authoringCapabilities(publication).containsAll(response.requiredCapabilities());
        }
    }

    private static Set<ContractRef<CapabilityId>> authoringCapabilities(CatalogAuthoringPublication publication) {
        if (publication == null || publication.capabilities() == null) {
            return Set.of();
        }
        return publication.capabilities().stream()
            .filter(entry -> entry != null && entry.editable())
            .map(CatalogAuthoringPublication.Entry::reference)
            .collect(Collectors.toUnmodifiableSet());
    }

    private boolean completeAuthoringTemplateRequest(PendingAuthoringTemplateRequest pending,
                                                     AuthoringTemplateResponse response) {
        if (pending == null || pendingAuthoringTemplateRequests.get(pending.requestId()) != pending) {
            return false;
        }
        Runnable delivery = () -> settleAuthoringTemplateRequest(pending, response);
        Runnable rejected = () -> settleAuthoringTemplateRequest(pending, null);
        return submitConnectionCallback(pending.source(), delivery, true, true, rejected);
    }

    private void settleAuthoringTemplateRequest(PendingAuthoringTemplateRequest pending,
                                                 AuthoringTemplateResponse response) {
        if (!pendingAuthoringTemplateRequests.remove(pending.requestId(), pending)) {
            return;
        }
        cancelPendingSend(pending.requestId().toString());
        pending.callback().accept(response);
    }

    private void handleRejectedProtocolEnvelope(ProtocolEnvelope<Map<String, Object>> envelope) {
        if (!authenticated.get() || envelope.requestId() == null
            || !serverId.equals(envelope.serverId().canonicalText())) {
            return;
        }
        if (!acceptAuthorityEpoch(envelope.authorityEpoch())) {
            failCorrelatedCoreEnvelope(envelope, "The rejected Core graph response used an invalid authority epoch.");
            return;
        }
        PendingTypedResourceRequest typed = pendingTypedResourceRequests.get(envelope.requestId());
        if (typed != null) {
            if (typed.matchesRejection(envelope)) {
                if (typed.mutation() && rejectionRetryable(envelope)) {
                    recoverRejectedTypedMutation(typed);
                } else {
                    failTypedResourceRequest(typed, rejectionMessage(envelope), false);
                }
            }
            return;
        }
        PendingCoreGraphRequest core = pendingCoreGraphRequests.get(envelope.requestId());
        if (core == null) {
            return;
        }
        diagnoseCoreRead(core, "rejection");
        if (!core.matchesRejection(envelope)) {
            failCorePendingWithRetryability(core, "The rejected Core graph response did not match its request.", false);
            return;
        }
        failCorePendingWithRetryability(core, rejectionMessage(envelope), rejectionRetryable(envelope));
    }

    private boolean rejectionRetryable(ProtocolEnvelope<Map<String, Object>> envelope) {
        Object value = null;
        if (envelope.body() instanceof ProtocolBody.ControlResponse response) {
            value = response.values().get("rejectionCode");
        }
        if (value == null) {
            value = envelope.unknown().get("rejectionCode");
        }
        if (!(value instanceof String text) || text.isBlank()) {
            return false;
        }
        try {
            return ProtocolRejectionCode.fromWire(text).retryability() != ProtocolRetryability.NEVER;
        } catch (IllegalArgumentException exception) {
            return false;
        }
    }

    private void recoverRejectedTypedMutation(PendingTypedResourceRequest pending) {
        if (pendingTypedResourceRequests.get(pending.requestId()) != pending
            || !scheduledTypedMutationRecoveries.add(pending.requestId())) {
            return;
        }
        int attempt = typedMutationRecoveryAttempts.merge(pending.requestId(), 1, Integer::sum);
        if (attempt > MAX_TYPED_MUTATION_RECOVERY_REPLAYS) {
            scheduledTypedMutationRecoveries.remove(pending.requestId());
            if (retainTypedTransportMutation(pending)) {
                notifyError("ReSync Resource Update Awaits Recovery. Reconnect To Check Its Result.");
            }
            return;
        }
        try {
            heartbeatScheduler.schedule(() -> {
                scheduledTypedMutationRecoveries.remove(pending.requestId());
                if (pendingTypedResourceRequests.get(pending.requestId()) != pending) {
                    return;
                }
                if (!isConnectionReadyGeneration(pending.transportGeneration())) {
                    retainTypedTransportMutation(pending);
                    return;
                }
                ResourceSaveFence fence = pending.operation() == ResourceOperationKind.CREATE
                    || pending.operation() == ResourceOperationKind.SAVE
                    ? resourceSaveFence(saveRequestId(pending)) : null;
                if ((pending.operation() == ResourceOperationKind.CREATE || pending.operation() == ResourceOperationKind.SAVE)
                    && (fence == null || !currentResourceSaveFence(fence))) {
                    retainTypedTransportMutation(pending);
                    return;
                }
                dispatchTypedResourceRequest(pending, fence);
            }, Duration.ofSeconds(TYPED_MUTATION_RECOVERY_DELAY_SECONDS));
        } catch (RuntimeException exception) {
            scheduledTypedMutationRecoveries.remove(pending.requestId());
            if (retainTypedTransportMutation(pending)) {
                notifyError("ReSync Resource Update Awaits Recovery. Reconnect To Check Its Result.");
            }
        }
    }

    private String rejectionMessage(ProtocolEnvelope<Map<String, Object>> envelope) {
        if (envelope.body() instanceof ProtocolBody.ControlResponse response) {
            Object message = response.values().get("rejectionMessage");
            if (message instanceof String text && !text.isBlank()) {
                return text;
            }
        }
        Object message = envelope.unknown().get("rejectionMessage");
        if (message instanceof String text && !text.isBlank()) {
            return text;
        }
        return switch (envelope.status()) {
            case NOT_FOUND -> "The requested ReSync resource was not found.";
            case READ_ONLY -> "The ReSync resource is read-only.";
            case UPGRADE_REQUIRED -> "The connected ReSync server requires a protocol upgrade.";
            default -> "The ReSync request was rejected.";
        };
    }

    private static UUID rejectionMutationId(ProtocolEnvelope<Map<String, Object>> envelope) {
        if (envelope == null) {
            return null;
        }
        if (envelope.mutationId() != null) {
            return envelope.mutationId();
        }
        if (!(envelope.body() instanceof ProtocolBody.ControlResponse response)) {
            return null;
        }
        Object value = response.values().get("mutationId");
        if (!(value instanceof String text) || text.isBlank()) {
            return null;
        }
        try {
            return UUID.fromString(text);
        } catch (IllegalArgumentException exception) {
            return null;
        }
    }

    private static ServerResourceLocator rejectionResource(ProtocolEnvelope<Map<String, Object>> envelope) {
        if (envelope == null) {
            return null;
        }
        if (envelope.resource() != null) {
            return envelope.resource();
        }
        if (!(envelope.body() instanceof ProtocolBody.ControlResponse response)) {
            return null;
        }
        Object value = response.values().get("resource");
        if (!(value instanceof String text) || text.isBlank()) {
            return null;
        }
        try {
            return ServerResourceLocator.parseCanonicalText(text);
        } catch (IllegalArgumentException exception) {
            return null;
        }
    }

    private void clearTypedResourceListState(PendingTypedResourceRequest pending) {
        if (pending == null || (pending.operation() != ResourceOperationKind.LIST
            && pending.operation() != ResourceOperationKind.QUERY)) {
            return;
        }
        TypedResourceListKey key = new TypedResourceListKey(pending.type(), pending.query());
        activeTypedResourceListCorrelations.remove(key, pending.correlationId());
        typedResourceListResults.remove(pending.correlationId());
    }

    private boolean removePendingTypedResourceRequest(PendingTypedResourceRequest pending) {
        synchronized (transportMutationRetentionLock) {
            if (pending == null || retainedTypedTransportMutations.containsKey(pending.requestId())
                || !pendingTypedResourceRequests.remove(pending.requestId(), pending)) {
                return false;
            }
            clearPendingTypedReplays(pending.requestId());
            typedRequestDeliveries.remove(pending.requestId());
            typedMutationRecoveryAttempts.remove(pending.requestId());
            scheduledTypedMutationRecoveries.remove(pending.requestId());
            return true;
        }
    }

    private PendingTypedResourceRequest removePendingTypedResourceRequest(UUID requestId) {
        synchronized (transportMutationRetentionLock) {
            if (requestId == null || retainedTypedTransportMutations.containsKey(requestId)) {
                return null;
            }
            PendingTypedResourceRequest pending = pendingTypedResourceRequests.remove(requestId);
            typedRequestDeliveries.remove(requestId);
            if (pending != null) {
                clearPendingTypedReplays(requestId);
                typedMutationRecoveryAttempts.remove(requestId);
                scheduledTypedMutationRecoveries.remove(requestId);
            }
            return pending;
        }
    }

    private void clearPendingTypedReplays(UUID requestId) {
        if (requestId == null) {
            return;
        }
        pendingTypedPageReplays.remove(requestId);
        pendingTypedDocumentReplays.remove(requestId);
        pendingAggregateCreateReplays.remove(requestId);
    }

    private void consumeTypedOpenIntent(PendingTypedResourceRequest pending, ReSyncResourceType type, String id) {
        if (pending == null || pending.operation() != ResourceOperationKind.LOAD || !pending.openWhenReceived()) {
            return;
        }
        FlowManager manager = client != null ? client.getFlowManager() : null;
        if (manager == null) {
            return;
        }
        FlowManager.ServerConnectionToken token = captureUiToken(manager);
        if (!manager.isCurrentServerConnection(token)) {
            return;
        }
        removeOpenIntent(pending);
        ScreenManager.getInstance().execute(() -> manager.runIfCurrentServerConnection(token, () -> {
            if (client == null || client.getHost() == null) {
                return;
            }
            FlowEditorScreen studioScreen = FlowEditorScreen.getStudioScreen(serverId);
            if (studioScreen != null) {
                studioScreen.openWorkspaceResource(type.typeId(), id);
                manager.activateOpenStudio(serverId, false);
                return;
            }
            manager.openStudioDocument(serverId, ReSyncProjectMetadata.resourceKey(type.typeId(), id),
                screen -> screen.openWorkspaceDesigner(type.typeId(), id, false));
        }));
    }

    private PendingTypedResourceRequest matchingPendingTypedResourceRequest(
        ProtocolEnvelope<Map<String, Object>> envelope, ResourceDocument<Map<String, Object>> document,
        ServerResourceLocator resource, ReSyncResourceType type) {
        if (envelope == null || type == null || resource == null) {
            return null;
        }
        if (envelope.requestId() != null) {
            PendingTypedResourceRequest pending = pendingTypedResourceRequests.get(envelope.requestId());
            if (pending != null) {
                return pending.matches(envelope, document, resource, type) ? pending : null;
            }
            if (envelope.kind() != ProtocolEnvelope.Kind.EVENT) {
                return null;
            }
        }
        if (envelope.kind() != ProtocolEnvelope.Kind.EVENT || document == null) {
            return null;
        }
        for (PendingTypedResourceRequest pending : pendingTypedResourceRequests.values()) {
            if (pending.matchesEvent(envelope, document, resource, type)) {
                return pending;
            }
        }
        return null;
    }

    private void handleTypedResourceConflict(ProtocolEnvelope<Map<String, Object>> envelope,
                                              PendingTypedResourceRequest pending,
                                              ResourceDocument<Map<String, Object>> document,
                                              ReSyncResourceType type,
                                              ServerResourceLocator resource,
                                              int generation) {
        if (pending == null) {
            return;
        }
        FlowManager manager = client != null ? client.getFlowManager() : null;
        boolean rebasedCreation = false;
        boolean projectionFenceCurrent = generation < 0
            || typedResourceDocumentFenceCurrent(generation, envelope.authorityEpoch());
        if (document != null) {
            GenericResourceProjectionOutcome projection = applyTypedResourceDocument(type, document,
                envelope.authorityEpoch(), false, false, generation);
            if (projection == GenericResourceProjectionOutcome.RETRY) {
                logger().operation("Resource Synchronization").warn("Deferred conflicting generic resource after projection failure");
                return;
            }
            if (projection != GenericResourceProjectionOutcome.APPLIED) {
                return;
            }
            projectionFenceCurrent = generation < 0
                || typedResourceDocumentFenceCurrent(generation, envelope.authorityEpoch());
        }
        if (manager != null && type == ReSyncResourceType.PROJECT_METADATA && pending.mutation()
            && (pending.operation() == ResourceOperationKind.CREATE || pending.operation() == ResourceOperationKind.SAVE)
            && document != null && !document.deleted()) {
            ReSyncProjectMetadata authoritative = decodeProjectMetadata(document);
            FlowManager.ServerConnectionToken conflictToken = captureUiToken(manager);
            if (authoritative != null && pending.mutationId() != null
                && projectionFenceCurrent
                && conflictToken != null && manager.isCurrentServerConnection(conflictToken)) {
                rebasedCreation = manager.rebaseCreationMetadataConflict(serverId, saveRequestId(pending),
                    pending.mutationId().toString(), authoritative);
                if (rebasedCreation) {
                    abandonTypedResourceRequest(pending);
                }
            }
        }
        if (rebasedCreation) {
            return;
        }
        if (document != null && !projectionFenceCurrent) {
            return;
        }
        String message = "The resource changed before the update completed.";
        if (document == null) {
            message = "The resource update was rejected by ReSync.";
        }
        failTypedResourceRequest(pending, message);
    }

    private ReSyncProjectMetadata decodeProjectMetadata(ResourceDocument<Map<String, Object>> document) {
        try {
            JsonElement payload = gson.toJsonTree(document.payload());
            if (!payload.isJsonObject()) {
                return null;
            }
            Object decoded = ReSyncResourceType.PROJECT_METADATA.deserialize(payload.toString());
            return decoded instanceof ReSyncProjectMetadata metadata ? metadata : null;
        } catch (RuntimeException exception) {
            return null;
        }
    }

    private boolean abandonTypedResourceRequest(PendingTypedResourceRequest pending) {
        if (!removePendingTypedResourceRequest(pending)) {
            return false;
        }
        String trackerId = saveRequestId(pending);
        cancelPendingSend(pending.requestId().toString());
        clearTypedResourceListState(pending);
        if (pending.mutation() && (pending.operation() == ResourceOperationKind.CREATE
            || pending.operation() == ResourceOperationKind.SAVE)) {
            releaseResourceSave(trackerId);
        }
        return true;
    }

    private enum GenericResourceProjectionOutcome {
        APPLIED,
        REJECTED,
        RETRY
    }

    private enum ProjectionRetryReason {
        UNKNOWN,
        FLOW_UNAVAILABLE,
        FENCE_CHANGED,
        DELETE_CAS,
        CACHE_CAS,
        SAVE_CAS,
        ACTIVATION_CAS,
        POST_FENCE,
        COMMIT,
        EXCEPTION
    }

    private static final class ProjectionRetryDiagnostic {
        private ProjectionRetryReason reason = ProjectionRetryReason.UNKNOWN;
        private long draftVersion = -1L;
        private long saveGeneration = -1L;
        private boolean currentAtFinish = true;

        private void record(ProjectionRetryReason reason) {
            this.reason = reason != null ? reason : ProjectionRetryReason.UNKNOWN;
        }

        private boolean currentAtFinish() {
            return currentAtFinish;
        }
    }

    private GenericResourceProjectionOutcome applyTypedResourceDocument(ReSyncResourceType type,
                                                                         ResourceDocument<Map<String, Object>> document,
                                                                         long authorityEpoch, boolean markSaved,
                                                                         boolean applyActivationState) {
        return applyTypedResourceDocument(type, document, authorityEpoch, markSaved, applyActivationState, -1);
    }

    private GenericResourceProjectionOutcome applyTypedResourceDocument(ReSyncResourceType type,
                                                                         ResourceDocument<Map<String, Object>> document,
                                                                         long authorityEpoch, boolean markSaved,
                                                                         boolean applyActivationState, int generation) {
        ReSyncResourceRevisionReconciler.Admission admission = null;
        try {
            if (generation >= 0 && !typedResourceDocumentFenceCurrent(generation, authorityEpoch)) {
                return GenericResourceProjectionOutcome.REJECTED;
            }
            boolean exactPageReplay = typedPageProjection.get() != null
                && exactAuthoritativeResourceDocument(type, document, authorityEpoch);
            if (type == null || document == null || !isProtocolResourceType(type)
                || !serverId.equals(document.resource().serverId().canonicalText())
                || !type.typeId().equals(document.resource().resourceType().value())
                || isStaleResourceRevision(type, document.resource().id(), document.revision()) && !exactPageReplay) {
                return GenericResourceProjectionOutcome.REJECTED;
            }
            JsonObject normalizedPayload = null;
            Object item = null;
            if (!document.deleted()) {
                JsonElement payloadElement = gson.toJsonTree(document.payload());
                if (!payloadElement.isJsonObject()) {
                    return GenericResourceProjectionOutcome.REJECTED;
                }
                normalizedPayload = payloadElement.getAsJsonObject();
                item = type.deserialize(normalizedPayload.toString());
                if (item == null || !document.resource().id().equals(type.extractId(item))) {
                    return GenericResourceProjectionOutcome.REJECTED;
                }
            }
            if (exactPageReplay) {
                typedPageProjection.get().add(new TypedPageProjectionEntry(type, document.resource().id(), item,
                    document.deleted(), false, document.revision(),
                    resourceRevisionWatermarks.get(resourceRevisionKey(type, document.resource().id())),
                    null, null, null));
                return GenericResourceProjectionOutcome.APPLIED;
            }
            admission = resourceRevisionReconciler.prepare(
                new ReSyncResourceRevisionReconciler.ResourceResult(serverId, type.typeId(), document.resource().id(),
                    document.revision(), document.mutationId().toString(), document.payloadHash().canonicalText(),
                    document.deleted(), normalizedPayload, authorityEpoch));
            if (!admission.accepted()) {
                return GenericResourceProjectionOutcome.REJECTED;
            }
            FlowManager manager = client != null ? client.getFlowManager() : null;
            if (manager == null) {
                resourceRevisionReconciler.rollback(admission);
                return GenericResourceProjectionOutcome.RETRY;
            }
            BooleanSupplier projectionFence = generation >= 0
                ? () -> typedResourceDocumentFenceCurrent(generation, authorityEpoch) : () -> true;
            return projectGenericResource(manager, type, document.resource().id(), item, document.deleted(), admission,
                markSaved, applyActivationState ? document.activationState() == ResourceActivationState.ACTIVE : null, null,
                projectionFence);
        } catch (RuntimeException exception) {
            if (admission != null && admission.accepted()) {
                resourceRevisionReconciler.rollback(admission);
            }
            return GenericResourceProjectionOutcome.REJECTED;
        }
    }

    private boolean typedResourceDocumentFenceCurrent(int generation, long authorityEpoch) {
        ConnectionSource source = inboundSource.get();
        return generation >= 0 && authorityEpoch >= 1L && authorityEpoch == handshakeAuthorityEpoch
            && isConnectionReadyGeneration(generation) && (source == null || connectionSource(generation) == source)
            && resourceRevisionReconciler.authorityEpoch(serverId) == authorityEpoch;
    }

    private GenericResourceProjectionOutcome projectGenericResource(FlowManager manager, ReSyncResourceType type,
                                                                     String resourceId, Object item, boolean deleted,
                                                                     ReSyncResourceRevisionReconciler.Admission admission,
                                                                     boolean markSaved, Boolean activationState,
                                                                     PendingTypedResourceRequest pending) {
        return projectGenericResource(manager, type, resourceId, item, deleted, admission, markSaved, activationState,
            pending, () -> true, null);
    }

    private GenericResourceProjectionOutcome projectGenericResource(FlowManager manager, ReSyncResourceType type,
                                                                     String resourceId, Object item, boolean deleted,
                                                                     ReSyncResourceRevisionReconciler.Admission admission,
                                                                     boolean markSaved, Boolean activationState,
                                                                     PendingTypedResourceRequest pending,
                                                                     BooleanSupplier projectionFence) {
        return projectGenericResource(manager, type, resourceId, item, deleted, admission, markSaved, activationState,
            pending, projectionFence, null);
    }

    private GenericResourceProjectionOutcome projectGenericResource(FlowManager manager, ReSyncResourceType type,
                                                                     String resourceId, Object item, boolean deleted,
                                                                     ReSyncResourceRevisionReconciler.Admission admission,
                                                                     boolean markSaved, Boolean activationState,
                                                                     PendingTypedResourceRequest pending,
                                                                     BooleanSupplier projectionFence,
                                                                     ProjectionRetryDiagnostic diagnostic) {
        if (preparedProjectMetadataSave(type, markSaved, pending)) {
            return projectPreparedProjectMetadataSave(manager, type, resourceId, item, admission, pending,
                projectionFence, diagnostic);
        }
        FlowManager.ResourceProjectionSnapshot snapshot = null;
        FlowManager.ResourceProjectionLease projectionLease = null;
        Long previousWatermark = typedPageProjection.get() != null
            ? resourceRevisionWatermarks.get(resourceRevisionKey(type, resourceId)) : null;
        boolean openIntentBefore = pendingOpenResources.get(type).contains(resourceId);
        boolean removedMetadata = false;
        long draftVersion = pending != null && pending.mutation()
            ? resourceSaveDraftVersion(saveRequestId(pending)) : -1L;
        try {
            if (projectionFence == null || !projectionFence.getAsBoolean()) {
                resourceRevisionReconciler.rollback(admission);
                return projectionRetry(diagnostic, ProjectionRetryReason.FENCE_CHANGED);
            }
            snapshot = manager.snapshotResourceProjection(serverId, type, resourceId, item);
            projectionLease = manager.beginResourceProjection(snapshot);
            if (!projectionFence.getAsBoolean()) {
                manager.restoreResourceProjection(snapshot, projectionLease);
                resourceRevisionReconciler.rollback(admission);
                restorePendingOpenIntent(type, resourceId, openIntentBefore);
                return projectionRetry(diagnostic, ProjectionRetryReason.FENCE_CHANGED);
            }
            if (deleted) {
                if (!manager.applyResourceDeletionAuthoritative(serverId, type, resourceId, projectionLease)) {
                    manager.restoreResourceProjection(snapshot, projectionLease);
                    resourceRevisionReconciler.rollback(admission);
                    restorePendingOpenIntent(type, resourceId, openIntentBefore);
                    return projectionRetry(diagnostic, ProjectionRetryReason.DELETE_CAS);
                }
                removedMetadata = true;
            } else {
                if (!manager.cacheResourceAuthoritative(serverId, type, item, draftVersion, projectionLease)) {
                    manager.restoreResourceProjection(snapshot, projectionLease);
                    resourceRevisionReconciler.rollback(admission);
                    restorePendingOpenIntent(type, resourceId, openIntentBefore);
                    return projectionRetry(diagnostic, ProjectionRetryReason.CACHE_CAS);
                }
                if (markSaved) {
                    if (!manager.markResourceSavedAuthoritative(serverId, type, resourceId, draftVersion,
                        admission.incoming().revision(), admission.incoming().payloadHash(), projectionLease)) {
                        manager.restoreResourceProjection(snapshot, projectionLease);
                        resourceRevisionReconciler.rollback(admission);
                        restorePendingOpenIntent(type, resourceId, openIntentBefore);
                        return projectionRetry(diagnostic, ProjectionRetryReason.SAVE_CAS);
                    }
                }
                if (activationState != null) {
                    if (!manager.applyResourceActivationStateAuthoritative(serverId, type, resourceId, activationState,
                        projectionLease, item)) {
                        manager.restoreResourceProjection(snapshot, projectionLease);
                        resourceRevisionReconciler.rollback(admission);
                        restorePendingOpenIntent(type, resourceId, openIntentBefore);
                        return projectionRetry(diagnostic, ProjectionRetryReason.ACTIVATION_CAS);
                    }
                }
            }
            if (!projectionFence.getAsBoolean()) {
                manager.restoreResourceProjection(snapshot, projectionLease);
                resourceRevisionReconciler.rollback(admission);
                restorePendingOpenIntent(type, resourceId, openIntentBefore);
                return projectionRetry(diagnostic, ProjectionRetryReason.POST_FENCE);
            }
            ReSyncResourceRevisionReconciler.Decision decision = resourceRevisionReconciler.commit(admission);
            if (!decision.accepted() && decision.outcome() != ReSyncResourceRevisionReconciler.Outcome.DUPLICATE) {
                manager.restoreResourceProjection(snapshot, projectionLease);
                resourceRevisionReconciler.rollback(admission);
                restorePendingOpenIntent(type, resourceId, openIntentBefore);
                return projectionRetry(diagnostic, ProjectionRetryReason.COMMIT);
            }
            recordResourceRevision(type, resourceId, admission.incoming().revision());
            if (deleted) {
                manager.finalizeResourceDeletionAuthoritative(serverId, type, resourceId, projectionLease);
            }
        } catch (RuntimeException exception) {
            try {
                if (snapshot != null) {
                    manager.restoreResourceProjection(snapshot, projectionLease);
                }
                resourceRevisionReconciler.rollback(admission);
                restorePendingOpenIntent(type, resourceId, openIntentBefore);
            } catch (RuntimeException rollbackException) {
                logger().operation("Resource Synchronization").warn("Could not restore generic resource projection");
            }
            return projectionRetry(diagnostic, ProjectionRetryReason.EXCEPTION);
        }
        TypedPageProjection pageProjection = typedPageProjection.get();
        if (pageProjection != null) {
            pageProjection.add(new TypedPageProjectionEntry(type, resourceId, item, deleted, removedMetadata,
                admission.incoming().revision(), previousWatermark, admission, snapshot, projectionLease));
            return GenericResourceProjectionOutcome.APPLIED;
        }
        try {
            if (deleted) {
                manager.notifyResourceDeletionCommitted(serverId, type, resourceId, removedMetadata);
                if (pending != null && pending.operation() == ResourceOperationKind.LOAD && pending.openWhenReceived()) {
                    removeOpenIntent(pending);
                }
            } else {
                if (type != ReSyncResourceType.PROJECT_METADATA
                    || !Boolean.TRUE.equals(aggregateMetadataProjection.get())) {
                    manager.notifyResourceDataReceivedAfterCommit(serverId, type, item);
                }
                if (activationState != null) {
                    manager.notifyResourceActivationCommitted(serverId, type, resourceId, activationState);
                }
                consumeTypedOpenIntent(pending, type, resourceId);
            }
        } catch (RuntimeException exception) {
            logger().operation("Resource Synchronization").warn("Could not deliver a committed resource projection: "
                + exception.getMessage());
        }
        return GenericResourceProjectionOutcome.APPLIED;
    }

    private ProjectionRetryDiagnostic captureProjectionRetrySaveState(ProjectionRetryDiagnostic diagnostic,
                                                                       PendingTypedResourceRequest pending) {
        if (diagnostic == null || pending == null || !pending.mutation()
            || (pending.operation() != ResourceOperationKind.CREATE && pending.operation() != ResourceOperationKind.SAVE)) {
            return diagnostic;
        }
        String requestId = saveRequestId(pending);
        diagnostic.draftVersion = resourceSaveDraftVersion(requestId);
        ResourceSavePreparation preparation = resourceSavePreparation(requestId);
        if (preparation != null) {
            diagnostic.saveGeneration = preparation.draftGeneration();
        }
        return diagnostic;
    }

    private boolean preparedProjectMetadataSave(ReSyncResourceType type, boolean markSaved,
                                                PendingTypedResourceRequest pending) {
        if (!markSaved || type != ReSyncResourceType.PROJECT_METADATA || pending == null || !pending.mutation()
            || (pending.operation() != ResourceOperationKind.CREATE && pending.operation() != ResourceOperationKind.SAVE)) {
            return false;
        }
        ResourceSavePreparation preparation = resourceSavePreparation(saveRequestId(pending));
        return preparation != null && preparation.lease() != null && preparation.draftGeneration() >= 0L;
    }

    private GenericResourceProjectionOutcome projectPreparedProjectMetadataSave(
        FlowManager manager, ReSyncResourceType type, String resourceId, Object item,
        ReSyncResourceRevisionReconciler.Admission admission, PendingTypedResourceRequest pending,
        BooleanSupplier projectionFence, ProjectionRetryDiagnostic diagnostic) {
        if (manager == null) {
            resourceRevisionReconciler.rollback(admission);
            return projectionRetry(diagnostic, ProjectionRetryReason.FLOW_UNAVAILABLE);
        }
        if (projectionFence == null || !projectionFence.getAsBoolean()) {
            resourceRevisionReconciler.rollback(admission);
            return projectionRetry(diagnostic, ProjectionRetryReason.FENCE_CHANGED);
        }
        ResourceSavePreparation preparation = resourceSavePreparation(saveRequestId(pending));
        if (preparation == null || preparation.lease() == null || preparation.draftGeneration() < 0L) {
            resourceRevisionReconciler.rollback(admission);
            return projectionRetry(diagnostic, ProjectionRetryReason.SAVE_CAS);
        }
        FlowManager.ResourceSaveSettlement settlement = manager.markPreparedResourceSavedAuthoritative(serverId, type,
            resourceId, admission.incoming().revision(), admission.incoming().payloadHash(), item, preparation.lease(),
            preparation.draftGeneration(), preparation.draftPayloadHash());
        if (!settlement.accepted()) {
            resourceRevisionReconciler.rollback(admission);
            return projectionRetry(diagnostic, ProjectionRetryReason.SAVE_CAS);
        }
        if (diagnostic != null) {
            diagnostic.currentAtFinish = settlement.currentAtFinish();
        }
        ReSyncResourceRevisionReconciler.Decision decision = resourceRevisionReconciler.commit(admission);
        if (!decision.accepted() && decision.outcome() != ReSyncResourceRevisionReconciler.Outcome.DUPLICATE) {
            return projectionRetry(diagnostic, ProjectionRetryReason.COMMIT);
        }
        recordResourceRevision(type, resourceId, admission.incoming().revision());
        try {
            manager.notifyResourceDataReceivedAfterCommit(serverId, type, item);
            consumeTypedOpenIntent(pending, type, resourceId);
        } catch (RuntimeException exception) {
            logger().operation("Resource Synchronization").warn("Could not deliver a committed resource projection");
        }
        return GenericResourceProjectionOutcome.APPLIED;
    }

    private GenericResourceProjectionOutcome projectionRetry(ProjectionRetryDiagnostic diagnostic,
                                                              ProjectionRetryReason reason) {
        if (diagnostic != null) {
            diagnostic.record(reason);
        }
        return GenericResourceProjectionOutcome.RETRY;
    }

    private void logProjectionDiagnostic(ProtocolEnvelope<Map<String, Object>> envelope,
                                          ResourceDocument<Map<String, Object>> document,
                                          ReSyncResourceType type, ServerResourceLocator resource,
                                          PendingTypedResourceRequest pending, int generation,
                                          ProjectionRetryDiagnostic diagnostic, String message) {
        ResourceOperationKind operation = envelope != null && envelope.body() instanceof ProtocolBody.ResourceDocumentResponse response
            ? response.operation() : pending != null ? pending.operation() : PendingTypedResourceRequest.operationOf(envelope);
        ReLogger diagnosticLogger = logger().operation("Resource Synchronization")
            .with("typeId", type != null ? type.typeId() : "-")
            .with("resourceId", resource != null ? resource.id() : "-")
            .with("operation", operation != null ? operation.name() : "-")
            .with("requestId", envelope != null && envelope.requestId() != null
                ? envelope.requestId() : pending != null ? pending.requestId() : "-")
            .with("correlationId", envelope != null && envelope.correlationId() != null
                ? envelope.correlationId() : pending != null ? pending.correlationId() : "-")
            .with("traceId", envelope != null && envelope.traceId() != null
                ? envelope.traceId() : pending != null ? pending.traceId() : "-")
            .with("generation", generation)
            .with("activeGeneration", activeTransportGeneration)
            .with("authorityEpoch", envelope != null ? envelope.authorityEpoch() : 0L)
            .with("pendingOperation", pending != null ? pending.operation() : "-")
            .with("pendingResource", pending != null && pending.resource() != null
                ? pending.resource().canonicalText() : "root")
            .with("pendingGeneration", pending != null ? pending.transportGeneration() : -1)
            .with("mutation", pending != null && pending.mutation())
            .with("draftVersion", diagnostic != null ? diagnostic.draftVersion : -1L)
            .with("saveGeneration", diagnostic != null ? diagnostic.saveGeneration : -1L)
            .with("currentAtFinish", diagnostic == null || diagnostic.currentAtFinish)
            .with("reason", diagnostic != null ? diagnostic.reason : ProjectionRetryReason.UNKNOWN)
            .with("documentDeleted", document != null && document.deleted());
        diagnosticLogger.warn(message);
        traceLifecycle(serverId, "resource_projection_retry", "resourceKey", type != null ? type.typeId() : "unknown",
            "resourceId", resource != null ? resource.id() : "unknown", "requestId", envelope != null ? envelope.requestId() : null,
            "reason", diagnostic != null ? diagnostic.reason : ProjectionRetryReason.UNKNOWN,
            "saveGeneration", diagnostic != null ? diagnostic.saveGeneration : -1L);
    }

    private void rememberOpenIntent(ReSyncResourceType type, String resourceId) {
        if (!isProtocolResourceType(type) || resourceId == null || resourceId.isBlank()) {
            return;
        }
        OpenResourceKey key = new OpenResourceKey(type, resourceId);
        long now = System.currentTimeMillis();
        int generation = currentOpenIntentGeneration();
        synchronized (openIntentLock) {
            pruneOpenIntentsLocked(now);
            PendingOpenIntent existing = pendingOpenIntents.get(key);
            if (existing == null || !serverId.equals(existing.serverId())) {
                while (pendingOpenIntents.size() >= MAX_RETAINED_OPEN_INTENTS) {
                    evictOldestOpenIntentLocked();
                }
                pendingOpenIntents.put(key, new PendingOpenIntent(serverId, type, resourceId, generation, now));
            }
        }
        pendingOpenResources.computeIfAbsent(type, ignored -> BrowserSafeState.set()).add(resourceId);
    }

    private void removeOpenIntent(ReSyncResourceType type, String resourceId) {
        if (type == null || resourceId == null || resourceId.isBlank()) {
            return;
        }
        OpenResourceKey key = new OpenResourceKey(type, resourceId);
        synchronized (openIntentLock) {
            pendingOpenIntents.remove(key);
        }
        acceptedCoreOpenIntents.remove(key);
        Set<String> pending = pendingOpenResources.get(type);
        if (pending != null) {
            pending.remove(resourceId);
        }
    }

    private void clearOpenIntents() {
        synchronized (openIntentLock) {
            pendingOpenIntents.clear();
        }
        acceptedCoreOpenIntents.clear();
        coreOpenIncompatibilities.clear();
        diagnosedAcceptedCoreOpenWaits.clear();
        pendingOpenResources.values().forEach(Set::clear);
    }

    public Optional<String> coreGraphOpenIncompatibility(ReSyncResourceType type, String resourceId) {
        CoreOpenIncompatibility incompatibility = currentCoreOpenIncompatibility(type, resourceId);
        return incompatibility == null ? Optional.empty() : Optional.of(incompatibility.reason());
    }

    CoreGraphActivationOutcome peekCoreGraphActivation(ReSyncResourceType type, String resourceId) {
        if (type == null || !type.isGraph() || resourceId == null || resourceId.isBlank()) {
            return new CoreGraphActivationOutcome(CoreGraphActivationState.PENDING,
                "Core graph activation requires a graph resource identity.", 0L);
        }
        ServerResourceLocator resource = coreResource(type, resourceId);
        if (resource == null || !isConnectedState()) {
            return new CoreGraphActivationOutcome(CoreGraphActivationState.PENDING,
                "The Core graph connection is unavailable.", 0L);
        }
        GraphResourceState state = resourceRevisionReconciler.graphState(resource).orElse(null);
        CoreGraphResourceProjection.Projection readOnly = resourceRevisionReconciler.graphResources()
            .readOnly(resource).orElse(null);
        ReSyncCatalogAuthoringProjection.Snapshot authoring = activeAuthoringSnapshot().orElse(null);
        if (readOnly != null && (state == null || readOnly.revision() > state.revision())) {
            CatalogBinding resourceBinding = readOnly.graphDocument() != null
                ? readOnly.graphDocument().catalogBinding()
                : readOnly.functionSourceDocument().graph().catalogBinding();
            CoreGraphActivationState bindingState = coreGraphBindingActivation(catalogAuthority,
                authoring != null ? authoring.publication().binding() : null, resourceBinding);
            if (bindingState == CoreGraphActivationState.PENDING) {
                requestCoreAuthoringRediscovery(type, resourceId, readOnly.revision());
                return new CoreGraphActivationOutcome(CoreGraphActivationState.PENDING,
                    "Core graph authoring publication is loading.", readOnly.revision());
            }
            if (!readOnly.hasUnsupportedCapabilities() && bindingState == CoreGraphActivationState.LIVE) {
                return new CoreGraphActivationOutcome(CoreGraphActivationState.PENDING,
                    "Core graph projection is refreshing.", readOnly.revision());
            }
            CoreGraphActivationState activationState = CoreGraphActivationState.INCOMPATIBLE;
            String reason = readOnly.rejectionReason().isBlank()
                ? "The Core graph is read-only in the active authoring publication." : readOnly.rejectionReason();
            return new CoreGraphActivationOutcome(activationState, reason, readOnly.revision());
        }
        if (state != null) {
            if (state.tombstone()) {
                return new CoreGraphActivationOutcome(CoreGraphActivationState.MISSING,
                    "The Core graph was deleted.", state.revision());
            }
            if (state.live()) {
                CatalogBinding resourceBinding = state.graphDocument() != null
                    ? state.graphDocument().catalogBinding()
                    : state.functionSourceDocument().graph().catalogBinding();
                CoreGraphActivationState bindingState = coreGraphBindingActivation(catalogAuthority,
                    authoring != null ? authoring.publication().binding() : null, resourceBinding);
                if (bindingState == CoreGraphActivationState.PENDING) {
                    requestCoreAuthoringRediscovery(type, resourceId, state.revision());
                    return new CoreGraphActivationOutcome(CoreGraphActivationState.PENDING,
                        "Core graph authoring publication is loading.", state.revision());
                }
                if (bindingState == CoreGraphActivationState.INCOMPATIBLE) {
                    return new CoreGraphActivationOutcome(CoreGraphActivationState.INCOMPATIBLE,
                        "The graph catalog binding does not match the active authoring publication.", state.revision());
                }
                return new CoreGraphActivationOutcome(CoreGraphActivationState.LIVE, "", state.revision());
            }
        }
        if (catalogAuthority == CatalogAuthority.TYPED_PUBLICATION && isResourceListAuthoritative(type)) {
            return new CoreGraphActivationOutcome(CoreGraphActivationState.MISSING,
                "The authoritative Core resource list does not contain this graph.", 0L);
        }
        return new CoreGraphActivationOutcome(CoreGraphActivationState.PENDING,
            "Core graph authority has not settled.", 0L);
    }

    static CoreGraphActivationState coreGraphBindingActivation(CatalogAuthority authority,
                                                                CatalogBinding activeBinding,
                                                                CatalogBinding resourceBinding) {
        if (authority != CatalogAuthority.TYPED_PUBLICATION || activeBinding == null) {
            return CoreGraphActivationState.PENDING;
        }
        return activeBinding.equals(resourceBinding)
            ? CoreGraphActivationState.LIVE : CoreGraphActivationState.INCOMPATIBLE;
    }

    static boolean admitsCoreAuthoringRediscovery(int attempts, long nowNanos, long nextAtNanos) {
        return attempts >= 0 && attempts < MAX_CORE_AUTHORING_REDISCOVERY_ATTEMPTS && nowNanos >= nextAtNanos;
    }

    private void requestCoreAuthoringRediscovery(ReSyncResourceType type, String resourceId, long revision) {
        if (!catalogAuthoringAdvertised || shutdownRequested || type == null || resourceId == null
            || resourceId.isBlank() || !isConnected()) {
            return;
        }
        ensureCatalogPublication(true);
    }

    private CoreOpenIncompatibility currentCoreOpenIncompatibility(ReSyncResourceType type, String resourceId) {
        if (type == null || !type.isGraph() || resourceId == null || resourceId.isBlank()) {
            return null;
        }
        OpenResourceKey key = new OpenResourceKey(type, resourceId);
        CoreOpenIncompatibility incompatibility = coreOpenIncompatibilities.get(key);
        if (incompatibility == null) {
            return null;
        }
        Optional<ReSyncCatalogAuthoringProjection.Snapshot> activeSnapshot = activeAuthoringSnapshot();
        boolean publicationChanged = incompatibility.authoringSnapshot() == null
            ? activeSnapshot.isPresent() : activeSnapshot.filter(incompatibility.authoringSnapshot()::equals).isEmpty();
        if (incompatibility.transportGeneration() != currentOpenIntentGeneration() || publicationChanged) {
            coreOpenIncompatibilities.remove(key, incompatibility);
            return null;
        }
        return incompatibility;
    }

    private void removeOpenIntent(PendingTypedResourceRequest pending) {
        if (pending == null || pending.operation() != ResourceOperationKind.LOAD || !pending.openWhenReceived()
            || pending.resource() == null) {
            return;
        }
        removeOpenIntentIfGeneration(pending.type(), pending.resource().id(), pending.transportGeneration());
    }

    private void removeOpenIntent(PendingCoreGraphRequest pending) {
        if (pending == null || pending.operation() != ResourceOperationKind.LOAD
            || !pendingCoreOpenRequests.contains(pending.requestId()) || pending.resource() == null) {
            return;
        }
        removeOpenIntentIfGeneration(pending.type(), pending.resource().id(), pending.transportGeneration());
    }

    private void removeOpenIntentIfGeneration(ReSyncResourceType type, String resourceId, int generation) {
        if (type == null || resourceId == null || resourceId.isBlank()) {
            return;
        }
        OpenResourceKey key = new OpenResourceKey(type, resourceId);
        boolean removed = false;
        synchronized (openIntentLock) {
            PendingOpenIntent intent = pendingOpenIntents.get(key);
            if (intent != null && intent.transportGeneration() == generation) {
                pendingOpenIntents.remove(key, intent);
                removed = true;
            }
        }
        if (removed) {
            acceptedCoreOpenIntents.computeIfPresent(key, (ignored, accepted) ->
                accepted.transportGeneration() == generation ? null : accepted);
            Set<String> pending = pendingOpenResources.get(type);
            if (pending != null) {
                pending.remove(resourceId);
            }
        }
    }

    private void updateOpenIntentGeneration(ReSyncResourceType type, String resourceId, int generation) {
        if (type == null || resourceId == null || resourceId.isBlank() || generation < 0) {
            return;
        }
        OpenResourceKey key = new OpenResourceKey(type, resourceId);
        synchronized (openIntentLock) {
            PendingOpenIntent existing = pendingOpenIntents.get(key);
            if (existing != null && serverId.equals(existing.serverId())
                && existing.transportGeneration() != generation) {
                pendingOpenIntents.put(key, existing.withGeneration(generation));
            }
        }
    }

    private int currentOpenIntentGeneration() {
        int generation = activeTransportGeneration;
        return generation >= 0 ? generation : currentConnectionGeneration();
    }

    private boolean hasPendingOpenLoad(ReSyncResourceType type, String resourceId) {
        if (type == null || resourceId == null || resourceId.isBlank()) {
            return false;
        }
        int generation = activeTransportGeneration;
        if (generation < 0) {
            return false;
        }
        for (PendingCoreGraphRequest pending : pendingCoreGraphRequests.values()) {
            if (pending != null && pending.operation() == ResourceOperationKind.LOAD
                && pending.transportGeneration() == generation && pending.resource() != null
                && pending.type() == type && resourceId.equals(pending.resource().id())
                && pendingCoreOpenRequests.contains(pending.requestId())) {
                return true;
            }
        }
        for (PendingTypedResourceRequest pending : pendingTypedResourceRequests.values()) {
            if (pending != null && pending.operation() == ResourceOperationKind.LOAD
                && pending.transportGeneration() == generation && pending.openWhenReceived()
                && pending.resource() != null && pending.type() == type
                && resourceId.equals(pending.resource().id())) {
                return true;
            }
        }
        return false;
    }

    private boolean openResourceDispatchReady() {
        int generation = activeTransportGeneration;
        return generation >= 0 && isConnectionReadyGeneration(generation) && sessionHydrationReady();
    }

    private void retryPendingOpenLoads(int generation) {
        if (!isConnectionReadyGeneration(generation) || !sessionHydrationReady()) {
            return;
        }
        List<PendingOpenIntent> intents;
        synchronized (openIntentLock) {
            pruneOpenIntentsLocked(System.currentTimeMillis());
            intents = new ArrayList<>(pendingOpenIntents.values());
        }
        for (PendingOpenIntent intent : intents) {
            if (intent == null || !serverId.equals(intent.serverId()) || intent.type() == null
                || intent.resourceId() == null || intent.resourceId().isBlank()
                || !isConnectionReadyGeneration(generation)) {
                continue;
            }
            if (hasPendingOpenLoad(intent.type(), intent.resourceId())) {
                continue;
            }
            updateOpenIntentGeneration(intent.type(), intent.resourceId(), generation);
            requestResource(intent.type(), intent.resourceId(), true);
        }
    }

    private void pruneOpenIntentsLocked(long now) {
        long cutoff = now - OPEN_INTENT_RETENTION_MILLIS;
        for (Map.Entry<OpenResourceKey, PendingOpenIntent> entry : List.copyOf(pendingOpenIntents.entrySet())) {
            PendingOpenIntent intent = entry.getValue();
            if (intent == null || now < intent.createdAtMillis()
                || intent.createdAtMillis() < cutoff || !serverId.equals(intent.serverId())) {
                if (pendingOpenIntents.remove(entry.getKey(), intent)) {
                    acceptedCoreOpenIntents.remove(entry.getKey());
                    Set<String> pending = pendingOpenResources.get(entry.getKey().type());
                    if (pending != null) {
                        pending.remove(entry.getKey().resourceId());
                    }
                }
            }
        }
    }

    private void evictOldestOpenIntentLocked() {
        Map.Entry<OpenResourceKey, PendingOpenIntent> oldest = null;
        for (Map.Entry<OpenResourceKey, PendingOpenIntent> entry : pendingOpenIntents.entrySet()) {
            if (oldest == null || entry.getValue().createdAtMillis() < oldest.getValue().createdAtMillis()) {
                oldest = entry;
            }
        }
        if (oldest == null || !pendingOpenIntents.remove(oldest.getKey(), oldest.getValue())) {
            return;
        }
        acceptedCoreOpenIntents.remove(oldest.getKey());
        Set<String> pending = pendingOpenResources.get(oldest.getKey().type());
        if (pending != null) {
            pending.remove(oldest.getKey().resourceId());
        }
    }

    private void restorePendingOpenIntent(ReSyncResourceType type, String resourceId, boolean present) {
        if (type == null || resourceId == null || resourceId.isBlank()) {
            return;
        }
        if (present) {
            rememberOpenIntent(type, resourceId);
        } else {
            removeOpenIntent(type, resourceId);
        }
    }

    private boolean shouldRetainOpenIntent(PendingTypedResourceRequest pending) {
        return pending != null && pending.operation() == ResourceOperationKind.LOAD
            && pending.openWhenReceived() && transientOpenIntentGeneration(pending.transportGeneration());
    }

    private boolean shouldRetainOpenIntent(PendingCoreGraphRequest pending) {
        return shouldRetainOpenIntent(pending, pending != null
            && pendingCoreOpenRequests.contains(pending.requestId()));
    }

    private boolean shouldRetainOpenIntent(PendingCoreGraphRequest pending, boolean openIntent) {
        return openIntent && pending != null && pending.operation() == ResourceOperationKind.LOAD
            && transientOpenIntentGeneration(pending.transportGeneration());
    }

    private boolean transientOpenIntentGeneration(int generation) {
        return generation < 0 || activeTransportGeneration < 0 || activeTransportGeneration != generation
            || !isConnectionReadyGeneration(generation);
    }

    private void failTypedResourceRequest(PendingTypedResourceRequest pending, String message) {
        failTypedResourceRequest(pending, message, true, shouldRetainOpenIntent(pending));
    }

    private void failTypedResourceRequest(PendingTypedResourceRequest pending, String message, boolean retryable) {
        failTypedResourceRequest(pending, message, retryable, shouldRetainOpenIntent(pending));
    }

    private void failTypedResourceRequest(PendingTypedResourceRequest pending, String message, boolean retryable,
                                           boolean retainOpenIntent) {
        synchronized (transportMutationRetentionLock) {
            if (pending == null || retainedTypedTransportMutations.containsKey(pending.requestId())
                || !removePendingTypedResourceRequest(pending)) {
                return;
            }
        }
        cancelPendingSend(pending.requestId().toString());
        clearTypedResourceListState(pending);
        if (!retainOpenIntent) {
            removeOpenIntent(pending);
        }
        String reason = message == null || message.isBlank() ? "The resource update failed." : message;
        traceLifecycle(serverId, reason.contains("did not confirm") ? "settlement_timeout" : "wire_failed",
            "serverId", serverId, "resourceKey", temporaryLifecycleResourceKey(pending.type(), pending.resource()),
            "operation", pending.operation(), "requestId", pending.requestId(), "mutationId", pending.mutationId(),
            "generation", pending.transportGeneration(), "authorityEpoch", handshakeAuthorityEpoch, "revision",
            pending.expectedRevision(), "elapsedMs", temporaryLifecycleElapsed(pending.requestId(), true), "reason",
            boundedCoreDiagnostic(reason));
        if (!pending.mutation()) {
            logger().operation("Resource Synchronization").warn("Typed resource request failed: type="
                + pending.type().typeId() + ",operation=" + pending.operation() + ",resource="
                + (pending.resource() != null ? pending.resource().canonicalText() : "root") + ",request="
                + pending.requestId() + ",correlation=" + pending.correlationId() + ",trace=" + pending.traceId()
                + ",generation=" + pending.transportGeneration() + ",reason=" + reason);
            return;
        }
        FlowManager manager = client != null ? client.getFlowManager() : null;
        if (pending.operation() == ResourceOperationKind.ACTIVATE) {
            if (manager != null) {
                manager.completeResourceActivation(serverId, pending.type(), pending.resource().id(),
                    pending.activationEnabled(), pending.legacyRequestId(), false, reason, true);
            }
            return;
        }
        if (pending.operation() == ResourceOperationKind.DELETE) {
            if (manager != null) {
                manager.failResourceDelete(serverId, pending.type(), pending.resource().id(), reason);
            }
            return;
        }
        if (pending.operation() != ResourceOperationKind.CREATE && pending.operation() != ResourceOperationKind.SAVE) {
            return;
        }
        if (pending.mutationId() != null) {
            pendingCreatePresentations.remove(pending.mutationId());
        }
        String trackerId = saveRequestId(pending);
        ResourceSaveFence fence = resourceSaveFence(trackerId);
        BooleanSupplier currentPayload = resourceSavePayloadFence(trackerId);
        if (DesignerSaveNotifications.isResumableRequest(serverId, trackerId)) {
            releaseResourceSave(trackerId);
            if (!notifyResumableResourceSaveFailure(pending.type(), pending.resource().id(), trackerId, retryable, reason)) {
                DesignerSaveNotifications.SaveTarget failedSave = DesignerSaveNotifications.failRequest(serverId, trackerId, reason);
                markResourceFailedCurrent(failedSave, fence);
                if (failedSave == null && pending.type() == ReSyncResourceType.PROJECT_METADATA) {
                    executeCurrentServerUi(manager, fence != null ? fence.connectionToken() : null,
                        () -> {
                            if (currentPayload.getAsBoolean()) {
                                markResourceFailed(manager, pending.type(), pending.resource().id());
                            }
                        });
                }
            }
            return;
        }
        completeResourceSave(trackerId);
        DesignerSaveNotifications.SaveTarget failedSave = DesignerSaveNotifications.failRequest(serverId, trackerId, reason);
        markResourceFailedCurrent(failedSave, fence);
        if (failedSave == null && pending.type() == ReSyncResourceType.PROJECT_METADATA) {
            executeCurrentServerUi(manager, fence != null ? fence.connectionToken() : null,
                () -> {
                    if (currentPayload.getAsBoolean()) {
                        markResourceFailed(manager, pending.type(), pending.resource().id());
                    }
                });
        }
    }

    private String saveRequestId(PendingTypedResourceRequest pending) {
        if (pending == null) {
            return "";
        }
        if (pending.legacyRequestId() != null && !pending.legacyRequestId().isBlank()) {
            return pending.legacyRequestId();
        }
        return pending.requestId().toString();
    }

    private boolean isCoreGraphEnvelope(ProtocolEnvelope<Map<String, Object>> envelope) {
        if (envelope == null) {
            return false;
        }
        if (envelope.body() instanceof ProtocolBody.ResourcePageResponse response) {
            return response.operation() != null && (response.operation() == ResourceOperationKind.LIST
                || response.operation() == ResourceOperationKind.QUERY)
                && coreOperation(envelope, response.operation())
                && envelope.resource() == null
                && envelope.requestId() != null
                && (RESOURCE_DOCUMENT_TYPE.equals(envelope.payloadType())
                    || RESOURCE_PAGE_TYPE.equals(envelope.payloadType()))
                && corePageBelongsToPendingRequest(envelope, response);
        }
        if (envelope.body() instanceof ProtocolBody.ResourceDocumentResponse response) {
            ResourceDocument<?> document = response.document();
            ReSyncResourceType type = coreGraphType(document.resource());
            if (type == null) {
                return false;
            }
            return response.operation() != ResourceOperationKind.ACTIVATE
                || coreCapabilityEnvelope(envelope) || isCoreAssetPayload(document.payload());
        }
        if (envelope.body() instanceof ProtocolBody.ConflictResponse conflict) {
            ReSyncResourceType type = coreGraphType(conflict.requestedResource());
            if (type == null) {
                return false;
            }
            ResourceDocument<?> current = conflict.current();
            if (current == null) {
                return !isResourceActivationEnvelope(envelope) || coreCapabilityEnvelope(envelope);
            }
            return !isResourceActivationEnvelope(envelope) || coreCapabilityEnvelope(envelope)
                || isCoreAssetPayload(current.payload());
        }
        return false;
    }

    private boolean corePageBelongsToPendingRequest(ProtocolEnvelope<Map<String, Object>> envelope,
                                                     ProtocolBody.ResourcePageResponse response) {
        UUID requestId = envelope.requestId();
        if (pendingTypedResourceRequests.containsKey(requestId)) {
            return false;
        }
        if (pendingCoreGraphRequests.containsKey(requestId)) {
            return true;
        }
        return !response.page().items().isEmpty() && response.page().items().stream().anyMatch(this::isCoreGraphDocument);
    }

    private boolean isCoreGraphDocument(ResourceDocument<?> document) {
        return document != null && coreGraphType(document.resource()) != null;
    }

    private boolean isCoreAssetPayload(Object payload) {
        if (!(payload instanceof Map<?, ?> values)) {
            return false;
        }
        return values.containsKey(CoreGraphResourceProjection.ASSET_FORMAT_VERSION)
            || values.containsKey(CoreGraphResourceProjection.ASSET_REVISION)
            || values.containsKey(CoreGraphResourceProjection.ASSET_MUTATION_ID)
            || values.containsKey(CoreGraphResourceProjection.ASSET_HASH)
            || values.containsKey(CoreGraphResourceProjection.CORE_PAYLOAD_KIND)
            || values.containsKey(CoreGraphResourceProjection.CORE_PAYLOAD_VERSION);
    }

    private boolean coreCapabilityEnvelope(ProtocolEnvelope<Map<String, Object>> envelope) {
        return envelope.capabilities().stream().anyMatch(capability ->
            "restudio.resync".equals(capability.owner().canonicalText())
                && Set.of("asset_integrity", "resource_revisions", "opaque_resources").contains(capability.id().value()));
    }

    private ReSyncResourceType coreGraphType(ServerResourceLocator resource) {
        if (resource == null || !"restudio.resync".equals(resource.owner().canonicalText())) {
            return null;
        }
        ReSyncResourceType type = ReSyncResourceType.byTypeId(resource.resourceType().value());
        return type != null && type.isGraph() ? type : null;
    }

    private void handleCoreGraphEnvelope(ProtocolEnvelope<Map<String, Object>> envelope, int generation) {
        long responseApplyStarted = System.nanoTime();
        if (!authenticated.get()) {
            return;
        }
        boolean valid;
        try {
            valid = validCoreEnvelope(envelope);
        } catch (RuntimeException exception) {
            failCorrelatedCoreEnvelope(envelope, "The server returned a malformed Core graph response.");
            return;
        }
        if (!valid) {
            if (isResourceActivationEnvelope(envelope)) {
                return;
            }
            failCorrelatedCoreEnvelope(envelope, "The server returned an invalid Core graph response.");
            return;
        }
        if (generation >= 0 && !isConnectionReadyGeneration(generation)) {
            return;
        }
        if (!acceptAuthorityEpoch(envelope.authorityEpoch())) {
            failCorrelatedCoreEnvelope(envelope, "The Core graph response used an invalid authority epoch.");
            return;
        }
        PendingCoreGraphRequest pending = matchingPendingCoreGraphRequest(envelope);
        if (envelope.requestId() != null && pending == null && pendingCoreGraphRequests.containsKey(envelope.requestId())) {
            if (isResourceActivationEnvelope(envelope)) {
                return;
            }
            failCorrelatedCoreEnvelope(envelope, "The Core graph response did not match its request.");
            return;
        }
        if (envelope.kind() != ProtocolEnvelope.Kind.EVENT && pending == null) {
            return;
        }
        if (envelope.kind() == ProtocolEnvelope.Kind.RESPONSE && pending == null) {
            return;
        }
        if (pending != null && envelope.kind() != ProtocolEnvelope.Kind.EVENT) {
            CoreRequestRecovery recovery = coreRequestRecoveries.get(pending.requestId());
            int attempt = recovery != null ? recovery.responseReceived() : 0;
            traceLifecycle(serverId, "response_received", "serverId", serverId, "type", pending.type().typeId(), "id",
                boundedCoreDiagnostic(pending.resource() == null ? "catalog" : pending.resource().id()), "operation",
                pending.operation(), "requestId", pending.requestId(), "correlationId", pending.correlationId(), "traceId",
                pending.traceId(), "mutationId", pending.mutationId(), "generation", generation, "authorityEpoch",
                envelope.authorityEpoch(), "attempt", attempt, "elapsedMs",
                temporaryLifecycleElapsed(pending.requestId(), false));
            if (recovery != null && attempt > 0) {
                heartbeatScheduler.schedule(() -> handleCoreRequestDeadline(pending, recovery, attempt, true), Duration.ofSeconds(CORE_RESPONSE_SETTLEMENT_TIMEOUT_SECONDS));
            }
        }
        ReSyncCatalogAuthoringProjection.Snapshot authoringSnapshot = activeAuthoringSnapshot()
            .filter(ignored -> catalogAuthority == CatalogAuthority.TYPED_PUBLICATION).orElse(null);
        CatalogAuthoringPublication authoringPublication = authoringSnapshot != null
            ? authoringSnapshot.publication() : null;
        Collection<String> supportedCapabilities = coreResourceCapabilities(authoringPublication);
        if (envelope.body() instanceof ProtocolBody.ResourcePageResponse) {
            synchronized (coreListGenerationLock) {
                try {
                    if (pending == null || !pending.matchesPage(envelope)) {
                        failCorePending(pending, "The Core graph page did not match its request.");
                        return;
                    }
                    CoreGraphResourceProjection.PageProjection page = CoreGraphResourceProjection
                        .projectPage(envelope, supportedCapabilities,
                            authoringPublication != null ? authoringPublication.binding() : null);
                    if (!page.accepted() || page.items().stream().anyMatch(projection ->
                        coreGraphType(projection.resource()) != pending.type())) {
                        failCorePending(pending, "The server returned an invalid Core graph page.");
                        return;
                    }
                    traceLifecycle(serverId, "wire_accepted", "serverId", serverId, "resourceKey",
                        pending.type().typeId() + ":catalog", "operation", pending.operation(), "requestId",
                        pending.requestId(), "mutationId", pending.mutationId(), "generation", generation,
                        "authorityEpoch", envelope.authorityEpoch(), "revision", envelope.revision(), "memberCount",
                        page.items().size(), "elapsedMs", temporaryLifecycleElapsed(pending.requestId(), false));
                    if (!isCurrentCoreListGeneration(pending)
                        || (generation >= 0 && !isConnectionReadyGeneration(generation))) {
                        return;
                    }
                    for (CoreGraphResourceProjection.Projection projection : page.items()) {
                        boolean applied;
                        synchronized (catalogLifecycleLock) {
                            applied = !projection.live() || currentCoreAuthoringSnapshot(authoringSnapshot);
                            if (applied) {
                                applyCoreProjection(projection, coreRediscoveryResponse(envelope, pending));
                            }
                        }
                        if (!applied) {
                            failCorePending(pending, "The active Core authoring catalog changed before the page was applied.");
                            return;
                        }
                    }
                    Set<ServerResourceLocator> resources = new HashSet<>();
                    Set<ServerResourceLocator> tombstones = new HashSet<>();
                    CoreResourcePageCursor previous = coreResourcePageCursors.get(envelope.correlationId());
                    if (previous != null && previous.type() == pending.type() && previous.operation() == page.operation()) {
                        resources.addAll(previous.resources());
                        tombstones.addAll(previous.tombstones());
                    }
                    for (CoreGraphResourceProjection.Projection item : page.items()) {
                        resources.add(item.resource());
                        if (item.tombstoned()) {
                            tombstones.add(item.resource());
                        } else {
                            tombstones.remove(item.resource());
                        }
                    }
                    CoreResourcePageCursor cursor = new CoreResourcePageCursor(
                        envelope.requestId(), envelope.correlationId(), pending.type(), page.operation(), page.nextCursor(),
                        page.complete(), resources, tombstones);
                    coreResourcePageCursors.put(envelope.correlationId(), cursor);
                    corePageContinuations.remove(pending.correlationId());
                    if (!page.complete()) {
                        corePageContinuations.put(pending.correlationId(), new CorePageContinuation(pending.type(),
                            pending.correlationId(), pending.traceId(), pending.query(), page.nextCursor(), page.operation()));
                        if (!requestCoreResourcePage(pending.type(), pending.correlationId())) {
                            failCorePending(pending, "The next Core graph page could not be requested.");
                            return;
                        }
                    } else {
                        notifyCoreGraphListComplete(cursor, pending);
                    }
                    if (!pendingCoreGraphRequests.remove(pending.requestId(), pending)) {
                        return;
                    }
                    coreRequestRecoveries.remove(pending.requestId());
                    cancelPendingSend(pending.requestId().toString());
                    temporaryLifecycleRequestStarts.remove(pending.requestId());
                } catch (RuntimeException exception) {
                    failCorePending(pending, "The server returned an invalid Core graph page.");
                    return;
                }
            }
            return;
        }
        if (envelope.body() instanceof ProtocolBody.ConflictResponse conflict && conflict.current() == null) {
            if (pending == null) {
                return;
            }
            consumeCoreOpenIntent(pending, null, null);
            try {
                notifyCoreGraphMutationResult(envelope, pending, null, generation);
            } catch (RuntimeException exception) {
                cancelPendingSend(pending.requestId().toString());
            }
            handleCoreConflictWithoutCurrent(envelope, conflict.requestedResource(), pending);
            return;
        }
        CoreGraphResourceProjection.Projection projection;
        try {
            projection = CoreGraphResourceProjection.project(envelope, supportedCapabilities,
                authoringPublication != null ? authoringPublication.binding() : null);
        } catch (RuntimeException exception) {
            failCorePending(pending, "The server returned an invalid Core graph response.");
            return;
        }
        if (!projection.accepted() || coreGraphType(projection.resource()) == null) {
            failCorePending(pending, "The server returned an invalid Core graph response.");
            return;
        }
        traceLifecycle(serverId, "wire_accepted", "serverId", serverId, "resourceKey",
            temporaryLifecycleResourceKey(coreGraphType(projection.resource()), projection.resource()), "operation",
            pending != null ? pending.operation() : envelope.operation().id().value(), "requestId", envelope.requestId(),
            "mutationId", envelope.mutationId(), "generation", generation, "authorityEpoch", envelope.authorityEpoch(),
            "revision", projection.revision(), "elapsedMs", temporaryLifecycleElapsed(envelope.requestId(), false));
        if (isResourceActivationEnvelope(envelope)) {
            boolean validActivation;
            try {
                validActivation = validCoreActivationResponse(envelope, projection.resourceDocument());
            } catch (RuntimeException exception) {
                validActivation = false;
            }
            if (!validActivation) {
                failCorePending(pending, "The server returned an invalid Core activation response.");
                return;
            }
        }
        if (pending != null && envelope.kind() != ProtocolEnvelope.Kind.EVENT
            && generation >= 0 && !isConnectionReadyGeneration(generation)) {
            return;
        }
        CoreActivationApplication coreActivation = null;
        try {
            boolean applied;
            synchronized (catalogLifecycleLock) {
                applied = !projection.live() || currentCoreAuthoringSnapshot(authoringSnapshot);
                if (applied) {
                    if (isResourceActivationEnvelope(envelope)) {
                        coreActivation = applyCoreActivation(projection);
                    } else {
                        applyCoreProjection(projection, coreRediscoveryResponse(envelope, pending));
                    }
                }
            }
            if (!applied) {
                failCorePending(pending, "The active Core authoring catalog changed before the resource was applied.");
                return;
            }
            if (isResourceActivationEnvelope(envelope)) {
                if (coreActivation == null) {
                    failCorePending(pending, "The Core activation response could not be applied atomically.");
                    return;
                }
            }
            consumeCoreOpenIntent(pending, projection, authoringSnapshot);
            if (pending != null) {
                traceLifecycle(serverId, "authoritative_projection_applied", "serverId", serverId, "type",
                    pending.type().typeId(), "id", boundedCoreDiagnostic(pending.resource() == null
                        ? "catalog" : pending.resource().id()), "operation", pending.operation(), "requestId",
                    pending.requestId(), "correlationId", pending.correlationId(), "traceId", pending.traceId(),
                    "mutationId", pending.mutationId(), "generation", generation, "authorityEpoch",
                    envelope.authorityEpoch(), "revision", projection.revision(), "responseApplyMs",
                    BrowserSafeState.nanosToMillis(Math.max(0L, System.nanoTime() - responseApplyStarted)), "elapsedMs",
                    temporaryLifecycleElapsed(pending.requestId(), false));
            }
        } catch (RuntimeException exception) {
            failCorePending(pending, "The Core graph response could not be applied.");
            return;
        }
        try {
            notifyCoreGraphMutationResult(envelope, pending, projection, generation);
        } catch (RuntimeException exception) {
            failCorePending(pending, "The Core graph response could not settle its mutation.");
            return;
        }
        if (coreActivation != null && coreActivation.pending() != null) {
            completeCoreActivation(projection, coreActivation.pending());
        } else if (pending != null && envelope.kind() != ProtocolEnvelope.Kind.EVENT) {
            if (!pendingCoreGraphRequests.remove(pending.requestId(), pending)) {
                return;
            } else {
                coreRequestRecoveries.remove(pending.requestId());
                cancelPendingSend(pending.requestId().toString());
                if (pending.mutationId() == null) {
                    traceLifecycle(serverId, "read_settlement_complete", "serverId", serverId, "resourceKey",
                        temporaryLifecycleResourceKey(pending.type(), pending.resource()), "operation",
                        pending.operation(), "requestId", pending.requestId(), "mutationId", null, "generation",
                        generation, "authorityEpoch", envelope.authorityEpoch(), "revision", projection.revision(),
                        "elapsedMs", temporaryLifecycleElapsed(pending.requestId(), true));
                }
            }
        }
    }

    private boolean isCurrentCoreListGeneration(PendingCoreGraphRequest pending) {
        if (pending == null || (pending.operation() != ResourceOperationKind.LIST
            && pending.operation() != ResourceOperationKind.QUERY)) {
            return false;
        }
        UUID active = activeCoreListCorrelations.get(new CoreListKey(pending.type(), pending.query()));
        return active == null || active.equals(pending.correlationId());
    }

    private boolean validCoreEnvelope(ProtocolEnvelope<Map<String, Object>> envelope) {
        if (envelope == null || !serverId.equals(envelope.serverId().canonicalText())
            || envelope.correlationId() == null || envelope.operation() == null
            || !"restudio.resync".equals(envelope.operation().owner().canonicalText())
            || envelope.payloadType() == null
            || !"restudio.resync".equals(envelope.payloadType().owner().canonicalText())) {
            return false;
        }
        if (envelope.body() instanceof ProtocolBody.ResourcePageResponse response) {
            return envelope.kind() == ProtocolEnvelope.Kind.RESPONSE
                && (envelope.status() == ProtocolEnvelope.Status.OK || envelope.status() == ProtocolEnvelope.Status.ACCEPTED)
                && envelope.requestId() != null && envelope.resource() == null && envelope.mutationId() == null
                && envelope.payloadHash() == null && !envelope.deleted()
                && (response.operation() == ResourceOperationKind.LIST || response.operation() == ResourceOperationKind.QUERY)
                && RESOURCE_PAGE_TYPE.equals(envelope.payloadType())
                && coreOperation(envelope, response.operation());
        }
        if (!"resource.document".equals(envelope.payloadType().id().value())) {
            return false;
        }
        if (envelope.body() instanceof ProtocolBody.ResourceDocumentResponse response) {
            ResourceDocument<?> document = response.document();
            ReSyncResourceType type = coreGraphType(document.resource());
            if (type == null || envelope.resource() == null || !envelope.resource().equals(document.resource())
                || !coreOperation(envelope, response.operation())) {
                return false;
            }
            if (envelope.kind() == ProtocolEnvelope.Kind.CONFLICT || envelope.kind() == ProtocolEnvelope.Kind.ACK) {
                if (envelope.requestId() == null) {
                    return false;
                }
            } else if (envelope.kind() != ProtocolEnvelope.Kind.EVENT) {
                return false;
            }
            return envelope.kind() == ProtocolEnvelope.Kind.CONFLICT
                ? envelope.status() == ProtocolEnvelope.Status.CONFLICT
                : envelope.status() == ProtocolEnvelope.Status.OK || envelope.status() == ProtocolEnvelope.Status.ACCEPTED;
        }
        if (envelope.body() instanceof ProtocolBody.ConflictResponse conflict) {
            ReSyncResourceType type = coreGraphType(conflict.requestedResource());
            return type != null && envelope.resource() != null && envelope.resource().equals(conflict.requestedResource())
                && envelope.requestId() != null && envelope.kind() == ProtocolEnvelope.Kind.CONFLICT
                && envelope.status() == ProtocolEnvelope.Status.CONFLICT && coreResourceOperation(envelope);
        }
        return false;
    }

    private static boolean coreOperation(ProtocolEnvelope<Map<String, Object>> envelope, ResourceOperationKind operation) {
        return operation != null && envelope.operation().id().value().equals(
            "resource." + operation.name().toLowerCase(Locale.ROOT));
    }

    private boolean coreResourceOperation(ProtocolEnvelope<Map<String, Object>> envelope) {
        String operation = envelope.operation().id().value();
        return operation.startsWith("resource.") && Set.of(
            "resource.create", "resource.save", "resource.rename", "resource.move", "resource.duplicate",
            "resource.activate", "resource.delete", "resource.load", "resource.subscribe").contains(operation);
    }

    private void applyCoreProjection(CoreGraphResourceProjection.Projection projection,
                                     boolean publishDuplicateRediscovery) {
        if (projection == null || projection.resource() == null) {
            return;
        }
        ReSyncResourceType type = coreGraphType(projection.resource());
        if (type == null || projection.rejected()) {
            return;
        }
        CoreGraphResourceCache cache = resourceRevisionReconciler.graphResources();
        CoreGraphResourceProjection.Projection previousReadOnly = projection.readOnly()
            ? cache.readOnly(projection.resource()).orElse(null) : null;
        Optional<GraphResourceCache.Reconciliation> reconciliation = resourceRevisionReconciler.reconcile(projection);
        if (reconciliation.isPresent()) {
            GraphResourceCache.Reconciliation result = reconciliation.orElseThrow();
            if (result.stale() || result.conflict()) {
                logger().operation("Resource Synchronization").warn("Rejected stale or conflicting Core graph resource reply");
            } else {
                if (projection.live() || projection.tombstoned()) {
                    coreOpenIncompatibilities.remove(new OpenResourceKey(type, projection.resource().id()));
                }
                if (result.applied() || publishDuplicateRediscovery && result.duplicate()) {
                    ResourceDocument<Map<String, Object>> document = projection.resourceDocument();
                    traceLifecycle(serverId, "authoritative_cache_applied", "serverId", serverId, "resourceKey",
                        type.typeId() + ":" + projection.resource().id(), "requestId", "event", "mutationId",
                        document != null ? document.mutationId() : null, "generation", activeTransportGeneration,
                        "authorityEpoch", handshakeAuthorityEpoch, "revision", projection.revision(), "cacheOutcome",
                        result.outcome());
                    notifyCoreGraphResourceListeners(new CoreGraphResourceTransition(projection.resource(), type,
                        projection, result.state(), result.outcome()));
                }
            }
        } else if (projection.readOnly()) {
            CoreGraphResourceProjection.Projection retained = cache.readOnly(projection.resource()).orElse(null);
            if (retained != null && sameProjection(retained, projection)
                && (previousReadOnly == null || !sameProjection(previousReadOnly, retained))) {
                notifyCoreGraphResourceListeners(new CoreGraphResourceTransition(projection.resource(), type,
                    retained, null, null));
            }
        }
        recordResourceRevision(type, projection.resource().id(), projection.revision());
    }

    private static boolean coreRediscoveryResponse(ProtocolEnvelope<Map<String, Object>> envelope,
                                                   PendingCoreGraphRequest pending) {
        return envelope != null && pending != null && envelope.kind() != ProtocolEnvelope.Kind.EVENT
            && coreReadOperation(pending.operation()) && pending.matches(envelope);
    }

    private static boolean coreReadOperation(ResourceOperationKind operation) {
        return operation == ResourceOperationKind.LOAD || operation == ResourceOperationKind.LIST
            || operation == ResourceOperationKind.QUERY;
    }

    private void diagnoseCoreRead(PendingCoreGraphRequest pending, String outcome) {
        if (pending == null || !coreReadOperation(pending.operation())) {
            return;
        }
        diagnoseCoreRead(pending.type(), pending.resource() == null ? null : pending.resource().id(),
            pending.operation(), pending.requestId(), pending.correlationId(), pending.traceId(), outcome);
    }

    private void diagnoseCoreRead(ReSyncResourceType type, String id, ResourceOperationKind operation,
                                  UUID requestId, UUID correlationId, UUID traceId, String outcome) {
        if (!coreReadOperation(operation)) {
            return;
        }
        logger().operation("Core Resource Read")
            .with("outcome", boundedCoreDiagnostic(outcome))
            .with("type", type == null ? "none" : type.typeId())
            .with("id", boundedCoreDiagnostic(id == null ? "catalog" : id))
            .with("operation", operation.name())
            .with("request", requestId == null ? "none" : requestId)
            .with("correlation", correlationId == null ? "none" : correlationId)
            .with("trace", traceId == null ? "none" : traceId)
            .with("generation", activeTransportGeneration)
            .with("authority", handshakeAuthorityEpoch)
            .warn("Core resource read did not complete");
    }

    private static String boundedCoreDiagnostic(String value) {
        String checked = value == null || value.isBlank() ? "none" : value;
        return checked.length() <= 128 ? checked : checked.substring(0, 128);
    }

    private Set<String> coreResourceCapabilities() {
        return coreResourceCapabilities(activeCatalogAuthoringPublication().orElse(null));
    }

    private Set<String> coreResourceCapabilities(CatalogAuthoringPublication publication) {
        LinkedHashSet<String> supported = new LinkedHashSet<>(ReSyncProtocolEnvelopeProjection
            .genericResourceCapabilities(FLOW_CONTRACT.clientCapabilities()));
        if (publication != null) {
            authoringCapabilities(publication).forEach(capability -> {
                supported.add(capability.canonicalText());
                if ("restudio.resync".equals(capability.owner().canonicalText())) {
                    supported.add(capability.id().value());
                }
            });
            publication.advertisedEditCapabilities().forEach(capability -> {
                supported.add(capability.canonicalText());
                if ("restudio.resync".equals(capability.owner().canonicalText())) {
                    supported.add(capability.id().value());
                }
            });
        }
        return Set.copyOf(supported);
    }

    private boolean currentCoreAuthoringSnapshot(ReSyncCatalogAuthoringProjection.Snapshot expected) {
        if (expected == null || catalogAuthority != CatalogAuthority.TYPED_PUBLICATION) {
            return false;
        }
        synchronized (catalogLifecycleLock) {
            return catalogAuthority == CatalogAuthority.TYPED_PUBLICATION
                && activeAuthoringSnapshot().filter(expected::equals).isPresent();
        }
    }

    private static boolean sameProjection(CoreGraphResourceProjection.Projection left,
                                          CoreGraphResourceProjection.Projection right) {
        return left != null && right != null
            && CoreGraphResourceCache.ProjectionKey.from(left).equals(CoreGraphResourceCache.ProjectionKey.from(right));
    }

    private void notifyCoreGraphResourceListeners(CoreGraphResourceTransition transition) {
        for (CoreGraphResourceListener listener : coreGraphResourceListeners) {
            submitCurrentConnectionCallback(() -> listener.onStateChanged(transition));
        }
    }

    private void notifyCoreGraphListComplete(CoreResourcePageCursor cursor, PendingCoreGraphRequest pending) {
        CoreListKey listKey = new CoreListKey(cursor.type(), pending != null ? pending.query() : null);
        UUID active = activeCoreListCorrelations.get(listKey);
        if (!cursor.correlationId().equals(active)
            || !activeCoreListCorrelations.remove(listKey, cursor.correlationId())) {
            return;
        }
        Set<ServerResourceLocator> resources = new HashSet<>();
        Set<ServerResourceLocator> tombstones = new HashSet<>();
        CoreGraphResourceCache cache = resourceRevisionReconciler.graphResources();
        boolean authoritativeRoot = cursor.operation() == ResourceOperationKind.LIST
            && normalizeOptionalText(pending != null ? pending.query() : null) == null;
        if (authoritativeRoot) {
            cache.reconcileAuthoritativeMembership(serverId, cursor.type().typeId(), cursor.resources());
            markResourceListProjection(cursor.type(), cursor.operation(), pending != null ? pending.query() : null);
        }
        Set<ServerResourceLocator> candidates = new HashSet<>(cursor.resources());
        if (authoritativeRoot) {
            cache.states().keySet().stream()
                .filter(resource -> serverId.equals(resource.serverId().canonicalText())
                    && cursor.type().typeId().equals(resource.resourceType().value()))
                .forEach(candidates::add);
            cache.readOnlyProjections().values().stream()
                .map(CoreGraphResourceProjection.Projection::resource)
                .filter(resource -> serverId.equals(resource.serverId().canonicalText())
                    && cursor.type().typeId().equals(resource.resourceType().value()))
                .forEach(candidates::add);
        }
        for (ServerResourceLocator resource : candidates) {
            GraphResourceState state = cache.state(resource).orElse(null);
            CoreGraphResourceProjection.Projection readOnly = cache.readOnly(resource).orElse(null);
            if (state != null && (readOnly == null || state.revision() >= readOnly.revision())) {
                resources.add(resource);
                if (state.tombstone()) {
                    tombstones.add(resource);
                }
            } else if (readOnly != null) {
                resources.add(resource);
                if (readOnly.tombstoned()) {
                    tombstones.add(resource);
                }
            }
        }
        CoreGraphListSnapshot snapshot = new CoreGraphListSnapshot(protocolServerId(), cursor.type(),
            cursor.requestId(), cursor.correlationId(), resources, tombstones, authoritativeRoot);
        traceLifecycle(serverId, "authoritative_list_applied", "serverId", serverId, "resourceKey",
            cursor.type().typeId() + ":catalog", "operation", cursor.operation(), "requestId", cursor.requestId(),
            "mutationId", null, "generation", activeTransportGeneration, "authorityEpoch", handshakeAuthorityEpoch,
            "memberCount", resources.size(), "tombstoneCount", tombstones.size(), "elapsedMs",
            temporaryLifecycleElapsed(cursor.requestId(), true));
        logger().operation("Resource Hydration").info("Core resource list applied: type=" + cursor.type().typeId()
            + ",count=" + resources.size() + ",tombstones=" + tombstones.size() + ",generation="
            + activeTransportGeneration + ",correlation=" + cursor.correlationId());
        for (CoreGraphListListener listener : coreGraphListListeners) {
            submitCurrentConnectionCallback(() -> listener.onComplete(snapshot));
        }
    }

    private void notifyCoreGraphMutationResult(ProtocolEnvelope<Map<String, Object>> envelope,
                                               PendingCoreGraphRequest pending,
                                               CoreGraphResourceProjection.Projection projection,
                                               int generation) {
        if (pending == null || pending.mutationId() == null
            || (envelope.kind() != ProtocolEnvelope.Kind.ACK && envelope.kind() != ProtocolEnvelope.Kind.CONFLICT)) {
            return;
        }
        ResourceDocument<Map<String, Object>> document = projection == null ? null : projection.resourceDocument();
        CoreGraphMutationResult result = new CoreGraphMutationResult(pending.requestId(), pending.correlationId(),
            pending.traceId(), pending.mutationId(), pending.operation(), pending.resource(), pending.expectedRevision(),
            pending.payloadHash(), document != null ? document.revision() : envelope.revision(),
            document != null ? document.mutationId() : envelope.mutationId(),
            document != null ? document.payloadHash() : envelope.payloadHash(), envelope.status(),
            document != null ? document.deleted() : envelope.deleted());
        settleCoreGraphSaveTracker(envelope, pending, projection, generation, result);
        if (authoritativeCoreGraphDeleteAck(envelope, pending, projection, document, result)) {
            FlowManager manager = client != null ? client.getFlowManager() : null;
            if (manager != null) {
                manager.acknowledgeResourceDelete(serverId, pending.type(), pending.resource().id());
                manager.observeResourceDeleteTombstone(serverId, pending.type(), pending.resource().id());
            }
        }
        for (CoreGraphMutationListener listener : coreGraphMutationListeners) {
            submitCurrentConnectionCallback(() -> listener.onResult(result));
        }
    }

    private void settleCoreGraphSaveTracker(ProtocolEnvelope<Map<String, Object>> envelope,
                                             PendingCoreGraphRequest pending,
                                             CoreGraphResourceProjection.Projection projection,
                                             int generation,
                                             CoreGraphMutationResult result) {
        if (pending.operation() != ResourceOperationKind.CREATE && pending.operation() != ResourceOperationKind.SAVE
            || pending.resource() == null) {
            return;
        }
        ReSyncResourceType type = pending.type();
        String id = pending.resource().id();
        String mutationId = pending.mutationId().toString();
        ResourceSaveFence saveFence = resourceSaveFence(mutationId);
        ResourceDocument<Map<String, Object>> document = projection == null ? null : projection.resourceDocument();
        boolean authoritativeAck = authoritativeCoreGraphAck(envelope, pending, projection, document, result)
            && pendingCoreGraphRequests.get(pending.requestId()) == pending
            && saveFence != null && generation == saveFence.transportGeneration()
            && currentResourceSaveFence(saveFence);
        if (authoritativeAck) {
            FlowManager manager = client != null ? client.getFlowManager() : null;
            BrowserSafeState.ReferenceValue<FlowManager.CoreGraphSaveSettlement> sessionSettlement =
                new BrowserSafeState.ReferenceValue<>(FlowManager.CoreGraphSaveSettlement.REJECTED);
            boolean projected = runCurrentServer(manager, saveFence.connectionToken(), () -> {
                if (!currentResourceSaveFence(saveFence)) {
                    return;
                }
                sessionSettlement.set(manager.settleCoreGraphEditorSessionSaveAuthoritative(
                    saveFence.connectionToken(), result, pending.submittedPayloadHash(), projection.corePayload()));
            });
            FlowManager.CoreGraphSaveSettlement settlement = sessionSettlement.get();
            traceLifecycle(serverId, "authoritative_ack_session_mark", "serverId", serverId, "resourceKey",
                type.typeId() + ":" + id, "requestId", pending.requestId(), "correlationId", pending.correlationId(),
                "traceId", pending.traceId(), "mutationId", pending.mutationId(), "generation", generation,
                "authorityEpoch", envelope.authorityEpoch(), "revision",
                document.revision(), "sessionMarked", settlement.editorUpdated(), "settled", settlement.settled(),
                "outcome", settlement);
            if (projected && settlement.settled()
                && completeCoreGraphSaveSettlement(pending, result, document, saveFence, settlement.editorUpdated())) {
                return;
            }
            if (projected && settlement.retryable()
                && scheduleCoreGraphSaveSettlementRecovery(pending, result, projection.corePayload(), document,
                    saveFence, generation)) {
                traceLifecycle(serverId, "settlement_recovery_started", "serverId", serverId, "resourceKey",
                    type.typeId() + ":" + id, "operation", pending.operation(), "requestId", pending.requestId(),
                    "mutationId", pending.mutationId(), "generation", generation, "authorityEpoch",
                    envelope.authorityEpoch(), "revision", document.revision(), "attempt", 1,
                    "maxAttempts", MAX_CORE_SAVE_SESSION_SETTLEMENT_ATTEMPTS);
                return;
            }
        }
        logger().operation("Core Graph Save").error(coreGraphSaveSettlementDiagnostic(
            envelope, pending, projection, document, result, saveFence, generation));
        failCoreGraphSaveSettlement(pending, document, saveFence,
            envelope.kind() == ProtocolEnvelope.Kind.CONFLICT
                ? "The Core graph changed before the save completed."
                : "The Core graph save could not reconcile its editor session.");
    }

    private boolean completeCoreGraphSaveSettlement(PendingCoreGraphRequest pending, CoreGraphMutationResult result,
                                                    ResourceDocument<Map<String, Object>> document,
                                                    ResourceSaveFence saveFence, boolean editorUpdated) {
        if (pending == null || pending.resource() == null || pending.mutationId() == null || document == null
            || saveFence == null || !currentResourceSaveFence(saveFence)) {
            return false;
        }
        ReSyncResourceType type = pending.type();
        String id = pending.resource().id();
        String mutationId = pending.mutationId().toString();
        FlowManager manager = client != null ? client.getFlowManager() : null;
        DesignerSaveNotifications.SaveTarget[] completed = {null};
        boolean[] accepted = {false};
        boolean projected = runCurrentServer(manager, saveFence.connectionToken(), () -> {
            if (!currentResourceSaveFence(saveFence)) {
                return;
            }
            if (pending.operation() == ResourceOperationKind.CREATE) {
                requestProjectMetadataList();
            }
            pendingCreatePresentations.remove(pending.mutationId());
            completeResourceSave(mutationId);
            completed[0] = DesignerSaveNotifications.completeMutation(serverId, type, id, mutationId);
            accepted[0] = true;
        });
        if (!projected || !accepted[0]) {
            return false;
        }
        DesignerSaveNotifications.SaveTarget target = completed[0];
        if (editorUpdated && target != null && target.shouldUpdateResourceState()) {
            String acknowledgedMutationId = document.mutationId().toString();
            executeCurrentServerUi(manager, saveFence.connectionToken(), () -> {
                GraphEditorScreen.clearEditorErrorsForServer(serverId, type.typeId(), id);
                GraphEditorScreen studioScreen = GraphEditorScreen.getStudioScreen(serverId);
                if (studioScreen != null) {
                    studioScreen.markStudioDocumentSaved(type.typeId(), id, target.sequence(), document.revision(),
                        document.payloadHash().canonicalText(), acknowledgedMutationId);
                }
            });
        } else if (target == null) {
            logger().operation("Core Graph Save").warn("Authoritative Core graph save settled without an active notification tracker: "
                + "type=" + type.typeId() + ",id=" + id + ",mutationId=" + mutationId);
        }
        if (pendingAggregateCreateReplays.containsKey(pending.requestId())) {
            aggregatePrimarySettlements.add(pending.requestId());
        }
        traceLifecycle(serverId, "settlement_complete", "serverId", serverId, "resourceKey",
            type.typeId() + ":" + id, "operation", pending.operation(), "requestId", pending.requestId(),
            "correlationId", pending.correlationId(), "traceId", pending.traceId(), "mutationId",
            pending.mutationId(), "generation", saveFence.transportGeneration(), "authorityEpoch",
            saveFence.authorityEpoch(), "revision", result.revision(), "metadataFollowUp",
            pending.operation() == ResourceOperationKind.CREATE, "elapsedMs",
            temporaryLifecycleElapsed(pending.requestId(), true));
        return true;
    }

    private boolean scheduleCoreGraphSaveSettlementRecovery(PendingCoreGraphRequest pending,
                                                             CoreGraphMutationResult result,
                                                             Object authoritativePayload,
                                                             ResourceDocument<Map<String, Object>> document,
                                                             ResourceSaveFence saveFence, int generation) {
        if (pending == null || pending.mutationId() == null || authoritativePayload == null || document == null
            || saveFence == null || generation != saveFence.transportGeneration()) {
            return false;
        }
        CoreSaveSessionSettlementRecovery recovery = new CoreSaveSessionSettlementRecovery(pending, result,
            authoritativePayload, document, saveFence, generation);
        CoreSaveSessionSettlementRecovery current = coreSaveSessionSettlementRecoveries.putIfAbsent(
            pending.mutationId(), recovery);
        if (current != null) {
            return true;
        }
        if (scheduleCoreGraphSaveSettlementRetry(recovery)) {
            return true;
        }
        coreSaveSessionSettlementRecoveries.remove(pending.mutationId(), recovery);
        return false;
    }

    private boolean scheduleCoreGraphSaveSettlementRetry(CoreSaveSessionSettlementRecovery recovery) {
        try {
            heartbeatScheduler.schedule(() -> retryCoreGraphSaveSettlement(recovery), Duration.ofSeconds(CORE_SAVE_SESSION_SETTLEMENT_RETRY_SECONDS));
            return true;
        } catch (RuntimeException exception) {
            return false;
        }
    }

    private void retryCoreGraphSaveSettlement(CoreSaveSessionSettlementRecovery recovery) {
        PendingCoreGraphRequest pending = recovery.pending;
        if (pending.mutationId() == null
            || coreSaveSessionSettlementRecoveries.get(pending.mutationId()) != recovery) {
            return;
        }
        int attempt = recovery.nextAttempt();
        if (attempt < 0 || recovery.generation != recovery.saveFence.transportGeneration()
            || !currentResourceSaveFence(recovery.saveFence)) {
            finishCoreGraphSaveSettlementRecoveryFailure(recovery);
            return;
        }
        FlowManager manager = client != null ? client.getFlowManager() : null;
        BrowserSafeState.ReferenceValue<FlowManager.CoreGraphSaveSettlement> sessionSettlement =
            new BrowserSafeState.ReferenceValue<>(FlowManager.CoreGraphSaveSettlement.REJECTED);
        boolean projected = runCurrentServer(manager, recovery.saveFence.connectionToken(), () -> {
            if (!currentResourceSaveFence(recovery.saveFence)) {
                return;
            }
            sessionSettlement.set(manager.settleCoreGraphEditorSessionSaveAuthoritative(
                recovery.saveFence.connectionToken(), recovery.result, pending.submittedPayloadHash(),
                recovery.authoritativePayload));
        });
        FlowManager.CoreGraphSaveSettlement settlement = sessionSettlement.get();
        traceLifecycle(serverId, "settlement_recovery_attempt", "serverId", serverId, "resourceKey",
            pending.type().typeId() + ":" + pending.resource().id(), "operation", pending.operation(), "requestId",
            pending.requestId(), "mutationId", pending.mutationId(), "generation", recovery.generation,
            "authorityEpoch", recovery.saveFence.authorityEpoch(), "revision", recovery.document.revision(),
            "attempt", attempt, "maxAttempts", MAX_CORE_SAVE_SESSION_SETTLEMENT_ATTEMPTS, "outcome", settlement);
        if (projected && settlement.settled()) {
            if (completeCoreGraphSaveSettlement(pending, recovery.result, recovery.document, recovery.saveFence,
                settlement.editorUpdated())) {
                coreSaveSessionSettlementRecoveries.remove(pending.mutationId(), recovery);
                return;
            }
            finishCoreGraphSaveSettlementRecoveryFailure(recovery);
            return;
        }
        if (projected && settlement.retryable() && attempt < MAX_CORE_SAVE_SESSION_SETTLEMENT_ATTEMPTS
            && scheduleCoreGraphSaveSettlementRetry(recovery)) {
            return;
        }
        finishCoreGraphSaveSettlementRecoveryFailure(recovery);
    }

    private void finishCoreGraphSaveSettlementRecoveryFailure(CoreSaveSessionSettlementRecovery recovery) {
        PendingCoreGraphRequest pending = recovery.pending;
        if (pending.mutationId() == null
            || !coreSaveSessionSettlementRecoveries.remove(pending.mutationId(), recovery)) {
            return;
        }
        failCoreGraphSaveSettlement(pending, recovery.document, recovery.saveFence,
            "The Core graph was saved, but its editor session could not be reconciled after rehydration.");
    }

    private void failCoreGraphSaveSettlement(PendingCoreGraphRequest pending,
                                             ResourceDocument<Map<String, Object>> document,
                                             ResourceSaveFence saveFence, String message) {
        ReSyncResourceType type = pending.type();
        String id = pending.resource().id();
        String mutationId = pending.mutationId().toString();
        traceLifecycle(serverId, "settlement_failed", "serverId", serverId, "resourceKey",
            type.typeId() + ":" + id, "operation", pending.operation(), "requestId", pending.requestId(),
            "correlationId", pending.correlationId(), "traceId", pending.traceId(), "mutationId",
            pending.mutationId(), "generation", saveFence != null ? saveFence.transportGeneration() : -1,
            "authorityEpoch", saveFence != null ? saveFence.authorityEpoch() : 0L, "revision",
            document != null ? document.revision() : 0L, "metadataFollowUp", false, "elapsedMs",
            temporaryLifecycleElapsed(pending.requestId(), true), "reason", message);
        pendingCreatePresentations.remove(pending.mutationId());
        completeResourceSave(mutationId);
        DesignerSaveNotifications.SaveTarget target = DesignerSaveNotifications.failMutation(serverId, type, id,
            mutationId, message);
        markResourceFailedCurrent(target, saveFence);
    }

    private static boolean authoritativeCoreGraphAck(ProtocolEnvelope<Map<String, Object>> envelope,
                                                     PendingCoreGraphRequest pending,
                                                     CoreGraphResourceProjection.Projection projection,
                                                     ResourceDocument<Map<String, Object>> document,
                                                     CoreGraphMutationResult result) {
        return envelope != null && envelope.kind() == ProtocolEnvelope.Kind.ACK && pending != null
            && document != null && !document.deleted() && result != null && result.accepted()
            && projection != null && projection.accepted() && !projection.tombstoned()
            && pending.mutationId().equals(document.mutationId()) && pending.matches(envelope)
            && projection.resource() != null && projection.resource().equals(pending.resource());
    }

    private static boolean authoritativeCoreGraphDeleteAck(ProtocolEnvelope<Map<String, Object>> envelope,
                                                           PendingCoreGraphRequest pending,
                                                           CoreGraphResourceProjection.Projection projection,
                                                           ResourceDocument<Map<String, Object>> document,
                                                           CoreGraphMutationResult result) {
        return envelope != null && envelope.kind() == ProtocolEnvelope.Kind.ACK && pending != null
            && pending.operation() == ResourceOperationKind.DELETE && document != null && document.deleted()
            && result != null && result.accepted() && result.deleted() && projection != null && projection.accepted()
            && projection.tombstoned() && pending.mutationId().equals(document.mutationId())
            && pending.matches(envelope) && pending.resource().equals(projection.resource());
    }

    private String coreGraphSaveSettlementDiagnostic(ProtocolEnvelope<Map<String, Object>> envelope,
                                                     PendingCoreGraphRequest pending,
                                                     CoreGraphResourceProjection.Projection projection,
                                                     ResourceDocument<Map<String, Object>> document,
                                                     CoreGraphMutationResult result,
                                                     ResourceSaveFence saveFence, int generation) {
        return "Core graph save settlement rejected: kindAck=" + (envelope.kind() == ProtocolEnvelope.Kind.ACK)
            + ",documentPresent=" + (document != null)
            + ",documentLive=" + (document != null && !document.deleted())
            + ",resultAccepted=" + result.accepted()
            + ",projectionAccepted=" + (projection != null && projection.accepted())
            + ",projectionTombstoned=" + (projection != null && projection.tombstoned())
            + ",projectionStatus=" + (projection != null ? projection.status() : null)
            + ",projectionReason=" + (projection != null ? projection.rejectionReason() : "")
            + ",requiredCapabilities=" + (projection != null ? projection.requiredCapabilities() : Set.of())
            + ",unsupportedCapabilities=" + (projection != null ? projection.unsupportedCapabilities() : Set.of())
            + ",mutationMatches=" + (document != null && pending.mutationId().equals(document.mutationId()))
            + ",envelopeMatches=" + pending.matches(envelope)
            + ",pendingCurrent=" + (pendingCoreGraphRequests.get(pending.requestId()) == pending)
            + ",resourceMatches=" + (projection != null && pending.resource().equals(projection.resource()))
            + ",saveFencePresent=" + (saveFence != null)
            + ",generationMatches=" + (saveFence != null && generation == saveFence.transportGeneration())
            + ",saveFenceCurrent=" + currentResourceSaveFence(saveFence)
            + ",requestId=" + pending.requestId() + ",mutationId=" + pending.mutationId();
    }

    private void consumeCoreOpenIntent(PendingCoreGraphRequest pending,
                                       CoreGraphResourceProjection.Projection projection,
                                       ReSyncCatalogAuthoringProjection.Snapshot authoringSnapshot) {
        if (pending == null || pending.operation() != ResourceOperationKind.LOAD
            || projection == null
            || projection.tombstoned() || projection.rejected()) {
            return;
        }
        if (!pendingCoreOpenRequests.contains(pending.requestId())) {
            return;
        }
        if (!pendingCoreOpenRequests.remove(pending.requestId())) {
            return;
        }
        pendingCoreGraphRequests.remove(pending.requestId(), pending);
        coreRequestRecoveries.remove(pending.requestId());
        cancelPendingSend(pending.requestId().toString());
        OpenResourceKey key = new OpenResourceKey(pending.type(), projection.resource().id());
        if (projection.readOnly()) {
            String reason = projection.rejectionReason() == null || projection.rejectionReason().isBlank()
                ? "This Core graph is not compatible with the active authoring publication."
                : projection.rejectionReason();
            CoreOpenIncompatibility incompatibility = new CoreOpenIncompatibility(pending.type(), projection.resource(),
                pending.transportGeneration(), projection.revision(), reason, authoringSnapshot);
            coreOpenIncompatibilities.put(key, incompatibility);
            removeOpenIntentIfGeneration(pending.type(), projection.resource().id(), pending.transportGeneration());
            FlowManager manager = client != null ? client.getFlowManager() : null;
            FlowManager.ServerConnectionToken token = captureUiToken(manager);
            if (manager != null && manager.isCurrentServerConnection(token)) {
                manager.notifyCoreGraphOpenIncompatibility(serverId, pending.type(), projection.resource().id(), reason);
            }
            traceLifecycle(serverId, "open_settlement_incompatible", "serverId", serverId, "type",
                pending.type().typeId(), "id", boundedCoreDiagnostic(projection.resource().id()), "operation",
                pending.operation(), "requestId", pending.requestId(), "correlationId", pending.correlationId(),
                "traceId", pending.traceId(), "mutationId", projection.mutationId(), "generation",
                pending.transportGeneration(), "authorityEpoch", projection.envelope().authorityEpoch(), "revision",
                projection.revision(), "reason", boundedCoreDiagnostic(reason));
            return;
        }
        coreOpenIncompatibilities.remove(key);
        AcceptedCoreOpenIntent accepted = new AcceptedCoreOpenIntent(pending.type(), projection.resource(),
            pending.transportGeneration(), pending.requestId(), pending.correlationId(), pending.traceId(), System.nanoTime());
        acceptedCoreOpenIntents.put(key, accepted);
        traceAcceptedCoreOpen(accepted, "open_response_applied", "awaiting_session", false);
        tryOpenAcceptedCoreIntent(key, accepted);
        if (acceptedCoreOpenIntents.get(key) == accepted) {
            boolean retryScheduled = submitCurrentConnectionCallback(() -> {
                if (acceptedCoreOpenIntents.get(key) == accepted) {
                    tryOpenAcceptedCoreIntent(key, accepted);
                }
            });
            traceAcceptedCoreOpen(accepted, "open_projection_retry_queued", retryScheduled ? "queued" : "rejected", false);
        }
    }

    private void retryAcceptedCoreOpenIntents(int generation) {
        if (generation < 0 || currentOpenIntentGeneration() != generation) {
            return;
        }
        for (Map.Entry<OpenResourceKey, AcceptedCoreOpenIntent> entry : List.copyOf(acceptedCoreOpenIntents.entrySet())) {
            AcceptedCoreOpenIntent accepted = entry.getValue();
            if (accepted != null && accepted.transportGeneration() == generation) {
                tryOpenAcceptedCoreIntent(entry.getKey(), accepted);
            }
        }
    }

    void coreGraphSessionProjected(ServerResourceLocator resource) {
        if (resource == null || !serverId.equals(resource.serverId().canonicalText())) {
            return;
        }
        ReSyncResourceType type = ReSyncResourceType.byTypeId(resource.resourceType().value());
        if (type == null || !type.isGraph()) {
            return;
        }
        OpenResourceKey key = new OpenResourceKey(type, resource.id());
        AcceptedCoreOpenIntent accepted = acceptedCoreOpenIntents.get(key);
        if (accepted == null || !resource.equals(accepted.resource())) {
            return;
        }
        tryOpenAcceptedCoreIntent(key, accepted);
    }

    private void tryOpenAcceptedCoreIntent(OpenResourceKey key, AcceptedCoreOpenIntent accepted) {
        if (key == null || accepted == null || acceptedCoreOpenIntents.get(key) != accepted
            || currentOpenIntentGeneration() != accepted.transportGeneration()
            || !currentOpenIntent(key, accepted.transportGeneration())) {
            if (key != null && accepted != null) {
                acceptedCoreOpenIntents.remove(key, accepted);
                diagnosedAcceptedCoreOpenWaits.remove(accepted.requestId());
            }
            traceAcceptedCoreOpen(accepted, "open_settlement_abandoned", "intent_or_generation_changed", true);
            return;
        }
        FlowManager manager = client != null ? client.getFlowManager() : null;
        FlowManager.ServerConnectionToken token = captureUiToken(manager);
        if (manager == null || !manager.isCurrentServerConnection(token)) {
            traceAcceptedCoreOpenWait(accepted, "connection_projection");
            return;
        }
        CoreGraphEditorSession session = manager.coreGraphEditorSession(serverId, accepted.type(), key.resourceId())
            .orElse(null);
        if (session == null || !accepted.resource().equals(session.resource())
            || !manager.isCurrentCoreGraphEditorSession(serverId, accepted.type(), key.resourceId(), session)) {
            traceAcceptedCoreOpenWait(accepted, "retained_session_projection");
            return;
        }
        ReSyncProjectMetadata.ResourceEntry metadata = manager.getProjectResource(serverId, accepted.type().typeId(),
            key.resourceId());
        String title = metadata != null && metadata.getDisplayName() != null && !metadata.getDisplayName().isBlank()
            ? metadata.getDisplayName() : key.resourceId();
        if (!acceptedCoreOpenIntents.remove(key, accepted)) {
            return;
        }
        boolean opened;
        try {
            opened = manager.openCoreGraphSession(accepted.resource(), session, title, "");
        } catch (RuntimeException exception) {
            opened = false;
        }
        if (opened) {
            removeOpenIntentIfGeneration(accepted.type(), key.resourceId(), accepted.transportGeneration());
            diagnosedAcceptedCoreOpenWaits.remove(accepted.requestId());
            traceAcceptedCoreOpen(accepted, "open_settlement_complete", "opened", true);
            return;
        }
        traceAcceptedCoreOpenWait(accepted, "ui_open_rejected");
        if (currentOpenIntent(key, accepted.transportGeneration())) {
            acceptedCoreOpenIntents.putIfAbsent(key, accepted);
        }
    }

    private void traceAcceptedCoreOpenWait(AcceptedCoreOpenIntent accepted, String outcome) {
        if (accepted == null) {
            return;
        }
        if (diagnosedAcceptedCoreOpenWaits.size() >= MAX_RETAINED_OPEN_INTENTS
            && !diagnosedAcceptedCoreOpenWaits.contains(accepted.requestId())) {
            diagnosedAcceptedCoreOpenWaits.stream().findFirst().ifPresent(diagnosedAcceptedCoreOpenWaits::remove);
        }
        if (diagnosedAcceptedCoreOpenWaits.add(accepted.requestId())) {
            traceAcceptedCoreOpen(accepted, "open_settlement_wait", outcome, false);
        }
    }

    private void traceAcceptedCoreOpen(AcceptedCoreOpenIntent accepted, String stage, String outcome,
                                       boolean terminal) {
        if (accepted == null) {
            return;
        }
        traceLifecycle(serverId, stage, "serverId", serverId, "type", accepted.type().typeId(), "id",
            boundedCoreDiagnostic(accepted.resource().id()), "requestId", accepted.requestId(), "correlationId",
            accepted.correlationId(), "traceId", accepted.traceId(), "mutationId", null, "generation",
            accepted.transportGeneration(), "authorityEpoch", handshakeAuthorityEpoch, "outcome", outcome,
            "responseWaitMs", BrowserSafeState.nanosToMillis(Math.max(0L, System.nanoTime() - accepted.acceptedAtNanos())),
            "elapsedMs", temporaryLifecycleElapsed(accepted.requestId(), terminal));
    }

    private boolean currentOpenIntent(OpenResourceKey key, int generation) {
        synchronized (openIntentLock) {
            PendingOpenIntent intent = pendingOpenIntents.get(key);
            return intent != null && serverId.equals(intent.serverId())
                && intent.transportGeneration() == generation;
        }
    }

    private void handleCoreConflictWithoutCurrent(ProtocolEnvelope<Map<String, Object>> envelope,
                                                   ServerResourceLocator resource,
                                                   PendingCoreGraphRequest pendingCore) {
        if (pendingCore == null) {
            return;
        }
        failCorePending(pendingCore, "The resource was not found on ReSync.");
    }

    private PendingCoreGraphRequest matchingPendingCoreGraphRequest(ProtocolEnvelope<Map<String, Object>> envelope) {
        if (envelope == null) {
            return null;
        }
        UUID requestId = envelope.requestId();
        if (requestId != null) {
            PendingCoreGraphRequest pending = pendingCoreGraphRequests.get(requestId);
            if (pending != null) {
                return pending.matches(envelope) ? pending : null;
            }
            if (envelope.kind() == ProtocolEnvelope.Kind.ACK || envelope.kind() == ProtocolEnvelope.Kind.CONFLICT) {
                return null;
            }
        }
        if (envelope.kind() != ProtocolEnvelope.Kind.EVENT) {
            return null;
        }
        ResourceDocument<?> document = envelope.body() instanceof ProtocolBody.ResourceDocumentResponse response
            ? response.document() : null;
        for (PendingCoreGraphRequest pending : pendingCoreGraphRequests.values()) {
            if (pending.matchesEvent(envelope, document)) {
                return pending;
            }
        }
        return null;
    }

    private boolean validCoreActivationResponse(ProtocolEnvelope<Map<String, Object>> envelope,
                                                ResourceDocument<Map<String, Object>> document) {
        if (envelope.kind() == ProtocolEnvelope.Kind.EVENT) {
            return true;
        }
        PendingResourceActivation pending = pendingCoreActivation(envelope,
            document == null ? envelope.resource() : document.resource());
        if (pending == null || document == null || envelope.resource() == null
            || !envelope.resource().equals(document.resource()) || envelope.revision() != document.revision()
            || !Objects.equals(envelope.mutationId(), document.mutationId())
            || !Objects.equals(envelope.payloadHash(), document.payloadHash())
            || envelope.deleted() != document.deleted()) {
            return false;
        }
        return envelope.kind() == ProtocolEnvelope.Kind.CONFLICT || pending.mutationId().equals(document.mutationId());
    }

    private PendingResourceActivation pendingCoreActivation(ProtocolEnvelope<Map<String, Object>> envelope,
                                                             ServerResourceLocator resource) {
        if (envelope == null || envelope.requestId() == null || resource == null) {
            return null;
        }
        PendingResourceActivation pending = pendingResourceActivations.get(envelope.requestId());
        if (pending == null || !pending.matches(resource) || !pending.correlationId().equals(envelope.correlationId())
            || (envelope.kind() != ProtocolEnvelope.Kind.CONFLICT && envelope.mutationId() != null
            && !pending.mutationId().equals(envelope.mutationId()))
            || !envelope.capabilities().containsAll(RESOURCE_ACTIVATION_CAPABILITIES)) {
            return null;
        }
        return pending;
    }

    private PendingResourceActivation pendingCoreActivationEvent(ServerResourceLocator resource,
                                                                  ResourceDocument<Map<String, Object>> document) {
        if (resource == null || document == null || document.mutationId() == null) {
            return null;
        }
        for (PendingResourceActivation pending : pendingResourceActivations.values()) {
            if (pending.matches(resource) && (pending.mutationId().equals(document.mutationId())
                || document.revision() > pending.expectedRevision())) {
                return pending;
            }
        }
        return null;
    }

    private CoreActivationApplication applyCoreActivation(CoreGraphResourceProjection.Projection projection) {
        ProtocolEnvelope<Map<String, Object>> envelope = projection.envelope();
        ServerResourceLocator resource = projection.resource();
        PendingResourceActivation pending = envelope.kind() == ProtocolEnvelope.Kind.EVENT
            ? pendingCoreActivationEvent(resource, projection.resourceDocument()) : pendingCoreActivation(envelope, resource);
        FlowManager manager = client != null ? client.getFlowManager() : null;
        ReSyncResourceType type = ReSyncResourceType.byTypeId(resource.resourceType().value());
        if (manager == null || type == null || !type.isGraph()) {
            return null;
        }
        CoreGraphResourceCache cache = resourceRevisionReconciler.graphResources();
        if (!cache.canReconcile(projection)) {
            return null;
        }
        FlowManager.ResourceProjectionSnapshot managerSnapshot = manager.snapshotResourceProjection(
            serverId, type, resource.id(), null);
        FlowManager.ResourceProjectionLease projectionLease = manager.beginResourceProjection(managerSnapshot);
        CoreGraphResourceCache.ResourceSnapshot graphSnapshot = cache.snapshot(resource);
        BrowserSafeState.ReferenceValue<CoreGraphResourceCache.ResourceSnapshot> graphApplied = new BrowserSafeState.ReferenceValue<>();
        BrowserSafeState.ReferenceValue<GraphResourceCache.Reconciliation> committed = new BrowserSafeState.ReferenceValue<>();
        boolean enabled = projection.activationState() == ResourceActivationState.ACTIVE;
        String settlementMessage = projection.tombstoned()
            ? "The resource was deleted before activation completed."
            : envelope.kind() == ProtocolEnvelope.Kind.CONFLICT
                ? "The resource changed before activation completed." : "";
        GraphResourceCache.Reconciliation result;
        try {
            if (!manager.commitCoreResourceActivation(serverId, type, resource.id(),
                pending != null ? pending.legacyRequestId() : null, enabled, settlementMessage,
                projection.tombstoned() || envelope.kind() == ProtocolEnvelope.Kind.CONFLICT, () -> {
                    if (!manager.applyCoreGraphProjectionAuthoritative(type, projection, projectionLease)) {
                        throw new IllegalStateException("The Core graph projection could not be fenced");
                    }
                    Optional<GraphResourceCache.Reconciliation> reconciliation = resourceRevisionReconciler.reconcile(projection);
                    if (reconciliation.isEmpty() || reconciliation.get().stale() || reconciliation.get().conflict()) {
                        throw new IllegalStateException("The Core activation response was stale or conflicting");
                    }
                    committed.set(reconciliation.orElseThrow());
                    graphApplied.set(cache.snapshot(resource));
                    recordResourceRevision(type, resource.id(), projection.revision());
                })) {
                throw new IllegalStateException("The Core activation response could not settle its pending state");
            }
            result = committed.get();
            if (result == null) {
                throw new IllegalStateException("The Core activation response did not produce a committed projection");
            }
        } catch (RuntimeException exception) {
            try {
                manager.restoreResourceProjection(managerSnapshot, projectionLease);
                CoreGraphResourceCache.ResourceSnapshot after = graphApplied.get();
                if (after != null) {
                    cache.restoreIfCurrent(graphSnapshot, after);
                }
            } catch (RuntimeException rollbackException) {
                logger().operation("Resource Synchronization").warn("Could not restore Core activation projection: "
                    + rollbackException.getMessage());
            }
            return null;
        }
        try {
            if (result.applied()) {
                notifyCoreGraphResourceListeners(new CoreGraphResourceTransition(resource, type, projection,
                    result.state(), result.outcome()));
            }
            manager.notifyCoreGraphProjectionCommitted(serverId);
        } catch (RuntimeException exception) {
            logger().operation("Resource Synchronization").warn("Could not deliver committed Core activation projection: "
                + exception.getMessage());
        }
        return new CoreActivationApplication(pending);
    }

    private void completeCoreActivation(CoreGraphResourceProjection.Projection projection,
                                        PendingResourceActivation pending) {
        ProtocolEnvelope<Map<String, Object>> envelope = projection.envelope();
        ServerResourceLocator resource = projection.resource();
        FlowManager manager = client != null ? client.getFlowManager() : null;
        if (pending != null && pendingResourceActivations.remove(pending.requestId(), pending)) {
            pendingCoreGraphRequests.remove(pending.requestId());
            coreRequestRecoveries.remove(pending.requestId());
            cancelPendingSend(pending.requestId().toString());
            if (manager != null) {
                if (projection.tombstoned()) {
                    manager.completeResourceActivation(serverId, pending.type(), resource.id(), pending.enabled(),
                        pending.legacyRequestId(), false, "The resource was deleted before activation completed.", true);
                } else {
                    manager.completeResourceActivationAuthoritative(serverId, pending.type(), resource.id(),
                        projection.activationState() == ResourceActivationState.ACTIVE, pending.legacyRequestId(),
                        envelope.kind() == ProtocolEnvelope.Kind.CONFLICT ? "The resource changed before activation completed." : "",
                        envelope.kind() == ProtocolEnvelope.Kind.CONFLICT);
                }
            }
        }
    }

    private boolean isResourceActivationEnvelope(ProtocolEnvelope<Map<String, Object>> envelope) {
        if (envelope == null) {
            return false;
        }
        if (envelope.body() instanceof ProtocolBody.ResourceDocumentResponse response) {
            return response.operation() == ResourceOperationKind.ACTIVATE;
        }
        if (envelope.body() instanceof ProtocolBody.ConflictResponse) {
            return RESOURCE_ACTIVATE_OPERATION.equals(envelope.operation());
        }
        return RESOURCE_ACTIVATE_OPERATION.equals(envelope.operation());
    }

    private void handleResourceActivationEnvelope(ReSyncProtocolEnvelopeProjection.Projection projection) {
        ProtocolEnvelope<Map<String, Object>> envelope = projection.envelope();
        ResourceDocument<Map<String, Object>> document = projection.resourceDocument();
        PendingCoreGraphRequest correlatedCore = pendingCoreGraphRequest(envelope);
        ServerResourceLocator resource = document != null ? document.resource()
            : envelope.body() instanceof ProtocolBody.ConflictResponse conflict ? conflict.requestedResource() : envelope.resource();
        boolean resourceServerMatches;
        try {
            resourceServerMatches = resource != null && resource.serverId() != null
                && serverId.equals(resource.serverId().canonicalText());
        } catch (RuntimeException exception) {
            resourceServerMatches = false;
        }
        if (!resourceServerMatches) {
            failCorePending(correlatedCore, "The Core activation response had no valid resource identity.");
            return;
        }
        if (envelope.resource() == null || !resource.equals(envelope.resource())) {
            failCorePending(correlatedCore, "The Core activation response did not match its resource.");
            return;
        }
        ReSyncResourceType type = ReSyncResourceType.byTypeId(resource.resourceType().value());
        if (!isProtocolResourceType(type)) {
            failCorePending(correlatedCore, "The Core activation response used an unsupported resource type.");
            return;
        }
        if (!type.isGraph()) {
            handleTypedResourceActivationEnvelope(projection, type, resource, document);
            return;
        }
        PendingResourceActivation pending = pendingResourceActivation(envelope, resource, document);
        if (envelope.kind() != ProtocolEnvelope.Kind.EVENT && pending == null) {
            failCorrelatedCoreEnvelope(envelope, "The Core activation response did not match its request.");
            return;
        }
        PendingCoreGraphRequest corePending = pending == null ? null : pendingCoreGraphRequests.get(pending.requestId());
        if (document == null) {
            if (corePending != null) {
                failCorePending(corePending, "The resource was not found on ReSync.");
            } else if (pending != null && pendingResourceActivations.remove(pending.requestId(), pending)) {
                cancelPendingSend(pending.requestId().toString());
                FlowManager manager = client != null ? client.getFlowManager() : null;
                if (manager != null) {
                    manager.completeResourceActivation(serverId, type, resource.id(), pending.enabled(), pending.legacyRequestId(), false,
                        "The resource was not found on ReSync.", true);
                }
            }
            return;
        }
        if (!document.deleted() && document.activationState() == null) {
            failCorePending(corePending, "The Core activation response did not include an activation state.");
            return;
        }
        GenericResourceProjectionOutcome outcome = applyTypedResourceDocument(type, document,
            projection.envelope().authorityEpoch(), projection.envelope().kind() != ProtocolEnvelope.Kind.CONFLICT, true);
        if (outcome == GenericResourceProjectionOutcome.RETRY) {
            logger().operation("Resource Synchronization").warn("Deferred generic graph activation after projection failure");
            return;
        }
        if (outcome != GenericResourceProjectionOutcome.APPLIED) {
            failCorePending(corePending, "The resource activation response was invalid or conflicting.");
            return;
        }
        FlowManager manager = client != null ? client.getFlowManager() : null;
        if (pending != null && pendingResourceActivations.remove(pending.requestId(), pending)) {
            pendingCoreGraphRequests.remove(pending.requestId());
            coreRequestRecoveries.remove(pending.requestId());
            cancelPendingSend(pending.requestId().toString());
            if (manager != null) {
                if (document.deleted()) {
                    manager.completeResourceActivation(serverId, type, resource.id(), pending.enabled(), pending.legacyRequestId(), false,
                        "The resource was deleted before activation completed.", true);
                } else {
                    boolean enabled = document.activationState() == ResourceActivationState.ACTIVE;
                    manager.completeResourceActivationAuthoritative(serverId, type, resource.id(), enabled,
                        pending.legacyRequestId(), envelope.kind() == ProtocolEnvelope.Kind.CONFLICT
                            ? "The resource changed before activation completed." : "", envelope.kind() == ProtocolEnvelope.Kind.CONFLICT);
                }
            }
        }
    }

    private void handleTypedResourceActivationEnvelope(ReSyncProtocolEnvelopeProjection.Projection projection,
                                                       ReSyncResourceType type, ServerResourceLocator resource,
                                                       ResourceDocument<Map<String, Object>> document) {
        ProtocolEnvelope<Map<String, Object>> envelope = projection.envelope();
        PendingTypedResourceRequest pending = matchingPendingTypedResourceRequest(envelope, document, resource, type);
        if (envelope.kind() != ProtocolEnvelope.Kind.EVENT && pending == null) {
            return;
        }
        FlowManager manager = client != null ? client.getFlowManager() : null;
        if (document == null) {
            if (removePendingTypedResourceRequest(pending)) {
                cancelPendingSend(pending.requestId().toString());
                if (manager != null) {
                    manager.completeResourceActivation(serverId, type, resource.id(), pending.activationEnabled(),
                        pending.legacyRequestId(), false, "The resource was not found on ReSync.", true);
                }
            }
            return;
        }
        if (!document.deleted() && document.activationState() == null) {
            if (pending != null) {
                failTypedResourceRequest(pending, "The server returned an invalid activation result.");
            }
            return;
        }
        GenericResourceProjectionOutcome outcome = applyTypedResourceDocument(type, document, envelope.authorityEpoch(),
            envelope.kind() != ProtocolEnvelope.Kind.CONFLICT, true);
        if (outcome == GenericResourceProjectionOutcome.RETRY) {
            logger().operation("Resource Synchronization").warn("Deferred generic activation after projection failure");
            return;
        }
        if (outcome != GenericResourceProjectionOutcome.APPLIED) {
            if (pending != null) {
                failTypedResourceRequest(pending, "The server returned an invalid activation result.");
            }
            return;
        }
        if (removePendingTypedResourceRequest(pending)) {
            cancelPendingSend(pending.requestId().toString());
            if (manager != null) {
                if (document.deleted()) {
                    manager.completeResourceActivation(serverId, type, resource.id(), pending.activationEnabled(),
                        pending.legacyRequestId(), false, "The resource was deleted before activation completed.", true);
                } else {
                    boolean enabled = document.activationState() == ResourceActivationState.ACTIVE;
                    manager.completeResourceActivationAuthoritative(serverId, type, resource.id(), enabled,
                        pending.legacyRequestId(), envelope.kind() == ProtocolEnvelope.Kind.CONFLICT
                            ? "The resource changed before activation completed." : "", envelope.kind() == ProtocolEnvelope.Kind.CONFLICT);
                }
            }
        }
    }

    private PendingResourceActivation pendingResourceActivation(ProtocolEnvelope<Map<String, Object>> envelope,
                                                                 ServerResourceLocator resource,
                                                                 ResourceDocument<Map<String, Object>> document) {
        UUID requestId = envelope.requestId();
        if (envelope.kind() == ProtocolEnvelope.Kind.ACK || envelope.kind() == ProtocolEnvelope.Kind.CONFLICT) {
            if (requestId == null) {
                return null;
            }
            PendingResourceActivation pending = pendingResourceActivations.get(requestId);
            return pending != null && pending.matchesResponse(envelope, resource, document) ? pending : null;
        }
        if (envelope.kind() != ProtocolEnvelope.Kind.EVENT || document == null) {
            return null;
        }
        UUID mutationId = document.mutationId();
        for (PendingResourceActivation pending : pendingResourceActivations.values()) {
            if (pending.matches(resource) && pending.mutationId().equals(mutationId)) {
                return pending;
            }
        }
        return null;
    }

    private void refreshValidDataChannels() {
        Set<Short> channels = new HashSet<>(channelIds.values());
        channels.add(numericChannel("flow", FLOW_CHANNEL_ID));
        channels.add(numericChannel("player_tracking", PLAYER_TRACKING_CHANNEL_ID));
        channels.add(numericChannel("world_management", WORLD_MANAGEMENT_CHANNEL_ID));
        channels.add(numericChannel("worldgen", WORLDGEN_CHANNEL_ID));
        validDataChannelIds = Set.copyOf(channels);
    }

    private void protocolError(String message) {
        String reason = message == null || message.isBlank() ? "Unknown protocol error" : message;
        logger().operation("Protocol").with("protocolError", reason).error("ReSync protocol error");
        if (!authenticated.get()) {
            Integer generation = inboundGeneration.get();
            observeHandshakeFailure(generation != null ? generation : connectionGeneration.get(),
                HandshakeStage.FAILED, "protocol_error");
            failConnectionAttempt("ReSync Handshake Failed. Retrying",
                generation != null ? generation : connectionGeneration.get());
            return;
        }
        notifyError("ReSyncProtocolError: " + reason);
        for (Consumer<String> listener : protocolErrorListeners) {
            listener.accept(reason);
        }
    }

    private void resetHandshakeAuthorityEpoch() {
        authorityEpochEstablished = false;
        handshakeAuthorityEpoch = 0L;
        authorityEpochAdvertised = false;
        triggerUpdateEpochNegotiated = false;
        triggerBindingEpoch = 0L;
        triggerBindingHash = null;
        optionQueriesAdvertised = false;
        genericResourceContractVersion = null;
        sessionCapabilities = null;
    }

    private void hydrateTriggerBindingState(JsonObject capabilities) {
        if (capabilities == null) {
            triggerBindingEpoch = 0L;
            triggerBindingHash = null;
            return;
        }
        JsonElement value = capabilities.get(ReSyncProtocolContract.FLOW_TRIGGER_UPDATE_BINDING_STATE_CAPABILITY);
        if (value == null || !value.isJsonObject()) {
            triggerBindingEpoch = 0L;
            triggerBindingHash = null;
            return;
        }
        JsonObject state = value.getAsJsonObject();
        JsonElement epochValue = state.get(ReSyncProtocolContract.FLOW_TRIGGER_UPDATE_BINDING_STATE_EPOCH_FIELD);
        JsonElement hashValue = state.get(ReSyncProtocolContract.FLOW_TRIGGER_UPDATE_BINDING_STATE_HASH_FIELD);
        if (epochValue == null || !epochValue.isJsonPrimitive() || !epochValue.getAsJsonPrimitive().isNumber()
            || hashValue == null || !hashValue.isJsonPrimitive() || !hashValue.getAsJsonPrimitive().isString()) {
            triggerBindingEpoch = 0L;
            triggerBindingHash = null;
            return;
        }
        try {
            long epoch = epochValue.getAsLong();
            String hash = hashValue.getAsString();
            if (epoch < 1L || hash.isBlank()) {
                triggerBindingEpoch = 0L;
                triggerBindingHash = null;
                return;
            }
            triggerBindingEpoch = epoch;
            triggerBindingHash = hash;
        } catch (RuntimeException exception) {
            triggerBindingEpoch = 0L;
            triggerBindingHash = null;
        }
    }

    long triggerBindingEpoch() {
        return triggerBindingEpoch;
    }

    String triggerBindingHash() {
        return triggerBindingHash;
    }

    int activeTransportGeneration() {
        synchronized (outboundLock) {
            return activeTransportGeneration;
        }
    }

    boolean withCurrentTransportGeneration(int generation, BooleanSupplier action) {
        if (action == null || generation < 0) {
            return false;
        }
        synchronized (outboundLock) {
            if (!isConnectionReadyGeneration(generation)) {
                return false;
            }
            return action.getAsBoolean();
        }
    }

    boolean matchesTriggerBindingState(long epoch, String hash) {
        synchronized (outboundLock) {
            return epoch > 0L && hash != null && !hash.isBlank() && triggerBindingEpoch == epoch
                && hash.equals(triggerBindingHash);
        }
    }

    boolean adoptTriggerBindingStateIfCurrent(int generation, long epoch, String hash) {
        if (generation < 0 || epoch < 1L || hash == null || hash.isBlank()) {
            return false;
        }
        synchronized (outboundLock) {
            if (!isConnectionReadyGeneration(generation) || triggerBindingEpoch > epoch
                || triggerBindingEpoch == epoch && !Objects.equals(triggerBindingHash, hash)) {
                return false;
            }
            triggerBindingEpoch = epoch;
            triggerBindingHash = hash;
            return true;
        }
    }

    private void hydrateHandshakeAuthorityEpoch(JsonObject capabilities) {
        HandshakeEpochDeclaration declaration = parseHandshakeAuthorityEpoch(capabilities);
        if (!declaration.advertised()) {
            return;
        }
        boolean previousAdvertised = authorityEpochAdvertised;
        boolean previousEstablished = authorityEpochEstablished;
        long previousHandshakeEpoch = handshakeAuthorityEpoch;
        ReSyncResourceRevisionReconciler.Snapshot previousReconciler = resourceRevisionReconciler.snapshot();
        Map<String, Long> previousRevisionWatermarks = Map.copyOf(resourceRevisionWatermarks);
        synchronized (worldGenAuthorityTransitionLock) {
            authorityEpochAdvertised = true;
            authorityEpochEstablished = false;
            if (!declaration.valid()) {
                logger().operation("Handshake").warn("ReSync advertised an invalid authority epoch; typed mutations remain blocked");
                return;
            }
            WorldGenManager manager = WorldGenManager.getInstance();
            long managerEpoch = manager.authorityEpoch(serverId);
            long reconcilerEpoch = resourceRevisionReconciler.authorityEpoch(serverId);
            if (managerEpoch != reconcilerEpoch) {
                if (declaration.epoch() == managerEpoch && reconcilerEpoch < managerEpoch) {
                    ReSyncResourceRevisionReconciler.EpochDecision decision = resourceRevisionReconciler
                        .observeAuthorityEpoch(serverId, declaration.epoch());
                    if (decision.accepted()
                        && resourceRevisionReconciler.authorityEpoch(serverId) == declaration.epoch()) {
                        if (decision.advanced()) {
                            resourceRevisionWatermarks.clear();
                        }
                        handshakeAuthorityEpoch = declaration.epoch();
                        authorityEpochEstablished = true;
                        return;
                    }
                }
                restoreHandshakeAuthorityState(previousAdvertised, previousEstablished, previousHandshakeEpoch,
                    previousReconciler, previousRevisionWatermarks);
                logger().operation("Handshake").with("authorityEpoch", declaration.epoch())
                    .warn("ReSync authority authorities are out of sync; typed mutations remain blocked");
                return;
            }
            long currentEpoch = managerEpoch;
            if (declaration.epoch() < currentEpoch) {
                restoreHandshakeAuthorityState(previousAdvertised, previousEstablished, previousHandshakeEpoch,
                    previousReconciler, previousRevisionWatermarks);
                logger().operation("Handshake").with("authorityEpoch", declaration.epoch())
                    .warn("ReSync advertised a stale authority epoch; typed mutations remain blocked");
                return;
            }
            handshakeAuthorityEpoch = currentEpoch;
            if (declaration.epoch() == currentEpoch) {
                authorityEpochEstablished = currentEpoch > 0L;
                if (!authorityEpochEstablished) {
                    logger().operation("Handshake").warn("ReSync authority epoch is not established; typed mutations remain blocked");
                }
                return;
            }
            WorldGenManager.EpochDecision decision = manager.acceptAuthorityEpoch(serverId, declaration.epoch(),
                new WorldGenManager.AuthorityEpochTransition() {
                    @Override
                    public boolean prepare(long nextEpoch) {
                        return canAdvanceWorldGenAuthorityEpoch(nextEpoch);
                    }

                    @Override
                    public boolean commit(long nextEpoch) {
                        return advanceWorldGenAuthorityEpoch(nextEpoch);
                    }

                    @Override
                    public void rollback(long previousEpoch, long nextEpoch) {
                        restoreHandshakeAuthorityState(previousAdvertised, previousEstablished, previousHandshakeEpoch,
                            previousReconciler, previousRevisionWatermarks);
                    }
                });
            if (!decision.accepted() || manager.authorityEpoch(serverId) != declaration.epoch()
                || resourceRevisionReconciler.authorityEpoch(serverId) != declaration.epoch()
                || handshakeAuthorityEpoch != declaration.epoch()) {
                restoreHandshakeAuthorityState(previousAdvertised, previousEstablished, previousHandshakeEpoch,
                    previousReconciler, previousRevisionWatermarks);
                logger().operation("Handshake").with("authorityEpoch", declaration.epoch())
                    .warn("ReSync authority epoch could not be committed atomically; typed mutations remain blocked");
                return;
            }
            authorityEpochEstablished = true;
        }
    }

    private void restoreHandshakeAuthorityState(boolean advertised, boolean established, long handshakeEpoch,
                                                ReSyncResourceRevisionReconciler.Snapshot reconcilerSnapshot,
                                                Map<String, Long> revisionWatermarks) {
        authorityEpochAdvertised = advertised;
        authorityEpochEstablished = established;
        handshakeAuthorityEpoch = handshakeEpoch;
        resourceRevisionReconciler.restore(reconcilerSnapshot);
        resourceRevisionWatermarks.clear();
        resourceRevisionWatermarks.putAll(revisionWatermarks);
    }

    private HandshakeEpochDeclaration parseHandshakeAuthorityEpoch(JsonObject capabilities) {
        if (capabilities == null) {
            return HandshakeEpochDeclaration.absent();
        }
        JsonElement direct = capabilities.get("authorityEpoch");
        JsonElement nested = null;
        JsonElement protocolEnvelope = capabilities.get("protocolEnvelope");
        if (protocolEnvelope != null && protocolEnvelope.isJsonObject()) {
            nested = protocolEnvelope.getAsJsonObject().get("authorityEpoch");
        }
        if (direct == null && nested == null) {
            return HandshakeEpochDeclaration.absent();
        }
        EpochValue directValue = epochValue(direct);
        EpochValue nestedValue = epochValue(nested);
        if (direct != null && nested != null
            && (!directValue.valid() || !nestedValue.valid() || directValue.value() != nestedValue.value())) {
            return HandshakeEpochDeclaration.invalid();
        }
        EpochValue selected = direct != null ? directValue : nestedValue;
        return new HandshakeEpochDeclaration(true, selected.valid(), selected.value());
    }

    private EpochValue epochValue(JsonElement value) {
        if (value == null) {
            return EpochValue.absent();
        }
        if (value.isJsonObject()) {
            JsonObject object = value.getAsJsonObject();
            JsonElement current = object.get("current");
            JsonElement epoch = object.get("epoch");
            if (current != null && epoch != null) {
                EpochValue currentValue = epochValue(current);
                EpochValue epochValueResult = epochValue(epoch);
                return currentValue.valid() && epochValueResult.valid() && currentValue.value() == epochValueResult.value()
                    ? currentValue : EpochValue.invalid();
            }
            return epochValue(current != null ? current : epoch);
        }
        if (!value.isJsonPrimitive() || !value.getAsJsonPrimitive().isNumber()) {
            return EpochValue.invalid();
        }
        try {
            long epoch = Long.parseLong(value.getAsString());
            return epoch < 1L ? EpochValue.invalid() : new EpochValue(true, true, epoch);
        } catch (RuntimeException exception) {
            return EpochValue.invalid();
        }
    }

    private boolean typedMutationAuthorityReady() {
        return authorityEpochAdvertised && authorityEpochEstablished && handshakeAuthorityEpoch > 0L
            && resourceRevisionReconciler.authorityEpoch(serverId) == handshakeAuthorityEpoch
            && WorldGenManager.getInstance().authorityEpoch(serverId) == handshakeAuthorityEpoch;
    }

    private boolean optionQueryAuthorityReady() {
        return authorityEpochAdvertised && authorityEpochEstablished && handshakeAuthorityEpoch > 0L;
    }

    private long optionQueryAuthorityEpoch() {
        if (!optionQueryAuthorityReady()) {
            throw new IllegalStateException("The established authority epoch is required for option queries");
        }
        return handshakeAuthorityEpoch;
    }

    private boolean acceptOptionQueryAuthorityEpoch(long authorityEpoch) {
        return optionQueryAuthorityReady() && authorityEpoch == handshakeAuthorityEpoch;
    }

    private String typedMutationAuthorityFailure() {
        if (!authorityEpochAdvertised) {
            return "The connected ReSync server did not advertise an authority epoch; the typed request was not sent.";
        }
        if (!authorityEpochEstablished || handshakeAuthorityEpoch < 1L) {
            return "The connected ReSync authority epoch is not established; the typed request was not sent.";
        }
        if (resourceRevisionReconciler.authorityEpoch(serverId) != handshakeAuthorityEpoch) {
            return "The connected ReSync authority epoch is stale; refresh and try again.";
        }
        if (WorldGenManager.getInstance().authorityEpoch(serverId) != handshakeAuthorityEpoch) {
            return "The connected World Generation authority epoch is stale; refresh and try again.";
        }
        return "The connected ReSync authority epoch is unavailable; the typed request was not sent.";
    }

    private void handleHandshakeResponse(byte[] payload, int generation) {
        boolean acknowledgedCatalogPublicationKey;
        if (!isActiveGeneration(generation) || !pendingHandshakeGeneration.compareAndSet(generation, -generation)) {
            return;
        }
        observeHandshakeStage(generation, HandshakeStage.RESPONSE_CLAIMED, "response_claimed");
        ByteBuffer buffer = ByteBuffer.wrap(payload);
        if (buffer.remaining() < 1) {
            protocolError("Handshake response too short");
            return;
        }

        byte success = buffer.get();
        if (success != 1) {
            logger().operation("Handshake").error("ReSync server rejected the connection");
            failConnectionAttempt("ReSync Connection Rejected. Retrying", generation);
            return;
        }

        if (buffer.remaining() < 4) {
            protocolError("Handshake message length missing");
            return;
        }
        int messageLen = buffer.getInt();
        if (messageLen < 0 || messageLen > buffer.remaining()) {
            protocolError("Invalid handshake message length");
            return;
        }
        buffer.position(buffer.position() + messageLen);

        if (buffer.remaining() < 4) {
            protocolError("Handshake protocol version missing");
            return;
        }
        int protocolVersion = buffer.getInt();
        logger().operation("Handshake").with("protocolVersion", protocolVersion).debug("ReSync protocol negotiated");

        if (buffer.remaining() < 4) {
            protocolError("Handshake server version length missing");
            return;
        }
        int serverVersionLen = buffer.getInt();
        if (serverVersionLen < 0 || serverVersionLen > buffer.remaining()) {
            protocolError("Invalid handshake server version length");
            return;
        }
        buffer.position(buffer.position() + serverVersionLen);

        if (buffer.remaining() < 4) {
            protocolError("Handshake world count missing");
            return;
        }
        int worldCount = buffer.getInt();
        if (worldCount < 0) {
            protocolError("Invalid handshake world count");
            return;
        }
        logger().operation("Handshake").with("worldCount", worldCount).debug("ReSync worlds received");
        for (int i = 0; i < worldCount; i++) {
            if (readSizedString(buffer) == null) {
                protocolError("Invalid handshake world entry");
                return;
            }
        }
        if (buffer.remaining() >= 4) {
            int tileSizeCount = buffer.getInt();
            if (tileSizeCount < 0 || buffer.remaining() < tileSizeCount * Integer.BYTES) {
                protocolError("Invalid handshake tile size list");
                return;
            }
            buffer.position(buffer.position() + tileSizeCount * Integer.BYTES);
        }
        if (buffer.remaining() >= 4) {
            int channelCount = buffer.getInt();
            for (int i = 0; i < channelCount; i++) {
                String channelName = readSizedString(buffer);
                if (channelName == null || buffer.remaining() < 4) {
                    protocolError("Invalid handshake channel entry");
                    return;
                }
                int numericId = buffer.getInt();
                if (numericId >= 0 && numericId <= 0xFFFF) {
                    registerChannel(channelName, (short) numericId);
                }
            }
            refreshValidDataChannels();
        }
        boolean hydratedCatalogPublication = catalogPublicationProjection.active().isPresent();
        boolean receivedServerCapabilities = false;
        acknowledgedCatalogPublicationKey = !hydratedCatalogPublication;
        boolean legacyServerNegotiated = buffer.remaining() < 4 && !hydratedCatalogPublication;
        JsonObject capabilities = null;
        boolean catalogAuthoringAdvertisedByServer = false;
        boolean optionQueriesAdvertisedByServer = false;
        CatalogVersion genericResourceContractVersionByServer = null;
        boolean typedPublicationAdvertised = false;
        boolean flowContractAdvertised = false;
        boolean triggerUpdateEpochAdvertised = false;
        if (buffer.remaining() < 4 && frameTransport == null) {
            protocolError("Handshake server identity is missing");
            return;
        }
        if (buffer.remaining() >= 4) {
            String capabilitiesJson = readSizedString(buffer);
            if (capabilitiesJson == null) {
                protocolError("Invalid handshake capabilities envelope");
                return;
            }
            if (capabilitiesJson.isBlank()) {
                protocolError("Handshake server identity is missing");
                return;
            } else {
                try {
                    JsonElement parsedCapabilities = JsonTreeParser.parse(capabilitiesJson);
                    if (!parsedCapabilities.isJsonObject()) {
                        protocolError("Invalid handshake capabilities envelope");
                        return;
                    } else {
                        capabilities = parsedCapabilities.getAsJsonObject();
                    }
                } catch (RuntimeException exception) {
                    protocolError("Invalid handshake capabilities envelope");
                    return;
                }
                if (!validateHandshakeServerIdentity(capabilities)) {
                    return;
                }
                observeHandshakeStage(generation, HandshakeStage.CAPABILITIES_VALIDATED, "server_identity_validated");
                receivedServerCapabilities = true;
                catalogAuthoringAdvertisedByServer = hasCatalogAuthoringCapability(capabilities);
                genericResourceContractVersionByServer = negotiateGenericResourceContractVersion(capabilities);
                typedPublicationAdvertised = hasTypedCatalogPublicationKey(capabilities);
                flowContractAdvertised = capabilities.has("flowContract");
                if (flowContractAdvertised) {
                    if (!validateNegotiatedFlowCapabilities(capabilities)) {
                        return;
                    }
                    optionQueriesAdvertisedByServer = hasNegotiatedFlowCapability(capabilities,
                        OPTION_QUERY_CAPABILITY);
                    triggerUpdateEpochAdvertised = hasNegotiatedFlowCapability(capabilities,
                        ReSyncProtocolContract.FLOW_TRIGGER_UPDATE_CAPABILITY);
                }
            }
        }

        if (!validateFramePeerServerIdentity(!receivedServerCapabilities)) {
            return;
        }

        observeHandshakeStage(generation, HandshakeStage.RESPONSE_FINALIZATION, "generation_validation");
        if (!isActiveGeneration(generation)) {
            observeHandshakeFailure(generation, HandshakeStage.AUTHENTICATION_REJECTED, "inactive_generation");
            return;
        }
        observeHandshakeStage(generation, HandshakeStage.AUTHENTICATION_STARTED, "generation_authentication");
        if (!authenticateGeneration(generation)) {
            return;
        }
        cancelConnectTimeout(generation);
        notifiedConnectionError.set(null);

        JsonObject negotiatedCapabilities = capabilities == null ? new JsonObject() : capabilities.deepCopy();
        synchronized (outboundLock) {
            if (!isConnectionReadyGeneration(generation)) {
                return;
            }
            sessionCapabilities = new SessionCapabilities(generation, negotiatedCapabilities);
        }
        if (receivedServerCapabilities) {
            setCatalogAuthoringAdvertised(catalogAuthoringAdvertisedByServer);
            genericResourceContractVersion = genericResourceContractVersionByServer;
            optionQueriesAdvertised = optionQueriesAdvertisedByServer
                && ReSyncProtocolContract.GENERIC_RESOURCE_CONTRACT_VERSION.equals(genericResourceContractVersion);
            hydrateHandshakeAuthorityEpoch(capabilities);
            hydrateTriggerBindingState(capabilities);
            triggerUpdateEpochNegotiated = flowContractAdvertised && triggerUpdateEpochAdvertised;
            if (typedPublicationAdvertised) {
                beginTypedReconciliation("CATALOG_PUBLICATION_KEY_RECONCILIATION");
            } else if (hydratedCatalogPublication || flowContractAdvertised) {
                beginTypedReconciliation("CATALOG_TYPED_PUBLICATION_UNAVAILABLE");
                acknowledgedCatalogPublicationKey = false;
            } else {
                legacyServerNegotiated = true;
            }
            FlowManager manager = owningFlowManager();
            if (manager != null) {
                observeHandshakeStage(generation, HandshakeStage.CAPABILITIES_CACHE_STARTED,
                    "flow_manager_capability_cache");
                manager.cacheServerCapabilities(serverId, capabilities);
                observeHandshakeStage(generation, HandshakeStage.CAPABILITIES_CACHED,
                    "flow_manager_capability_cache");
            }
            observeHandshakeStage(generation, HandshakeStage.CORE_REQUEST_RECONCILIATION_STARTED,
                "pending_core_requests");
            failUnsupportedCoreGraphRequests();
            observeHandshakeStage(generation, HandshakeStage.CORE_REQUESTS_RECONCILED, "pending_core_requests");
            if (typedPublicationAdvertised) {
                observeHandshakeStage(generation, HandshakeStage.CATALOG_ACKNOWLEDGEMENT_STARTED,
                    "catalog_publication_key");
                acknowledgedCatalogPublicationKey = acknowledgeCatalogPublicationKey(capabilities);
                observeHandshakeStage(generation, HandshakeStage.CATALOG_ACKNOWLEDGED,
                    acknowledgedCatalogPublicationKey ? "catalog_key_acknowledged" : "catalog_key_not_acknowledged");
            }
            observeHandshakeStage(generation, HandshakeStage.DURABILITY_HEALTH_STARTED, "durability_health");
            try {
                notifyDurabilityHealth(capabilities);
            } catch (RuntimeException exception) {
                logger().operation("Handshake").with("reason", exception.getMessage()).warn("Could not display storage health");
            }
            observeHandshakeStage(generation, HandshakeStage.DURABILITY_HEALTH_COMPLETED, "durability_health");
        } else if (hydratedCatalogPublication) {
            setCatalogAuthoringAdvertised(false);
            beginTypedReconciliation("CATALOG_TYPED_CAPABILITIES_UNAVAILABLE");
            acknowledgedCatalogPublicationKey = false;
        }

        if (typedCatalogAuthorityAdvertised) {
            legacyCompatibilityProven = false;
        } else if (legacyServerNegotiated) {
            typedCatalogAuthorityAdvertised = false;
            setCatalogAuthoringAdvertised(false);
            legacyCompatibilityProven = true;
            retireTypedInteractionProjection();
            catalogPublicationProjection.clear();
            catalogAuthoringProjection.clear();
            resourceRevisionReconciler.clearServer(serverId);
            resourceRevisionWatermarks.clear();
            FlowManager manager = owningFlowManager();
            if (manager != null) {
                manager.cacheServerCapabilities(serverId, new JsonObject());
            }
            loadCachedRegistry();
        }

        if (!receivedServerCapabilities) {
            FlowManager manager = owningFlowManager();
            if (manager != null) {
                manager.cacheServerCapabilities(serverId, new JsonObject());
            }
            failPendingCoreGraphRequests("The server no longer advertises Core graph support.");
        }
        boolean startupSubscriptionsReady = runStartupStep(generation, "startup subscriptions",
            () -> subscribeStartupChannels(generation));
        boolean pluginSubscriptionsReady = startupSubscriptionsReady
            && runStartupStep(generation, "plugin subscriptions", () -> subscribePluginChannels(generation));
        if (startupSubscriptionsReady && pluginSubscriptionsReady) {
            observeHandshakeStage(generation, HandshakeStage.STARTUP_ORDERING_RELEASE_STARTED,
                "startup_subscription_ordering");
        }
        releaseStartupSubscriptionOrdering(generation);
        if (startupSubscriptionsReady && pluginSubscriptionsReady) {
            observeHandshakeStage(generation, HandshakeStage.STARTUP_ORDERING_RELEASE_COMPLETED,
                "startup_subscription_ordering");
        }
        if (!startupSubscriptionsReady || !pluginSubscriptionsReady
            || !runStartupStep(generation, "collaboration", collaboration::connectionReady)) {
            return;
        }
        if (!runStartupStep(generation, "resource lists", this::flushPendingResourceListRequests)) {
            return;
        }
        logger().operation("Handshake").info("ReSync client authenticated");
        if (!runStartupStep(generation, "heartbeat", () -> startHeartbeat(generation))
            || !runStartupStep(generation, "option catalog", () -> OptionCatalogCache.getInstance().markServerStale(serverId))) {
            return;
        }
        if (typedCatalogAuthorityAdvertised) {
            if (acknowledgedCatalogPublicationKey) {
                if (!runStartupStep(generation, "catalog authority", this::refreshCatalogAuthority)) {
                    return;
                }
            } else {
                if (!runStartupStep(generation, "catalog reconciliation",
                    () -> beginTypedReconciliation("CATALOG_PUBLICATION_KEY_MISMATCH_RECONCILIATION"))) {
                    return;
                }
            }
            boolean publicationRefreshRequired = !acknowledgedCatalogPublicationKey
                || (catalogAuthoringAdvertised && activeAuthoringSnapshot().isEmpty());
            if (!runStartupStep(generation, "catalog publication",
                () -> ensureCatalogPublicationAfterHydration(publicationRefreshRequired))) {
                return;
            }
        } else if (legacyCompatibilityProven) {
            if (!runStartupStep(generation, "catalog authority", this::refreshCatalogAuthority)
                || !runStartupStep(generation, "node registry", this::requestNodeRegistry)) {
                return;
            }
        } else {
            if (!runStartupStep(generation, "catalog reconciliation",
                () -> beginTypedReconciliation("CATALOG_PUBLICATION_RECONCILIATION_REQUIRED"))
                || !runStartupStep(generation, "catalog publication",
                    () -> ensureCatalogPublicationAfterHydration(true))) {
                return;
            }
        }
        if (!runStartupStep(generation, "job snapshots", this::requestJobSnapshots)
            || !runStartupStep(generation, "send queue", this::flushPendingSends)) {
            return;
        }
        if (!pendingSendsDrained(generation)) {
            observeHandshakeStage(generation, HandshakeStage.STARTUP_COMPLETION_PENDING, "pending_send_queue");
            synchronized (outboundLock) {
                if (isConnectionReadyGeneration(generation)) {
                    pendingStartupCompletionGeneration = generation;
                }
            }
            return;
        }
        completeStartupAfterPendingSends(generation);
    }

    private boolean validateHandshakeServerIdentity(JsonObject capabilities) {
        JsonElement value = capabilities.get("serverId");
        if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isString()) {
            protocolError("Handshake server identity is missing or invalid");
            return false;
        }
        String handshakeServerId = value.getAsString();
        if (!isCanonicalServerIdentity(serverId)) {
            protocolError("Configured server identity is not canonical");
            return false;
        }
        if (!isCanonicalServerIdentity(handshakeServerId)) {
            protocolError("Handshake server identity is not canonical");
            return false;
        }
        if (!serverId.equals(handshakeServerId)) {
            protocolError("Handshake server identity does not match the configured server");
            return false;
        }
        return true;
    }

    private boolean validateFramePeerServerIdentity(boolean required) {
        if (frameTransport == null || framePeerServerId.isEmpty()) {
            if (required) {
                protocolError("Capabilityless handshake peer server identity is missing");
                return false;
            }
            return true;
        }
        String peerServerId = framePeerServerId.orElseThrow().canonicalText();
        if (!isCanonicalServerIdentity(serverId) || !peerServerId.equals(serverId)) {
            protocolError("Frame transport peer server identity does not match the configured server");
            return false;
        }
        return true;
    }

    private static boolean isCanonicalServerIdentity(String value) {
        if (value == null || value.isBlank()) {
            return false;
        }
        try {
            return UUID.fromString(value).toString().equals(value);
        } catch (IllegalArgumentException exception) {
            return false;
        }
    }

    private void completeStartupAfterPendingSends(int generation) {
        synchronized (outboundLock) {
            if (!isConnectionReadyGeneration(generation) || drainingPendingSends || !pendingSends.isEmpty()) {
                return;
            }
            if (completedStartupGeneration == generation || completingStartupGeneration == generation) {
                return;
            }
            completingStartupGeneration = generation;
            pendingStartupCompletionGeneration = generation;
        }
        boolean terminalSuccess = false;
        try {
            if (!runStartupStep(generation, "catalog receipt outbox",
                () -> drainCatalogPublicationReceiptOutbox(generation)) || !pendingSendsDrained(generation)) {
                return;
            }
            BrowserSafeState.BooleanValue workspacesConnected = new BrowserSafeState.BooleanValue();
            if (!runStartupStep(generation, "workspaces",
                () -> workspacesConnected.set(connectWorkspaces(generation))) || !workspacesConnected.get()) {
                if (isConnectionReadyGeneration(generation) && pendingSendsDrained(generation)) {
                    scheduleTransportFailure(generation, "workspace_startup");
                }
                return;
            }
            synchronized (outboundLock) {
                if (!isConnectionReadyGeneration(generation) || drainingPendingSends || !pendingSends.isEmpty()
                    || completingStartupGeneration != generation) {
                    return;
                }
                completedStartupGeneration = generation;
                pendingStartupCompletionGeneration = -1;
                completingStartupGeneration = -1;
                terminalSuccess = true;
            }
        } finally {
            if (!terminalSuccess) {
                synchronized (outboundLock) {
                    if (completingStartupGeneration == generation) {
                        completingStartupGeneration = -1;
                    }
                }
            }
        }
        if (isConnectionReadyGeneration(generation)) {
            notifyPluginChannelsAvailable();
            reestablishSession(generation);
            retryPendingOpenLoads(generation);
            observeHandshakeStage(generation, HandshakeStage.CONNECTION_LISTENER_QUEUED, "connection_listener");
            boolean listenerQueued = submitCurrentConnectionCallback(() -> {
                observeHandshakeStage(generation, HandshakeStage.CONNECTION_LISTENER_RUNNING, "connection_listener");
                connectionListener.run();
                observeHandshakeStage(generation, HandshakeStage.COMPLETE, "connection_listener_completed");
            });
            if (!listenerQueued) {
                observeHandshakeFailure(generation, HandshakeStage.FAILED, "connection_listener_rejected");
            }
            submitCurrentConnectionCallback(() -> refreshRetainedStudio(generation));
        }
    }

    private void reestablishSession(int generation) {
        synchronized (outboundLock) {
            boolean publicationHydration = catalogAuthority == CatalogAuthority.TYPED_PUBLICATION;
            if (!isConnectionReadyGeneration(generation)
                || sessionHydrationGeneration.get() == generation
                && (!publicationHydration || sessionPublicationHydrationGeneration.get() == generation)
                || completedStartupGeneration != generation || !sessionHydrationReady()) {
                return;
            }
            sessionHydrationGeneration.set(generation);
            if (publicationHydration) {
                sessionPublicationHydrationGeneration.set(generation);
            }
        }
        logger().operation("Resource Hydration").info("Re-establishing typed resource lists: generation=" + generation
            + ",authority=" + catalogAuthority + ",catalogReady=" + typedMutationAuthorityReady());
        for (ReSyncResourceType type : ReSyncResourceType.values()) {
            if (!isConnectionReadyGeneration(generation)) {
                return;
            }
            if (isProtocolResourceType(type)) {
                requestResourceList(type);
            }
        }
    }

    private boolean sessionHydrationReady() {
        return legacyReadCompatibilityAllowed()
            || catalogAuthority == CatalogAuthority.TYPED_PUBLICATION && typedMutationAuthorityReady();
    }

    private void refreshRetainedStudio(int generation) {
        if (!isConnectionReadyGeneration(generation)) {
            return;
        }
        FlowManager manager = client != null ? client.getFlowManager() : null;
        if (manager != null) {
            manager.refreshStudioWorkspace(serverId, true);
        }
    }

    private void resetResourceListProjection(int generation) {
        authoritativeResourceListTypes.clear();
        authoritativeResourceListGeneration.set(generation);
        sessionHydrationGeneration.set(-1);
        sessionPublicationHydrationGeneration.set(-1);
    }

    private void markResourceListProjection(ReSyncResourceType type, ResourceOperationKind operation,
                                             String query) {
        if (type == null || operation != ResourceOperationKind.LIST || normalizeOptionalText(query) != null) {
            return;
        }
        int generation = activeTransportGeneration;
        if (generation < 0 || authoritativeResourceListGeneration.get() != generation
            || !isConnectionReadyGeneration(generation)) {
            return;
        }
        authoritativeResourceListTypes.add(type);
        logger().operation("Resource Hydration").debug("Resource list became authoritative: type=" + type.typeId()
            + ",generation=" + generation + ",authoritativeTypes=" + authoritativeResourceListTypes.size());
    }

    public boolean isResourceListAuthoritative(ReSyncResourceType type) {
        int generation = activeTransportGeneration;
        return type != null && generation >= 0 && authoritativeResourceListGeneration.get() == generation
            && authoritativeResourceListTypes.contains(type) && isConnectionReadyGeneration(generation);
    }

    private boolean runStartupStep(int generation, String name, Runnable action) {
        if (!isConnectionReadyGeneration(generation)) {
            observeHandshakeFailure(generation, HandshakeStage.FAILED,
                "startup_step_not_ready:" + name + ";retirement=" + lastRetirementDiagnostic);
            return false;
        }
        observeHandshakeStage(generation, HandshakeStage.STARTUP_STEP_STARTED, name);
        try {
            action.run();
        } catch (RuntimeException exception) {
            logger().operation("Handshake").with("step", name).with("reason", exception.getMessage()).warn("ReSync startup step failed");
            observeHandshakeFailure(generation, HandshakeStage.FAILED, "startup_step_exception:" + name);
            scheduleTransportFailure(generation, "startup_step_exception:" + name);
            return false;
        }
        if (!isConnectionReadyGeneration(generation)) {
            observeHandshakeFailure(generation, HandshakeStage.FAILED,
                "startup_step_retired:" + name + ";retirement=" + lastRetirementDiagnostic);
            return false;
        }
        observeHandshakeStage(generation, HandshakeStage.STARTUP_STEP_COMPLETED, name);
        return true;
    }

    private boolean pendingSendsDrained(int generation) {
        synchronized (outboundLock) {
            return isConnectionReadyGeneration(generation) && !drainingPendingSends && pendingSends.isEmpty();
        }
    }

    private void releaseStartupSubscriptionOrdering(int generation) {
        synchronized (outboundLock) {
            if (startupSubscriptionGeneration == generation) {
                startupSubscriptionGeneration = -1;
            }
        }
    }

    boolean connectWorkspaces(int generation) {
        synchronized (outboundLock) {
            if (!isConnectionReadyGeneration(generation) || drainingPendingSends || !pendingSends.isEmpty()) {
                return false;
            }
        }
        boolean connected = workspaces.connect(generation);
        if (!isConnectionReadyGeneration(generation)) {
            workspaces.disconnect("Connection Replaced", generation);
            return false;
        }
        return connected;
    }

    private void runLifecycleListener(String name, Runnable listener) {
        submitCurrentConnectionCallback(listener);
    }

    private void notifyFlowManagerDisconnected() {
        FlowManager manager = client != null ? client.getFlowManager() : null;
        if (manager != null) {
            manager.handleFlowClientDisconnected(this);
        }
    }

    private boolean validateNegotiatedFlowCapabilities(JsonObject capabilities) {
        if (capabilities == null || !capabilities.has("flowContract") || !capabilities.get("flowContract").isJsonObject()) {
            protocolError("Server did not negotiate the Flow registry contract");
            return false;
        }
        JsonObject contract = capabilities.getAsJsonObject("flowContract");
        int version = contract.has("version") ? contract.get("version").getAsInt() : 0;
        int minimumClientVersion = contract.has("minimumClientVersion") ? contract.get("minimumClientVersion").getAsInt() : 0;
        if (!FLOW_CONTRACT.accepts(version, minimumClientVersion)) {
            protocolError("Server Flow registry contract is incompatible: " + version);
            return false;
        }
        List<String> supported = flowContractCapabilities(contract, "supported");
        List<String> negotiated = flowContractCapabilities(contract, "negotiated");
        if (!FLOW_CONTRACT.matchesNegotiation(supported, negotiated)
            && !matchesNegotiatedFlowCapabilities(supported, negotiated)) {
            protocolError("Server Flow registry contract negotiation is malformed");
            return false;
        }
        if (!FLOW_CONTRACT.hasRequiredCapabilities(negotiated)) {
            List<String> missing = FLOW_CONTRACT.requiredCapabilities().stream()
                .filter(capability -> !negotiated.contains(capability))
                .toList();
            protocolError("Server Flow registry contract is missing capabilities: " + String.join(", ", missing.stream().sorted().toList()));
            return false;
        }
        return true;
    }

    private boolean matchesNegotiatedFlowCapabilities(List<String> supported, List<String> negotiated) {
        if (supported == null || supported.isEmpty() || negotiated == null || negotiated.isEmpty()
            || supported.stream().anyMatch(value -> value == null || value.isBlank())
            || negotiated.stream().anyMatch(value -> value == null || value.isBlank())
            || supported.size() != supported.stream().distinct().count()
            || negotiated.size() != negotiated.stream().distinct().count()) {
            return false;
        }
        List<String> expected = supported.stream()
            .filter(value -> FLOW_CONTRACT.clientCapabilities().contains(value) || isCatalogAuthoringCapability(value))
            .toList();
        return expected.equals(negotiated);
    }

    private boolean hasNegotiatedFlowCapability(JsonObject capabilities, String capability) {
        if (capabilities == null || capability == null || capability.isBlank()
            || !capabilities.has("flowContract") || !capabilities.get("flowContract").isJsonObject()) {
            return false;
        }
        List<String> negotiated = flowContractCapabilities(capabilities.getAsJsonObject("flowContract"), "negotiated");
        return negotiated != null && negotiated.contains(capability);
    }

    private List<String> flowContractCapabilities(JsonObject contract, String property) {
        if (contract == null || property == null || !contract.has(property) || !contract.get(property).isJsonArray()) {
            return null;
        }
        List<String> values = new ArrayList<>();
        for (JsonElement element : contract.getAsJsonArray(property)) {
            if (element == null || !element.isJsonPrimitive() || !element.getAsJsonPrimitive().isString()) {
                return null;
            }
            values.add(element.getAsString());
        }
        return values;
    }

    private boolean acknowledgeCatalogPublicationKey(JsonObject capabilities) {
        JsonElement value = firstValue(capabilities, "catalogPublicationKey", "catalogCacheKey", "activeCatalogKey");
        if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isString()) {
            logger().operation("Catalog Publication").debug("Server did not acknowledge a typed catalog publication key");
            return false;
        }
        try {
            CatalogCacheKey key = CatalogCacheKey.parseCanonicalText(value.getAsString());
            if (!acknowledgeCatalogPublicationKey(key)) {
                if (catalogPublicationProjection.acknowledgedKey().filter(key::equals).isPresent()) {
                    logger().operation("Catalog Publication").debug("Server catalog publication requires reconciliation");
                } else {
                    logger().operation("Catalog Publication").warn("Server catalog publication key was rejected");
                }
                return false;
            }
        } catch (RuntimeException exception) {
            logger().operation("Catalog Publication").warn("Server catalog publication key is invalid: " + exception.getMessage());
            return false;
        }
        return true;
    }

    private boolean hasTypedCatalogPublicationKey(JsonObject capabilities) {
        return capabilities != null && (capabilities.has("catalogPublicationKey")
            || capabilities.has("catalogCacheKey") || capabilities.has("activeCatalogKey"));
    }

    private boolean hasCatalogAuthoringCapability(JsonObject capabilities) {
        if (capabilities == null) {
            return false;
        }
        if (namedCapability(capabilities, "catalogAuthoring")
            || namedCapability(capabilities, "catalog_authoring")
            || namedCapability(capabilities, CATALOG_AUTHORING_CAPABILITY)) {
            return true;
        }
        JsonObject flowContract = capabilities.has("flowContract") && capabilities.get("flowContract").isJsonObject()
            ? capabilities.getAsJsonObject("flowContract") : null;
        if (flowContract != null) {
            if (capabilityValue(flowContract.get("negotiated"))) {
                return true;
            }
        }
        for (String property : List.of("capabilities", "supportedCapabilities", "negotiatedCapabilities")) {
            if (capabilityValue(capabilities.get(property))) {
                return true;
            }
        }
        return false;
    }

    private boolean namedCapability(JsonObject object, String name) {
        if (object == null || name == null || !object.has(name)) {
            return false;
        }
        JsonElement value = object.get(name);
        if (value == null || value.isJsonNull()) {
            return false;
        }
        if (value.isJsonPrimitive() && value.getAsJsonPrimitive().isBoolean()) {
            return value.getAsBoolean();
        }
        return !value.isJsonPrimitive() || isCatalogAuthoringCapability(value.getAsString());
    }

    private boolean capabilityValue(JsonElement value) {
        if (value == null || value.isJsonNull()) {
            return false;
        }
        if (value.isJsonPrimitive()) {
            if (value.getAsJsonPrimitive().isBoolean()) {
                return value.getAsBoolean();
            }
            return value.getAsJsonPrimitive().isString()
                && isCatalogAuthoringCapability(value.getAsString());
        }
        if (value.isJsonArray()) {
            for (JsonElement element : value.getAsJsonArray()) {
                if (capabilityValue(element)) {
                    return true;
                }
            }
            return false;
        }
        JsonObject object = value.getAsJsonObject();
        if (object.has("enabled") && object.get("enabled").isJsonPrimitive()
            && object.getAsJsonPrimitive("enabled").isBoolean()) {
            return object.get("enabled").getAsBoolean();
        }
        return object.has(CATALOG_AUTHORING_CAPABILITY) || object.has("catalog_authoring");
    }

    private boolean isCatalogAuthoringCapability(String value) {
        return CATALOG_AUTHORING_CAPABILITY.equals(value) || "catalog_authoring".equals(value);
    }

    private void notifyDurabilityHealth(JsonObject capabilities) {
        if (capabilities == null || !capabilities.has("durabilityHealth") || !capabilities.get("durabilityHealth").isJsonObject()) {
            return;
        }
        JsonObject health = capabilities.getAsJsonObject("durabilityHealth");
        String fingerprint = health.toString();
        if (fingerprint.equals(durabilityHealthFingerprint)) {
            return;
        }
        durabilityHealthFingerprint = fingerprint;
        String status = health.has("status") ? health.get("status").getAsString() : "HEALTHY";
        int issues = health.has("issues") && health.get("issues").isJsonArray() ? health.getAsJsonArray("issues").size() : 0;
        int recovered = health.has("recoveredTransactions") ? health.get("recoveredTransactions").getAsInt() : 0;
        if ("HEALTHY".equals(status) && recovered == 0) {
            return;
        }
        if ("DEGRADED".equals(status) && onlyRecoverableCopies(health)) {
            return;
        }
        Notification.Type type = "CRITICAL".equals(status) ? Notification.Type.ERROR
            : "DEGRADED".equals(status) ? Notification.Type.WARN : Notification.Type.INFO;
        String title = "HEALTHY".equals(status) ? "Storage Recovered" : "Storage Needs Attention";
        String message = durabilityMessage(health, issues, recovered);
        FlowManager manager = client != null ? client.getFlowManager() : null;
        executeCurrentServerUi(manager, () -> new Notification(title, message, type));
    }

    private boolean onlyRecoverableCopies(JsonObject health) {
        if (!health.has("issues") || !health.get("issues").isJsonArray() || health.getAsJsonArray("issues").isEmpty()) {
            return false;
        }
        for (JsonElement element : health.getAsJsonArray("issues")) {
            if (!element.isJsonObject()) {
                return false;
            }
            String code = element.getAsJsonObject().has("code") ? element.getAsJsonObject().get("code").getAsString() : "";
            if (!Set.of("ORPHANED_RESOURCE_COPY", "ORPHANED_GRAPH_COPY").contains(code)) {
                return false;
            }
        }
        return true;
    }

    private String durabilityMessage(JsonObject health, int issues, int recovered) {
        if (issues <= 0) {
            return recovered + " Interrupted Saves Recovered";
        }
        JsonObject issue = health.getAsJsonArray("issues").get(0).getAsJsonObject();
        String resourceId = issue.has("resourceId") ? issue.get("resourceId").getAsString() : "";
        String detail = issue.has("message") ? issue.get("message").getAsString() : issues + " Storage Issues";
        String path = issue.has("path") ? issue.get("path").getAsString() : "";
        String message = resourceId.isBlank() ? detail : resourceId + " · " + detail;
        if (!path.isBlank()) {
            message += "\n" + path;
        }
        return issues > 1 ? message + " · " + (issues - 1) + " More" : message;
    }

    private String readSizedString(ByteBuffer buffer) {
        if (buffer.remaining() < 4) {
            return null;
        }
        int length = buffer.getInt();
        if (length < 0 || buffer.remaining() < length) {
            return null;
        }
        byte[] bytes = new byte[length];
        buffer.get(bytes);
        return new String(bytes, StandardCharsets.UTF_8);
    }

    private String readRemainingJson(ByteBuffer buffer) {
        byte[] bytes = new byte[buffer.remaining()];
        buffer.get(bytes);
        return new String(bytes, StandardCharsets.UTF_8);
    }

    private void handleChannelRegistry(byte[] payload) {
        JsonObject root = gson.fromJson(new String(payload, StandardCharsets.UTF_8), JsonObject.class);
        if (root == null) {
            return;
        }
        boolean snapshot = root.has("snapshot") && root.get("snapshot").getAsBoolean();
        Set<String> previousPluginChannels = BrowserSafeState.set();
        if (snapshot) {
            for (String channelId : channelIds.keySet()) {
                if (isPluginChannel(channelId)) {
                    previousPluginChannels.add(channelId);
                }
            }
        }
        if (snapshot) {
            channelIds.clear();
            numericChannels.clear();
        }
        JsonObject channels = root.has("channels") && root.get("channels").isJsonObject() ? root.getAsJsonObject("channels") : null;
        if (channels != null) {
            for (Map.Entry<String, JsonElement> entry : channels.entrySet()) {
                int numericId = entry.getValue().getAsInt();
                if (numericId >= 0 && numericId <= 0xFFFF) {
                    registerChannel(entry.getKey(), (short) numericId);
                }
            }
        }
        if (snapshot) {
            for (String channelId : previousPluginChannels) {
                if (!channelIds.containsKey(channelId)) {
                    removeChannel(channelId);
                }
            }
        }
        JsonElement removed = root.get("removedChannels");
        if (removed != null && removed.isJsonArray()) {
            for (JsonElement element : removed.getAsJsonArray()) {
                if (element != null && !element.isJsonNull()) {
                    removeChannel(element.getAsString());
                }
            }
        }
        refreshValidDataChannels();
        subscribePluginChannels();
        notifyPluginChannelsAvailable();
    }

    private void registerChannel(String channelId, short numericId) {
        if (channelId == null || channelId.isBlank()) {
            return;
        }
        channelIds.put(channelId, numericId);
        numericChannels.put(numericId, channelId);
    }

    private void removeChannel(String channelId) {
        Short numericId = channelIds.remove(channelId);
        if (numericId != null) {
            numericChannels.remove(numericId);
        }
        if (!availablePluginChannels.remove(channelId)) {
            return;
        }
        Set<PluginChannelListener> listeners = pluginChannelListeners.get(channelId);
        if (listeners != null) {
            for (PluginChannelListener listener : listeners) {
                notifyPluginListener(channelId, () -> listener.onRemoved(channelId));
            }
        }
    }

    private boolean isPluginChannel(String channelId) {
        return channelId != null
            && !"flow".equals(channelId)
            && !"player_tracking".equals(channelId)
            && !"world_management".equals(channelId)
            && !"worldgen".equals(channelId);
    }

    private void dispatchPluginChannelData(String channelId, byte[] data) {
        Set<PluginChannelListener> listeners = pluginChannelListeners.get(channelId);
        if (listeners == null || listeners.isEmpty()) {
            return;
        }
        byte[] payload = data == null ? new byte[0] : data;
        for (PluginChannelListener listener : listeners) {
            notifyPluginListener(channelId, () -> listener.onData(channelId, payload.clone()));
        }
    }

    private void subscribePluginChannels() {
        if (!isConnectedState()) {
            return;
        }
        for (String channelId : new ArrayList<>(pluginChannelSubscriptions)) {
            if (isPluginChannel(channelId) && channelIds.containsKey(channelId)) {
                sendSubscribe(channelId);
            }
        }
    }

    private void subscribePluginChannels(int generation) {
        if (!isConnectionReadyGeneration(generation)) {
            return;
        }
        for (String channelId : new ArrayList<>(pluginChannelSubscriptions)) {
            if (isPluginChannel(channelId) && channelIds.containsKey(channelId)) {
                sendStartupSubscribe(channelId, "", generation);
            }
        }
    }

    private void notifyPluginChannelsAvailable() {
        int generation = activeTransportGeneration;
        if (!isConnectionReadyGeneration(generation)) {
            return;
        }
        for (String channelId : channelIds.keySet()) {
            if (!isPluginChannel(channelId)) {
                continue;
            }
            if (!availablePluginChannels.add(channelId)) {
                continue;
            }
            Set<PluginChannelListener> listeners = pluginChannelListeners.get(channelId);
            if (listeners != null) {
                for (PluginChannelListener listener : listeners) {
                    notifyPluginListener(channelId, () -> listener.onAvailable(channelId));
                }
            }
        }
    }

    private void notifyPluginChannelsUnavailable() {
        for (String channelId : List.copyOf(availablePluginChannels)) {
            if (!availablePluginChannels.remove(channelId)) {
                continue;
            }
            Set<PluginChannelListener> listeners = pluginChannelListeners.get(channelId);
            if (listeners != null) {
                for (PluginChannelListener listener : listeners) {
                    notifyPluginListener(channelId, () -> listener.onRemoved(channelId));
                }
            }
        }
    }

    private void notifyPluginListener(String channelId, Runnable notification) {
        submitCurrentConnectionCallback(notification);
    }

    private short numericChannel(String channelId, short fallback) {
        Short numericId = channelIds.get(channelId);
        return numericId == null ? fallback : numericId;
    }

    private boolean isActiveGeneration(int generation) {
        return connectionGeneration.get() == generation && !shutdownRequested;
    }

    boolean currentConnectionOwnsTransport() {
        synchronized (outboundLock) {
            if (frameTransport != null) {
                int generation = activeTransportGeneration;
                int pendingGeneration = pendingHandshakeGeneration.get();
                return generation > 0 && isActiveGeneration(generation)
                    && connectionSource != null && connectionSource.accepts(generation)
                    && (authenticated.get() || pendingGeneration == generation || pendingGeneration == -generation);
            }
            return currentConnectionOwnsSocketLocked(wsClient.get());
        }
    }

    private boolean currentConnectionOwnsSocketLocked(Object socket) {
        int generation = activeTransportGeneration;
        int pendingGeneration = pendingHandshakeGeneration.get();
        return socket != null && socket == generationWebSocket && wsClient.get() == socket
            && generation > 0 && isActiveGeneration(generation)
            && connectionSource != null && connectionSource.accepts(generation)
            && (authenticated.get() || pendingGeneration == generation || pendingGeneration == -generation);
    }

    private boolean isConnectionReadyGeneration(int generation) {
        synchronized (outboundLock) {
            return isActiveGeneration(generation) && activeTransportGeneration == generation && authenticated.get()
                && connectionSource != null && connectionSource.accepts(generation);
        }
    }

    boolean authenticateGeneration(int generation) {
        synchronized (outboundLock) {
            boolean active = isActiveGeneration(generation);
            boolean sourcePresent = connectionSource != null;
            boolean sourceAccepts = sourcePresent && connectionSource.accepts(generation);
            int pendingGeneration = pendingHandshakeGeneration.get();
            if (!active || activeTransportGeneration != generation || !sourceAccepts) {
                String reason = !active ? "inactive_generation"
                    : activeTransportGeneration != generation ? "transport_generation_mismatch"
                    : !sourcePresent ? "source_missing" : "source_retired";
                String diagnostic = reason + ";retirement=" + lastRetirementDiagnostic;
                traceLifecycle(serverId, "handshake_authentication_rejected", "generation", generation,
                    "activeGeneration", activeTransportGeneration, "pendingGeneration", pendingGeneration,
                    "active", active, "sourcePresent", sourcePresent, "sourceAccepts", sourceAccepts,
                    "reason", reason, "retirement", lastRetirementDiagnostic);
                observeHandshakeFailure(generation, HandshakeStage.AUTHENTICATION_REJECTED, diagnostic);
                return false;
            }
            if (!pendingHandshakeGeneration.compareAndSet(-generation, 0)) {
                traceLifecycle(serverId, "handshake_authentication_rejected", "generation", generation,
                    "activeGeneration", activeTransportGeneration, "pendingGeneration", pendingHandshakeGeneration.get(),
                    "active", active, "sourcePresent", sourcePresent, "sourceAccepts", sourceAccepts,
                    "reason", "response_claim_missing");
                observeHandshakeFailure(generation, HandshakeStage.AUTHENTICATION_REJECTED, "response_claim_missing");
                return false;
            }
            authenticated.set(true);
            connecting.set(false);
            connectionFailure.set(ConnectionFailure.NONE);
            consecutiveReconnectFailures.set(0);
            frameOpeningFailureHandled.set(false);
            terminalFrameDisconnectPublished.set(false);
            cancelReconnectTask();
            startupSubscriptionGeneration = generation;
            observeHandshakeStage(generation, HandshakeStage.AUTHENTICATED, "startup_subscriptions_pending");
            return true;
        }
    }

    boolean claimConnectTimeout(int generation) {
        synchronized (outboundLock) {
            if (!isActiveGeneration(generation) || authenticated.get()) {
                return false;
            }
            return pendingHandshakeGeneration.compareAndSet(generation, 0);
        }
    }

    private ConnectionSource connectionSource(int generation) {
        synchronized (outboundLock) {
            return isActiveGeneration(generation) && activeTransportGeneration == generation
                && connectionSource != null && connectionSource.accepts(generation) ? connectionSource : null;
        }
    }

    private boolean isCurrentWebSocket(Object client, int generation) {
        synchronized (outboundLock) {
            return isActiveGeneration(generation) && activeTransportGeneration == generation
                && generationWebSocket == client && wsClient.get() == client;
        }
    }

    private ConnectionRetirement retireConnectionGeneration(int generation, String diagnostic) {
        ConnectionRetirement retirement;
        synchronized (outboundLock) {
            if (!connectionGeneration.compareAndSet(generation, generation + 1)) {
                return ConnectionRetirement.unchanged();
            }
            Object socket = activeTransportGeneration == generation ? generationWebSocket : null;
            ConnectionSource source = connectionSource != null && connectionSource.generation() == generation
                ? connectionSource : null;
            if (source != null) {
                source.retire();
                connectionSource = null;
            }
            activeTransportGeneration = -1;
            startupSubscriptionGeneration = -1;
            if (pendingStartupCompletionGeneration == generation) {
                pendingStartupCompletionGeneration = -1;
            }
            if (completingStartupGeneration == generation) {
                completingStartupGeneration = -1;
            }
            if (completedStartupGeneration == generation) {
                completedStartupGeneration = -1;
            }
            authoritativeResourceListGeneration.set(-1);
            authoritativeResourceListTypes.clear();
            sessionHydrationGeneration.set(-1);
            sessionPublicationHydrationGeneration.set(-1);
            generationWebSocket = null;
            if (socket != null) {
                wsClient.compareAndSet(socket, null);
            }
            if (!pendingHandshakeGeneration.compareAndSet(generation, 0)) {
                pendingHandshakeGeneration.compareAndSet(-generation, 0);
            }
            authenticated.set(false);
            connecting.set(true);
            lastRetirementDiagnostic = diagnostic == null || diagnostic.isBlank() ? "unspecified" : diagnostic;
            retirement = new ConnectionRetirement(true, socket, source);
        }
        if (retirement.retired()) {
            retireResourceSavesWithoutDispatch();
        }
        return retirement;
    }

    private boolean abandonConnectionGeneration(int generation) {
        synchronized (connectionCleanupLock) {
            ConnectionRetirement retirement = retireConnectionGeneration(generation, "connection_abandoned");
            if (!retirement.retired()) {
                return false;
            }
            cancelConnectTimeout(generation);
            if (retirement.socket() != null) {
                ReSyncDirectSockets.connector.close(retirement.socket());
            }
            failPendingTriggerUpdates("ReSync Connection Failed");
            clearCatalogPublication("CATALOG_PUBLICATION_GENERATION_RETIRED");
            connecting.set(false);
            return true;
        }
    }

    private void scheduleConnectTimeout(int generation) {
        synchronized (connectTimeoutLock) {
            cancelConnectTimeoutLocked();
            connectTimeoutGeneration = generation;
            connectTimeoutTask = heartbeatScheduler.schedule(() -> {
            if (!claimConnectTimeout(generation)) {
                return;
            }
            observeHandshakeFailure(generation, HandshakeStage.TIMED_OUT, "handshake_timeout");
            if (frameTransport != null) {
                logger().operation("Connect").warn("ReSync bridge handshake timed out");
            }
            synchronized (connectionCleanupLock) {
                if (frameTransport != null && isActiveGeneration(generation)) {
                    observeFrameTransportCloseReason(frameTransport.closeReason());
                }
                ConnectionRetirement retirement = retireConnectionGeneration(generation, "handshake_timeout");
                if (!retirement.retired()) {
                    return;
                }
                connectionFailure.compareAndSet(ConnectionFailure.NONE, ConnectionFailure.ENDPOINT_UNREACHABLE);
                boolean recovering = frameTransport != null && beginFrameRecovery(generation + 1);
                submitConnectionCleanup(retirement.source(), () -> {
                try {
                    if (retirement.socket() != null) {
                        ReSyncDirectSockets.connector.close(retirement.socket());
                    }
                    if (frameTransport != null) {
                        try {
                            if (recovering) {
                                frameTransport.retireSession();
                            } else {
                                frameTransport.close();
                            }
                        } catch (RuntimeException error) {
                            logger().operation("Connect").error("Could not close timed out ReSync transport", error);
                        }
                    }
                     disconnectCollaboration("Connection Timed Out", generation);
                     notifyPluginChannelsUnavailable();
                     PendingConnectionFailures failures = failPendingConnectionRequests("ReSync Connection Timed Out", true);
                     if (frameTransport == null) {
                        notifyFlowManagerDisconnected();
                        scheduleReconnect(generation + 1);
                     }
                    if (!recovering && frameTransport != null) {
                        publishTerminalFrameDisconnect(isRetryableConnectionFailure() ? "ReSync Connection Timed Out" : frameConnectionFailureMessage(),
                            !failures.saveMutations() && !failures.resourceDeletes());
                    }
                     if (failures.saveMutations() || failures.resourceDeletes()) {
                         return;
                    }
                    if (!recovering && frameTransport == null) {
                        notifyError("ReSync Connection Timed Out");
                    }
                } finally {
                    connecting.set(false);
                }
                });
            }
            }, Duration.ofSeconds(CONNECT_TIMEOUT_SECONDS));
        }
    }

    private void cancelConnectTimeout() {
        synchronized (connectTimeoutLock) {
            cancelConnectTimeoutLocked();
        }
    }

    private void cancelConnectTimeoutLocked() {
        if (connectTimeoutTask != null) {
            connectTimeoutTask.cancel();
            connectTimeoutTask = null;
        }
        connectTimeoutGeneration = -1;
    }

    private void cancelConnectTimeout(int generation) {
        synchronized (connectTimeoutLock) {
            if (connectTimeoutGeneration == generation) {
                cancelConnectTimeoutLocked();
            }
        }
    }

    private void handleDataMessage(short channel, byte[] data, int generation) {
        if (!isConnectionReadyGeneration(generation)) {
            protocolError("Data received before handshake authentication");
            return;
        }
        if (channel == numericChannel("player_tracking", PLAYER_TRACKING_CHANNEL_ID)) {
            handlePlayerTrackingMessage(data);
            return;
        }

        if (channel == numericChannel("world_management", WORLD_MANAGEMENT_CHANNEL_ID)) {
            handleWorldManagementMessage(data);
            return;
        }

        if (channel == numericChannel("worldgen", WORLDGEN_CHANNEL_ID)) {
            handleWorldGenMessage(data);
            return;
        }

        if (channel != numericChannel("flow", FLOW_CHANNEL_ID)) {
            String channelId = numericChannels.get(channel);
            if (channelId != null && isPluginChannel(channelId)) {
                dispatchPluginChannelData(channelId, data);
                return;
            }
            protocolError("Unknown channel: " + (channel & 0xFFFF));
            return;
        }

        ByteBuffer buffer = ByteBuffer.wrap(data);
        if (!buffer.hasRemaining()) {
            protocolError("Empty flow packet");
            return;
        }
        byte packetId = buffer.get();

        if (ReSyncResourceType.isLegacyGraphResponse(packetId)) {
            return;
        }

        ReSyncResourceType dataType = ReSyncResourceType.byDataResponse(packetId);
        if (dataType != null) {
            if (!legacyReadCompatibilityAllowed()) {
                return;
            }
            handleResourceData(dataType, buffer);
            return;
        }
        ReSyncResourceType listType = ReSyncResourceType.byListResponse(packetId);
        if (listType != null) {
            if (!legacyReadCompatibilityAllowed()) {
                return;
            }
            handleResourceList(listType, buffer, generation);
            return;
        }
        ReSyncResourceType saveAckType = ReSyncResourceType.bySaveAck(packetId);
        if (saveAckType != null) {
            if (!legacyMutationCompatibilityAllowed()) {
                return;
            }
            handleResourceSaveAck(saveAckType, buffer);
            return;
        }

        switch (packetId) {
            case ReSyncProtocolContract.FLOW_PACKET_GUI_STATE:
                handleGuiState(buffer);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_ERROR:
                handleFlowError(buffer);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_EDIT_TARGET_STATE:
                handleEditTargetState(buffer);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_PRESENCE_SNAPSHOT:
                handlePresenceSnapshot(buffer);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_RESOURCE_CHANGED:
                handleResourceEvent(buffer, false, generation);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_RESOURCE_DELETED:
                handleResourceEvent(buffer, true, generation);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_RESOURCE_ACTIVATION_RESULT:
                handleResourceActivationResult(buffer);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_WORKSPACE_SNAPSHOT:
                workspaceSource.applySnapshot(readRemainingJson(buffer), generation);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_WORKSPACE_OPERATION:
                workspaceSource.applyOperation(readRemainingJson(buffer), generation);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_WORKSPACE_AWARENESS:
                workspaceSource.applyAwareness(readRemainingJson(buffer), generation);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_WORKSPACE_RESYNC:
                workspaceSource.applyResync(readRemainingJson(buffer), generation);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_COLLABORATION_CHAT:
                collaboration.applyMessage(readRemainingJson(buffer));
                break;
            case ReSyncProtocolContract.FLOW_PACKET_QUICK_EDIT_OPEN:
                handleQuickEditOpen(buffer);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_QUICK_EDIT_RESULT:
                handleQuickEditResult(buffer);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_OPEN_CUSTOM_CONTENT:
                handleOpenCustomContent(buffer);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_JOB:
                handleFlowJob(buffer);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_PLACEHOLDER_PREVIEW:
                handlePlaceholderPreview(buffer);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_OPTION_CATALOG:
                handleOptionCatalog(buffer);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_TRACE_SNAPSHOT:
                handleTraceSnapshot(buffer);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_TRACE_EVENT:
                handleTraceEvent(buffer);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_DEBUG_EVENT:
                handleDebugSnapshot(buffer);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_FUNCTION_TEST_RESULT:
                handleFunctionTestResult(buffer);
                break;
            case ReSyncProtocolContract.MESSAGE_LOG_PACKET_RESPONSE:
                handleMessageLogPage(buffer);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_NODE_REGISTRY:
                handleNodeRegistrySnapshot(buffer, true);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_NODE_REGISTRY_DELTA:
                handleNodeRegistrySnapshot(buffer, false);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_CATALOG_PUBLICATION:
                handleCatalogPublication(buffer);
                break;
            case ReSyncProtocolContract.FLOW_PACKET_CATALOG_PUBLICATION_CHUNK:
                handleCatalogPublicationChunk(buffer);
                break;
        }
    }

    private void handleCatalogPublicationChunk(ByteBuffer buffer) {
        Integer inbound = inboundGeneration.get();
        int generation = inbound != null ? inbound : activeTransportGeneration;
        if (!authenticated.get() || generation < 0 || generation != activeTransportGeneration
            || !isConnectionReadyGeneration(generation)) {
            return;
        }
        CatalogPublicationAdmission admission = captureCatalogPublicationAdmission(generation, false);
        if (admission == null) {
            return;
        }
        submitCatalogPublicationWork(CatalogPublicationWork.chunk(admission, buffer));
    }

    private void handleCatalogPublication(ByteBuffer buffer) {
        Integer inbound = inboundGeneration.get();
        int generation = inbound != null ? inbound : activeTransportGeneration;
        if (!authenticated.get() || generation < 0 || generation != activeTransportGeneration
            || !isConnectionReadyGeneration(generation)) {
            return;
        }
        CatalogPublicationAdmission admission = captureCatalogPublicationAdmission(generation, true);
        if (admission == null) {
            return;
        }
        submitCatalogPublicationWork(CatalogPublicationWork.publication(admission, buffer));
    }

    private CatalogPublicationAdmission captureCatalogPublicationAdmission(int generation, boolean reconcile) {
        CatalogPublicationAdmission admission;
        synchronized (coreOptionDispatchLock) {
            synchronized (catalogLifecycleLock) {
                Optional<ServerId> expectedServer = catalogPublicationProjection.expectedServerId();
                if (shutdownRequested || !authenticated.get() || activeTransportGeneration != generation
                    || expectedServer.isEmpty()) {
                    return null;
                }
                long activity = catalogPublicationActivity.incrementAndGet();
                if (!currentCatalogAcquisitionLocked(catalogAcquisition) || catalogAcquisition.settled) {
                    long followUp = currentCatalogAcquisitionLocked(catalogAcquisition)
                        ? catalogAcquisition.followUpSequence : 0L;
                    boolean followUpFull = followUp > 0L && catalogAcquisition.followUpFull;
                    catalogAcquisition = new CatalogAcquisition(++catalogAcquisitionSequence, generation,
                        handshakeAuthorityEpoch, new CatalogDemand(++catalogDemandSequence, true, 0L),
                        catalogAcquisitionNanos());
                    catalogAcquisition.followUpSequence = followUp;
                    catalogAcquisition.followUpFull = followUpFull;
                    catalogAcquisition.pending = false;
                    catalogAcquisition.phase = "receiving";
                    armCatalogAcquisitionTimeoutLocked(catalogAcquisition);
                }
                if (reconcile && !catalogAcquisition.failed) {
                    markCatalogReconciliationLocked("CATALOG_PUBLICATION_RECONCILIATION");
                }
                admission = new CatalogPublicationAdmission(generation, handshakeAuthorityEpoch, catalogAcquisition.token,
                    activity, expectedServer.orElseThrow(),
                    catalogPublicationProjection.active().orElse(null), catalogAuthoringProjection.active().orElse(null),
                    catalogPublicationProjection.acknowledgedKey().orElse(null), catalogAuthoringAdvertised);
            }
        }
        if (reconcile) {
            notifyCatalogAuthorityUpdated();
        }
        return admission;
    }

    private void submitCatalogPublicationWork(CatalogPublicationWork work) {
        int bytes = work.payload().remaining();
        if (!reserveCatalogPublicationWork(bytes)) {
            catalogPublicationWorkEpoch.incrementAndGet();
            rejectCatalogPublicationAdmission(work.admission(), CATALOG_PUBLICATION_QUEUE_FULL);
            resetCatalogChunkAssembly();
            return;
        }
        CatalogPublicationWork admitted = work.withReservation(bytes, catalogPublicationWorkEpoch.get());
        try {
            catalogPublicationWorker.execute(new CatalogPublicationTask(admitted));
        } catch (IllegalStateException exception) {
            catalogPublicationWorkEpoch.incrementAndGet();
            rejectCatalogPublicationAdmission(work.admission(), CATALOG_PUBLICATION_QUEUE_FULL);
            resetCatalogChunkAssembly();
            releaseCatalogPublicationWork(bytes);
        }
    }

    boolean reserveCatalogPublicationWork(int bytes) {
        if (bytes < 1 || bytes > CatalogPublicationChunkPacket.MAX_PUBLICATION_BYTES) {
            return false;
        }
        long current = catalogPublicationWorkBytes.get();
        while (current <= MAX_CATALOG_PUBLICATION_WORK_BYTES - bytes) {
            if (catalogPublicationWorkBytes.compareAndSet(current, current + bytes)) {
                return true;
            }
            current = catalogPublicationWorkBytes.get();
        }
        return false;
    }

    private void processCatalogPublicationWork(CatalogPublicationWork work) {
        if (work.epoch() != catalogPublicationWorkEpoch.get() || shutdownRequested) {
            if (work.kind() == CatalogPublicationWork.Kind.CHUNK) {
                resetCatalogChunkAssembly();
            }
            releaseCatalogPublicationWork(work.reservedBytes());
            return;
        }
        if (work.kind() == CatalogPublicationWork.Kind.CHUNK) {
            processCatalogPublicationChunk(work);
            return;
        }
        boolean transferred = false;
        try {
            if (!currentCatalogPublicationAdmission(work.admission())) {
                return;
            }
            resetCatalogChunkAssembly();
            byte[] canonicalBytes = copyRemaining(work.payload());
            if (catalogPublicationDecoder == null) {
                processCatalogPublication(canonicalBytes, work.admission(), null);
            } else {
                new BrowserCatalogPublicationTask(canonicalBytes, work.admission(), null, work.epoch(),
                    work.reservedBytes()).start();
                transferred = true;
            }
        } finally {
            if (!transferred) {
                releaseCatalogPublicationWork(work.reservedBytes());
            }
        }
    }

    private void processCatalogPublicationChunk(CatalogPublicationWork work) {
        boolean transferred = false;
        CompletedCatalogPublication completed = null;
        long discardedBytes = 0L;
        String rejection = null;
        String rejectionReason = null;
        try {
            synchronized (catalogChunkLock) {
                try {
                    if (!currentCatalogTransport(work.admission())) {
                        discardedBytes += discardCatalogChunkAssemblyLocked();
                        return;
                    }
                    CatalogPublicationChunkPacket.Chunk chunk = CatalogPublicationChunkPacket.decode(
                        ReSyncProtocolContract.FLOW_PACKET_CATALOG_PUBLICATION_CHUNK, work.payload());
                    if (!catalogPublicationChunkReassembler.hasActiveTransfer() && catalogChunkReservedBytes > 0L) {
                        discardedBytes += discardCatalogChunkAssemblyLocked();
                    }
                    byte[] digest = chunk.digest();
                    boolean sameTransfer = catalogChunkScope == work.admission().generation()
                        && catalogChunkTotalLength == chunk.totalLength() && catalogChunkCount == chunk.chunkCount()
                        && Arrays.equals(catalogChunkDigest, digest);
                    if (!sameTransfer) {
                        if (chunk.chunkIndex() != 0) {
                            throw new IllegalArgumentException("Catalog publication transfer must begin with chunk zero");
                        }
                        discardedBytes += discardCatalogChunkAssemblyLocked();
                        catalogChunkScope = work.admission().generation();
                        catalogChunkTotalLength = chunk.totalLength();
                        catalogChunkCount = chunk.chunkCount();
                        catalogChunkDigest = digest;
                        catalogChunkNextIndex = 0;
                    }
                    if (chunk.chunkIndex() < catalogChunkNextIndex) {
                        Optional<byte[]> duplicate = catalogPublicationDecoder == null
                            ? catalogPublicationChunkReassembler.accept(work.admission().generation(), chunk)
                            : catalogPublicationChunkReassembler.acceptUnverified(work.admission().generation(), chunk);
                        if (duplicate.isPresent()) {
                            throw new IllegalArgumentException("Catalog publication duplicate completed a transfer");
                        }
                        catalogChunkAdmission = work.admission();
                        if (!scheduleCatalogChunkExpiry()) {
                            discardedBytes += discardCatalogChunkAssemblyLocked();
                            catalogPublicationWorkEpoch.incrementAndGet();
                            rejection = "CATALOG_PUBLICATION.CHUNK_TIMEOUT";
                            rejectionReason = "Catalog chunk expiry could not be scheduled";
                        }
                        return;
                    }
                    if (chunk.chunkIndex() != catalogChunkNextIndex) {
                        throw new IllegalArgumentException("Catalog publication chunks must arrive sequentially");
                    }
                    Optional<byte[]> assembled = catalogPublicationDecoder == null
                        ? catalogPublicationChunkReassembler.accept(work.admission().generation(), chunk)
                        : catalogPublicationChunkReassembler.acceptUnverified(work.admission().generation(), chunk);
                    int headerBytes = CatalogPublicationChunkPacket.HEADER_BYTES - 1;
                    int payloadBytes = work.reservedBytes() - headerBytes;
                    if (payloadBytes < 1) {
                        throw new IllegalArgumentException("Catalog publication chunk payload is empty");
                    }
                    releaseCatalogPublicationWork(headerBytes);
                    catalogChunkReservedBytes += payloadBytes;
                    transferred = true;
                    catalogChunkNextIndex++;
                    catalogChunkAdmission = work.admission();
                    observeCatalogProgress(work.admission(), "receiving", work.epoch());
                    if (assembled.isPresent()) {
                        long reservedBytes = catalogChunkReservedBytes;
                        ReSyncCatalogPublicationReceiptOutbox.PublicationIdentity identity =
                            new ReSyncCatalogPublicationReceiptOutbox.PublicationIdentity(
                                assembled.orElseThrow().length, chunk.digest());
                        clearCatalogChunkTracking();
                        completed = new CompletedCatalogPublication(assembled.orElseThrow(), work.admission(),
                            identity, reservedBytes);
                    } else if (shutdownRequested) {
                        discardedBytes += discardCatalogChunkAssemblyLocked();
                    } else if (!scheduleCatalogChunkExpiry()) {
                        discardedBytes += discardCatalogChunkAssemblyLocked();
                        catalogPublicationWorkEpoch.incrementAndGet();
                        rejection = "CATALOG_PUBLICATION.CHUNK_TIMEOUT";
                        rejectionReason = "Catalog chunk expiry could not be scheduled";
                    }
                } catch (RuntimeException exception) {
                    discardedBytes += discardCatalogChunkAssemblyLocked();
                    catalogPublicationWorkEpoch.incrementAndGet();
                    rejection = "CATALOG_PUBLICATION.CHUNK_REJECTED";
                    rejectionReason = exception.getMessage();
                }
            }
        } finally {
            if (rejection != null) {
                rejectCatalogPublicationAdmission(work.admission(), rejection);
                logger().operation("Catalog Publication").with("reason", rejectionReason)
                    .warn("Rejected invalid catalog publication chunk");
            }
            releaseCatalogPublicationWork(discardedBytes);
            if (!transferred) {
                releaseCatalogPublicationWork(work.reservedBytes());
            }
        }
        if (completed != null) {
            if (catalogPublicationDecoder == null) {
                try {
                    processCatalogPublication(completed.canonicalBytes(), completed.admission(), completed.identity());
                } finally {
                    releaseCatalogPublicationWork(completed.reservedBytes());
                }
            } else {
                new BrowserCatalogPublicationTask(completed.canonicalBytes(), completed.admission(),
                    completed.identity(), work.epoch(), completed.reservedBytes()).start();
            }
        }
    }

    private void processCatalogPublication(byte[] canonicalBytes, CatalogPublicationAdmission admission,
                                           ReSyncCatalogPublicationReceiptOutbox.PublicationIdentity verifiedIdentity) {
        if (!currentCatalogPublicationAdmission(admission)) {
            return;
        }
        observeCatalogProgress(admission, "decoding");
        PreparedCatalogPublication prepared;
        try {
            CatalogCachePublicationCodec.ValidatedPublication validated =
                catalogPublicationCodec.decodeValidatedPublication(canonicalBytes);
            CatalogCachePublication publication = validated.publication();
            observeCatalogProgress(admission, "preparing");
            if (!admission.expectedServer().equals(publication.serverId())) {
                throw new IllegalArgumentException("Catalog publication server does not match the connection");
            }
            CatalogPublicationReceipt pendingReceipt = CatalogPublicationReceipt
                .pending(stableClientId, catalogPublicationReceiptOwnerToken(admission.generation()), publication)
                .dispatched();
            CatalogPublicationReceipt.Transition received = pendingReceipt.clientReceived(publication.key(),
                publication.revision());
            if (!received.accepted()) {
                throw new IllegalArgumentException(received.code());
            }
            ReSyncCatalogPublicationReceiptHandler.PreparedApplication application = catalogPublicationReceiptHandler
                .prepare(received.receipt().orElseThrow(), validated);
            ReSyncTypedInteractionProjection interaction = null;
            if (application.ready()) {
                try {
                    ReSyncCatalogAuthoringProjection.Snapshot authoring = preparedInteractionAuthoring(application);
                    interaction = residentTypedInteractionProjection(admission, application.node().candidate(), authoring);
                    if (interaction == null) {
                        interaction = ReSyncTypedInteractionProjection.from(application.node().candidate(),
                            authoring != null ? authoring.publication() : null);
                    }
                } catch (ReSyncTypedInteractionProjection.ValidationException exception) {
                    application = ReSyncCatalogPublicationReceiptHandler.PreparedApplication.rejected(
                        publication.key(), publication.revision(), exception.diagnostic());
                }
            }
            prepared = new PreparedCatalogPublication(publication, application, interaction,
                verifiedIdentity == null ? ReSyncCatalogPublicationReceiptOutbox.PublicationIdentity.of(canonicalBytes)
                    : verifiedIdentity);
        } catch (RuntimeException exception) {
            rejectCatalogPublicationAdmission(admission, "CATALOG_PUBLICATION.PAYLOAD_REJECTED");
            logger().operation("Catalog Publication").with("reason", exception.getMessage())
                .warn("Rejected invalid catalog publication");
            return;
        }
        completeCatalogPublication(admission, prepared);
    }

    CatalogCachePublication decodeCatalogPublication(byte[] canonicalBytes) {
        return catalogPublicationCodec.decodeBytes(canonicalBytes);
    }

    private void completeCatalogPublication(CatalogPublicationAdmission admission,
                                            PreparedCatalogPublication prepared) {
        ReSyncCatalogPublicationReceiptOutbox.Reservation reservation = null;
        List<PendingCoreOptionRequest> retiredOptionRequests = List.of();
        boolean applied = false;
        boolean rejected = false;
        boolean outboxFull = false;
        String diagnostic = prepared.application().diagnostic();
        synchronized (coreOptionDispatchLock) {
            synchronized (catalogLifecycleLock) {
                if (!currentCatalogPublicationAdmissionLocked(admission)
                    || prepared.application().ready() && !prepared.matchesPrevious(admission)) {
                    traceLifecycle(serverId, "catalog_publication_discarded", "serverId", serverId,
                        "resourceKey", prepared.publication().key().canonicalText(), "requestId", "catalog",
                        "generation", admission.generation(), "authorityEpoch", admission.authorityEpoch(),
                        "reason", "admission_changed");
                    return;
                }
                reservation = catalogPublicationReceiptOutbox.reserveReceived(prepared.publication().key(),
                    prepared.publication().revision(), prepared.identity());
                if (reservation == null) {
                    markCatalogReconciliationLocked("CATALOG_PUBLICATION.RECEIPT_OUTBOX_FULL");
                    outboxFull = true;
                } else if (prepared.application().ready()) {
                    boolean optionAuthorityChanged = prepared.application().authoring() != null
                        && prepared.application().authoring().candidate() != prepared.application().previousAuthoring();
                    ReSyncCatalogPublicationReceiptHandler.Application committed = catalogPublicationReceiptHandler
                        .commit(prepared.application(), snapshot -> publishTypedInteractionProjection(snapshot,
                            prepared.interaction()));
                    if (!committed.applied()) {
                        catalogPublicationReceiptOutbox.release(reservation);
                        return;
                    }
                    catalogPublicationReceiptOutbox.publishReceived(reservation);
                    catalogPublicationReceiptOutbox.stageTerminal(prepared.publication().key(),
                        prepared.publication().revision(), prepared.identity(),
                        ReSyncCatalogPublicationReceiptOutbox.Terminal.APPLIED, "");
                    ReSyncCatalogAuthoringProjection.Snapshot installedAuthoring = activeAuthoringSnapshot()
                        .orElse(null);
                    if (installedAuthoring != null) {
                        retiredOptionRequests = retirePendingCoreOptionRequestsExcept(installedAuthoring,
                            admission.authorityEpoch(),
                            "The catalog publication changed before the option query completed");
                        OptionCatalogCache.getInstance().retainCorePublication(admission.expectedServer(),
                            installedAuthoring.publication().binding(), installedAuthoring.publication().contractVersion(),
                            installedAuthoring.checksum(), installedAuthoring.revision(), admission.authorityEpoch());
                    } else {
                        retiredOptionRequests = retirePendingCoreOptionRequests(
                            "The catalog publication no longer provides option queries");
                        OptionCatalogCache.getInstance().purgeCoreServer(admission.expectedServer());
                    }
                    if (optionAuthorityChanged) {
                        coreOptionInvalidationSequences.clear();
                    }
                    catalogPublicationConfirmed = true;
                    catalogAuthority = CatalogAuthority.TYPED_PUBLICATION;
                    catalogAuthorityDiagnostic = "";
                    applied = true;
                    if (currentCatalogAcquisitionLocked(catalogAcquisition)) {
                        catalogAcquisition.failed = false;
                        catalogAcquisition.settled = true;
                        catalogAcquisition.pending = false;
                        catalogAcquisition.phase = "committed";
                        cancelCatalogAcquisitionTimeoutLocked();
                    }
                } else {
                    catalogPublicationReceiptOutbox.publishReceived(reservation);
                    catalogPublicationReceiptOutbox.stageTerminal(prepared.publication().key(),
                        prepared.publication().revision(), prepared.identity(),
                        ReSyncCatalogPublicationReceiptOutbox.Terminal.REJECTED, diagnostic);
                    markCatalogReconciliationLocked(diagnostic);
                    rejected = true;
                }
            }
        }
        cancelRetiredCoreOptionRequests(retiredOptionRequests);
        if (outboxFull) {
            retryCurrentCatalogAcquisition(admission, "CATALOG_PUBLICATION.RECEIPT_OUTBOX_FULL");
            logger().operation("Catalog Debug").warn("Catalog application blocked by receipt outbox: "
                + catalogAuthorityDebugState());
            notifyCatalogAuthorityUpdated();
            return;
        }
        drainCatalogPublicationReceiptOutbox(admission.generation());
        if (applied) {
            logger().operation("Catalog Debug").info("Catalog application committed: "
                + catalogAuthorityDebugState());
            ReSyncResourceDropCapabilities.clearCatalog(serverId);
            retireLegacyRegistryProjection();
            notifyCatalogAuthorityUpdated();
            queueCatalogAcquisitionDrain();
        } else if (rejected) {
            logger().operation("Catalog Debug").warn("Catalog application rejected: diagnostic=" + diagnostic
                + ",state=" + catalogAuthorityDebugState());
            ReSyncResourceDropCapabilities.clearCatalog(serverId);
            retireLegacyRegistryProjection();
            failPendingAuthoringTemplateRequests(diagnostic);
            notifyCatalogAuthorityUpdated();
            logger().operation("Catalog Publication").warn(diagnostic);
            if (prepared.publication().kind() == CatalogCachePublication.Kind.DELTA
                || diagnostic.contains("AUTHORING")) {
                retryCurrentCatalogAcquisition(admission, diagnostic);
            } else {
                synchronized (catalogLifecycleLock) {
                    if (currentCatalogAcquisitionLocked(catalogAcquisition)) {
                        failCatalogAcquisitionLocked(catalogAcquisition, diagnostic);
                    }
                }
            }
        }
    }

    private boolean currentCatalogTransport(CatalogPublicationAdmission admission) {
        return admission != null && !shutdownRequested && authenticated.get()
            && activeTransportGeneration == admission.generation()
            && connectionGeneration.get() == admission.generation()
            && handshakeAuthorityEpoch == admission.authorityEpoch();
    }

    private boolean currentCatalogPublicationAdmission(CatalogPublicationAdmission admission) {
        synchronized (catalogLifecycleLock) {
            return currentCatalogPublicationAdmissionLocked(admission);
        }
    }

    private boolean currentCatalogPublicationAdmissionLocked(CatalogPublicationAdmission admission) {
        return currentCatalogTransport(admission) && catalogPublicationActivity.get() == admission.activity()
            && catalogAcquisition != null && catalogAcquisition.token == admission.acquisitionToken()
            && catalogPublicationProjection.expectedServerId().filter(admission.expectedServer()::equals).isPresent()
            && catalogPublicationProjection.active().orElse(null) == admission.previousNode()
            && catalogAuthoringProjection.active().orElse(null) == admission.previousAuthoring()
            && Objects.equals(catalogPublicationProjection.acknowledgedKey().orElse(null),
                admission.previousAcknowledgedKey())
            && catalogAuthoringAdvertised == admission.authoringRequired();
    }

    private void rejectCatalogPublicationAdmission(CatalogPublicationAdmission admission, String diagnostic) {
        CatalogAcquisition acquisition;
        synchronized (catalogLifecycleLock) {
            acquisition = catalogAcquisition;
            if (!currentCatalogPublicationAdmissionLocked(admission)
                || !currentCatalogAcquisitionLocked(acquisition) || acquisition.failed) return;
            markCatalogReconciliationLocked(diagnostic);
        }
        retryCatalogAcquisition(acquisition, diagnostic);
        notifyCatalogAuthorityUpdated();
    }

    private void markCatalogReconciliationLocked(String diagnostic) {
        typedCatalogAuthorityAdvertised = true;
        legacyCompatibilityProven = false;
        catalogPublicationConfirmed = false;
        clearTypedInteractionProjection();
        catalogAuthority = CatalogAuthority.TYPED_RECONCILIATION;
        catalogAuthorityDiagnostic = diagnostic;
    }

    void releaseCatalogPublicationWork(long bytes) {
        if (bytes <= 0L) {
            return;
        }
        if (catalogPublicationAccountingClosed.get()) {
            catalogPublicationWorkBytes.updateAndGet(current -> Math.max(0L, current - bytes));
            return;
        }
        long remaining = catalogPublicationWorkBytes.addAndGet(-bytes);
        if (remaining < 0L) {
            catalogPublicationWorkBytes.set(0L);
            throw new IllegalStateException("Catalog publication work accounting underflow");
        }
        if (remaining == 0L && catalogPublicationWorker.getQueue().isEmpty()) {
            queueCatalogAcquisitionDrain();
        }
    }

    private void resetCatalogChunkAssembly() {
        long reserved;
        synchronized (catalogChunkLock) {
            reserved = discardCatalogChunkAssemblyLocked();
        }
        releaseCatalogPublicationWork(reserved);
    }

    private long discardCatalogChunkAssemblyLocked() {
        catalogPublicationChunkReassembler.clear();
        long reserved = catalogChunkReservedBytes;
        clearCatalogChunkTracking();
        return reserved;
    }

    private void clearCatalogChunkTracking() {
        TaskScheduler.ScheduledTask timeout = catalogChunkIdleTimeout;
        catalogChunkIdleTimeout = null;
        if (timeout != null) {
            timeout.cancel();
        }
        catalogChunkScope = Long.MIN_VALUE;
        catalogChunkTotalLength = 0;
        catalogChunkCount = 0;
        catalogChunkNextIndex = 0;
        catalogChunkDigest = null;
        catalogChunkAdmission = null;
        catalogChunkReservedBytes = 0L;
    }

    private boolean scheduleCatalogChunkExpiry() {
        TaskScheduler.ScheduledTask timeout = catalogChunkIdleTimeout;
        if (timeout != null) {
            timeout.cancel();
        }
        CatalogChunkTransfer transfer = new CatalogChunkTransfer(catalogChunkScope, catalogChunkTotalLength,
            catalogChunkCount, catalogChunkNextIndex, catalogChunkDigest, catalogChunkAdmission);
        try {
            catalogChunkIdleTimeout = heartbeatScheduler.schedule(() -> {
                try {
                    catalogPublicationWorker.execute(new CatalogChunkExpiryTask(transfer));
                } catch (IllegalStateException exception) {
                    expireCatalogChunkTransfer(transfer);
                }
            }, Duration.ofSeconds(CATALOG_CHUNK_IDLE_SECONDS));
            return true;
        } catch (IllegalStateException exception) {
            return false;
        }
    }

    private void expireCatalogChunkTransfer(CatalogChunkTransfer transfer) {
        long discardedBytes = 0L;
        synchronized (catalogChunkLock) {
            if (transfer.matches(catalogChunkScope, catalogChunkTotalLength, catalogChunkCount, catalogChunkNextIndex,
                catalogChunkDigest, catalogChunkAdmission)) {
                catalogPublicationWorkEpoch.incrementAndGet();
                discardedBytes = discardCatalogChunkAssemblyLocked();
            }
        }
        if (discardedBytes > 0L) {
            rejectCatalogPublicationAdmission(transfer.admission(),
                "CATALOG_PUBLICATION.CHUNK_TIMEOUT");
            releaseCatalogPublicationWork(discardedBytes);
        }
    }

    private String catalogPublicationReceiptOwnerToken(int generation) {
        return stableClientId + ":transport:" + Integer.toUnsignedString(generation);
    }

    int pendingCatalogPublicationWork() {
        return catalogPublicationWorker.getQueue().size() + catalogPublicationWorker.getActiveCount();
    }

    long pendingCatalogPublicationBytes() {
        return catalogPublicationWorkBytes.get();
    }

    String catalogPublicationWorkerThreadName() {
        return "ReSync-Catalog-Publication";
    }

    Async<String> catalogPublicationWorkerIdentity() {
        Async<String> identity = Async.pending();
        try {
            catalogPublicationWorker.execute(() -> identity.complete(TaskIdentities.access.name()));
        } catch (IllegalStateException exception) {
            identity.fail(exception);
        }
        return identity;
    }

    private record CatalogPublicationAdmission(int generation, long authorityEpoch, long acquisitionToken,
                                               long activity, ServerId expectedServer,
                                               ReSyncCatalogPublicationProjection.Snapshot previousNode,
                                               ReSyncCatalogAuthoringProjection.Snapshot previousAuthoring,
                                               CatalogCacheKey previousAcknowledgedKey, boolean authoringRequired) {
        private CatalogPublicationAdmission {
            expectedServer = Objects.requireNonNull(expectedServer, "Expected catalog server is required");
            if (generation < 0 || activity < 1L) {
                throw new IllegalArgumentException("Catalog publication admission is invalid");
            }
        }
    }

    private record CatalogPublicationWork(Kind kind, CatalogPublicationAdmission admission, ByteBuffer payload,
                                          int reservedBytes, long epoch) {
        private CatalogPublicationWork {
            kind = Objects.requireNonNull(kind, "Catalog publication work kind is required");
            admission = Objects.requireNonNull(admission, "Catalog publication admission is required");
            payload = Objects.requireNonNull(payload, "Catalog publication payload is required").asReadOnlyBuffer();
            if (!payload.hasRemaining() || reservedBytes < 0L) {
                throw new IllegalArgumentException("Catalog publication work payload is invalid");
            }
        }

        private static CatalogPublicationWork publication(CatalogPublicationAdmission admission, ByteBuffer payload) {
            return new CatalogPublicationWork(Kind.PUBLICATION, admission, payload.slice(), 0, 0L);
        }

        private static CatalogPublicationWork chunk(CatalogPublicationAdmission admission, ByteBuffer payload) {
            return new CatalogPublicationWork(Kind.CHUNK, admission, payload.slice(), 0, 0L);
        }

        private CatalogPublicationWork withReservation(int bytes, long epoch) {
            return new CatalogPublicationWork(kind, admission, payload, bytes, epoch);
        }

        private enum Kind {
            PUBLICATION,
            CHUNK
        }
    }

    private final class CatalogPublicationTask implements Runnable {
        private final CatalogPublicationWork work;

        private CatalogPublicationTask(CatalogPublicationWork work) {
            this.work = Objects.requireNonNull(work, "Catalog publication work is required");
        }

        @Override
        public void run() {
            processCatalogPublicationWork(work);
        }

        private int reservedBytes() {
            return work.reservedBytes();
        }
    }

    private final class BrowserCatalogPublicationTask implements ReSyncCatalogPublicationDecoder.Callback {
        private final byte[] canonicalBytes;
        private final CatalogPublicationAdmission admission;
        private final ReSyncCatalogPublicationReceiptOutbox.PublicationIdentity expectedIdentity;
        private final long workEpoch;
        private final long reservedBytes;
        private final List<CatalogCachePublication.Entry> entries = new ArrayList<>();
        private CatalogCachePublication first;
        private byte[] authoringBytes;
        private byte[] nodeBytes;
        private int nextPart;
        private int totalParts;
        private int nextNodeOffset;
        private boolean finished;

        private BrowserCatalogPublicationTask(byte[] canonicalBytes, CatalogPublicationAdmission admission,
                                              ReSyncCatalogPublicationReceiptOutbox.PublicationIdentity expectedIdentity,
                                              long workEpoch, long reservedBytes) {
            this.canonicalBytes = canonicalBytes;
            this.admission = admission;
            this.expectedIdentity = expectedIdentity;
            this.workEpoch = workEpoch;
            this.reservedBytes = reservedBytes;
        }

        private void start() {
            if (!current()) {
                discard();
                return;
            }
            observeCatalogProgress(admission, "decoding", workEpoch);
            try {
                catalogPublicationDecoder.decode(canonicalBytes, this);
            } catch (RuntimeException exception) {
                failed(exception.getMessage());
            }
        }

        @Override
        public void part(int index, int total, byte[] partBytes) {
            if (finished) {
                return;
            }
            if (!current()) {
                discard();
                return;
            }
            try {
                if (partBytes == null || partBytes.length == 0 || partBytes.length > 512 * 1024
                    || total < 1 || total > CatalogPublicationChunkPacket.MAX_CHUNKS
                    || index != nextPart || nextPart > 0 && total != totalParts) {
                    throw new IllegalArgumentException("Catalog publication worker part order is invalid");
                }
                CatalogCachePublicationCodec.ValidatedPublication validated =
                    catalogPublicationCodec.decodeValidatedPublication(partBytes);
                CatalogCachePublication publication = validated.publication();
                if (first == null) {
                    first = publication;
                    totalParts = total;
                    authoringBytes = validated.authoringCanonicalBytes();
                } else if (publication.kind() != first.kind() || !publication.key().equals(first.key())
                    || !Objects.equals(publication.catalogBinding(), first.catalogBinding())
                    || publication.revision() != first.revision()
                    || publication.authoringPublication() != null || !publication.unknown().isEmpty()) {
                    throw new IllegalArgumentException("Catalog publication worker part identity changed");
                }
                if (!entries.isEmpty() && !publication.entries().isEmpty()
                    && entries.getLast().definitionKey().canonicalText().compareTo(
                        publication.entries().getFirst().definitionKey().canonicalText()) >= 0) {
                    throw new IllegalArgumentException("Catalog publication worker part order changed");
                }
                entries.addAll(publication.entries());
                nextPart++;
            } catch (RuntimeException exception) {
                failed(exception.getMessage());
            }
        }

        @Override
        public void node(int offset, int total, byte[] partBytes) {
            if (finished) {
                return;
            }
            if (!current()) {
                discard();
                return;
            }
            try {
                if (first == null || first.authoringPublication() == null || partBytes == null
                    || partBytes.length == 0 || partBytes.length > 128 * 1024
                    || total < 1 || total > CatalogPublicationChunkPacket.MAX_PUBLICATION_BYTES
                    || offset != nextNodeOffset || nodeBytes != null && nodeBytes.length != total
                    || partBytes.length > total - offset) {
                    throw new IllegalArgumentException("Catalog publication worker node bytes are invalid");
                }
                if (nodeBytes == null) {
                    nodeBytes = new byte[total];
                }
                System.arraycopy(partBytes, 0, nodeBytes, offset, partBytes.length);
                nextNodeOffset += partBytes.length;
            } catch (RuntimeException exception) {
                failed(exception.getMessage());
            }
        }

        @Override
        public void completed(byte[] sha256) {
            if (finished) {
                return;
            }
            if (!current()) {
                discard();
                return;
            }
            try {
                if (sha256 == null || sha256.length != CatalogPublicationChunkPacket.SHA256_BYTES
                    || first == null || nextPart != totalParts
                    || first.authoringPublication() != null
                        && (nodeBytes == null || nextNodeOffset != nodeBytes.length)
                    || first.authoringPublication() == null && nodeBytes != null
                    || expectedIdentity != null && !Arrays.equals(expectedIdentity.sha256(), sha256)) {
                    throw new IllegalArgumentException("Catalog publication worker digest or parts do not match");
                }
                ReSyncCatalogPublicationReceiptOutbox.PublicationIdentity identity = expectedIdentity == null
                    ? new ReSyncCatalogPublicationReceiptOutbox.PublicationIdentity(canonicalBytes.length, sha256)
                    : expectedIdentity;
                CatalogCachePublication publication = new CatalogCachePublication(first.kind(), first.key(),
                    first.catalogBinding(), first.revision(), entries, first.authoringPublication(), first.unknown());
                prepare(publication, identity);
            } catch (RuntimeException exception) {
                failed(exception.getMessage());
            }
        }

        private void prepare(CatalogCachePublication publication,
                             ReSyncCatalogPublicationReceiptOutbox.PublicationIdentity identity) {
            if (!admission.expectedServer().equals(publication.serverId())) {
                throw new IllegalArgumentException("Catalog publication server does not match the connection");
            }
            observeCatalogProgress(admission, "preparing", workEpoch);
            CatalogPublicationReceipt pendingReceipt = CatalogPublicationReceipt
                .pending(stableClientId, catalogPublicationReceiptOwnerToken(admission.generation()), publication)
                .dispatched();
            CatalogPublicationReceipt.Transition received = pendingReceipt.clientReceived(publication.key(),
                publication.revision());
            if (!received.accepted()) {
                throw new IllegalArgumentException(received.code());
            }
            ReSyncCatalogPublicationReceiptHandler.PreparedApplication application = catalogPublicationReceiptHandler
                .prepareWorkerValidated(received.receipt().orElseThrow(), publication, canonicalBytes,
                    nodeBytes == null ? canonicalBytes : nodeBytes, authoringBytes);
            if (!application.ready()) {
                publish(new PreparedCatalogPublication(publication, application, null, identity));
                return;
            }
            ReSyncCatalogAuthoringProjection.Snapshot authoring = preparedInteractionAuthoring(application);
            ReSyncTypedInteractionProjection resident = residentTypedInteractionProjection(admission,
                application.node().candidate(), authoring);
            if (resident != null) {
                publish(new PreparedCatalogPublication(publication, application, resident, identity));
                return;
            }
            ReSyncTypedInteractionProjection.Builder builder = ReSyncTypedInteractionProjection.begin(
                application.node().candidate(), authoring != null ? authoring.publication() : null);
            BrowserWork.execute(() -> project(publication, application, identity, builder));
        }

        private void project(CatalogCachePublication publication,
                             ReSyncCatalogPublicationReceiptHandler.PreparedApplication application,
                             ReSyncCatalogPublicationReceiptOutbox.PublicationIdentity identity,
                             ReSyncTypedInteractionProjection.Builder builder) {
            if (finished) {
                return;
            }
            if (!current()) {
                discard();
                return;
            }
            try {
                if (!builder.advance(8)) {
                    BrowserWork.execute(() -> project(publication, application, identity, builder));
                    return;
                }
                publish(new PreparedCatalogPublication(publication, application, builder.finish(), identity));
            } catch (ReSyncTypedInteractionProjection.ValidationException exception) {
                publish(new PreparedCatalogPublication(publication,
                    ReSyncCatalogPublicationReceiptHandler.PreparedApplication.rejected(publication.key(),
                        publication.revision(), exception.diagnostic()), null, identity));
            } catch (RuntimeException exception) {
                failed(exception.getMessage());
            }
        }

        private void publish(PreparedCatalogPublication prepared) {
            if (!current()) {
                discard();
                return;
            }
            try {
                completeCatalogPublication(admission, prepared);
            } finally {
                discard();
            }
        }

        @Override
        public void failed(String reason) {
            if (finished) {
                return;
            }
            boolean active = current();
            discard();
            if (active) {
                rejectCatalogPublicationAdmission(admission, "CATALOG_PUBLICATION.PAYLOAD_REJECTED");
                logger().operation("Catalog Publication").with("reason", reason == null ? "Worker failed" : reason)
                    .warn("Rejected invalid catalog publication");
            }
        }

        private boolean current() {
            return !finished && workEpoch == catalogPublicationWorkEpoch.get()
                && currentCatalogPublicationAdmission(admission);
        }

        private void discard() {
            if (!finished) {
                finished = true;
                releaseCatalogPublicationWork(reservedBytes);
            }
        }
    }

    private final class CatalogChunkExpiryTask implements Runnable {
        private final CatalogChunkTransfer transfer;

        private CatalogChunkExpiryTask(CatalogChunkTransfer transfer) {
            this.transfer = Objects.requireNonNull(transfer, "Catalog chunk transfer is required");
        }

        @Override
        public void run() {
            expireCatalogChunkTransfer(transfer);
        }
    }

    private record CatalogChunkTransfer(long scope, int totalLength, int chunkCount, int nextChunkIndex,
                                        byte[] digest, CatalogPublicationAdmission admission) {
        private CatalogChunkTransfer {
            digest = Objects.requireNonNull(digest, "Catalog chunk digest is required").clone();
            admission = Objects.requireNonNull(admission, "Catalog chunk admission is required");
            if (scope < 0L || totalLength < 1 || chunkCount < 1 || nextChunkIndex < 1
                || nextChunkIndex > chunkCount) {
                throw new IllegalArgumentException("Catalog chunk transfer is invalid");
            }
        }

        @Override
        public byte[] digest() {
            return digest.clone();
        }

        private boolean matches(long currentScope, int currentTotalLength, int currentChunkCount,
                                int currentNextChunkIndex, byte[] currentDigest,
                                CatalogPublicationAdmission currentAdmission) {
            return scope == currentScope && totalLength == currentTotalLength && chunkCount == currentChunkCount
                && nextChunkIndex == currentNextChunkIndex && Arrays.equals(digest, currentDigest)
                && admission == currentAdmission;
        }
    }

    private record CompletedCatalogPublication(byte[] canonicalBytes, CatalogPublicationAdmission admission,
                                               ReSyncCatalogPublicationReceiptOutbox.PublicationIdentity identity,
                                               long reservedBytes) {
        private CompletedCatalogPublication {
            canonicalBytes = Objects.requireNonNull(canonicalBytes, "Canonical catalog publication is required");
            admission = Objects.requireNonNull(admission, "Catalog publication admission is required");
            identity = Objects.requireNonNull(identity, "Verified catalog publication identity is required");
            if (canonicalBytes.length == 0 || reservedBytes < canonicalBytes.length) {
                throw new IllegalArgumentException("Completed catalog publication reservation is invalid");
            }
            if (identity.canonicalLength() != canonicalBytes.length) {
                throw new IllegalArgumentException("Verified catalog publication length does not match");
            }
        }
    }

    private record PreparedCatalogPublication(CatalogCachePublication publication,
                                              ReSyncCatalogPublicationReceiptHandler.PreparedApplication application,
                                              ReSyncTypedInteractionProjection interaction,
                                              ReSyncCatalogPublicationReceiptOutbox.PublicationIdentity identity) {
        private PreparedCatalogPublication {
            publication = Objects.requireNonNull(publication, "Catalog publication is required");
            application = Objects.requireNonNull(application, "Prepared catalog application is required");
            identity = Objects.requireNonNull(identity, "Catalog publication identity is required");
            if (!publication.key().equals(application.key()) || publication.revision() != application.revision()
                || application.ready() != (interaction != null)) {
                throw new IllegalArgumentException("Prepared catalog publication is inconsistent");
            }
        }

        private boolean matchesPrevious(CatalogPublicationAdmission admission) {
            return application.node().previous() == admission.previousNode()
                && application.previousAuthoring() == admission.previousAuthoring()
                && Objects.equals(application.previousAcknowledgedKey(), admission.previousAcknowledgedKey());
        }
    }

    private boolean publishTypedInteractionProjection(ReSyncCatalogPublicationProjection.Snapshot exactNode,
                                                      ReSyncTypedInteractionProjection prepared) {
        if (exactNode == null || prepared == null) {
            return false;
        }
        CatalogCacheKey key = exactNode.publication().key();
        Optional<ReSyncCatalogPublicationProjection.Snapshot> current = catalogPublicationProjection.active();
        Optional<CatalogCacheKey> currentAcknowledged = catalogPublicationProjection.acknowledgedKey();
        if (current.isEmpty() || current.orElseThrow() != exactNode || currentAcknowledged.isEmpty()
            || !key.equals(currentAcknowledged.orElseThrow()) || !key.equals(prepared.key())) {
            return false;
        }
        TypedInteractionState state = new TypedInteractionState(TypedInteractionStamp.of(exactNode,
            catalogAuthoringProjection.active().orElse(null)), connectionGeneration.get(), handshakeAuthorityEpoch, prepared);
        residentTypedInteraction = state;
        typedInteractionState.set(state);
        typedInteractionDiagnostic = "";
        return true;
    }

    private boolean currentTypedInteractionProjection() {
        TypedInteractionState state = typedInteractionState.get();
        if (state == null) {
            return false;
        }
        Optional<ReSyncCatalogPublicationProjection.Snapshot> active = catalogPublicationProjection.active();
        Optional<CatalogCacheKey> acknowledged = catalogPublicationProjection.acknowledgedKey();
        return active.isPresent() && acknowledged.isPresent() && state.key().equals(acknowledged.orElseThrow())
            && state.stamp().matches(active.orElseThrow(), catalogAuthoringProjection.active().orElse(null))
            && typedInteractionState.get() == state;
    }

    private static ReSyncCatalogAuthoringProjection.Snapshot preparedInteractionAuthoring(
        ReSyncCatalogPublicationReceiptHandler.PreparedApplication application) {
        return application.authoring() != null ? application.authoring().candidate() : application.previousAuthoring();
    }

    private ReSyncTypedInteractionProjection residentTypedInteractionProjection(CatalogPublicationAdmission admission,
        ReSyncCatalogPublicationProjection.Snapshot node, ReSyncCatalogAuthoringProjection.Snapshot authoring) {
        synchronized (catalogLifecycleLock) {
            TypedInteractionState state = residentTypedInteraction;
            return currentCatalogPublicationAdmissionLocked(admission) && state != null
                && state.generation() == admission.generation() && state.authorityEpoch() == admission.authorityEpoch()
                && state.stamp().matches(node, authoring) ? state.projection() : null;
        }
    }

    private void clearTypedInteractionProjection() {
        typedInteractionState.set(null);
        typedInteractionDiagnostic = "";
    }

    private void retireTypedInteractionProjection() {
        clearTypedInteractionProjection();
        synchronized (catalogLifecycleLock) {
            residentTypedInteraction = null;
        }
    }

    private void drainCatalogPublicationReceiptOutbox(int generation) {
        if (generation < 0 || !isConnectionReadyGeneration(generation)) {
            return;
        }
        for (ReSyncCatalogPublicationReceiptOutbox.Pending pending : catalogPublicationReceiptOutbox.pending()) {
            boolean receivedDelivered = pending.receivedDelivered();
            if (!receivedDelivered) {
                byte[] payload = CatalogPublicationReceiptPacket.encodeClientReceived(pending.key(), pending.revision());
                if (!sendCatalogPublicationReceiptFrame(generation, payload)) {
                    return;
                }
                catalogPublicationReceiptOutbox.markReceivedDelivered(pending);
                receivedDelivered = true;
            }
            if (pending.terminal() == null || !receivedDelivered) {
                continue;
            }
            byte[] payload = pending.terminal() == ReSyncCatalogPublicationReceiptOutbox.Terminal.APPLIED
                ? CatalogPublicationReceiptPacket.encodeCacheApplied(pending.key(), pending.revision())
                : CatalogPublicationReceiptPacket.encodeCacheRejected(pending.key(), pending.revision(), pending.diagnosticCode());
            if (!sendCatalogPublicationReceiptFrame(generation, payload)) {
                return;
            }
            catalogPublicationReceiptOutbox.markTerminalDelivered(pending);
        }
    }

    private boolean sendCatalogPublicationReceiptFrame(int generation, byte[] payload) {
        try {
            return sendFrame(ReSyncProtocolContract.MESSAGE_DATA, payload, numericChannel("flow", FLOW_CHANNEL_ID), false,
                generation);
        } catch (RuntimeException exception) {
            logger().operation("Catalog Publication").with("reason", exception.getMessage())
                .warn("Could not send catalog publication receipt");
            return false;
        }
    }

    private void handlePlayerTrackingMessage(byte[] data) {
        try {
            String json = new String(data, StandardCharsets.UTF_8);
            JsonObject envelope = gson.fromJson(json, JsonObject.class);
            String type = envelope != null && envelope.has("type") ? envelope.get("type").getAsString() : "";
            if ("player_control_capabilities".equals(type)) {
                playerControlCapabilities = envelope;
                return;
            }
            if ("player_control_response".equals(type)) {
                String requestId = envelope.has("requestId") ? envelope.get("requestId").getAsString() : "";
                Async<JsonObject> pending = pendingPlayerControlRequests.get(requestId);
                if (pending != null) {
                    submitConnectionCallback(inboundSource.get(),
                        () -> settlePlayerControlRequest(requestId, pending, envelope, null), true, true,
                        () -> settlePlayerControlRequest(requestId, pending, null,
                            new IllegalStateException("The ReSync player response was too large to deliver.")));
                }
                return;
            }
            PlayerTrackingUpdate update = PlayerTrackingJson.read(envelope);
            if (update == null) {
                return;
            }
            if (client != null && client.getFlowManager() != null) {
                client.getFlowManager().applyPlayerTrackingUpdate(serverId, update);
            }
        } catch (Exception e) {
            logger().operation("Player Tracking").error("Could not read player tracking update", e);
        }
    }

    private void handleWorldManagementMessage(byte[] data) {
        try {
            String json = new String(data, StandardCharsets.UTF_8);
            JsonElement parsed = JsonTreeParser.parse(json);
            if (!parsed.isJsonObject()) {
                return;
            }
            JsonObject root = parsed.getAsJsonObject();
            WorldChannelMessage message = new WorldChannelMessage(
                FlowJson.string(root, "type", ""),
                FlowJson.string(root, "action", ""),
                FlowJson.bool(root, "success", false),
                FlowJson.string(root, "message", ""),
                root.get("data"),
                FlowJson.longValue(root, "timestamp", 0L));
            if (message == null) {
                return;
            }
            trackWorldJob(message);
            if (client != null && client.getFlowManager() != null) {
                client.getFlowManager().applyWorldManagementMessage(serverId, message);
            }
        } catch (Exception e) {
            logger().operation("World Management").error("Could not read world management update", e);
        }
    }

    private void trackWorldJob(WorldChannelMessage message) {
        if (message == null || message.getData() == null) {
            return;
        }
        if (!"job".equals(message.getType()) && !"jobStatus".equals(message.getAction()) && !"jobAccepted".equals(message.getAction())) {
            return;
        }
        if (message.getData().isJsonArray()) {
            for (JsonElement item : message.getData().getAsJsonArray()) {
                if (item.isJsonObject()) {
                    trackGenericJob(item.getAsJsonObject());
                }
            }
            return;
        }
        if (message.getData().isJsonObject()) {
            JsonObject data = message.getData().getAsJsonObject();
            trackGenericJob(data);
        }
    }

    private void handleFlowJob(ByteBuffer buffer) {
        String json = readRemainingJson(buffer);
        JsonObject envelope = gson.fromJson(json, JsonObject.class);
        if (envelope != null && envelope.has("data")) {
            trackJobElement(envelope.get("data"));
        } else {
            trackGenericJob(envelope);
        }
    }

    private void handleTraceSnapshot(ByteBuffer buffer) {
        String json = readRemainingJson(buffer);
        FlowManager manager = client != null ? client.getFlowManager() : null;
        if (manager != null && manager.getDebugController() != null) {
            manager.getDebugController().applyTraceSnapshot(serverId, json);
        }
    }

    private void handleTraceEvent(ByteBuffer buffer) {
        String json = readRemainingJson(buffer);
        FlowManager manager = client != null ? client.getFlowManager() : null;
        if (manager != null && manager.getDebugController() != null) {
            manager.getDebugController().applyTraceEvent(serverId, json);
        }
    }

    private void handleDebugSnapshot(ByteBuffer buffer) {
        String json = readRemainingJson(buffer);
        FlowManager manager = client != null ? client.getFlowManager() : null;
        if (manager != null && manager.getDebugController() != null) {
            manager.getDebugController().applyDebugSnapshot(serverId, json);
        }
    }

    private void handleMessageLogPage(ByteBuffer buffer) {
        String json = readRemainingJson(buffer);
        try {
            JsonObject page = gson.fromJson(json, JsonObject.class);
            FlowManager manager = client != null ? client.getFlowManager() : null;
            if (manager != null && page != null) {
                manager.cacheMessageLogPage(serverId, page);
            }
        } catch (Exception e) {
            logger().operation("Message Log").error("Could not read message log", e);
        }
    }

    private void trackJobElement(JsonElement element) {
        if (element == null || element.isJsonNull()) {
            return;
        }
        if (element.isJsonArray()) {
            for (JsonElement item : element.getAsJsonArray()) {
                trackJobElement(item);
            }
            return;
        }
        if (element.isJsonObject()) {
            trackGenericJob(element.getAsJsonObject());
        }
    }

    private void trackGenericJob(JsonObject data) {
        if (data == null) {
            return;
        }
        if (data.has("data")) {
            trackJobElement(data.get("data"));
            return;
        }
        String jobId = stringField(data, "jobId");
        if (jobId == null || jobId.isBlank()) {
            jobId = stringField(data, "operationId");
        }
        if (jobId == null || jobId.isBlank()) {
            jobId = stringField(data, "taskId");
        }
        if (jobId == null || jobId.isBlank()) {
            return;
        }
        FlowManager manager = client != null ? client.getFlowManager() : null;
        FlowManager.ServerConnectionToken token = captureUiToken(manager);
        if (manager == null || !manager.isCurrentServerConnection(token)) {
            return;
        }
        startJobRetentionTicker();
        String status = stringField(data, "status");
        String action = stringField(data, "action");
        long now = System.currentTimeMillis();
        JsonObject previous;
        String previousStatus;
        boolean duplicateTerminal;
        boolean replayedTerminal;
        synchronized (jobRetentionLock) {
            previous = jobs.put(jobId, data);
            previousStatus = previous != null ? stringField(previous, "status") : null;
            boolean terminal = isTerminalJobStatus(status);
            TrackedJobState priorState = trackedJobStates.get(jobId);
            long sequence = priorState != null ? priorState.sequence() : jobSequence.incrementAndGet();
            long terminalAt = terminal
                ? priorState != null && priorState.terminal() ? priorState.terminalAt() : now
                : 0L;
            trackedJobStates.put(jobId, new TrackedJobState(
                priorState != null ? priorState.firstSeenAt() : now,
                now,
                sequence,
                terminal,
                terminalAt));
            if (terminal) {
                boolean previouslyNotified = terminalJobNotifications.contains(jobId);
                terminalJobNotifications.add(jobId);
                TrackedJobState priorNotification = terminalJobNotificationStates.get(jobId);
                long notificationSequence = priorNotification != null
                    ? priorNotification.sequence() : jobSequence.incrementAndGet();
                terminalJobNotificationStates.put(jobId, new TrackedJobState(
                    priorNotification != null ? priorNotification.firstSeenAt() : now,
                    now,
                    notificationSequence,
                    true,
                    priorNotification != null && priorNotification.terminal()
                        ? priorNotification.terminalAt() : now));
                replayedTerminal = previous == null && previouslyNotified;
            } else {
                terminalJobNotifications.remove(jobId);
                terminalJobNotificationStates.remove(jobId);
                replayedTerminal = false;
            }
            duplicateTerminal = status != null && status.equalsIgnoreCase(previousStatus)
                && terminal;
            pruneJobTrackingLocked(now);
        }
        logger().operation("Run Job").with("jobId", jobId).with("action", action).with("status", status).debug("ReSync job updated");
        if (duplicateTerminal || replayedTerminal) {
            String requestId = jobRequestId(data);
            if (requestId != null && !requestId.isBlank() && pendingTriggerUpdates.containsKey(requestId)) {
                TriggerUpdateOutcome outcome = "succeeded".equalsIgnoreCase(status)
                    ? parseTriggerUpdateOutcome(data.get("result"), true, false, stringField(data, "message"))
                    : parseTriggerUpdateOutcome(null, false, false, messageFromJob(data));
                settlePendingTriggerUpdate(requestId, outcome);
            }
            return;
        }
        if ("succeeded".equalsIgnoreCase(status)) {
            if (isTriggerUpdateAction(action)) {
                settlePendingTriggerUpdate(jobRequestId(data), parseTriggerUpdateOutcome(data.get("result"), true,
                    false, stringField(data, "message")));
            }
            completeResourceDelete(data);
            refreshAfterJob(action);
        } else if ("failed".equalsIgnoreCase(status)) {
            String reason = stringField(data, "errorText");
            if (reason == null || reason.isBlank()) {
                reason = stringField(data, "message");
            }
            List<Map<String, Object>> attributeErrors = parseAttributeValidationErrors(reason);
            if (!attributeErrors.isEmpty()) {
                List<Map<String, Object>> errors = attributeErrors;
                executeCurrentServerUi(manager, token,
                    () -> ContentDesignerScreen.handleAttributeValidationErrorsForServer(serverId, errors));
                reason = summarizeAttributeValidationErrors(attributeErrors);
            } else {
                reason = formatFlowDiagnostics(reason);
            }
            String message = reason == null || reason.isBlank() ? "Failed" : reason;
            String requestId = jobRequestId(data);
            failResourceDelete(requestId, message);
            if (isTriggerUpdateAction(action) && settlePendingTriggerUpdate(requestId,
                parseTriggerUpdateOutcome(null, false, false, messageFromJob(data)))) {
                return;
            }
            ResourceSaveFence saveFence = resourceSaveFence(requestId);
            completeResourceSave(requestId);
            DesignerSaveNotifications.SaveTarget failedSave = DesignerSaveNotifications.failRequest(serverId, requestId, message);
            if (failedSave != null) {
                markResourceFailedCurrent(failedSave, saveFence);
                return;
            }
            if (isWorldGenProjectSaveAction(action) || isWorldGenProjectDeleteAction(action)) {
                String projectId = stringField(data, "resourceId");
                if (projectId == null || projectId.isBlank()) {
                    projectId = stringField(data, "target");
                }
                String mutationId = stringField(data, "mutationId");
                String operationId = stringField(data, "operationId");
                String failedProjectId = projectId;
                WorldGenManager worldGenManager = WorldGenManager.getInstance();
                boolean[] failed = {false};
                worldGenManager.withSourceConnectionToken(token, () -> failed[0] = worldGenManager.failProjectMutationFromIdentity(
                    serverId, action, failedProjectId, stringField(data, "requestId"), mutationId, operationId, message));
                if (failed[0]) {
                    return;
                }
            }
            if (DesignerSaveNotifications.consumeRecentError(serverId, message)) {
                return;
            }
            String title = action == null || action.isBlank() ? "ReSync Failed" : action + " Failed";
            executeCurrentServerUi(manager, token, () -> new Notification(title, message, Notification.Type.ERROR));
        } else if (isTriggerUpdateAction(action) && isTriggerFailureStatus(status)) {
            settlePendingTriggerUpdate(jobRequestId(data), parseTriggerUpdateOutcome(null, false, false,
                stringField(data, "message")));
        }
    }

    private String messageFromJob(JsonObject data) {
        String message = stringField(data, "errorText");
        if (message == null || message.isBlank()) {
            message = stringField(data, "message");
        }
        return message;
    }

    private TriggerUpdateOutcome parseTriggerUpdateOutcome(JsonElement value, boolean acceptedHint,
                                                            boolean staleHint, String diagnostic) {
        JsonObject state = null;
        if (value != null && !value.isJsonNull()) {
            try {
                if (value.isJsonObject()) {
                    state = value.getAsJsonObject();
                } else if (value.isJsonPrimitive() && value.getAsJsonPrimitive().isString()) {
                    JsonElement parsed = JsonTreeParser.parse(value.getAsString());
                    if (parsed.isJsonObject()) {
                        state = parsed.getAsJsonObject();
                    }
                }
            } catch (RuntimeException ignored) {
            }
        }
        if (state == null && diagnostic != null && !diagnostic.isBlank()) {
            try {
                JsonElement parsed = JsonTreeParser.parse(diagnostic);
                if (parsed.isJsonObject()) {
                    state = parsed.getAsJsonObject();
                }
            } catch (RuntimeException ignored) {
            }
        }
        if (state == null) {
            return new TriggerUpdateOutcome(acceptedHint, staleHint, acceptedHint, acceptedHint,
                0L, null, List.of(), diagnostic);
        }
        boolean accepted = booleanValue(state, ReSyncProtocolContract.FLOW_TRIGGER_UPDATE_RESULT_ACCEPTED_FIELD,
            acceptedHint);
        boolean stale = booleanValue(state, ReSyncProtocolContract.FLOW_TRIGGER_UPDATE_RESULT_STALE_FIELD,
            staleHint);
        boolean durable = booleanValue(state, ReSyncProtocolContract.FLOW_TRIGGER_UPDATE_RESULT_DURABLE_FIELD,
            accepted);
        boolean runtimeReady = booleanValue(state,
            ReSyncProtocolContract.FLOW_TRIGGER_UPDATE_RESULT_RUNTIME_READY_FIELD, accepted);
        long epoch = longValue(state, ReSyncProtocolContract.FLOW_TRIGGER_UPDATE_RESULT_EPOCH_FIELD, 0L);
        String hash = textValue(state, ReSyncProtocolContract.FLOW_TRIGGER_UPDATE_RESULT_HASH_FIELD);
        List<TriggerBinding> bindings = decodeTriggerUpdateBindings(state.get(
            ReSyncProtocolContract.FLOW_TRIGGER_UPDATE_RESULT_BINDINGS_FIELD));
        if (bindings == null) {
            return TriggerUpdateOutcome.rejected("Trigger update authoritative bindings are invalid");
        }
        String finalizationError = textValue(state,
            ReSyncProtocolContract.FLOW_TRIGGER_UPDATE_RESULT_FINALIZATION_ERROR_FIELD);
        String detail = finalizationError == null || finalizationError.isBlank() ? diagnostic : finalizationError;
        return new TriggerUpdateOutcome(accepted, stale, durable, runtimeReady, epoch, hash, bindings, detail);
    }

    private List<TriggerBinding> decodeTriggerUpdateBindings(JsonElement value) {
        if (value == null || !value.isJsonArray()) {
            return null;
        }
        try {
            if (value.getAsJsonArray().size() > MAX_TRIGGER_BINDINGS) {
                return null;
            }
            Set<String> identities = new HashSet<>();
            List<TriggerBinding> result = new ArrayList<>(value.getAsJsonArray().size());
            for (JsonElement encoded : value.getAsJsonArray()) {
                if (!encoded.isJsonObject()) {
                    return null;
                }
                JsonObject object = encoded.getAsJsonObject();
                TriggerType triggerType;
                try {
                    triggerType = TriggerType.valueOf(FlowJson.string(object, "type", ""));
                } catch (IllegalArgumentException exception) {
                    return null;
                }
                TriggerBinding binding = new TriggerBinding(FlowJson.string(object, "id", ""),
                    FlowJson.string(object, "flowId", ""), triggerType,
                    FlowJson.string(object, "context", null));
                if (binding == null || binding.getId() == null || binding.getId().isBlank()
                    || binding.getFlowId() == null || binding.getFlowId().isBlank() || binding.getType() == null
                    || binding.getId().length() > MAX_TRIGGER_BINDING_TEXT
                    || binding.getFlowId().length() > MAX_TRIGGER_BINDING_TEXT
                    || binding.getId().getBytes(StandardCharsets.UTF_8).length > MAX_TRIGGER_BINDING_TEXT
                    || binding.getFlowId().getBytes(StandardCharsets.UTF_8).length > MAX_TRIGGER_BINDING_TEXT
                    || binding.getContext() != null && binding.getContext().length() > MAX_TRIGGER_BINDING_TEXT
                    || binding.getContext() != null
                        && binding.getContext().getBytes(StandardCharsets.UTF_8).length > MAX_TRIGGER_BINDING_TEXT
                    || !identities.add(binding.getId())) {
                    return null;
                }
                result.add(new TriggerBinding(binding.getId(), binding.getFlowId(), binding.getType(),
                    binding.getContext()));
            }
            return List.copyOf(result);
        } catch (RuntimeException exception) {
            return null;
        }
    }

    private boolean booleanValue(JsonObject object, String field, boolean fallback) {
        JsonElement value = object == null ? null : object.get(field);
        if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isBoolean()) {
            return fallback;
        }
        return value.getAsBoolean();
    }

    private long longValue(JsonObject object, String field, long fallback) {
        JsonElement value = object == null ? null : object.get(field);
        if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isNumber()) {
            return fallback;
        }
        try {
            return value.getAsLong();
        } catch (RuntimeException exception) {
            return fallback;
        }
    }

    private String textValue(JsonObject object, String field) {
        JsonElement value = object == null ? null : object.get(field);
        if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isString()) {
            return null;
        }
        String text = value.getAsString();
        return text == null || text.isBlank() ? null : text;
    }

    private String jobRequestId(JsonObject data) {
        String requestId = stringField(data, "requestId");
        return requestId == null || requestId.isBlank() ? stringField(data, "operationId") : requestId;
    }

    private boolean isTriggerUpdateAction(String action) {
        return "updateTriggers".equalsIgnoreCase(action);
    }

    private boolean isTriggerFailureStatus(String status) {
        return "cancelled".equalsIgnoreCase(status) || "canceled".equalsIgnoreCase(status)
            || "rejected".equalsIgnoreCase(status) || "timeout".equalsIgnoreCase(status)
            || "timed_out".equalsIgnoreCase(status);
    }

    private List<Map<String, Object>> parseAttributeValidationErrors(String reason) {
        if (reason == null || !reason.contains("ATTRIBUTE_VALIDATION:")) {
            return List.of();
        }
        String json = reason.substring(reason.indexOf("ATTRIBUTE_VALIDATION:") + "ATTRIBUTE_VALIDATION:".length());
        try {
            JsonElement root = gson.fromJson(json, JsonElement.class);
            if (root == null || !root.isJsonArray()) {
                return List.of();
            }
            List<Map<String, Object>> errors = new ArrayList<>();
            for (JsonElement element : root.getAsJsonArray()) {
                if (element != null && element.isJsonObject()) {
                    Map<String, Object> error = new LinkedHashMap<>();
                    for (Map.Entry<String, JsonElement> entry : element.getAsJsonObject().entrySet()) {
                        error.put(entry.getKey(), entry.getValue() != null && !entry.getValue().isJsonNull() ? entry.getValue().getAsString() : "");
                    }
                    errors.add(error);
                }
            }
            return errors;
        } catch (RuntimeException ignored) {
            return List.of();
        }
    }

    private String summarizeAttributeValidationErrors(List<Map<String, Object>> errors) {
        if (errors == null || errors.isEmpty()) {
            return "Invalid Components";
        }
        Map<String, Object> first = errors.getFirst();
        String component = String.valueOf(first.getOrDefault("component", "")).trim();
        String message = String.valueOf(first.getOrDefault("message", "")).trim();
        if (!component.isBlank() && !message.isBlank()) {
            return component + ": " + message;
        }
        if (!component.isBlank()) {
            return component;
        }
        return !message.isBlank() ? message : "Invalid Components";
    }

    private String formatFlowDiagnostics(String raw) {
        if (raw == null || raw.isBlank()) {
            return "The flow could not be saved.";
        }
        int start = raw.indexOf('[');
        int end = raw.lastIndexOf(']');
        if (start < 0 || end <= start) {
            List<String> messages = new ArrayList<>();
            for (String issue : raw.split(";")) {
                String friendly = issue.trim().replaceFirst("^[A-Z][A-Z0-9_]*:\\s*", "");
                if (!friendly.isBlank() && !messages.contains(friendly)) {
                    messages.add(sentence(friendly));
                }
            }
            return messages.isEmpty() ? raw : String.join("\n", messages);
        }
        try {
            JsonElement parsed = JsonTreeParser.parse(raw.substring(start, end + 1));
            if (!parsed.isJsonArray()) {
                return raw;
            }
            List<String> messages = new ArrayList<>();
            String remediation = "";
            for (JsonElement element : parsed.getAsJsonArray()) {
                if (!element.isJsonObject()) {
                    continue;
                }
                JsonObject diagnostic = element.getAsJsonObject();
                String message = diagnosticText(diagnostic, "message");
                if (message.isBlank()) {
                    continue;
                }
                String pin = diagnosticText(diagnostic, "pin");
                String friendly = sentence(message);
                if (!pin.isBlank()) {
                    friendly += " Check " + sentenceLabel(pin) + ".";
                }
                messages.add(friendly);
                if (remediation.isBlank()) {
                    remediation = diagnosticText(diagnostic, "remediation");
                }
                if (messages.size() == 3) {
                    break;
                }
            }
            if (messages.isEmpty()) {
                return raw;
            }
            String result = String.join("\n", messages);
            int total = parsed.getAsJsonArray().size();
            if (total > messages.size()) {
                result += "\n" + (total - messages.size()) + " more issue" + (total - messages.size() == 1 ? "" : "s") + " need attention.";
            }
            if (!remediation.isBlank()) {
                result += "\nHow to fix: " + sentence(remediation);
            }
            return result;
        } catch (RuntimeException ignored) {
            return raw;
        }
    }

    private void completeResourceDelete(JsonObject data) {
        String requestId = stringField(data, "requestId");
        if (requestId == null || requestId.isBlank()) {
            requestId = stringField(data, "operationId");
        }
        PendingLegacyDelete pending = removePendingLegacyDelete(requestId);
        FlowManager manager = client != null ? client.getFlowManager() : null;
        if (pending == null || manager == null) {
            return;
        }
        ReSyncResourceType type = ReSyncResourceType.byTypeId(pending.key.type());
        if (type != null) {
            manager.confirmResourceDeleted(serverId, type, pending.key.id());
        }
    }

    private void failResourceDelete(String requestId, String message) {
        PendingLegacyDelete pending = removePendingLegacyDelete(requestId);
        FlowManager manager = client != null ? client.getFlowManager() : null;
        if (pending == null || manager == null) {
            return;
        }
        ReSyncResourceType type = ReSyncResourceType.byTypeId(pending.key.type());
        if (type != null) {
            manager.failResourceDelete(serverId, type, pending.key.id(), message);
        }
    }

    private PendingLegacyDelete removePendingLegacyDelete(String requestId) {
        if (requestId == null || requestId.isBlank()) {
            return null;
        }
        PendingLegacyDelete pending = pendingResourceDeletes.remove(requestId);
        if (pending != null) {
            pending.cancelTimeout();
            cancelPendingSend(requestId);
        }
        return pending;
    }

    private void handlePresenceSnapshot(ByteBuffer buffer) {
        collaboration.applySnapshot(readRemainingJson(buffer));
    }

    private void handleResourceEvent(ByteBuffer buffer, boolean deleted, int generation) {
        String json = readRemainingJson(buffer);
        JsonObject object;
        try {
            JsonElement parsed = JsonTreeParser.parse(json);
            object = parsed.isJsonObject() ? parsed.getAsJsonObject() : null;
        } catch (RuntimeException exception) {
            object = null;
        }
        if (object == null) {
            protocolError("Invalid resource event");
            return;
        }
        if (coreResourceEvent(object)) {
            handleCoreResourceEvent(json, deleted, generation);
            return;
        }
        ResourceEvent event = resourceEvent(object);
        if (event == null || event.type() == null || event.resourceId() == null) {
            return;
        }
        FlowManager manager = client != null ? client.getFlowManager() : null;
        FlowManager.ServerConnectionToken token = captureUiToken(manager);
        if (manager == null || !manager.isCurrentServerConnection(token)) {
            return;
        }
        if (!acceptLegacyReadAuthorityEpoch(event.authorityEpoch())) {
            return;
        }
        ReSyncResourceType type = ReSyncResourceType.byTypeId(event.type());
        if (!isProtocolResourceType(type) || event.resourceId().isBlank()) {
            return;
        }
        long revision = resourceRevision(event.payload(), type);
        if (isStaleResourceRevision(type, event.resourceId(), revision)) {
            logger().operation("Resource Synchronization").warn("Rejected stale resource event");
            return;
        }
        collaboration.applyResourceChange(new ReSyncCollaborationClient.ResourceChange(event.type(), event.resourceId(),
            event.authorSessionId(), event.author(), event.changedAt(), deleted));
        if (deleted) {
            manager.confirmResourceDeletedFromProjection(serverId, type, event.resourceId());
            recordResourceRevision(type, event.resourceId(), revision);
            requestResourceList(type);
            return;
        }
        try {
            Object item = type.deserialize(event.payload());
            cacheResource(manager, type, item);
            handleResourceDataReceived(manager, type, item);
            recordResourceRevision(type, event.resourceId(), revision);
            executeCurrentServerUi(manager, token, () -> manager.refreshStudioWorkspace(serverId, true));
        } catch (RuntimeException exception) {
            requestResource(type, event.resourceId(), false);
        }
    }

    private boolean coreResourceEvent(JsonObject object) {
        return object.has("revision") && object.has("mutationId") && object.has("deleted")
            && object.has("canonicalEnvelope");
    }

    private void handleCoreResourceEvent(String json, boolean deletedPacket, int generation) {
        CoreResourceEvent event;
        try {
            JsonElement parsed = JsonTreeParser.parse(json);
            event = parsed.isJsonObject() ? decodeCoreResourceEvent(parsed.getAsJsonObject()) : null;
        } catch (RuntimeException exception) {
            protocolError("Invalid Core resource event");
            return;
        }
        ReSyncResourceType type = event != null ? ReSyncResourceType.byTypeId(event.type()) : null;
        UUID mutationId;
        try {
            mutationId = event == null || event.mutationId() == null ? null : UUID.fromString(event.mutationId());
        } catch (IllegalArgumentException exception) {
            mutationId = null;
        }
        if (event == null || !isProtocolResourceType(type) || !type.isGraph()
            || event.resourceId() == null || event.resourceId().isBlank() || event.revision() < 1L
            || mutationId == null || !mutationId.toString().equals(event.mutationId())
            || event.deleted() != deletedPacket
            || (event.deleted() ? event.activationState() != null
                : event.activationState() == null || event.activationState().isBlank())
            || event.canonicalEnvelope() == null || event.canonicalEnvelope().isBlank()) {
            protocolError("Invalid Core resource event");
            return;
        }
        FlowManager manager = client != null ? client.getFlowManager() : null;
        FlowManager.ServerConnectionToken token = captureUiToken(manager);
        if (manager == null || !manager.isCurrentServerConnection(token)) {
            return;
        }
        if (event.deleted()) {
            CoreGraphResourceProjection.Projection projection = coreResourceEventTombstone(event, type, mutationId);
            if (projection == null || !withCurrentTransportGeneration(generation, () -> {
                if (!typedMutationAuthorityReady() || handshakeAuthorityEpoch < 1L
                    || !manager.isCurrentServerConnection(token)) {
                    return false;
                }
                applyCoreProjection(projection, false);
                return true;
            })) {
                requestResource(type, event.resourceId(), false);
            }
        } else {
            requestResource(type, event.resourceId(), false);
        }
        requestResourceList(type);
    }

    private CoreGraphResourceProjection.Projection coreResourceEventTombstone(CoreResourceEvent event,
                                                                               ReSyncResourceType type,
                                                                               UUID mutationId) {
        if (event == null || type == null || mutationId == null || !typedMutationAuthorityReady()
            || handshakeAuthorityEpoch < 1L) {
            return null;
        }
        try {
            ServerResourceLocator resource = resourceLocator(type, event.resourceId());
            if (resource == null) {
                return null;
            }
            CoreGraphAssetCodec.Tombstone tombstone = new CoreGraphAssetCodec().decodeTombstone(
                event.canonicalEnvelope().getBytes(StandardCharsets.UTF_8), resource);
            if (tombstone.revision() != event.revision() || !tombstone.mutationId().equals(mutationId)
                || !tombstone.deleted() || tombstone.integrityHash() == null) {
                return null;
            }
            ResourceDocument<Map<String, Object>> document = ResourceDocument.tombstone(resource,
                tombstone.revision(), tombstone.mutationId(), tombstone.priorPayloadHash(), event.author());
            Set<ContractRef<CapabilityId>> capabilities = genericResourceEnvelopeCapabilities();
            ProtocolEnvelope<Map<String, Object>> envelope = new ProtocolEnvelope<>(
                ProtocolEnvelope.Kind.EVENT,
                genericResourceContractVersion,
                UUID.randomUUID(),
                null,
                mutationId,
                mutationId,
                protocolServerId(),
                resource,
                tombstone.revision(),
                handshakeAuthorityEpoch,
                tombstone.mutationId(),
                coreOperationReference(ResourceOperationKind.DELETE),
                capabilities,
                RESOURCE_DOCUMENT_TYPE,
                null,
                tombstone.priorPayloadHash(),
                true,
                null,
                null,
                null,
                null,
                null,
                0L,
                ProtocolEnvelope.Status.OK,
                List.of(),
                Map.of(),
                new ProtocolBody.ResourceDocumentResponse(ResourceOperationKind.DELETE, document)
            );
            ReSyncProtocolEnvelopeProjection.Projection envelopeProjection =
                new ReSyncProtocolEnvelopeProjection.Projection(envelope, capabilities, Set.of(), Map.of(), Map.of(), document);
            return new CoreGraphResourceProjection.Projection(envelopeProjection, document,
                CoreGraphResourceProjection.Status.TOMBSTONED, null, null, tombstone.revision(),
                tombstone.mutationId(), null, null, 0, 0, null, Set.of(), Set.of(), "");
        } catch (RuntimeException exception) {
            logger().operation("Resource Synchronization").warn("Rejected invalid Core resource tombstone event");
            return null;
        }
    }

    private void handleResourceActivationResult(ByteBuffer buffer) {
        ResourceActivationResult result;
        try {
            JsonElement parsed = JsonTreeParser.parse(readRemainingJson(buffer));
            result = parsed.isJsonObject() ? resourceActivationResult(parsed.getAsJsonObject()) : null;
        } catch (RuntimeException exception) {
            protocolError("Invalid resource update result");
            return;
        }
        ReSyncResourceType type = result != null ? ReSyncResourceType.byTypeId(result.type()) : null;
        FlowManager manager = client != null ? client.getFlowManager() : null;
        if (result == null || !isProtocolResourceType(type) || result.resourceId() == null || result.resourceId().isBlank()
            || result.requestId() == null || result.requestId().isBlank()) {
            return;
        }
        PendingLegacyActivation pending = pendingLegacyActivations.get(result.requestId());
        if (pending == null) {
            return;
        }
        if (!acceptAuthorityEpoch(result.authorityEpoch())) {
            failLegacyActivation(pending, "The resource activation used an invalid authority epoch.");
            return;
        }
        if (pending.type() != type || !pending.resourceId().equals(result.resourceId())
            || pending.enabled() != result.enabled()) {
            failLegacyActivation(pending, "The server returned a mismatched resource activation result.");
            return;
        }
        if (!pendingLegacyActivations.remove(result.requestId(), pending)) {
            return;
        }
        cancelPendingSend(result.requestId());
        if (manager == null) {
            return;
        }
        manager.completeResourceActivation(serverId, type, result.resourceId(), result.enabled(), result.requestId(), result.success(), result.message(),
            !result.editorError());
    }

    private boolean failLegacyActivation(PendingLegacyActivation pending, String message) {
        if (pending == null || !pendingLegacyActivations.remove(pending.requestId(), pending)) {
            return false;
        }
        cancelPendingSend(pending.requestId());
        FlowManager manager = client != null ? client.getFlowManager() : null;
        if (manager != null) {
            manager.completeResourceActivation(serverId, pending.type(), pending.resourceId(), pending.enabled(), pending.requestId(),
                false, message, true);
        }
        return true;
    }

