    public record CoreGraphRequestBinding(UUID requestId, UUID correlationId, UUID traceId, UUID mutationId,
                                          ResourceOperationKind operation, ServerResourceLocator resource,
                                          long expectedRevision, String query, String cursor,
                                          ReSyncResourceType type, ContentHash payloadHash) {
        public CoreGraphRequestBinding {
            requestId = Objects.requireNonNull(requestId, "requestId");
            correlationId = Objects.requireNonNull(correlationId, "correlationId");
            traceId = Objects.requireNonNull(traceId, "traceId");
            operation = Objects.requireNonNull(operation, "operation");
            type = Objects.requireNonNull(type, "type");
            if (!type.isGraph()) {
                throw new IllegalArgumentException("Core graph requests require a graph resource type");
            }
            if (expectedRevision < 0L) {
                throw new IllegalArgumentException("Expected revision cannot be negative");
            }
            query = normalizeOptionalText(query);
            cursor = normalizeOptionalText(cursor);
            if (operation == ResourceOperationKind.LIST || operation == ResourceOperationKind.QUERY) {
                if (resource != null || mutationId != null) {
                    throw new IllegalArgumentException("Core page requests cannot carry resource mutation fields");
                }
            } else if (resource == null) {
                throw new IllegalArgumentException("Core resource requests require a resource locator");
            }
            if (resourceMutationOperation(operation) && mutationId == null) {
                throw new IllegalArgumentException("Core mutations require a mutation ID");
            }
        }

        private static String normalizeOptionalText(String value) {
            if (value == null) {
                return null;
            }
            String normalized = value.trim();
            return normalized.isBlank() ? null : normalized;
        }
    }

    public record TypedResourceRequestBinding(UUID requestId, UUID correlationId, UUID traceId, UUID mutationId,
                                              ResourceOperationKind operation, ServerResourceLocator resource,
                                              long expectedRevision, ReSyncResourceType type, ContentHash payloadHash) {
        public TypedResourceRequestBinding {
            requestId = Objects.requireNonNull(requestId, "requestId");
            correlationId = Objects.requireNonNull(correlationId, "correlationId");
            traceId = Objects.requireNonNull(traceId, "traceId");
            operation = Objects.requireNonNull(operation, "operation");
            type = Objects.requireNonNull(type, "type");
            if (expectedRevision < 0L) {
                throw new IllegalArgumentException("Resource request revisions cannot be negative");
            }
            if (resource != null && !type.typeId().equals(resource.resourceType().value())) {
                throw new IllegalArgumentException("Resource request type does not match its locator");
            }
            if (resourceMutationOperation(operation) && (mutationId == null || resource == null)) {
                throw new IllegalArgumentException("Resource mutations require a locator and mutation ID");
            }
        }

    }

