    private record PendingCoreGraphRequest(UUID requestId, UUID correlationId, UUID traceId, UUID mutationId,
                                           ResourceOperationKind operation, ServerResourceLocator resource,
                                           long expectedRevision, String query, String cursor,
                                           ReSyncResourceType type, ContentHash payloadHash,
                                           ContentHash submittedPayloadHash, CatalogVersion contractVersion,
                                           int transportGeneration) {
        private PendingCoreGraphRequest {
            CoreGraphRequestBinding binding = new CoreGraphRequestBinding(requestId, correlationId, traceId, mutationId,
                operation, resource, expectedRevision, query, cursor, type, payloadHash);
            query = binding.query();
            cursor = binding.cursor();
            if (transportGeneration < 0) {
                throw new IllegalArgumentException("Core graph request transport generation cannot be negative");
            }
        }

        private CoreGraphRequestBinding binding() {
            return new CoreGraphRequestBinding(requestId, correlationId, traceId, mutationId, operation, resource,
                expectedRevision, query, cursor, type, payloadHash);
        }

        private PendingCoreGraphRequest forTransportGeneration(int generation) {
            return new PendingCoreGraphRequest(requestId, correlationId, traceId, mutationId, operation, resource,
                expectedRevision, query, cursor, type, payloadHash, submittedPayloadHash, contractVersion, generation);
        }

        private boolean matches(ProtocolEnvelope<Map<String, Object>> envelope) {
            if (envelope == null || !requestId.equals(envelope.requestId()) || !correlationId.equals(envelope.correlationId())
                || !traceId.equals(envelope.traceId()) || !coreOperation(envelope, operation)
                || contractVersion == null || !contractVersion.equals(envelope.contractVersion())
                || !envelope.capabilities().containsAll(operation == ResourceOperationKind.ACTIVATE
                    ? RESOURCE_ACTIVATION_CAPABILITIES : GENERIC_RESOURCE_CAPABILITIES)) {
                return false;
            }
            if (envelope.body() instanceof ProtocolBody.ResourcePageResponse response) {
                return (operation == ResourceOperationKind.LIST || operation == ResourceOperationKind.QUERY)
                    && response.operation() == operation && envelope.resource() == null;
            }
            if (envelope.body() instanceof ProtocolBody.ResourceDocumentResponse response) {
                ResourceDocument<?> document = response.document();
                if (operation != response.operation() || resource == null || !resource.equals(envelope.resource())
                    || !resource.equals(document.resource())) {
                    return false;
                }
                if (envelope.kind() == ProtocolEnvelope.Kind.ACK && mutationId != null
                    && !mutationId.equals(document.mutationId())) {
                    return false;
                }
                return Objects.equals(envelope.mutationId(), document.mutationId())
                    && envelope.revision() == document.revision()
                    && Objects.equals(envelope.payloadHash(), document.payloadHash())
                    && envelope.deleted() == document.deleted();
            }
            if (envelope.body() instanceof ProtocolBody.ConflictResponse conflict) {
                ResourceDocument<?> current = conflict.current();
                boolean exactCurrent = current == null || resource != null && resource.equals(current.resource())
                    && envelope.revision() == current.revision()
                    && Objects.equals(envelope.mutationId(), current.mutationId())
                    && Objects.equals(envelope.payloadHash(), current.payloadHash())
                    && envelope.deleted() == current.deleted();
                boolean mutationMatches = (operation == ResourceOperationKind.ACTIVATE && current != null)
                    || mutationId == null || envelope.mutationId() == null || mutationId.equals(envelope.mutationId());
                return resource != null && resource.equals(envelope.resource())
                    && resource.equals(conflict.requestedResource()) && exactCurrent && mutationMatches;
            }
            return false;
        }

        private boolean matchesPage(ProtocolEnvelope<Map<String, Object>> envelope) {
            return matches(envelope) && envelope.body() instanceof ProtocolBody.ResourcePageResponse;
        }

        private boolean matchesRejection(ProtocolEnvelope<Map<String, Object>> envelope) {
            return envelope != null && requestId.equals(envelope.requestId())
                && correlationId.equals(envelope.correlationId()) && traceId.equals(envelope.traceId())
                && contractVersion != null && contractVersion.equals(envelope.contractVersion())
                && coreOperation(envelope, operation) && type.isGraph()
                && Objects.equals(resource, rejectionResource(envelope))
                && Objects.equals(mutationId, rejectionMutationId(envelope));
        }

        private boolean matchesEvent(ProtocolEnvelope<Map<String, Object>> envelope, ResourceDocument<?> document) {
            if (envelope == null || document == null || envelope.kind() != ProtocolEnvelope.Kind.EVENT
                || resource == null || !resource.equals(document.resource()) || !resource.equals(envelope.resource())
                || contractVersion == null || !contractVersion.equals(envelope.contractVersion())
                || !coreOperation(envelope, operation)) {
                return false;
            }
            if (document.revision() < expectedRevision) {
                return false;
            }
            return envelope.mutationId() != null && envelope.mutationId().equals(document.mutationId())
                && envelope.revision() == document.revision()
                && envelope.payloadHash() != null && envelope.payloadHash().equals(document.payloadHash())
                && envelope.deleted() == document.deleted();
        }
    }

    private static final class CoreRequestRecovery {
        private final ResourceOperation operation;
        private final ContentHash payloadHash;
        private final boolean mutation;
        private final ResourceSaveFence fence;
        private int attempt;
        private int responseAttempt;
        private int transportAttempt;
        private boolean replayed;

        private CoreRequestRecovery(ResourceOperation operation, ContentHash payloadHash, boolean mutation,
                                    ResourceSaveFence fence) {
            this.operation = Objects.requireNonNull(operation, "Core recovery operation is required");
            this.payloadHash = payloadHash;
            this.mutation = mutation;
            this.fence = fence;
        }

        private synchronized int dispatched() {
            return ++attempt;
        }

        private synchronized void dispatchFailed(int failedAttempt) {
            if (attempt == failedAttempt && responseAttempt < failedAttempt && transportAttempt < failedAttempt) {
                attempt--;
            }
        }

        private synchronized boolean transportSettled(int settledAttempt) {
            if (attempt != settledAttempt || transportAttempt >= settledAttempt) {
                return false;
            }
            transportAttempt = settledAttempt;
            return true;
        }

        private synchronized int responseReceived() {
            responseAttempt = attempt;
            return attempt;
        }

        private synchronized boolean current(int expectedAttempt) {
            return attempt == expectedAttempt;
        }

        private synchronized boolean responseReceived(int expectedAttempt) {
            return responseAttempt == expectedAttempt;
        }

        private synchronized boolean claimReplay(int expectedAttempt) {
            if (attempt != expectedAttempt || replayed) {
                return false;
            }
            replayed = true;
            return true;
        }
    }

    private static final class TypedRequestDelivery {
        private int attempt;
        private int transportAttempt;
        private boolean replayed;

        private synchronized int dispatched() {
            return ++attempt;
        }

        private synchronized void dispatchFailed(int failedAttempt) {
            if (attempt == failedAttempt && transportAttempt < failedAttempt) {
                attempt--;
            }
        }

        private synchronized boolean transportSettled(int settledAttempt) {
            if (attempt != settledAttempt || transportAttempt >= settledAttempt) {
                return false;
            }
            transportAttempt = settledAttempt;
            return true;
        }

        private synchronized boolean current(int expectedAttempt) {
            return attempt == expectedAttempt && transportAttempt == expectedAttempt;
        }

        private synchronized boolean claimReplay(int expectedAttempt) {
            if (attempt != expectedAttempt || transportAttempt != expectedAttempt || replayed) {
                return false;
            }
            replayed = true;
            return true;
        }
    }

