    private void sendPlayerTrackingAction(String action, UUID playerId) {
        if (action == null || action.isBlank()) {
            return;
        }
        if (!isConnected()) {
            return;
        }
        JsonObject request = new JsonObject();
        request.addProperty("action", action);
        if (playerId != null) request.addProperty("playerId", playerId.toString());
        byte[] jsonBytes = JsonTreeParser.write(request).getBytes(StandardCharsets.UTF_8);
        sendFrame(4, jsonBytes, numericChannel("player_tracking", PLAYER_TRACKING_CHANNEL_ID));
    }

    private void sendWorldRequest(Map<String, Object> request) {
        if (shutdownRequested) return;
        if (request == null || request.isEmpty()) {
            return;
        }
        Map<String, Object> snapshot = new LinkedHashMap<>(request);
        attachRequestId(snapshot);
        sendWorldRequest(gson.toJson(snapshot).getBytes(StandardCharsets.UTF_8));
    }

    private void sendWorldRequest(byte[] jsonBytes) {
        if (shutdownRequested) return;
        if (!isConnected()) {
            enqueuePendingSend(null, jsonBytes.length + 1L, PendingSendPriority.STANDARD, null, -1,
                () -> queuedSend(() -> sendWorldRequest(jsonBytes)));
            return;
        }
        sendFrame(4, jsonBytes, numericChannel("world_management", WORLD_MANAGEMENT_CHANNEL_ID));
    }

    private void attachRequestId(Map<String, Object> request) {
        Object actionValue = request.get("action");
        String action = actionValue instanceof String value ? value : "";
        if (action.isBlank() || isReadOnlyWorldAction(action) || request.containsKey("requestId")) {
            return;
        }
        request.put("requestId", stableClientId + ":" + action + ":" + UUID.randomUUID());
    }

    private boolean isReadOnlyWorldAction(String action) {
        return switch (action) {
            case "snapshot", "auditSnapshot", "jobSnapshot", "operationStatus", "mapSnapshot", "whoWorld", "scanUnregisteredWorlds" -> true;
            default -> false;
        };
    }

    boolean sendResourceSave(ReSyncResourceType type, Object item) {
        return sendResourceSave(type, item, null);
    }

    boolean sendResourceSave(ReSyncResourceType type, Object item,
                             DesignerSaveNotifications.SaveTicket ticket) {
        if (shutdownRequested) {
            DesignerSaveNotifications.failExact(ticket, "ReSync Offline");
            return false;
        }
        if (!isProtocolResourceType(type) || !type.isGraph() || item == null) {
            DesignerSaveNotifications.failExact(ticket, "The Core graph save request is invalid.");
            return false;
        }
        return sendCoreGraphSave(type, item, ticket);
    }

    boolean sendResourceSave(ReSyncResourceType type, SyncedResourceCache.SaveLease<?> lease) {
        return sendResourceSave(type, lease, null);
    }

    boolean sendResourceSave(ReSyncResourceType type, SyncedResourceCache.SaveLease<?> lease,
                             DesignerSaveNotifications.SaveTicket ticket) {
        if (shutdownRequested || !isProtocolResourceType(type) || lease == null
            || lease.resourceId() == null || lease.resourceId().isBlank() || !serverId.equals(lease.serverId())) {
            DesignerSaveNotifications.failExact(ticket, "The resource save request is invalid.");
            return false;
        }
        if (ticket != null && (!serverId.equals(ticket.serverId()) || type != ticket.type()
            || !lease.resourceId().equals(ticket.id()) || !DesignerSaveNotifications.isPending(ticket))) {
            DesignerSaveNotifications.failExact(ticket, "The resource changed before the save was queued. Try again.");
            return false;
        }
        if (!lease.isCurrent()) {
            if (ticket != null) {
                DesignerSaveNotifications.failExact(ticket, "The resource changed before the save was queued. Try again.");
            } else {
                DesignerSaveNotifications.failResource(serverId, type, lease.resourceId(),
                    "The resource changed before the save was queued. Try again.");
            }
            return false;
        }
        return queueResourceSave(type, lease, lease.resourceId(), ticket);
    }

    boolean sendPreparedResourceSave(ReSyncResourceType type, String id, String payloadJson,
                                     ContentHash payloadHash, DesignerSaveNotifications.SaveTicket ticket) {
        return sendPreparedResourceSave(type, id, payloadJson, payloadHash, ticket, null,
            resourceSaveGeneration(type, id));
    }

    boolean sendPreparedResourceCreate(ReSyncResourceType type, String id, String payloadJson,
                                       ContentHash payloadHash, FlowManager.CreationMetadataIntent metadata,
                                       DesignerSaveNotifications.SaveTicket ticket) {
        ResourcePresentationIntent presentation = createPresentation(type, id, metadata);
        UUID mutationId = ticket != null ? parseSaveIdentity(ticket.mutationId()) : null;
        if (presentation == null || mutationId == null) {
            DesignerSaveNotifications.failExact(ticket, "ReSync Resource Creation Requires Protocol v1.2");
            return false;
        }
        if (!supportsAggregateResourceCreation(type)) {
            return retryAggregateCreateAdmission(type, id, ticket,
                "ReSync Resource Creation Requires Protocol v1.2");
        }
        ResourcePresentationIntent existing = pendingCreatePresentations.putIfAbsent(mutationId, presentation);
        if (existing != null && !existing.equals(presentation)) {
            DesignerSaveNotifications.failExact(ticket, "The resource presentation changed before creation was sent.");
            return false;
        }
        boolean admitted = sendPreparedResourceSave(type, id, payloadJson, payloadHash, ticket, null, -1L);
        if (!admitted) {
            pendingCreatePresentations.remove(mutationId, presentation);
        }
        return admitted;
    }

    static ResourcePresentationIntent createPresentation(ReSyncResourceType type, String id,
                                                         FlowManager.CreationMetadataIntent metadata) {
        if (type == null || id == null || id.isBlank() || metadata == null || metadata.folder()
            || !type.typeId().equals(metadata.type()) || !id.equals(metadata.id()) || metadata.name() == null
            || metadata.path() == null || metadata.sortOrder() < 0) {
            return null;
        }
        try {
            return new ResourcePresentationIntent(metadata.name(),
                FlowManager.canonicalResourcePath(type, id, metadata.path()), metadata.sortOrder());
        } catch (RuntimeException exception) {
            return null;
        }
    }

    private boolean retryAggregateCreateAdmission(ReSyncResourceType type, String id,
                                                   DesignerSaveNotifications.SaveTicket ticket, String message) {
        if (ticket != null && DesignerSaveNotifications.isResumable(ticket)) {
            String requestId = ticket.requestId();
            DesignerSaveNotifications.detachResumable(ticket);
            notifyResumableResourceSaveFailure(type, id, requestId, true, message);
            return false;
        }
        DesignerSaveNotifications.failExact(ticket, message);
        return false;
    }

    boolean sendPreparedResourceSave(ReSyncResourceType type, String id, String payloadJson,
                                     ContentHash payloadHash, DesignerSaveNotifications.SaveTicket ticket,
                                     SyncedResourceCache.SaveLease<?> draftLease, long draftGeneration) {
        return sendPreparedResourceSave(type, id, payloadJson, payloadHash, ticket, draftLease, draftGeneration,
            -1L, null, false);
    }

    boolean sendPreparedResourceSave(ReSyncResourceType type, String id, String payloadJson,
                                     ContentHash payloadHash, DesignerSaveNotifications.SaveTicket ticket,
                                     SyncedResourceCache.SaveLease<?> draftLease, long draftGeneration,
                                     long expectedRevision, String expectedAuthoritativeHash,
                                     boolean preserveNewerDraft) {
        return sendPreparedResourceSave(type, id, payloadJson, payloadHash, ticket, draftLease, draftGeneration,
            expectedRevision, expectedAuthoritativeHash, -1L, preserveNewerDraft);
    }

    boolean sendPreparedResourceSave(ReSyncResourceType type, String id, String payloadJson,
                                     ContentHash payloadHash, DesignerSaveNotifications.SaveTicket ticket,
                                     SyncedResourceCache.SaveLease<?> draftLease, long draftGeneration,
                                     long expectedRevision, String expectedAuthoritativeHash,
                                     long expectedAuthoritativeGeneration, boolean preserveNewerDraft) {
        if (shutdownRequested || !isProtocolResourceType(type) || id == null || id.isBlank()
            || payloadJson == null || payloadJson.isBlank() || payloadHash == null || ticket == null
            || !serverId.equals(ticket.serverId()) || type != ticket.type() || !id.equals(ticket.id())
            || !DesignerSaveNotifications.isPending(ticket)) {
            DesignerSaveNotifications.failExact(ticket, "The resource save request is invalid.");
            return false;
        }
        UUID requestUuid = parseSaveIdentity(ticket.requestId());
        UUID mutationId = parseSaveIdentity(ticket.mutationId());
        if (requestUuid == null || mutationId == null) {
            DesignerSaveNotifications.failExact(ticket, "The resource save identity is invalid.");
            return false;
        }
        ServerResourceLocator resource = resourceLocator(type, id);
        if (resource == null) {
            DesignerSaveNotifications.failExact(ticket, "The resource locator is unavailable.");
            return false;
        }
        ResourceSaveFence fence = captureResourceSaveFence();
        if (fence == null) {
            notifyResumableResourceSaveFailure(type, id, requestUuid.toString(), true,
                "The ReSync connection changed before the resource was ready to save.");
            return false;
        }
        ResourceSavePreparation preparation;
        try {
            ContentHash draftPayloadHash = draftLease == null ? null : ResourcePayloadCodecs.json()
                .canonicalize(jsonObjectPayload(draftLease.serialize(type::serialize))).checksum();
            preparation = new ResourceSavePreparation(type, draftLease, payloadJson, payloadHash, draftPayloadHash,
                draftGeneration, id,
                requestUuid.toString(), requestUuid, mutationId, UUID.randomUUID(), UUID.randomUUID(), resource, fence,
                expectedRevision, expectedAuthoritativeHash, expectedAuthoritativeGeneration, preserveNewerDraft);
        } catch (RuntimeException exception) {
            DesignerSaveNotifications.failExact(ticket, "The resource save request is invalid.");
            return false;
        }
        boolean admitted = enqueueResourceSave(new ResourceSaveKey(type, id), requestUuid.toString(),
            preparation.draftVersion(), fence, preparation,
            preparation::currentPayload, () -> prepareResourceSave(preparation),
            () -> failPreparedResourceSave(preparation, "The resource save queue is full. Try again."));
        if (!admitted) {
            failPreparedResourceSave(preparation, "The resource save queue is full. Try again.");
        }
        return admitted;
    }

    private boolean queueResourceSave(ReSyncResourceType type, SyncedResourceCache.SaveLease<?> lease, String id,
                                      DesignerSaveNotifications.SaveTicket ticket) {
        UUID requestUuid = ticket != null ? parseSaveIdentity(ticket.requestId()) : null;
        if (requestUuid == null) {
            requestUuid = UUID.randomUUID();
        }
        String requestId = requestUuid.toString();
        if (ticket != null) {
            if (ticket.requestId() == null || ticket.requestId().isBlank()) {
                if (!DesignerSaveNotifications.attachRequestId(ticket, requestId)) {
                    DesignerSaveNotifications.failExact(ticket, "The resource changed before the save was queued. Try again.");
                    return false;
                }
            } else if (!requestId.equals(ticket.requestId())) {
                DesignerSaveNotifications.failExact(ticket, "The resource changed before the save was queued. Try again.");
                return false;
            }
        } else {
            DesignerSaveNotifications.attachRequestId(serverId, type, id, requestId);
        }
        ServerResourceLocator resource = resourceLocator(type, id);
        if (resource == null) {
            failTrackedResourceSave(type, id, requestId, "The resource locator is unavailable.");
            return false;
        }
        ResourceSaveFence fence = captureResourceSaveFence();
        if (fence == null) {
            failTrackedResourceSave(type, id, requestId, "The ReSync connection changed before the resource was ready to save.");
            return false;
        }
        UUID mutationId = ticket != null ? parseSaveIdentity(ticket.mutationId()) : null;
        if (mutationId == null) {
            mutationId = UUID.randomUUID();
            if (ticket != null && !DesignerSaveNotifications.attachMutationId(ticket, mutationId.toString())) {
                DesignerSaveNotifications.failExact(ticket, "The resource changed before the save was queued. Try again.");
                return false;
            }
        }
        ResourceSavePreparation preparation = new ResourceSavePreparation(type, lease, null, null,
            resourceSaveGeneration(type, id), id, requestId,
            requestUuid, mutationId, UUID.randomUUID(), UUID.randomUUID(), resource, fence);
        boolean admitted = enqueueResourceSave(new ResourceSaveKey(type, id), requestId, preparation.draftVersion(), fence,
            preparation,
            preparation::currentPayload,
            () -> prepareResourceSave(preparation),
            () -> failPreparedResourceSave(preparation, "The resource save queue is full. Try again."));
        if (!admitted) {
            failPreparedResourceSave(preparation, "The resource save queue is full. Try again.");
        }
        return admitted;
    }

    private UUID parseSaveIdentity(String value) {
        if (value == null || value.isBlank()) {
            return null;
        }
        try {
            return UUID.fromString(value);
        } catch (IllegalArgumentException exception) {
            return null;
        }
    }

    private long resourceSaveGeneration(ReSyncResourceType type, String id) {
        FlowManager manager = client != null ? client.getFlowManager() : null;
        return manager != null ? manager.resourceSaveGeneration(serverId, type, id) : -1L;
    }

    boolean submitResourcePreparation(Runnable preparation) {
        if (shutdownRequested || preparation == null) {
            return false;
        }
        try {
            resourcePreparations.execute(preparation);
            return true;
        } catch (IllegalStateException exception) {
            return false;
        }
    }

    private boolean enqueueResourceSave(ResourceSaveKey key, String trackerId, long draftVersion, ResourceSaveFence fence,
                                        ResourceSavePreparation payloadPreparation, BooleanSupplier currentPayload,
                                        Runnable preparation, Runnable rejection) {
        ResourceSaveWork work = new ResourceSaveWork(key, trackerId, draftVersion, fence, payloadPreparation, currentPayload,
            preparation, rejection, System.nanoTime());
        boolean start;
        synchronized (resourceSaveQueueLock) {
            if (shutdownRequested || retainedResourceSaves >= MAX_PENDING_RESOURCE_PREPARATIONS
                || resourceSavesByTracker.containsKey(trackerId)) {
                return false;
            }
            ArrayDeque<ResourceSaveWork> queue = resourceSaveQueues.computeIfAbsent(key, ignored -> new ArrayDeque<>());
            start = queue.isEmpty();
            queue.addLast(work);
            resourceSavesByTracker.put(trackerId, work);
            retainedResourceSaves++;
        }
        if (!start || submitResourcePreparation(() -> runResourceSavePreparation(work))) {
            return true;
        }
        rejectQueuedResourceSave(work);
        return true;
    }

    private void completeResourceSave(String trackerId) {
        ResourceSaveWork work;
        synchronized (resourceSaveQueueLock) {
            work = resourceSavesByTracker.get(trackerId);
        }
        if (work != null && work.key().type() == ReSyncResourceType.LOOT_TABLE) {
            logger().operation("Loot Save").with("resource", work.key().id())
                .with("elapsedMs", (System.nanoTime() - work.queuedAtNanos()) / 1_000_000L).info("Loot save settled");
        }
        removeResourceSave(trackerId);
    }

    private void releaseResourceSave(String trackerId) {
        removeResourceSave(trackerId);
    }

    private void retireResourceSavesWithoutDispatch() {
        synchronized (resourceSaveQueueLock) {
            resourceSaveQueues.clear();
            resourceSavesByTracker.clear();
            retainedResourceSaves = 0;
        }
    }

    private void removeResourceSave(String trackerId) {
        if (trackerId == null || trackerId.isBlank()) {
            return;
        }
        ResourceSaveWork next = null;
        synchronized (resourceSaveQueueLock) {
            ResourceSaveWork completed = resourceSavesByTracker.remove(trackerId);
            if (completed == null) {
                return;
            }
            ArrayDeque<ResourceSaveWork> queue = resourceSaveQueues.get(completed.key());
            if (queue == null || queue.peekFirst() != completed) {
                resourceSavesByTracker.put(trackerId, completed);
                return;
            }
            queue.removeFirst();
            retainedResourceSaves--;
            if (queue.isEmpty()) {
                resourceSaveQueues.remove(completed.key());
            } else {
                next = queue.peekFirst();
            }
        }
        ResourceSaveWork queued = next;
        if (queued != null && !submitResourcePreparation(() -> runResourceSavePreparation(queued))) {
            rejectQueuedResourceSave(queued);
        }
    }

    private void runResourceSavePreparation(ResourceSaveWork work) {
        long startedAtNanos = System.nanoTime();
        try {
            work.preparation().run();
            if (work.key().type() == ReSyncResourceType.LOOT_TABLE) {
                logger().operation("Loot Save").with("resource", work.key().id())
                    .with("queueMs", (startedAtNanos - work.queuedAtNanos()) / 1_000_000L)
                    .with("preparationMs", (System.nanoTime() - startedAtNanos) / 1_000_000L).info("Loot save preparation finished");
            }
        } catch (RuntimeException | Error failure) {
            ReLog.logger(LogTypes.FLOW).source(LogSource.server(serverId, serverId))
                .component(ReSyncFlowClient.class).operation("Resource Save Preparation")
                .error(String.valueOf(failure));
            if (work.payloadPreparation() != null) {
                failPreparedResourceSave(work.payloadPreparation(), "Resource Save Preparation Failed", false);
            } else {
                rejectQueuedResourceSave(work);
            }
        }
    }

    private long resourceSaveDraftVersion(String trackerId) {
        if (trackerId == null || trackerId.isBlank()) {
            return -1L;
        }
        synchronized (resourceSaveQueueLock) {
            ResourceSaveWork work = resourceSavesByTracker.get(trackerId);
            return work != null ? work.draftVersion() : -1L;
        }
    }

    private ResourceSavePreparation resourceSavePreparation(String trackerId) {
        if (trackerId == null || trackerId.isBlank()) {
            return null;
        }
        synchronized (resourceSaveQueueLock) {
            ResourceSaveWork work = resourceSavesByTracker.get(trackerId);
            return work != null ? work.payloadPreparation() : null;
        }
    }

    private ResourceSaveFence resourceSaveFence(String trackerId) {
        if (trackerId == null || trackerId.isBlank()) {
            return null;
        }
        synchronized (resourceSaveQueueLock) {
            ResourceSaveWork work = resourceSavesByTracker.get(trackerId);
            return work != null ? work.fence() : null;
        }
    }

    private BooleanSupplier resourceSavePayloadFence(String trackerId) {
        if (trackerId == null || trackerId.isBlank()) {
            return () -> false;
        }
        synchronized (resourceSaveQueueLock) {
            ResourceSaveWork work = resourceSavesByTracker.get(trackerId);
            return work != null ? work.currentPayload() : () -> false;
        }
    }

    private void rejectQueuedResourceSave(ResourceSaveWork work) {
        if (work == null) {
            return;
        }
        work.rejection().run();
        completeResourceSave(work.trackerId());
    }

    private void prepareResourceSave(ResourceSavePreparation preparation) {
        if (!currentResourceSavePreparation(preparation)) {
            failPreparedResourceSave(preparation, "The ReSync connection changed before the resource was ready to save.");
            return;
        }
        long authoritativeRevision = authoritativeResourceRevision(preparation.type(), preparation.id());
        ResourcePresentationIntent createPresentation = pendingCreatePresentations.get(preparation.mutationId());
        if (createPresentation != null) {
            ReSyncResourceRevisionReconciler.ResourceResult current = resourceRevisionReconciler.get(serverId,
                preparation.type().typeId(), preparation.id());
            boolean allowed = resourceCreationAllowed(preparation, authoritativeRevision, current);
            boolean live = current != null && !current.deleted() && current.revision() == authoritativeRevision
                && current.authorityEpoch() == preparation.fence().authorityEpoch();
            traceLifecycle(serverId, "create_preflight", "serverId", serverId, "resourceKey",
                temporaryLifecycleResourceKey(preparation.type(), preparation.resource()), "mutationId",
                preparation.mutationId(), "requestId", preparation.requestId(), "maxRevision", authoritativeRevision,
                "reconcilerRevision", current == null ? -1L : current.revision(), "reconcilerDeleted",
                current != null && current.deleted(), "reconcilerEpoch", current == null ? -1L : current.authorityEpoch(),
                "authorityEpoch", preparation.fence().authorityEpoch(), "outcome",
                allowed ? authoritativeRevision == 0L ? "missing" : "recreation" : live ? "live_conflict" : "ambiguous");
            if (!allowed) {
                failPreparedResourceSave(preparation, live ? "The resource already exists on ReSync."
                    : "The resource state is not confirmed. Refresh it before creating it again.", false);
                return;
            }
        }
        String json;
        try {
            json = preparation.serializePayload();
        } catch (RuntimeException exception) {
            failPreparedResourceSave(preparation, saveFailureMessage(exception));
            return;
        }
        if (!currentResourceSavePreparation(preparation)
            || !currentResourceSaveAuthority(preparation, authoritativeRevision)) {
            failPreparedResourceSave(preparation, "The resource changed while preparing the save. Try again.");
            return;
        }
        Map<String, Object> payload;
        try {
            payload = jsonObjectPayload(json);
        } catch (RuntimeException exception) {
            failPreparedResourceSave(preparation, "The resource payload is not a JSON object.");
            return;
        }
        CanonicalPayload<Map<String, Object>> canonical;
        try {
            canonical = ResourcePayloadCodecs.json().canonicalize(payload);
        } catch (RuntimeException exception) {
            failPreparedResourceSave(preparation, "The resource payload could not be canonicalized.");
            return;
        }
        if (preparation.preparedPayloadHash() != null
            && !preparation.preparedPayloadHash().equals(canonical.checksum())) {
            failPreparedResourceSave(preparation, "The prepared resource payload changed before the save was sent.");
            return;
        }
        if (!currentResourceSavePreparation(preparation)
            || !currentResourceSaveAuthority(preparation, authoritativeRevision)) {
            failPreparedResourceSave(preparation, "The resource changed while preparing the save. Try again.");
            return;
        }
        long expectedRevision = createPresentation != null ? authoritativeRevision
            : preparation.expectedRevision() >= 0L ? preparation.expectedRevision()
            : Math.max(authoritativeRevision, resourceRevisionFromPayload(payload));
        ResourceOperationKind operationKind = createPresentation != null ? ResourceOperationKind.CREATE
            : preparation.expectedRevision() >= 0L || expectedRevision > 0L
            ? ResourceOperationKind.SAVE : ResourceOperationKind.CREATE;
        if (preparation.expectedRevision() < 0L && (preparation.type().isGraph()
            || !supportsGenericResource(preparation.type(), operationKind, true)
            || !catalogAuthorityAllowsTypedMutation(catalogAuthority)) && legacyMutationCompatibilityAllowed()) {
            if (!sendLegacyResourceSave(preparation.type(), preparation.id(), json, preparation.requestId())) {
                failPreparedResourceSave(preparation, "The ReSync send queue is full. Try again after reconnecting.");
                return;
            }
            heartbeatScheduler.schedule(() -> {
                ResourceSaveFence activeFence = resourceSaveFence(preparation.requestId());
                if (activeFence == null) {
                    return;
                }
                boolean resumable = DesignerSaveNotifications.isResumableRequest(serverId, preparation.requestId());
                if (resumable) {
                    releaseResourceSave(preparation.requestId());
                    notifyResumableResourceSaveFailure(preparation.type(), preparation.id(), preparation.requestId(), true,
                        "ReSync did not confirm the resource update.");
                    return;
                }
                completeResourceSave(preparation.requestId());
                DesignerSaveNotifications.SaveTarget failed = DesignerSaveNotifications.failRequest(serverId,
                    preparation.requestId(), "ReSync did not confirm the resource update.");
                markResourceFailedCurrent(failed, activeFence);
                if (failed == null && preparation.type() == ReSyncResourceType.PROJECT_METADATA) {
                    FlowManager manager = client != null ? client.getFlowManager() : null;
                    executeCurrentServerUi(manager, activeFence.connectionToken(),
                        () -> {
                            if (preparation.currentPayload()) {
                                markResourceFailed(manager, preparation.type(), preparation.id());
                            }
                        });
                }
            }, Duration.ofSeconds(15L));
            return;
        }
        ResourceOperation operation = operationKind == ResourceOperationKind.SAVE
            ? new ResourceSaveRequest<>(preparation.resource(), expectedRevision, canonical, preparation.mutationId())
            : createPresentation != null
            ? new ResourceCreateRequest<>(preparation.resource(), canonical, preparation.mutationId(), createPresentation)
            : new ResourceCreateRequest<>(preparation.resource(), canonical, preparation.mutationId());
        PendingTypedResourceRequest pending = typedResourceRequest(preparation.type(), operation, preparation.resource(),
            expectedRevision, preparation.mutationId(), canonical.checksum(), true, false, null, json,
            preparation.requestId(), false, preparation.requestUuid(), preparation.correlationId(), preparation.traceId());
        dispatchTypedResourceRequest(pending, preparation.fence());
    }

    private ResourceSaveFence captureResourceSaveFence() {
        int generation = activeTransportGeneration;
        ConnectionSource source = connectionSource(generation);
        if (generation < 0 || source == null || !typedMutationAuthorityReady()) {
            return null;
        }
        long authorityEpoch = handshakeAuthorityEpoch;
        FlowManager manager = client != null ? client.getFlowManager() : null;
        FlowManager.ServerConnectionToken connectionToken = captureUiToken(manager);
        if (authorityEpoch < 1L || manager != null && connectionToken == null) {
            return null;
        }
        ResourceSaveFence fence = new ResourceSaveFence(generation, source, authorityEpoch, connectionToken);
        return currentResourceSaveFence(fence) ? fence : null;
    }

    private boolean currentResourceSaveFence(ResourceSaveFence fence) {
        if (fence == null || shutdownRequested || activeTransportGeneration != fence.transportGeneration()
            || connectionSource(fence.transportGeneration()) != fence.connectionSource()
            || !fence.connectionSource().accepts(fence.transportGeneration()) || !typedMutationAuthorityReady()
            || handshakeAuthorityEpoch != fence.authorityEpoch()
            || resourceRevisionReconciler.authorityEpoch(serverId) != fence.authorityEpoch()) {
            return false;
        }
        FlowManager manager = client != null ? client.getFlowManager() : null;
        return fence.connectionToken() == null || manager != null && manager.isCurrentServerConnection(fence.connectionToken());
    }

    private boolean currentResourceSavePreparation(ResourceSavePreparation preparation) {
        if (preparation == null || shutdownRequested
            || !preparation.currentPayload()
            || !preparation.resource().equals(resourceLocator(preparation.type(), preparation.id()))) {
            return false;
        }
        if (preparation.draftGeneration() >= 0L) {
            FlowManager manager = client != null ? client.getFlowManager() : null;
            if (manager == null || !preparation.preserveNewerDraft()
                && !manager.matchesResourceSaveDraft(serverId, preparation.type(), preparation.id(),
                    preparation.lease(), preparation.draftGeneration(), preparation.draftPayloadHash())) {
                return false;
            }
        }
        if (preparation.expectedRevision() >= 0L) {
            FlowManager manager = client != null ? client.getFlowManager() : null;
            long expectedGeneration = !preparation.preserveNewerDraft() && preparation.lease() == null
                ? preparation.expectedAuthoritativeGeneration() : -1L;
            if (manager == null || !manager.matchesAuthoritativeResourceFence(serverId, preparation.type(),
                preparation.id(), preparation.expectedRevision(), preparation.expectedAuthoritativeHash(),
                expectedGeneration)) {
                return false;
            }
        }
        if (!currentResourceSaveFence(preparation.fence())) {
            return false;
        }
        return true;
    }

    private boolean currentResourceSaveAuthority(ResourceSavePreparation preparation, long capturedRevision) {
        if (preparation == null) {
            return false;
        }
        if (preparation.expectedRevision() >= 0L) {
            FlowManager manager = client != null ? client.getFlowManager() : null;
            long expectedGeneration = !preparation.preserveNewerDraft() && preparation.lease() == null
                ? preparation.expectedAuthoritativeGeneration() : -1L;
            return manager != null && manager.matchesAuthoritativeResourceFence(serverId, preparation.type(),
                preparation.id(), preparation.expectedRevision(), preparation.expectedAuthoritativeHash(),
                expectedGeneration);
        }
        return authoritativeResourceRevision(preparation.type(), preparation.id()) == capturedRevision
            && (!pendingCreatePresentations.containsKey(preparation.mutationId())
                || resourceCreationAllowed(preparation, capturedRevision, resourceRevisionReconciler.get(serverId,
                    preparation.type().typeId(), preparation.id())));
    }

    private boolean resourceCreationAllowed(ResourceSavePreparation preparation, long revision,
                                              ReSyncResourceRevisionReconciler.ResourceResult current) {
        return revision == 0L || current != null && current.deleted() && current.revision() == revision
            && current.authorityEpoch() == preparation.fence().authorityEpoch();
    }

    private boolean validResourceSaveAckPreparation(ResourceSavePreparation preparation, ResourceSaveFence saveFence) {
        return preparation != null && !shutdownRequested
            && preparation.resource().equals(resourceLocator(preparation.type(), preparation.id()))
            && preparation.fence().equals(saveFence)
            && currentResourceSaveFence(preparation.fence());
    }

    private void failPreparedResourceSave(ResourceSavePreparation preparation, String message) {
        failPreparedResourceSave(preparation, message, true);
    }

    private void failPreparedResourceSave(ResourceSavePreparation preparation, String message, boolean retryable) {
        if (preparation == null) {
            return;
        }
        ReLog.logger(LogTypes.FLOW).source(LogSource.server(serverId, serverId))
            .component(ReSyncFlowClient.class).operation("Resource Save Preparation").error(message);
        if (!retryable) {
            pendingCreatePresentations.remove(preparation.mutationId());
        }
        cancelPendingSend(preparation.requestId());
        if (DesignerSaveNotifications.isResumableRequest(serverId, preparation.requestId())) {
            releaseResourceSave(preparation.requestId());
            if (!notifyResumableResourceSaveFailure(preparation.type(), preparation.id(), preparation.requestId(), retryable, message)) {
                DesignerSaveNotifications.SaveTarget failed = DesignerSaveNotifications.failRequest(serverId,
                    preparation.requestId(), message);
                markResourceFailedCurrent(failed, preparation.fence());
            }
            return;
        }
        completeResourceSave(preparation.requestId());
        DesignerSaveNotifications.SaveTarget failedSave = DesignerSaveNotifications.failRequest(serverId,
            preparation.requestId(), message);
        markResourceFailedCurrent(failedSave, preparation.fence());
        if (failedSave == null && preparation.type() == ReSyncResourceType.PROJECT_METADATA) {
            FlowManager manager = client != null ? client.getFlowManager() : null;
            executeCurrentServerUi(manager, preparation.fence().connectionToken(),
                () -> {
                    if (preparation.currentPayload()) {
                        markResourceFailed(manager, preparation.type(), preparation.id());
                    }
                });
        }
    }

    private boolean sendLegacyResourceSave(ReSyncResourceType type, String id, String json, String requestId) {
        if (shutdownRequested) return false;
        if (!isProtocolResourceType(type) || !type.hasFlowPackets() || id == null || id.isBlank() || json == null
            || requestId == null || requestId.isBlank()) {
            return false;
        }
        DesignerSaveNotifications.attachRequestId(serverId, type, id, requestId);
        if (!legacyResourceSavePending(type, id, requestId)) {
            cancelPendingSend(requestId);
            return false;
        }
        ResourceSaveFence saveFence = resourceSaveFence(requestId);
        if (saveFence == null || !currentResourceSaveFence(saveFence)) {
            cancelPendingSend(requestId);
            return false;
        }
        if (!isConnected()) {
            logger().operation("Save Flow").with("flowType", type.displayName()).warn("ReSync is disconnected; save queued");
            boolean admitted = enqueuePendingSend(requestId, 5L + requestId.getBytes(StandardCharsets.UTF_8).length
                + json.getBytes(StandardCharsets.UTF_8).length,
                () -> legacyResourceSavePending(type, id, requestId)
                    && queuedSend(() -> sendLegacyResourceSave(type, id, json, requestId)));
            return admitted;
        }
        byte[] jsonBytes = json.getBytes(StandardCharsets.UTF_8);
        if (type == ReSyncResourceType.FLOW) {
            logger().operation("Save Flow").with("bytes", jsonBytes.length).debug("Sending flow save");
        }
        byte[] requestIdBytes = requestId.getBytes(StandardCharsets.UTF_8);
        ByteBuffer buffer = ByteBuffer.allocate(1 + 4 + requestIdBytes.length + jsonBytes.length);
        buffer.put(type.saveByte());
        buffer.putInt(requestIdBytes.length);
        buffer.put(requestIdBytes);
        buffer.put(jsonBytes);
        boolean sent = sendFrame(4, buffer.array(), numericChannel("flow", FLOW_CHANNEL_ID), false,
            saveFence.transportGeneration());
        if (!sent && pendingSendThread != TaskIdentities.access.current()) {
            boolean admitted = enqueuePendingSend(requestId, 5L + requestId.getBytes(StandardCharsets.UTF_8).length
                + json.getBytes(StandardCharsets.UTF_8).length,
                () -> legacyResourceSavePending(type, id, requestId)
                    && queuedSend(() -> sendLegacyResourceSave(type, id, json, requestId)));
            return admitted;
        }
        return sent;
    }

    private boolean legacyResourceSavePending(ReSyncResourceType type, String id, String requestId) {
        if (type == null || id == null || id.isBlank() || requestId == null || requestId.isBlank()) {
            return false;
        }
        ResourceSaveWork work;
        synchronized (resourceSaveQueueLock) {
            work = resourceSavesByTracker.get(requestId);
        }
        return work != null && work.key().type() == type && work.key().id().equals(id)
            && work.currentPayload().getAsBoolean() && currentResourceSaveFence(work.fence())
            && (type == ReSyncResourceType.PROJECT_METADATA
                || DesignerSaveNotifications.isTrackedRequest(serverId, type, id, requestId));
    }

    boolean sendSettledResourceDelete(ReSyncResourceType type, String id) {
        if (shutdownRequested) {
            traceDeletePreflight(type, id, "rejected", "shutdown", null, null, 0L, null, null);
            return false;
        }
        if (!isProtocolResourceType(type) || id == null || id.isBlank()) {
            traceDeletePreflight(type, id, "rejected", "invalid_target", null, null, 0L, null, null);
            return false;
        }
        if (type.isGraph()) {
            return sendCoreGraphDelete(type, id);
        }
        if (!supportsGenericResource(type, ResourceOperationKind.DELETE, true)) {
            traceDeletePreflight(type, id, "rejected", "capability_unavailable", null, null, 0L, null, null);
            return false;
        }
        if (!catalogAuthorityAllowsTypedMutation(catalogAuthority)) {
            traceDeletePreflight(type, id, "rejected", "publication_fence_unavailable", null, null, 0L, null, null);
            return false;
        }
        if (!typedMutationAuthorityReady()) {
            traceDeletePreflight(type, id, "rejected", "authority_epoch_unavailable", null, null, 0L, null, null);
            return false;
        }
        String requestId = UUID.randomUUID().toString();
        long expectedRevision = authoritativeResourceRevision(type, id);
        ServerResourceLocator resource = resourceLocator(type, id);
        if (resource == null) {
            traceDeletePreflight(type, id, "rejected", "resource_locator_unavailable", UUID.fromString(requestId),
                null, expectedRevision, null, null);
            return false;
        }
        if (expectedRevision <= 0L) {
            traceDeletePreflight(type, id, "rejected", "revision_unavailable", UUID.fromString(requestId), null,
                expectedRevision, null, null);
            return false;
        }
        UUID mutationId = UUID.randomUUID();
        ResourceOperation operation = new ResourceDeleteRequest(resource, expectedRevision, mutationId);
        PendingTypedResourceRequest pending = typedResourceRequest(type, operation, resource, expectedRevision, mutationId,
            null, true, false, null, id, requestId, false, UUID.fromString(requestId), UUID.randomUUID(), UUID.randomUUID());
        DesignerSaveNotifications.attachRequestId(serverId, type, id, requestId);
        boolean admitted = dispatchTypedResourceRequest(pending);
        traceDeletePreflight(type, id, admitted ? "admitted" : "rejected",
            admitted ? "dispatch_accepted" : "dispatch_rejected", UUID.fromString(requestId), mutationId,
            expectedRevision, null, null);
        return admitted;
    }

    void sendResourceDelete(ReSyncResourceType type, String id) {
        if (shutdownRequested) return;
        if (!isProtocolResourceType(type)) {
            return;
        }
        if (type.isGraph()) {
            sendCoreGraphDelete(type, id);
            return;
        }
        if (id == null || id.isBlank()) {
            return;
        }
        String requestId = UUID.randomUUID().toString();
        long expectedRevision = authoritativeResourceRevision(type, id);
        if ((!supportsGenericResource(type, ResourceOperationKind.DELETE, true)
            || !catalogAuthorityAllowsTypedMutation(catalogAuthority)) && legacyMutationCompatibilityAllowed()) {
            sendLegacyResourceDelete(type, id, id, requestId);
            return;
        }
        ServerResourceLocator resource = resourceLocator(type, id);
        if (resource == null || expectedRevision <= 0L) {
            markResourceFailed(client != null ? client.getFlowManager() : null, type, id);
            return;
        }
        UUID mutationId = UUID.randomUUID();
        ResourceOperation operation = new ResourceDeleteRequest(resource, expectedRevision, mutationId);
        PendingTypedResourceRequest pending = typedResourceRequest(type, operation, resource, expectedRevision, mutationId,
            null, true, false, null, id, requestId, false, UUID.fromString(requestId), UUID.randomUUID(), UUID.randomUUID());
        DesignerSaveNotifications.attachRequestId(serverId, type, id, requestId);
        dispatchTypedResourceRequest(pending);
    }

    void sendResourceActivation(ReSyncResourceType type, String resourceId, boolean enabled, String requestId) {
        if (shutdownRequested) return;
        if (!isProtocolResourceType(type) || resourceId == null || resourceId.isBlank() || requestId == null || requestId.isBlank()) {
            return;
        }
        if (supportsGenericResourceActivation(type) && catalogAuthorityAllowsTypedMutation(catalogAuthority)) {
            sendGenericResourceActivation(type, resourceId, enabled, requestId);
            return;
        }
        if (type.isGraph() || !legacyMutationCompatibilityAllowed()) {
            FlowManager manager = client != null ? client.getFlowManager() : null;
            if (manager != null) {
                manager.completeResourceActivation(serverId, type, resourceId, enabled, requestId, false,
                    !supportsGenericResourceActivation(type)
                        ? "The server does not advertise the typed resource activation capability."
                        : "The typed catalog authority is not established; the resource update was not sent.",
                    true);
            }
            return;
        }
        sendLegacyResourceActivation(type, resourceId, enabled, requestId);
    }

    private void sendGenericResourceActivation(ReSyncResourceType type, String resourceId, boolean enabled, String legacyRequestId) {
        FlowManager manager = client != null ? client.getFlowManager() : null;
        ServerId protocolServer = protocolServerId();
        long expectedRevision = authoritativeResourceRevision(type, resourceId);
        if (protocolServer == null || expectedRevision <= 0L) {
            if (manager != null) {
                manager.completeResourceActivation(serverId, type, resourceId, enabled, legacyRequestId, false,
                    "The resource revision is unavailable. Refresh the resource and try again.", true);
            }
            return;
        }
        UUID requestId = UUID.randomUUID();
        UUID mutationId = UUID.randomUUID();
        ServerResourceLocator resource = new ServerResourceLocator(protocolServer,
            ContractRef.of(PROTOCOL_OWNER, ResourceTypeId.of(type.typeId())), resourceId);
        ResourceActivateRequest operation = new ResourceActivateRequest(resource, expectedRevision,
            enabled ? ResourceActivationState.ACTIVE : ResourceActivationState.INACTIVE, mutationId);
        UUID correlationId = UUID.randomUUID();
        UUID traceId = UUID.randomUUID();
        if (!type.isGraph()) {
            PendingTypedResourceRequest pending = typedResourceRequest(type, operation, resource, expectedRevision, mutationId,
                null, true, false, null, null, legacyRequestId, enabled, requestId, correlationId, traceId);
            dispatchTypedResourceRequest(pending);
            return;
        }
        pendingResourceActivations.put(requestId, new PendingResourceActivation(requestId, correlationId, mutationId, resource,
            expectedRevision, type, resourceId, enabled, legacyRequestId));
        PendingCoreGraphRequest pending = coreRequest(requestId, type, ResourceOperationKind.ACTIVATE, resource,
            expectedRevision, mutationId, null, null, correlationId, traceId, null);
        dispatchCoreGraphRequest(pending, operation, null, true);
    }

    private void sendLegacyResourceActivation(ReSyncResourceType type, String resourceId, boolean enabled, String requestId) {
        if (shutdownRequested) return;
        if (!isProtocolResourceType(type) || resourceId == null || resourceId.isBlank()
            || requestId == null || requestId.isBlank()) {
            return;
        }
        FlowManager manager = client != null ? client.getFlowManager() : null;
        FlowManager.ServerConnectionToken token = captureUiToken(manager);
        PendingLegacyActivation pending = pendingLegacyActivations.computeIfAbsent(requestId,
            ignored -> new PendingLegacyActivation(type, resourceId, enabled, requestId, token));
        if (pending.type() != type || !pending.resourceId().equals(resourceId) || pending.enabled() != enabled) {
            return;
        }
        if (manager == null || !manager.isCurrentServerConnection(pending.token())) {
            return;
        }
        if (!isConnected()) {
            enqueuePendingSend(requestId, Math.max(CALLBACK_RETAINED_BYTES,
                requestId.getBytes(StandardCharsets.UTF_8).length
                    + resourceId.getBytes(StandardCharsets.UTF_8).length), () -> {
                if (!pendingLegacyActivations.containsKey(requestId)) {
                    return false;
                }
                return queuedSend(() -> sendLegacyResourceActivation(type, resourceId, enabled, requestId));
            });
            return;
        }
        JsonObject request = new JsonObject();
        request.addProperty("type", type.typeId());
        request.addProperty("resourceId", resourceId);
        request.addProperty("enabled", enabled);
        request.addProperty("requestId", requestId);
        byte[] json = gson.toJson(request).getBytes(StandardCharsets.UTF_8);
        ByteBuffer packet = ByteBuffer.allocate(1 + json.length);
        packet.put(ReSyncProtocolContract.FLOW_PACKET_RESOURCE_ACTIVATION);
        packet.put(json);
        if (!sendFrame(4, packet.array(), numericChannel("flow", FLOW_CHANNEL_ID), false)) {
            if (pendingSendThread == TaskIdentities.access.current()) {
                return;
            }
            enqueuePendingSend(requestId, Math.max(CALLBACK_RETAINED_BYTES,
                requestId.getBytes(StandardCharsets.UTF_8).length
                    + resourceId.getBytes(StandardCharsets.UTF_8).length), () -> {
                if (!pendingLegacyActivations.containsKey(requestId)) {
                    return false;
                }
                return queuedSend(() -> sendLegacyResourceActivation(type, resourceId, enabled, requestId));
            });
            return;
        }
        heartbeatScheduler.schedule(() -> {
            if (!pendingLegacyActivations.remove(requestId, pending)) {
                return;
            }
            cancelPendingSend(requestId);
            if (manager != null) {
                executeCurrentServerUi(manager, pending.token(), () -> manager.completeResourceActivation(serverId, type, resourceId, enabled, requestId, false,
                    "ReSync did not confirm the update. Try again.", true));
            }
        }, Duration.ofSeconds(15L));
    }

    private boolean supportsGenericCoreResource(ReSyncResourceType type, ResourceOperationKind operation,
                                                boolean mutation) {
        return type != null && type.isGraph() && supportsGenericResource(type, operation, mutation);
    }

    private boolean supportsGenericResource(ReSyncResourceType type, ResourceOperationKind operation,
                                            boolean mutation) {
        if (type == null || !isProtocolResourceType(type) || operation == null || protocolServerId() == null) {
            return false;
        }
        if (operation == ResourceOperationKind.ACTIVATE) {
            return supportsGenericResourceActivation(type);
        }
        JsonObject protocol = resourceProtocolCapabilities();
        if (protocol == null) {
            return false;
        }
        if (protocol.has("supported") && !protocol.get("supported").getAsBoolean()) {
            return false;
        }
        if (genericResourceContractVersion == null || (mutation && !hasDurableEnvelopeAuthority(protocol))) {
            return false;
        }
        String advertised = switch (operation) {
            case LIST -> "list";
            case QUERY -> "query";
            case LOAD -> "load";
            case CREATE -> "create";
            case SAVE -> "save";
            case DELETE -> "delete";
            case ACTIVATE -> "activate";
            case DUPLICATE -> "duplicate";
            default -> "";
        };
        return !advertised.isBlank() && hasResourceOperation(protocol, mutation, advertised);
    }

    boolean supportsAggregateResourceCreation(ReSyncResourceType type) {
        if (!supportsGenericResource(type, ResourceOperationKind.CREATE, true) || !typedMutationAuthorityReady()) {
            return false;
        }
        JsonObject protocol = resourceProtocolCapabilities();
        if (protocol == null) {
            return false;
        }
        JsonObject contract = protocol.has("genericResourceContract")
            && protocol.get("genericResourceContract").isJsonObject()
            ? protocol.getAsJsonObject("genericResourceContract") : null;
        return genericResourceContractVersion != null
            && genericResourceContractVersion.compareTo(new CatalogVersion(1, 2)) >= 0
            && (contract != null && hasCapability(contract, "resource_create_presentation")
            || hasCapability(protocol, "resource_create_presentation"));
    }

    private boolean hasResourceOperation(JsonObject protocol, boolean mutation, String operation) {
        if (!protocol.has("resourceOperations") || !protocol.get("resourceOperations").isJsonObject()) {
            return false;
        }
        JsonObject operations = protocol.getAsJsonObject("resourceOperations");
        JsonElement values = operations.get(mutation ? "mutate" : "read");
        if (containsText(values, operation) || containsText(values, "resource." + operation)) {
            return true;
        }
        return false;
    }

    boolean supportsGenericResourceActivation(ReSyncResourceType type) {
        if (!isProtocolResourceType(type) || protocolServerId() == null) {
            return false;
        }
        JsonObject protocol = resourceProtocolCapabilities();
        if (protocol == null) {
            return false;
        }
        if (protocol.has("supported") && !protocol.get("supported").getAsBoolean()) {
            return false;
        }
        if (!hasDurableEnvelopeAuthority(protocol) || !hasActivationOperation(protocol)
            || !hasGenericResourceContract(protocol)) {
            return false;
        }
        return true;
    }

    private JsonObject resourceCapabilities() {
        SessionCapabilities current = sessionCapabilities;
        if (current != null) {
            return current.generation() == connectionGeneration.get() ? current.value() : null;
        }
        FlowManager manager = client != null ? client.getFlowManager() : null;
        return manager != null ? manager.getServerCapabilities(serverId) : null;
    }

    private JsonObject resourceProtocolCapabilities() {
        JsonObject capabilities = resourceCapabilities();
        return capabilities != null && capabilities.has("protocolEnvelope")
            && capabilities.get("protocolEnvelope").isJsonObject()
            ? capabilities.getAsJsonObject("protocolEnvelope") : null;
    }

    private boolean genericResourceProtocolAdvertised(JsonObject capabilities) {
        return negotiateGenericResourceContractVersion(capabilities) != null;
    }

    private boolean hasDurableEnvelopeAuthority(JsonObject protocol) {
        if (!protocol.has("mutationAuthority") || !protocol.get("mutationAuthority").isJsonObject()) {
            return false;
        }
        JsonObject authority = protocol.getAsJsonObject("mutationAuthority");
        return authority.has("supported") && authority.get("supported").getAsBoolean()
            && authority.has("durable") && authority.get("durable").getAsBoolean();
    }

    private boolean hasActivationOperation(JsonObject protocol) {
        if (!protocol.has("resourceOperations") || !protocol.get("resourceOperations").isJsonObject()) {
            return false;
        }
        JsonObject operations = protocol.getAsJsonObject("resourceOperations");
        return containsText(operations.get("mutate"), "activate");
    }

    private boolean hasGenericResourceContract(JsonObject protocol) {
        if (genericResourceContractVersion == null
            || genericResourceContractVersion.compareTo(new CatalogVersion(1, 1)) < 0) {
            return false;
        }
        if (protocol.has("genericResourceContract") && protocol.get("genericResourceContract").isJsonObject()) {
            return hasCapability(protocol.getAsJsonObject("genericResourceContract"), "resource_activation");
        }
        return hasCapability(protocol, "resource_activation");
    }

    private CatalogVersion negotiateGenericResourceContractVersion(JsonObject capabilities) {
        if (capabilities == null || !capabilities.has("protocolEnvelope")
            || !capabilities.get("protocolEnvelope").isJsonObject()) {
            return null;
        }
        JsonObject protocol = capabilities.getAsJsonObject("protocolEnvelope");
        if (protocol.has("supported") && (!protocol.get("supported").isJsonPrimitive()
            || !protocol.get("supported").getAsJsonPrimitive().isBoolean()
            || !protocol.get("supported").getAsBoolean())) {
            return null;
        }
        JsonElement value = firstValue(protocol, "genericResourceContractVersion", "resourceContractVersion",
            "contractVersion");
        if (protocol.has("genericResourceContract")) {
            if (!protocol.get("genericResourceContract").isJsonObject()) {
                return null;
            }
            JsonObject contract = protocol.getAsJsonObject("genericResourceContract");
            if (!contract.has("version")) {
                return null;
            }
            value = contract.get("version");
        }
        CatalogVersion advertised = parseGenericResourceContractVersion(value);
        CatalogVersion current = ReSyncProtocolContract.GENERIC_RESOURCE_CONTRACT_VERSION;
        if (advertised == null || advertised.compareTo(new CatalogVersion(1, 0)) < 0) {
            return null;
        }
        return advertised.compareTo(current) < 0 ? advertised : current;
    }

    private CatalogVersion parseGenericResourceContractVersion(JsonElement value) {
        if (value == null) {
            return null;
        }
        try {
            if (value.isJsonPrimitive() && value.getAsJsonPrimitive().isString()) {
                String[] parts = value.getAsString().split("\\.", -1);
                return parts.length == 2 ? new CatalogVersion(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]))
                    : null;
            }
            if (!value.isJsonObject()) {
                return null;
            }
            JsonObject object = value.getAsJsonObject();
            JsonElement generation = object.get("generation");
            JsonElement major = object.get("major");
            JsonElement minor = object.get("minor");
            if (minor == null || generation == null && major == null) {
                return null;
            }
            int generationValue = generation != null ? generation.getAsInt() : major.getAsInt();
            if (generation != null && major != null && generationValue != major.getAsInt()) {
                return null;
            }
            return new CatalogVersion(generationValue, minor.getAsInt());
        } catch (RuntimeException exception) {
            return null;
        }
    }

    private Set<ContractRef<CapabilityId>> genericResourceEnvelopeCapabilities() {
        JsonObject protocol = resourceProtocolCapabilities();
        return protocol != null && hasGenericResourceContract(protocol)
            ? RESOURCE_ACTIVATION_CAPABILITIES : GENERIC_RESOURCE_CAPABILITIES;
    }

    private Set<ContractRef<CapabilityId>> aggregateResourceEnvelopeCapabilities() {
        LinkedHashSet<ContractRef<CapabilityId>> capabilities = new LinkedHashSet<>(genericResourceEnvelopeCapabilities());
        capabilities.add(ReSyncProtocolContract.RESOURCE_CREATE_PRESENTATION_CAPABILITY);
        return Set.copyOf(capabilities);
    }

    private boolean hasCapability(JsonObject object, String capability) {
        for (String property : List.of("capabilities", "resourceCapabilities", "genericCapabilities")) {
            if (containsCapability(object.get(property), capability)) {
                return true;
            }
        }
        return false;
    }

    private boolean containsCapability(JsonElement value, String capability) {
        if (value == null || !value.isJsonArray()) {
            return false;
        }
        for (JsonElement element : value.getAsJsonArray()) {
            if (element != null && element.isJsonPrimitive() && (capability.equals(element.getAsString())
                || (PROTOCOL_OWNER.canonicalText() + "/" + capability).equals(element.getAsString()))) {
                return true;
            }
        }
        return false;
    }

    private boolean containsText(JsonElement value, String expected) {
        if (value == null || !value.isJsonArray()) {
            return false;
        }
        for (JsonElement element : value.getAsJsonArray()) {
            if (element != null && element.isJsonPrimitive() && expected.equals(element.getAsString())) {
                return true;
            }
        }
        return false;
    }

    private boolean versionAtLeast(JsonElement value, int generation, int minor) {
        if (value == null) {
            return false;
        }
        try {
            if (value.isJsonPrimitive()) {
                String text = value.getAsString();
                String[] parts = text.split("\\.", -1);
                return parts.length == 2 && Integer.parseInt(parts[0]) > generation
                    || parts.length == 2 && Integer.parseInt(parts[0]) == generation && Integer.parseInt(parts[1]) >= minor;
            }
            if (value.isJsonObject()) {
                JsonObject object = value.getAsJsonObject();
                int actualGeneration = object.has("generation") ? object.get("generation").getAsInt()
                    : object.has("major") ? object.get("major").getAsInt() : 0;
                int actualMinor = object.has("minor") ? object.get("minor").getAsInt() : 0;
                return actualGeneration > generation || actualGeneration == generation && actualMinor >= minor;
            }
        } catch (RuntimeException ignored) {
            return false;
        }
        return false;
    }

    private ServerId protocolServerId() {
        try {
            return new ServerId(UUID.fromString(serverId));
        } catch (RuntimeException exception) {
            return null;
        }
    }

    private long authoritativeResourceRevision(ReSyncResourceType type, String resourceId) {
        long watermark = resourceRevisionWatermarks.getOrDefault(resourceRevisionKey(type, resourceId), 0L);
        FlowManager manager = client != null ? client.getFlowManager() : null;
        long cachedRevision = manager != null ? manager.authoritativeResourceRevision(serverId, type, resourceId) : 0L;
        return Math.max(Math.max(watermark, cachedRevision), resourceRevisionReconciler.revision(serverId, type.typeId(), resourceId));
    }

    boolean retainsResourceActivation(ReSyncResourceType type, String resourceId, String legacyRequestId) {
        if (type == null || resourceId == null || resourceId.isBlank()
            || legacyRequestId == null || legacyRequestId.isBlank()) {
            return false;
        }
        synchronized (transportMutationRetentionLock) {
            if (type.isGraph()) {
                for (PendingResourceActivation pending : pendingResourceActivations.values()) {
                    if (pending.type() == type && resourceId.equals(pending.resourceId())
                        && legacyRequestId.equals(pending.legacyRequestId())
                        && retainedCoreTransportMutations.containsKey(pending.requestId())) {
                        return true;
                    }
                }
                return false;
            }
            for (PendingTypedResourceRequest pending : retainedTypedTransportMutations.values()) {
                if (pending.operation() == ResourceOperationKind.ACTIVATE && pending.type() == type
                    && pending.resource() != null && resourceId.equals(pending.resource().id())
                    && legacyRequestId.equals(pending.legacyRequestId())) {
                    return true;
                }
            }
            return false;
        }
    }

    private void failPendingResourceActivations(String message) {
        if (pendingResourceActivations.isEmpty()) {
            return;
        }
        FlowManager manager = client != null ? client.getFlowManager() : null;
        for (PendingResourceActivation pending : List.copyOf(pendingResourceActivations.values())) {
            synchronized (transportMutationRetentionLock) {
                if (retainedCoreTransportMutations.containsKey(pending.requestId())
                    || retainedTypedTransportMutations.containsKey(pending.requestId())
                    || !pendingResourceActivations.remove(pending.requestId(), pending)) {
                    continue;
                }
                pendingCoreGraphRequests.remove(pending.requestId());
                coreRequestRecoveries.remove(pending.requestId());
            }
            cancelPendingSend(pending.requestId().toString());
            if (manager == null) {
                continue;
            }
            manager.completeResourceActivation(serverId, pending.type(), pending.resourceId(), pending.enabled(), pending.legacyRequestId(),
                false, message, true);
        }
    }

    private void failPendingCoreGraphRequests(String message) {
        failPendingCoreGraphRequests(message, false);
    }

    private void failPendingCoreGraphRequests(String message, boolean retainOpenIntents) {
        for (PendingCoreGraphRequest pending : List.copyOf(pendingCoreGraphRequests.values())) {
            CoreRequestRecovery recovery = pending == null ? null : coreRequestRecoveries.get(pending.requestId());
            if (retainCoreTransportMutation(pending, recovery) || retainPendingCoreGraphSave(pending)) {
                continue;
            }
            boolean retain = retainOpenIntents && pending != null && pending.operation() == ResourceOperationKind.LOAD
                && pendingCoreOpenRequests.contains(pending.requestId());
            failCorePending(pending, message, retain);
        }
        failPendingResourceActivations(message);
        synchronized (coreListGenerationLock) {
            corePageContinuations.clear();
            coreResourcePageCursors.clear();
            activeCoreListCorrelations.clear();
        }
        failPendingTypedResourceRequests(message, retainOpenIntents);
    }

    private void retainPendingCoreGraphSaves() {
        for (PendingCoreGraphRequest pending : List.copyOf(pendingCoreGraphRequests.values())) {
            retainPendingCoreGraphSave(pending);
        }
    }

    private boolean retainPendingCoreGraphSave(PendingCoreGraphRequest pending) {
        synchronized (coreSaveRecoveryLock) {
            return retainPendingCoreGraphSaveLocked(pending);
        }
    }

    private boolean retainPendingCoreGraphSaveLocked(PendingCoreGraphRequest pending) {
        if (pending == null || pending.operation() != ResourceOperationKind.SAVE || pending.resource() == null
            || pending.mutationId() == null || !DesignerSaveNotifications.isResumableRequest(serverId,
                pending.requestId().toString()) || !DesignerSaveNotifications.isTrackedRequest(serverId, pending.type(),
                pending.resource().id(), pending.requestId().toString())) {
            return false;
        }
        CoreRequestRecovery requestRecovery = coreRequestRecoveries.get(pending.requestId());
        if (requestRecovery == null || !requestRecovery.mutation
            || requestRecovery.operation.kind() != ResourceOperationKind.SAVE) {
            return false;
        }
        RetainedCoreGraphSave recovery = new RetainedCoreGraphSave(pending, requestRecovery.operation,
            requestRecovery.payloadHash);
        RetainedCoreGraphSave existing = retainedCoreGraphSaves.putIfAbsent(pending.requestId(), recovery);
        if (existing != null) {
            return existing.equals(recovery);
        }
        if (!pendingCoreGraphRequests.remove(pending.requestId(), pending)) {
            retainedCoreGraphSaves.remove(pending.requestId(), recovery);
            return false;
        }
        coreRequestRecoveries.remove(pending.requestId(), requestRecovery);
        coreSaveSessionSettlementRecoveries.remove(pending.mutationId());
        cancelPendingSend(pending.requestId().toString());
        traceLifecycle(serverId, "save_recovery_retained", "serverId", serverId, "resourceKey",
            pending.type().typeId() + ":" + pending.resource().id(), "operation", pending.operation(), "requestId",
            pending.requestId(), "correlationId", pending.correlationId(), "traceId", pending.traceId(), "mutationId",
            pending.mutationId(), "generation", pending.transportGeneration(), "authorityEpoch", handshakeAuthorityEpoch,
            "revision", pending.expectedRevision());
        return true;
    }

    private boolean retainCoreTransportMutation(PendingCoreGraphRequest pending, CoreRequestRecovery recovery) {
        synchronized (transportMutationRetentionLock) {
            if (pending == null || recovery == null || !recovery.mutation) {
                return false;
            }
            if (pending.operation() == ResourceOperationKind.SAVE && retainPendingCoreGraphSave(pending)) {
                return true;
            }
            if (pending.operation() != ResourceOperationKind.CREATE && pending.operation() != ResourceOperationKind.SAVE
                && pending.operation() != ResourceOperationKind.DELETE
                && pending.operation() != ResourceOperationKind.ACTIVATE) {
                return false;
            }
            RetainedCoreTransportMutation retained = new RetainedCoreTransportMutation(pending, recovery.operation,
                recovery.payloadHash);
            RetainedCoreTransportMutation existing = retainedCoreTransportMutations.putIfAbsent(pending.requestId(), retained);
            if (existing != null) {
                return existing.equals(retained);
            }
            if (!pendingCoreGraphRequests.remove(pending.requestId(), pending)) {
                retainedCoreTransportMutations.remove(pending.requestId(), retained);
                return false;
            }
            coreRequestRecoveries.remove(pending.requestId(), recovery);
        }
        cancelPendingSend(pending.requestId().toString());
        traceLifecycle(serverId, "transport_mutation_retained", "serverId", serverId, "resourceKey",
            temporaryLifecycleResourceKey(pending.type(), pending.resource()), "operation", pending.operation(),
            "requestId", pending.requestId(), "mutationId", pending.mutationId(), "generation",
            pending.transportGeneration(), "authorityEpoch", handshakeAuthorityEpoch, "revision",
            pending.expectedRevision());
        return true;
    }

    private boolean retainTypedTransportMutation(PendingTypedResourceRequest pending) {
        synchronized (transportMutationRetentionLock) {
            if (pending == null || !pending.mutation()) {
                return false;
            }
            PendingTypedResourceRequest existing = retainedTypedTransportMutations.putIfAbsent(pending.requestId(), pending);
            if (existing != null) {
                return existing == pending;
            }
            if (!pendingTypedResourceRequests.remove(pending.requestId(), pending)) {
                retainedTypedTransportMutations.remove(pending.requestId(), pending);
                return false;
            }
            typedRequestDeliveries.remove(pending.requestId());
            clearPendingTypedReplays(pending.requestId());
            typedMutationRecoveryAttempts.remove(pending.requestId());
            scheduledTypedMutationRecoveries.remove(pending.requestId());
        }
        cancelPendingSend(pending.requestId().toString());
        traceLifecycle(serverId, "transport_mutation_retained", "serverId", serverId, "resourceKey",
            temporaryLifecycleResourceKey(pending.type(), pending.resource()), "operation", pending.operation(),
            "requestId", pending.requestId(), "mutationId", pending.mutationId(), "generation",
            pending.transportGeneration(), "authorityEpoch", handshakeAuthorityEpoch, "revision",
            pending.expectedRevision());
        return true;
    }

    private boolean retiredCoreSaveTransport(PendingCoreGraphRequest pending) {
        return pending.operation() == ResourceOperationKind.SAVE && pending.transportGeneration() >= 0
            && (activeTransportGeneration < 0 || activeTransportGeneration != pending.transportGeneration());
    }

    private void retryRetainedCoreGraphSaves(int generation) {
        if (!isConnectionReadyGeneration(generation) || catalogAuthority != CatalogAuthority.TYPED_PUBLICATION
            || !typedMutationAuthorityReady()) {
            return;
        }
        for (Map.Entry<UUID, RetainedCoreGraphSave> entry : List.copyOf(retainedCoreGraphSaves.entrySet())) {
            UUID requestId = entry.getKey();
            RetainedCoreGraphSave recovery = entry.getValue();
            PendingCoreGraphRequest retained = recovery.pending();
            if (!DesignerSaveNotifications.isResumableRequest(serverId, requestId.toString())
                || !DesignerSaveNotifications.isTrackedRequest(serverId, retained.type(), retained.resource().id(),
                    requestId.toString())) {
                retainedCoreGraphSaves.remove(requestId, recovery);
                continue;
            }
            if (!supportsGenericCoreResource(retained.type(), ResourceOperationKind.SAVE, true)) {
                failRetainedCoreGraphSave(requestId, recovery,
                    "The server no longer advertises the Core graph save capability.");
                continue;
            }
            ResourceSaveFence fence = captureResourceSaveFence();
            if (fence == null || fence.transportGeneration() != generation) {
                return;
            }
            if (!retainedCoreGraphSaves.remove(requestId, recovery)) {
                continue;
            }
            PendingCoreGraphRequest resumed = retained.forTransportGeneration(generation);
            if (pendingCoreGraphRequests.putIfAbsent(requestId, resumed) != null) {
                retainedCoreGraphSaves.putIfAbsent(requestId, recovery);
                continue;
            }
            String mutationId = resumed.mutationId().toString();
            boolean admitted = enqueueResourceSave(new ResourceSaveKey(resumed.type(), resumed.resource().id()),
                mutationId, -1L, fence, null, () -> true,
                () -> dispatchCoreGraphRequest(resumed, recovery.operation(), recovery.payloadHash(), true, fence),
                () -> failResumedCoreGraphSave(resumed, "The Core graph save recovery queue is full."));
            if (!admitted) {
                failResumedCoreGraphSave(resumed, "The Core graph save recovery queue is full.");
                continue;
            }
            traceLifecycle(serverId, "save_recovery_dispatched", "serverId", serverId, "resourceKey",
                resumed.type().typeId() + ":" + resumed.resource().id(), "operation", resumed.operation(), "requestId",
                resumed.requestId(), "correlationId", resumed.correlationId(), "traceId", resumed.traceId(), "mutationId",
                resumed.mutationId(), "generation", generation, "authorityEpoch", fence.authorityEpoch(), "revision",
                resumed.expectedRevision());
        }
    }

    private void retryRetainedTransportMutations(int generation) {
        if (!isConnectionReadyGeneration(generation) || catalogAuthority != CatalogAuthority.TYPED_PUBLICATION
            || !typedMutationAuthorityReady()) {
            return;
        }
        for (Map.Entry<UUID, RetainedCoreTransportMutation> entry
            : List.copyOf(retainedCoreTransportMutations.entrySet())) {
            UUID requestId = entry.getKey();
            RetainedCoreTransportMutation retained = entry.getValue();
            PendingCoreGraphRequest resumed = retained.pending().forTransportGeneration(generation);
            synchronized (transportMutationRetentionLock) {
                if (pendingCoreGraphRequests.putIfAbsent(requestId, resumed) != null) {
                    continue;
                }
                if (!retainedCoreTransportMutations.remove(requestId, retained)) {
                    pendingCoreGraphRequests.remove(requestId, resumed);
                    continue;
                }
            }
            traceLifecycle(serverId, "transport_mutation_replayed", "serverId", serverId, "resourceKey",
                temporaryLifecycleResourceKey(resumed.type(), resumed.resource()), "operation", resumed.operation(),
                "requestId", resumed.requestId(), "mutationId", resumed.mutationId(), "generation", generation,
                "authorityEpoch", handshakeAuthorityEpoch, "revision", resumed.expectedRevision());
            dispatchCoreGraphRequest(resumed, retained.operation(), retained.payloadHash(), true);
        }
        for (Map.Entry<UUID, PendingTypedResourceRequest> entry
            : List.copyOf(retainedTypedTransportMutations.entrySet())) {
            UUID requestId = entry.getKey();
            PendingTypedResourceRequest retained = entry.getValue();
            PendingTypedResourceRequest resumed = retained.forTransportGeneration(generation);
            ResourceSaveFence fence = resumed.operation() == ResourceOperationKind.CREATE
                || resumed.operation() == ResourceOperationKind.SAVE ? captureResourceSaveFence() : null;
            if ((resumed.operation() == ResourceOperationKind.CREATE || resumed.operation() == ResourceOperationKind.SAVE)
                && (fence == null || fence.transportGeneration() != generation)) {
                continue;
            }
            synchronized (transportMutationRetentionLock) {
                if (pendingTypedResourceRequests.putIfAbsent(requestId, resumed) != null) {
                    continue;
                }
                if (!retainedTypedTransportMutations.remove(requestId, retained)) {
                    pendingTypedResourceRequests.remove(requestId, resumed);
                    continue;
                }
            }
            traceLifecycle(serverId, "transport_mutation_replayed", "serverId", serverId, "resourceKey",
                temporaryLifecycleResourceKey(resumed.type(), resumed.resource()), "operation", resumed.operation(),
                "requestId", resumed.requestId(), "mutationId", resumed.mutationId(), "generation", generation,
                "authorityEpoch", handshakeAuthorityEpoch, "revision", resumed.expectedRevision());
            if (fence == null) {
                dispatchTypedResourceRequest(resumed);
                continue;
            }
            String trackerId = saveRequestId(resumed);
            boolean admitted = enqueueResourceSave(new ResourceSaveKey(resumed.type(), resumed.resource().id()),
                trackerId, -1L, fence, null, () -> true,
                () -> dispatchTypedResourceRequest(resumed, fence),
                () -> retainTypedTransportMutation(resumed));
            if (!admitted) {
                retainTypedTransportMutation(resumed);
            }
        }
    }

    private void failRetainedCoreGraphSave(UUID requestId, RetainedCoreGraphSave recovery, String message) {
        if (requestId == null || recovery == null || !retainedCoreGraphSaves.remove(requestId, recovery)) {
            return;
        }
        settleRetainedCoreGraphSaveFailure(recovery.pending(), message);
    }

    private void failResumedCoreGraphSave(PendingCoreGraphRequest pending, String message) {
        if (pending == null || !pendingCoreGraphRequests.remove(pending.requestId(), pending)) {
            return;
        }
        coreRequestRecoveries.remove(pending.requestId());
        cancelPendingSend(pending.requestId().toString());
        completeResourceSave(pending.mutationId().toString());
        settleRetainedCoreGraphSaveFailure(pending, message);
    }

    private void settleRetainedCoreGraphSaveFailure(PendingCoreGraphRequest pending, String message) {
        DesignerSaveNotifications.SaveTarget target = DesignerSaveNotifications.failMutation(serverId, pending.type(),
            pending.resource().id(), pending.mutationId().toString(), message);
        markResourceFailedCurrent(target, null);
    }

    private void failRetainedCoreGraphSaves(String message) {
        for (Map.Entry<UUID, RetainedCoreGraphSave> entry : List.copyOf(retainedCoreGraphSaves.entrySet())) {
            failRetainedCoreGraphSave(entry.getKey(), entry.getValue(), message);
        }
    }

    private void failRetainedTransportMutations(String message) {
        for (Map.Entry<UUID, RetainedCoreTransportMutation> entry
            : List.copyOf(retainedCoreTransportMutations.entrySet())) {
            UUID requestId = entry.getKey();
            RetainedCoreTransportMutation retained = entry.getValue();
            synchronized (transportMutationRetentionLock) {
                if (!retainedCoreTransportMutations.remove(requestId, retained)) {
                    continue;
                }
                PendingCoreGraphRequest pending = retained.pending();
                pendingCoreGraphRequests.putIfAbsent(requestId, pending);
                coreRequestRecoveries.putIfAbsent(requestId,
                    new CoreRequestRecovery(retained.operation(), retained.payloadHash(), true, null));
            }
            PendingCoreGraphRequest pending = retained.pending();
            failCorePending(pending, message);
        }
        for (Map.Entry<UUID, PendingTypedResourceRequest> entry
            : List.copyOf(retainedTypedTransportMutations.entrySet())) {
            UUID requestId = entry.getKey();
            PendingTypedResourceRequest pending = entry.getValue();
            synchronized (transportMutationRetentionLock) {
                if (!retainedTypedTransportMutations.remove(requestId, pending)) {
                    continue;
                }
                pendingTypedResourceRequests.putIfAbsent(requestId, pending);
            }
            failTypedResourceRequest(pending, message);
        }
    }

    private void failPendingTypedResourceRequests(String message) {
        failPendingTypedResourceRequests(message, false);
    }

    private void failPendingTypedResourceRequests(String message, boolean retainOpenIntents) {
        for (PendingTypedResourceRequest pending : List.copyOf(pendingTypedResourceRequests.values())) {
            if (retainTypedTransportMutation(pending)) {
                continue;
            }
            boolean retain = retainOpenIntents && pending != null && pending.operation() == ResourceOperationKind.LOAD
                && pending.openWhenReceived();
            failTypedResourceRequest(pending, message, true, retain);
        }
        activeTypedResourceListCorrelations.clear();
        typedResourceListResults.clear();
    }

    private void retainPendingTransportMutations() {
        for (PendingCoreGraphRequest pending : List.copyOf(pendingCoreGraphRequests.values())) {
            CoreRequestRecovery recovery = pending == null ? null : coreRequestRecoveries.get(pending.requestId());
            retainCoreTransportMutation(pending, recovery);
        }
        for (PendingTypedResourceRequest pending : List.copyOf(pendingTypedResourceRequests.values())) {
            retainTypedTransportMutation(pending);
        }
    }

    private Set<String> retainedTransportSaveRequestIds() {
        synchronized (transportMutationRetentionLock) {
            Set<String> requestIds = new HashSet<>();
            for (RetainedCoreTransportMutation retained : retainedCoreTransportMutations.values()) {
                if (retained.pending().operation() == ResourceOperationKind.SAVE) {
                    requestIds.add(retained.pending().requestId().toString());
                }
            }
            for (PendingTypedResourceRequest retained : retainedTypedTransportMutations.values()) {
                if (retained.operation() == ResourceOperationKind.SAVE) {
                    requestIds.add(saveRequestId(retained));
                }
            }
            return Set.copyOf(requestIds);
        }
    }

    private void failPendingAuthoringTemplateRequests(String message) {
        for (PendingAuthoringTemplateRequest pending : List.copyOf(pendingAuthoringTemplateRequests.values())) {
            completeAuthoringTemplateRequest(pending, null);
        }
    }

    private void failPendingCoreOptionRequests(String message) {
        for (PendingCoreOptionRequest pending : List.copyOf(pendingCoreOptionRequests.values())) {
            failCoreOptionRequest(pending, message);
        }
    }

    private void failUnsupportedCoreGraphRequests() {
        for (PendingCoreGraphRequest pending : List.copyOf(pendingCoreGraphRequests.values())) {
            boolean mutation = resourceMutationOperation(pending.operation());
            if (supportsGenericCoreResource(pending.type(), pending.operation(), mutation)) {
                continue;
            }
            failCorePending(pending, "The server no longer advertises the Core graph capability required for this update.");
        }
    }

    private void failPendingLegacyActivations(String message) {
        FlowManager manager = client != null ? client.getFlowManager() : null;
        for (PendingLegacyActivation pending : List.copyOf(pendingLegacyActivations.values())) {
            if (!pendingLegacyActivations.remove(pending.requestId(), pending)) {
                continue;
            }
            cancelPendingSend(pending.requestId());
            if (manager == null) {
                continue;
            }
            if (manager != null) {
                runCurrentServer(manager, pending.token(), () -> manager.completeResourceActivation(serverId, pending.type(),
                    pending.resourceId(), pending.enabled(), pending.requestId(), false, message, true));
            }
        }
    }

    private boolean failPendingResourceDeletes(String message) {
        FlowManager manager = client != null ? client.getFlowManager() : null;
        boolean failed = false;
        for (Map.Entry<String, PendingLegacyDelete> entry : List.copyOf(pendingResourceDeletes.entrySet())) {
            PendingLegacyDelete pending = entry.getValue();
            if (pending == null || !pendingResourceDeletes.remove(entry.getKey(), pending)) {
                continue;
            }
            pending.cancelTimeout();
            cancelPendingSend(entry.getKey());
            failed = true;
            if (manager != null) {
                ReSyncResourceType type = ReSyncResourceType.byTypeId(pending.key.type());
                if (type != null) {
                    manager.failResourceDelete(serverId, type, pending.key.id(), message);
                }
            }
        }
        return failed;
    }

    private boolean failPendingSaveMutations(String message) {
        List<String> pendingRequestIds = DesignerSaveNotifications.pendingRequestIdsForServer(serverId);
        Set<String> retainedRequestIds = retainedTransportSaveRequestIds();
        List<DesignerSaveNotifications.SaveTarget> failedSaves = new ArrayList<>();
        for (String requestId : pendingRequestIds) {
            if (retainedRequestIds.contains(requestId)) {
                continue;
            }
            if (DesignerSaveNotifications.isResumableRequest(serverId, requestId)) {
                retainPendingResourceSave(requestId);
            } else {
                cancelPendingSend(requestId);
                DesignerSaveNotifications.SaveTarget failed = DesignerSaveNotifications.failRequest(serverId,
                    requestId, message);
                if (failed != null) {
                    failedSaves.add(failed);
                }
            }
        }
        retireResourceSavesWithoutDispatch();
        boolean failed = failPendingTriggerUpdates(message);
        FlowManager manager = client != null ? client.getFlowManager() : null;
        for (DesignerSaveNotifications.SaveTarget failedSave : failedSaves) {
            failed = true;
            if (failedSave.shouldUpdateResourceState()) {
                markResourceFailed(manager, failedSave.type(), failedSave.id());
            }
        }
        WorldGenManager worldGenManager = WorldGenManager.getInstance();
        for (WorldGenManager.WorldGenMutationIdentity identity : worldGenManager.pendingWorldGenMutations(serverId)) {
            failed |= worldGenManager.failWorldGenMutation(serverId, identity, message);
        }
        return failed;
    }

    private PendingConnectionFailures failPendingConnectionRequests(String message, boolean retainOpenIntents) {
        retainPendingCoreGraphSaves();
        retainPendingTransportMutations();
        failPendingCoreOptionRequests(message);
        boolean failedSaveMutations = failPendingSaveMutations(message);
        failPendingCoreGraphRequests(message, retainOpenIntents);
        failPendingLegacyActivations(message);
        boolean failedResourceDeletes = failPendingResourceDeletes(message);
        return new PendingConnectionFailures(failedResourceDeletes, failedSaveMutations);
    }

    private boolean retainPendingResourceSave(String requestId) {
        UUID requestUuid = parseSaveIdentity(requestId);
        if (requestUuid == null) {
            return false;
        }
        PendingTypedResourceRequest pending = removePendingTypedResourceRequest(requestUuid);
        cancelPendingSend(requestId);
        return pending != null;
    }

    private boolean failPendingTriggerUpdates(String message) {
        boolean failed = false;
        List<PendingTriggerUpdate> pending;
        synchronized (triggerUpdateAdmissionLock) {
            pending = new ArrayList<>(pendingTriggerUpdates.values());
        }
        for (PendingTriggerUpdate update : pending) {
            if (settlePendingTriggerUpdate(update, TriggerUpdateOutcome.rejected(message))) {
                failed = true;
            }
        }
        return failed;
    }

    private void sendResourceDelete(ReSyncResourceType type, String id, String payload) {
        if (shutdownRequested) return;
        if (!isProtocolResourceType(type)) {
            return;
        }
        if (type.isGraph()) {
            sendCoreGraphDelete(type, id);
            return;
        }
        String requestId = mutationRequestId(type.displayName() + "Delete", id);
        trackPendingLegacyDelete(type, id, requestId);
        sendLegacyResourceDelete(type, id, payload, requestId);
    }

    private void sendLegacyResourceDelete(ReSyncResourceType type, String id, String payload, String requestId) {
        if (shutdownRequested) return;
        if (!isProtocolResourceType(type) || !type.hasFlowPackets() || type.isGraph() || id == null || id.isBlank() || payload == null
            || requestId == null || requestId.isBlank()) {
            if (requestId != null) {
                removePendingLegacyDelete(requestId);
            }
            return;
        }
        trackPendingLegacyDelete(type, id, requestId);
        if (!isConnected()) {
            enqueuePendingSend(requestId, 5L + requestId.getBytes(StandardCharsets.UTF_8).length
                + payload.getBytes(StandardCharsets.UTF_8).length, () -> {
                if (!pendingResourceDeletes.containsKey(requestId)) {
                    return false;
                }
                return queuedSend(() -> sendLegacyResourceDelete(type, id, payload, requestId));
            });
            return;
        }
        byte[] requestIdBytes = requestId.getBytes(StandardCharsets.UTF_8);
        byte[] idBytes = payload.getBytes(StandardCharsets.UTF_8);
        ByteBuffer buffer = ByteBuffer.allocate(1 + 4 + requestIdBytes.length + idBytes.length);
        buffer.put(type.deleteByte());
        buffer.putInt(requestIdBytes.length);
        buffer.put(requestIdBytes);
        buffer.put(idBytes);
        if (!sendFrame(4, buffer.array(), numericChannel("flow", FLOW_CHANNEL_ID), false)
            && pendingSendThread != TaskIdentities.access.current()) {
            enqueuePendingSend(requestId, 5L + requestId.getBytes(StandardCharsets.UTF_8).length
                + payload.getBytes(StandardCharsets.UTF_8).length, () -> {
                if (!pendingResourceDeletes.containsKey(requestId)) {
                    return false;
                }
                return queuedSend(() -> sendLegacyResourceDelete(type, id, payload, requestId));
            });
        }
    }

    private void trackPendingLegacyDelete(ReSyncResourceType type, String id, String requestId) {
        if (type == null || id == null || id.isBlank() || requestId == null || requestId.isBlank()) {
            return;
        }
        PendingLegacyDelete pending = new PendingLegacyDelete(new ReSyncResourceKey(type.typeId(), id));
        if (pendingResourceDeletes.putIfAbsent(requestId, pending) != null) {
            return;
        }
        try {
            pending.timeoutTask = heartbeatScheduler.schedule(
                () -> failResourceDelete(requestId, "Resource Delete Timed Out"), Duration.ofSeconds(LEGACY_DELETE_TIMEOUT_SECONDS));
        } catch (RuntimeException exception) {
            if (pendingResourceDeletes.remove(requestId, pending)) {
                pending.cancelTimeout();
                FlowManager manager = client != null ? client.getFlowManager() : null;
                if (manager != null) {
                    manager.failResourceDelete(serverId, type, id, "Resource Delete Timed Out");
                }
            }
        }
    }

    private boolean isProtocolResourceType(ReSyncResourceType type) {
        return type != null && type.enabled() && ReSyncProtocolContract.resource(type.typeId()) != null;
    }

